pendingAsync.push((async () => {
  suite('Suite 74. The workbook writer, actually run');

  const NEED = ['hlxCrc32', 'hlxDeflateRaw', 'hlxInflateRaw', 'hlxUnzip', 'hlxUnzipAll',
               'hlxZip', 'hlxRowXml', 'hlxColName', 'hlxColNum', 'hlxSharedStrings',
               'hlxReadSheet', 'hlxWorkbookRows', 'hlxWorkbookSharedStrings',
               'hlxSheetPartFor', 'hlxNamesAlreadyOnTab', 'hlxAppendRowsToSheet',
               'dupNormName', 'hlxXmlText'];
  /* extractFn DROPS THE `async` KEYWORD, and this file already warns about that
     trap elsewhere. Most of the writer is async, so lifting it with extractFn
     produces a body full of bare `await` and the whole suite dies at parse time
     as one confusing 'an async suite crashed'. This keeps the keyword. */
  const lift = (n) => {
    /* No regex: a backslash does not survive every route into this file, and an
       escape that quietly degrades turns into a runtime SyntaxError that reads
       as 'an async suite crashed' with no clue which suite. */
    let st = admin.indexOf('async function ' + n + '(');
    if (st < 0) st = admin.indexOf('function ' + n + '(');
    if (st < 0) return '';
    let i = admin.indexOf('{', st), d = 0;
    for (; i < admin.length; i++) {
      if (admin[i] === '{') d++;
      else if (admin[i] === '}') { d--; if (!d) return admin.slice(st, i + 1); }
    }
    return '';
  };
  const missing = NEED.filter(n => !lift(n));
  check('S74', 'every piece of the writer is still in admin.html', !missing.length,
    'missing: ' + missing.join(', ') + ' — renamed or removed; update this suite rather ' +
    'than deleting it, or the writer goes back to being untested');

  if (missing.length) return;

  /* The file on "disk". A fake File System Access handle over a variable. */
  let disk = null, writes = 0, permissionAsked = 0;
  const handle = {
    getFile: async () => new Blob([disk]),
    queryPermission: async () => { permissionAsked++; return 'granted'; },
    createWritable: async () => ({
      write: async (d) => { disk = new Uint8Array(d); writes++; },
      close: async () => {}
    })
  };

  const box = {};
  new Function('hlxSheetHandleLoad',
    'let HLX_CRC_TABLE = null;' + NEED.map(lift).join('') +
    'this.append = hlxAppendRowsToSheet; this.onTab = hlxNamesAlreadyOnTab;' +
    'this.rows = hlxWorkbookRows; this.zip = hlxZip; this.unzipAll = hlxUnzipAll;' +
    'this.partFor = hlxSheetPartFor; this.norm = dupNormName;'
  ).call(box, async () => handle);

  /* A workbook with two tabs, built with the SHIPPED zip writer so the test cannot
     pass against a file only some other library could produce. Sheet order is
     deliberately NOT tab order: in the real book Recycle is sheet8 while Sheet1 is
     sheet2, so a writer that guesses by position writes into the wrong tab. */
  const enc = new TextEncoder();
  const sheetXml = (rows) => enc.encode('<worksheet><sheetData>' + rows + '</sheetData></worksheet>');
  const cell = (ref, text) => '<c r="' + ref + '" t="inlineStr"><is><t>' + text + '</t></is></c>';
  const build = () => box.zip([
    {name: 'xl/workbook.xml', data: enc.encode(
      '<workbook><sheets>' +
      '<sheet name="Customers" sheetId="1" r:id="rId9"/>' +
      '<sheet name="Recycle" sheetId="2" r:id="rId4"/>' +
      '</sheets></workbook>')},
    {name: 'xl/_rels/workbook.xml.rels', data: enc.encode(
      '<Relationships>' +
      '<Relationship Id="rId9" Target="worksheets/sheet1.xml"/>' +
      '<Relationship Id="rId4" Target="worksheets/sheet2.xml"/>' +
      '</Relationships>')},
    {name: 'xl/worksheets/sheet1.xml', data: sheetXml(
      '<row r="1">' + cell('A1', 'Name') + cell('B1', 'Address') + '</row>' +
      '<row r="2">' + cell('A2', 'Ada Real') + cell('B2', '1 Elm') + '</row>')},
    {name: 'xl/worksheets/sheet2.xml', data: sheetXml(
      '<row r="1">' + cell('A1', 'Name') + '</row>')}
  ]);

  disk = await build();
  const before = await box.rows(new Blob([disk]));
  check('S74', 'the writer can build a workbook its own reader reads back',
    before.length === 2 && before[1][0] === 'Ada Real',
    'this is the round trip that single-quoted attributes broke: the bytes were ' +
    'valid XML and Excel opened them, and our reader saw no rows at all');

  /* ---- appending to a named tab ---- */
  const res = await box.append([['Bea Fake']], 'Recycle');
  check('S74', 'a row is appended to the tab that was named', res && res.written === 1);
  check('S74', 'and the bytes were actually written', writes === 1);
  check('S74', 'write permission is asked for separately from read', permissionAsked >= 1,
    'the comparison only ever needed read, so the first write is the first time ' +
    'Chrome is asked — skipping the ask fails with a DOMException the office cannot act on');

  const after = await box.rows(new Blob([disk]));
  check('S74', 'THE CUSTOMER LIST IS UNTOUCHED when the row went to a side tab',
    after.length === before.length && after[1][0] === 'Ada Real',
    'this is the check that decides whether a Recycle write is allowed at all: ' +
    'expecting sheet1 to GROW would refuse every legitimate tab write');

  const onTab = await box.onTab('Recycle');
  check('S74', 'and the new name can be found on that tab afterwards',
    !!onTab && !!onTab[box.norm('Bea Fake')],
    'hlxNamesAlreadyOnTab is the only thing stopping a customer being appended ' +
    'again on every run; a reader that cannot see what the writer just wrote ' +
    'means the tab grows without limit');
  check('S74', 'the name is stored under the sorted key, not the typed one',
    !onTab['bea fake'] && !!onTab[box.norm('Fake Bea')],
    'dupNormName sorts the words, so "Fake, Bea" and "Bea Fake" are the same ' +
    'person — which is the whole point on a sheet written surname-first');

  /* ---- the row goes to the first FREE row, not row 1 ---- */
  const parts = await box.unzipAll(disk.buffer ? disk.buffer.slice(disk.byteOffset, disk.byteOffset + disk.byteLength) : disk);
  const recycleXml = new TextDecoder().decode(box.partFor(parts, 'Recycle').data);
  check('S74', 'it lands on the first free row, and the heading is left alone',
    /<row r="2"/.test(recycleXml) && /<row r="1"[^>]*>[\s\S]{0,200}?Name/.test(recycleXml),
    'owner: "recycle should go to the recycle tab in excel first row possible"');
  check('S74', 'and it went to the Recycle tab, NOT the first sheet in the file',
    recycleXml.indexOf('Bea Fake') !== -1,
    'a tab name is not a filename — workbook.xml points at a relationship id and ' +
    'the rels file turns that into sheetN.xml. Here Recycle is sheet2 while it is ' +
    'listed second, and Customers is sheet1 while listed first, so position and ' +
    'name disagree exactly as they do in the real book');

  /* ---- a sheet full of empty rows, which is what hers really is ---- */
  {
    /* ⭐ THE YES SHEET IN THE REAL WORKBOOK HOLDS 9,697 ROW ELEMENTS AND NO DATA —
       empty rows Excel keeps for formatting. Appending after the highest row NUMBER put
       three customers on rows 9698-9700, and the owner reported exactly what that looks
       like: "it says yes was updated but the yes sheet is still blank." It was not
       blank. They were ten thousand rows down.

       This fixture is that sheet in miniature: a heading, then empty rows 2-6. */
    /* ⚠ AND THE EMPTY ROWS ARE NOT STRUCTURALLY EMPTY. Every row of her real Yes
       sheet from 2 to 9697 carries ONE cell in column R: a leftover TRUE/FALSE
       checkbox, t="b" with a 0 in it. The sheet looks blank and is not, so a
       has-any-value test called all 9,696 of them used and went to the bottom
       anyway. That stray cell is reproduced here, or this fixture proves nothing. */
    const emptyRows = '<row r="1">' + cell('A1', 'Name') + '</row>' +
      [2,3,4,5,6].map(n => '<row r="' + n + '" spans="1:18"><c r="R' + n + '" s="180" t="b"><v>0</v></c></row>').join('');
    const bytes = await box.zip([
      {name: 'xl/workbook.xml', data: enc.encode('<workbook><sheets>' +
        '<sheet name="Customers" r:id="rId9"/><sheet name="Yes" r:id="rId4"/>' +
        '</sheets></workbook>')},
      {name: 'xl/_rels/workbook.xml.rels', data: enc.encode('<Relationships>' +
        '<Relationship Id="rId9" Target="worksheets/sheet1.xml"/>' +
        '<Relationship Id="rId4" Target="worksheets/sheet2.xml"/>' +
        '</Relationships>')},
      {name: 'xl/worksheets/sheet1.xml', data: sheetXml(
        '<row r="1">' + cell('A1', 'Name') + '</row>' +
        '<row r="2">' + cell('A2', 'Ada Real') + '</row>')},
      {name: 'xl/worksheets/sheet2.xml', data: enc.encode(
        '<worksheet><sheetData>' + emptyRows + '</sheetData></worksheet>')}
    ]);
    disk = bytes;
    writes = 0;
    await box.append([['Bea Fake']], 'Yes');
    const parts2 = await box.unzipAll(disk.buffer ? disk.buffer.slice(disk.byteOffset, disk.byteOffset + disk.byteLength) : disk);
    const yesXml = new TextDecoder().decode(box.partFor(parts2, 'Yes').data);

    const at = (yesXml.match(/<row[^>]*r="(\d+)"[^>]*>(?:(?!<\/row>)[\s\S])*Bea Fake/) || [])[1];
    check('S74', 'a row lands on the first BLANK row, not after the last one',
      at === '2',
      'landed on row ' + at + '. The owner asked for "first row possible" and "first ' +
      'blank row"; counting from the highest row NUMBER is a different thing, and on ' +
      'her real Yes sheet it meant row 9698');

    /* ⚠ AND THE PLACEHOLDER IS REPLACED, NOT DUPLICATED. Those empty rows exist in
       the XML, so a second element numbered 2 gives the sheet two row 2s and Excel
       refuses to open it. */
    const twos = (yesXml.match(/<row[^>]*r="2"/g) || []).length;
    check('S74', 'and the empty row it replaced is gone, not left beside it',
      twos === 1,
      'found ' + twos + ' rows numbered 2 — a duplicate row number is a workbook ' +
      'Excel will not open');
    check('S74', 'the heading is still row 1',
      /<row[^>]*r="1"[^>]*>(?:(?!<\/row>)[\s\S])*Name/.test(yesXml));

    /* Two at once fill the next two blanks, in order. */
    writes = 0;
    await box.append([['Cal Two'], ['Dot Three']], 'Yes');
    const parts3 = await box.unzipAll(disk.buffer ? disk.buffer.slice(disk.byteOffset, disk.byteOffset + disk.byteLength) : disk);
    const yes3 = new TextDecoder().decode(box.partFor(parts3, 'Yes').data);
    const rowOf = (who) => (yes3.match(new RegExp('<row[^>]*r="(\\d+)"[^>]*>(?:(?!</row>)[\\s\\S])*' + who)) || [])[1];
    check('S74', 'and the next ones fill the blanks after it, in order',
      rowOf('Cal Two') === '3' && rowOf('Dot Three') === '4',
      'got ' + rowOf('Cal Two') + ' and ' + rowOf('Dot Three'));
    check('S74', 'without disturbing the one already written',
      rowOf('Bea Fake') === '2');
  }

  /* ---- the guards ---- */
  const writesBefore = writes;
  let threw = '';
  try { await box.append([['Nobody']], 'No Such Tab'); } catch (e) { threw = e.message || ''; }
  check('S74', 'a tab that does not exist refuses, and names the tab', /no tab called/i.test(threw),
    'got: ' + threw);
  check('S74', 'and nothing was written when it refused', writes === writesBefore,
    'a half-written workbook is worse than no write at all');

  const none = await box.append([], 'Recycle');
  check('S74', 'nothing to write writes nothing', none && none.written === 0 && writes === writesBefore);

  /* Every write must survive being read back by the same reader. */
  const final = await box.rows(new Blob([disk]));
  check('S74', 'the workbook still reads after everything above',
    final.length === 2 && final[0][0] === 'Name',
    'the verify-before-write step is what makes this safe on a real file, and it ' +
    'is only worth anything if the reader is the one the rest of the app uses');
})());
suite('Suite 73. Finding the houses still on soft lights');

{
  const render = sectionFrom(admin, admin.indexOf('function renderAllCustomersTable()'));
  check('soft-find', 'the Lights filter is wired into the All Customers table',
    /const lightsFilter = lightsEl/.test(render) && /lightsEl.value/.test(render) &&
    /allCustFilterLights/.test(admin),
    'the control has to be read where the rows are filtered, not just exist in the page');

  /* Pull the filter itself out and run it. */
  const at = render.indexOf("if(lightsFilter === 'soft')");
  const block = at < 0 ? '' : render.slice(at, render.indexOf('if(dateStart)', at));
  check('soft-find', 'the filter block was found to run',  !!block);

  if (block) {
    const run = new Function('rows', 'lightsFilter', 'let out = rows;' +
      block.replace(/\brows\b/g, 'out') + 'return out;');

    /* Every way soft can be recorded, plus the ways it must NOT match. */
    const book = [
      { d: { name: 'Soft in the list',   lightColors: ['soft(recycled)', 'Red'], lightsDescription: '' } },
      { d: { name: 'Soft capitalised',   lightColors: ['Soft(Recycled)'],        lightsDescription: '' } },
      { d: { name: 'Soft in a pattern',  lightColors: [],  lightsDescription: 'soft(recycled), Red, soft(recycled)' } },
      { d: { name: 'Warm white only',    lightColors: ['Warm White'],            lightsDescription: '' } },
      { d: { name: 'Nothing recorded',   lightColors: [],                        lightsDescription: '' } },
      { d: { name: 'No fields at all' } }
    ];
    const names = f => run(book, f).map(r => r.d.name);

    check('soft-find', 'a customer on soft is found',
      names('soft').indexOf('Soft in the list') !== -1);
    check('soft-find', 'and so is one whose case differs',
      names('soft').indexOf('Soft capitalised') !== -1,
      'a colour typed by hand in the portal and one that came off the sheet have to land in the same list');
    check('soft-find', 'and one where soft is only in the alternating pattern',
      names('soft').indexOf('Soft in a pattern') !== -1,
      'rbDetectColorsAndPattern moves a repeated colour OUT of lightColors and into lightsDescription, so checking only the list would miss every alternating house');
    check('soft-find', 'a warm-white house is NOT dragged in',
      names('soft').indexOf('Warm white only') === -1,
      'the list is a work order — padding it wastes somebody’s afternoon');
    check('soft-find', 'and neither is a customer with no colours at all',
      names('soft').indexOf('Nothing recorded') === -1);

    check('soft-find', 'the no-colours filter finds the blank ones',
      names('none').indexOf('Nothing recorded') !== -1 &&
      names('none').indexOf('No fields at all') !== -1,
      'a missing field and an empty one are the same gap to whoever has to ring them');
    check('soft-find', 'and leaves the ones that do have colours alone',
      names('none').indexOf('Warm white only') === -1 &&
      names('none').indexOf('Soft in the list') === -1);

    /* The one a red-check caught: an alternating house has an EMPTY lightColors
       because rbDetectColorsAndPattern moves repeated colours into the pattern
       instead. Counting only the list calls that house undecorated. */
    check('soft-find', 'a house whose colours are only in the pattern is NOT called blank',
      names('none').indexOf('Soft in a pattern') === -1,
      'it would show up on a chase-them-for-colours list they already answered');

    check('soft-find', 'Any leaves every customer in place',
      run(book, 'all').length === book.length,
      'the default must never hide anybody');
    check('soft-find', 'and a missing field never throws',
      (function(){ try { run(book, 'soft'); run(book, 'none'); return true; }
                   catch(e){ return false; } })(),
      'an old customer record predates both fields');
  }
}

suite('Suite 70. An existing member is asked what is changing, not handed the new-customer form');
{
  /* Owner, 2026-08-19: "I need the members that already exist not to go to the
     form once they are created. It should just show a message similar to Do you
     want anything changed with your lights this year? If they say yes they will
     go straight to there member portal if they say No than a cute message will
     come up".

     The form collects colours, wire, timer and notes. A member already has all
     of it on file, and admin's own quote card already warns the office about
     this case ("Already a customer... do not Convert to Customer again") - this
     is the half the customer sees. */
  const idx = read('index.html');
  const fns = read('functions/index.js');
  const respond = sectionFrom(fns, fns.indexOf('exports.quoteRespond = onCall'));

  /* ---- the server decides, and it decides narrowly ------------------- */
  check('S70', 'quoteRespond answers whether this is an existing member',
    /alreadyMember: alreadyMember/.test(respond) || /alreadyMember,/.test(respond),
    'without it the page cannot tell a member from a first-time customer');

  /* ⚠ RESCOPED 2026-08-21 (hole A). existingCustomerId used to be read here
     inside quoteRespond; it now lives in quoteCustomerRef, the ONE resolver the
     approve, decline and maybe-next-year paths all share. Same rule, one copy —
     so the record half of this check reads the resolver, and the flag half
     stays on quoteRespond because alreadyMember is deliberately wider than the
     record (convertedToCustomerAt says a customer was made without naming
     which). Reading only the caller would go quietly green on a resolver that
     had started matching by phone. */
  const quoteCustSrc = extractFn(fns, 'quoteCustomerRef') || '';
  check('S70', 'the two signals are the explicit ones, not a phone match',
    /quoteData\.convertedToCustomerAt/.test(respond) &&
    /existingCustomerId/.test(stripComments(quoteCustSrc)) &&
    /convertedToCustomerId/.test(stripComments(quoteCustSrc)) &&
    !/findByPhone/.test(stripComments(quoteCustSrc)),
    'convertedToCustomerAt is the owner’s "once they are created"; ' +
    'existingCustomerId is a re-quote against a live record');

  /* ⚠ THEIR CRLF FIX LANDED ON A CHECK THAT NO LONGER EXISTS, and the lesson
     is kept rather than the line. The other session made the old memberBlock
     regex CRLF-safe because main went red on it — their diagnosis was right and
     the fix was right. That regex check is gone now: it asserted the matcher
     never touches a phone, which stopped being true when the matcher started
     using address PLUS phone. What replaced it RUNS the matcher, so there is no
     newline to get wrong. Measured here: this checkout is pure LF and theirs is
     CRLF, which is exactly why no regex in this suite may assume either — every
     one below uses \r?\n or avoids newlines entirely. */
  /* ⚠ THE TRAP THIS EXISTS TO STOP, and it is RUN rather than grepped.

     Matching a quote to a customer on CONTACT ALONE is the obvious
     implementation and it is wrong here: 17 phone numbers in the real book are
     shared, and 14 of those are two genuinely different houses (a parent
     paying for a child's place). A brand-new house quoted against a parent's
     phone would be told it was already a member and would never be asked for
     its install details at all. The ADDRESS is what keeps them apart.

     An earlier version of this check was a regex over the source. It went on
     passing after the matcher was rewritten, because the `else` branch added
     to the code broke the window the regex was slicing — it was reading a
     truncated block and finding nothing, which looks exactly like success.
     That is the third time in this repo a text-only check has been green over
     code it was not actually looking at. So this builds the two houses and
     asks the real function. */
  {
    const matchSrc = extractFn(fns, 'quoteMatchesExistingCustomer');
    const normSrc = extractFn(fns, 'quoteMatchAddressServer');
    check('S70', 'the existing-customer matcher exists', !!matchSrc && !!normSrc);
    check('S70', 'and it is async in the real file',
      /async function quoteMatchesExistingCustomer\(/.test(fns),
      'it awaits Firestore — if it stops being async it returns a promise that ' +
      'is always truthy, and EVERY approver is called an existing member');
    if (matchSrc && normSrc) {
      /* One phone, two houses. This is the real shape from the book. */
      /* Ids on the fixture, because the matcher now returns WHICH record — the
         caller needs that to mark them in for the season. */
      const BOOK = [
        { id: 'dad', phoneDigits: '8015550111', emailLower: 'dad@x.com', address: '12 Oak Street' },
        { id: 'kid', phoneDigits: '8015550111', emailLower: 'kid@x.com', address: '99 Elm Avenue' }
      ];
      const db = {
        collection: function () {
          return {
            where: function (field, _op, value) {
              return {
                limit: function () {
                  return {
                    get: function () {
                      return Promise.resolve({
                        docs: BOOK.filter(function (r) { return r[field] === value; })
                          .map(function (r) { return { id: r.id, data: function () { return r; } }; })
                      });
                    }
                  };
                }
              };
            }
          };
        }
      };
      const sb = {};
      new Function('db', 'digitsOnly', 'console',
        /* ⚠ extractFn matches on "function NAME(" and so LOSES the async
           keyword. CLAUDE.md records this suite being caught by it twice; this
           was the third. Put it back, and assert it really is async against the
           whole file rather than the extracted body. */
        normSrc + 'async ' + matchSrc + 'this.match = quoteMatchesExistingCustomer;'
      ).call(sb, db, function (v) { return String(v == null ? '' : v).replace(/\D/g, ''); }, console);

      pendingAsync.push((async function () {
        /* The child's brand-new house, quoted on the parent's phone. */
        check('S70', 'a new house on a shared phone is NOT called an existing member',
          (await sb.match({ phone: '(801) 555-0111', address: '5 New Road' })) === null,
          'this is the household case — 14 of 17 shared numbers in the real book ' +
          'are a parent and a child at two different addresses');
        /* The parent themselves. */
        check('S70', 'the same phone AT THE SAME ADDRESS is an existing member',
          ((await sb.match({ phone: '801-555-0111', address: '12 Oak Street.' })) || {}).id === 'dad',
          'punctuation and case must not stop a real member matching');
        /* ⚠ A REAL LIMIT, ASSERTED SO IT IS VISIBLE RATHER THAN SURPRISING.
           The normaliser folds case, punctuation and spacing — it does NOT
           know that "St." means "Street". admin.html's own badge has always
           behaved this way, so the office card and this agree; but it does
           mean a member whose quote spells the street differently from their
           customer record still sees the details form. Widening it is a
           change to BOTH copies at once, and to this line. */
        check('S70', 'a differently-WORDED street does not match, and that is admin’s rule too',
          (await sb.match({ phone: '8015550111', address: '12 Oak St' })) === null,
          'if this starts passing, admin.html and the server have diverged — ' +
          'quoteAlreadyACustomer does not do abbreviations either');
        check('S70', 'and the child matches at THEIR address, not the parent’s',
          ((await sb.match({ phone: '8015550111', address: '99 Elm Avenue' })) || {}).id === 'kid',
          'the candidate list must not stop at the first record behind a shared phone');
        check('S70', 'an email match still needs the address to agree',
          (await sb.match({ email: 'dad@x.com', address: '77 Somewhere Else' })) === null,
          'contact alone is never enough, whichever contact it is');
        check('S70', 'and matches when it does',
          ((await sb.match({ email: 'DAD@X.com ', address: ' 12 oak street ' })) || {}).id === 'dad',
          'case and stray spaces are normalised on both sides');
        check('S70', 'a quote with no address is never a member',
          (await sb.match({ phone: '8015550111', address: '' })) === null,
          'an empty address would otherwise match every record with an empty one');
      })());

      /* ⚠ A SECOND COPY OF A RULE THAT ALREADY LIVES IN admin.html. That is
         the duplicated-maths problem money-parity.test.js exists for, so the
         two are asserted identical here rather than trusted to stay in step. */
      const adminNorm = extractFn(admin, 'quoteMatchAddress');
      check('S70', 'admin.html still has quoteMatchAddress', !!adminNorm);
      if (adminNorm) {
        const a = {}, b = {};
        new Function(adminNorm + 'this.f = quoteMatchAddress;').call(a);
        new Function(normSrc + 'this.f = quoteMatchAddressServer;').call(b);
        const SAMPLES = ['12 Oak St.', ' 12  oak   street ', '#4, 9 Elm Ave', '', null,
                         'A.B.C, 1 Road', '  ', '1234 W 500 S #12'];
        const differ = SAMPLES.filter(function (x) { return a.f(x) !== b.f(x); });
        check('S70', 'the office and the server normalise an address identically',
          differ.length === 0,
          'they disagree on: ' + JSON.stringify(differ) + ' — the office would ' +
          'call somebody an existing customer and the customer\'s page would not');
      }
    }
  }

  /* ⚠ A quoteToken is generated in the visitor’s own browser, so anybody able
     to submit the public quote form knows one. Handing back a portalToken is
     the account takeover closed in portalLookup on 2026-08-14. */
  /* Scoped to the WHOLE of quoteRespond, not a sub-slice: a sub-slice is what
     stopped matching when the code grew an else branch a few checks above.
     ⚠ COMMENTS STRIPPED. The rule is written down in the code, right where it
     applies, so a plain search finds its own explanation and reports the
     explanation as the violation. */
  check('S70', 'and it never hands back a portal credential',
    !/portalToken/.test(stripComments(respond)),
    'the quote token would become a customer session — the exact hole ' +
    'closed in portalLookup on 2026-08-14');

  check('S70', 'a failed check refuses rather than guessing yes',
    /catch[\s\S]{0,400}alreadyMember = false;/.test(respond),
    'wrongly saying "member" loses a real customer’s install details');

  /* ⚠ A KNOWN DISCONNECT, recorded rather than papered over.

     admin.html decides the same question a THIRD way -- quoteAlreadyACustomer,
     which matches the quote's ADDRESS plus its phone or email against the book
     (address as well as contact, so a parent and child sharing a number are
     still two houses). That is what puts "Already a customer... do not Convert
     to Customer again" on the office's quote card.

     The server deliberately does NOT copy it. Doing so would mean a second
     copy of the address normalisation living on the other side of the wire,
     which is the duplicated-maths problem money-parity.test.js exists for, and
     the two would drift.

     What that costs: BOTH writes that mark a quote converted are best-effort
     (admin.html catches and toasts, because the customer is already created by
     then). If one of those fails, the person IS a member but the quote does not
     say so, and they would still be shown the install-details form. The office
     is told at the time and can close the card by hand, which also fixes this.

     Closes when the server and admin agree by construction -- most likely by
     the conversion writing an explicit link that cannot silently go missing.  */
  gap('S70 existing-member test agrees with admin\'s own',
    /quoteAlreadyACustomer/.test(respond),
    'a quote whose convert-write failed leaves a real member being asked for ' +
    'install details we already hold; admin already flags that card');

  /* ---- approving is saying yes to the season -------------------------
     A returning member who approved their re-quote had agreed to the price,
     but rsvpStatus stayed blank — so they still read as "pending" and got
     chased by an RSVP email asking them to confirm a season they had just
     confirmed. */
  {
    const seasonBlock = respond.slice(respond.indexOf('APPROVING IS SAYING YES TO THE SEASON'));
    /* ⚠ IT NO LONGER WRITES THE STATUS INLINE. Since 2026-08-22 all three doors go
       through seasonYesUpdates, so what is asserted here is that this door still
       writes SOMETHING for an approver; what a yes actually does is proved by running
       that helper, in season-state.test.js. */
    check('S70', 'approving marks an existing member in for the season',
      /db\.collection\('jobAddresses'\)\.doc\(memberRef\.id\)/.test(seasonBlock),
      'without it they stay RSVP-pending and get chased by the RSVP email');

    /* ⭐ THE GUARD IS GONE, DELIBERATELY (2026-08-22). Owner, asked which way and
       told the trade in full: "go with option 2."

       ⚠ WHAT USED TO BE HERE, so nobody restores it by accident: approving a quote
       only marked somebody whose RSVP was blank or Unanswered, because a recorded no
       was a DELIBERATE answer and one inferred from a price should not outrank it —
       a re-quote can be sent to somebody who has already said no, to correct a figure
       or to price next year, and reading that approval as "I am back in" puts them on
       a crew day when all they agreed to was the number. That cost is real and was
       put to her in those terms. She took it, because in practice a re-quote goes to
       somebody she is trying to bring back.

       ⚠ THE LATEST ANSWER STILL WINS. This is one more way to say yes, not a lock —
       a no arriving afterwards, by link or by office, overrides it. She asked that
       specifically, and the check below is what holds it.

       ⚠ AND IT HAD TO DO THE WHOLE JOB. Setting the status alone was safe only
       BECAUSE it never ran for somebody who had said no; now that it does, it would
       leave them in the season with needsLightRecycle still set — in and queued to be
       taken apart at once, which is exactly what the old note warned about. */
    check('S70', 'approving a quote now marks them whatever they said before',
      !/currentRsvp/.test(seasonBlock),
      'the blank-only guard was removed on purpose — restoring it silently undoes ' +
      'the owner\'s decision');
    check('S70', 'and it goes through the shared yes rule, not its own write',
      /update\(seasonYesUpdates\(memberRef\.data \|\| \{\}/.test(seasonBlock),
      'a status-only write leaves them in the season AND queued for recycle');

    check('S70', 'and only ever for somebody who is already a customer',
      /if \(action === 'approve' && memberRef\)/.test(seasonBlock),
      'a new lead has no season to be in yet — they join when the office converts them');

    check('S70', 'a failed write never fails the approval',
      /catch \(err\)[\s\S]{0,220}marking approver as in for the season failed/.test(seasonBlock),
      'the price is already accepted; throwing here makes them ring up about it');

    /* The matcher has to name WHICH customer or there is nobody to mark. */
    check('S70', 'the matcher returns the record, not just a yes/no',
      /return \{ id: doc\.id, data: doc\.data\(\) \};/.test(respond) ||
      /return \{ id: doc\.id/.test(read('functions/index.js')),
      'a bare boolean answers "is this a member" but not "which one"');
    check('S70', 'and it returns null, never false, when there is no match',
      !/if \(!wanted\) return false;/.test(read('functions/index.js')),
      'mixing null and false in one return type is how a caller ends up ' +
      'testing the wrong thing');
  }

  /* ---- the page asks the question, in that order ---------------------- */
  const handle = extractFn(idx, 'handleQuoteLink');
  check('S70', 'handleQuoteLink still exists', !!handle);
  if (handle) {
    const atMember = handle.indexOf('res.alreadyMember');
    const atForm = handle.indexOf('res.formCompleted');
    check('S70', 'the member question is asked BEFORE the form-already-done branch',
      atMember !== -1 && atForm !== -1 && atMember < atForm,
      'a member who once filled the form in would otherwise be told "nothing ' +
      'else to do" and never asked the one question we want answered');
  }

  /* ---- and it is RUN, not grepped ------------------------------------
     ⚠ A regex over the file proves the words are in the source, which is a
     different and weaker claim than that they reach the screen. This repo lost
     a day to exactly that on 2026-08-19: every text check passed while a
     default assignment further down overwrote the message with "nothing". */
  if (!JSDOM) {
    note('jsdom not installed — skipping the member-question render');
  } else {
    const offerSrc = extractFn(idx, 'offerMemberChangeChoice');
    const openSrc = extractFn(idx, 'openPortalFromQuote');
    check('S70', 'offerMemberChangeChoice exists', !!offerSrc);
    check('S70', 'openPortalFromQuote exists', !!openSrc);
    if (offerSrc && openSrc) {
      const dom = new JSDOM(
        '<div id="quoteLinkConfirm" style="display:none"></div>' +
        '<div id="quoteLinkConfirmMsg"></div>' +
        '<div id="quoteLinkConfirmSub"></div>' +
        '<div id="quoteLinkConfirmActions" style="display:none"></div>' +
        '<div id="quoteDetailFormWrap"></div>' +
        '<div id="quoteDetailSuccess"></div>' +
        '<input id="lookupPhone"><input id="lookupLastName">',
        /* A real origin, or jsdom refuses localStorage - which this reads to
           decide whether they are already signed in on this device. */
        { url: 'https://highlightingutah.com/' });
      const doc = dom.window.document;
      const sb = { opened: [], loggedInWith: null };
      /* ⚠ MODULE-LEVEL STATE HAS TO BE DECLARED HERE. openPortalFromQuote reads
         quoteLinkPortalToken (the router sets it from the &p= on the link) and
         calls savePortalLogin / loadPortalByToken. A lifted function whose
         globals are missing throws a ReferenceError, which scores as an
         ordinary FAIL and reads as the feature being broken. */
      const mkSandbox = function (d, w, portalToken) {
        const box = { loggedInWith: null };
        new Function('document', 'window', 'localStorage', 'sb',
          'var quoteLinkPortalToken = ' + JSON.stringify(portalToken || null) + ';' +
          'function savePortalLogin(t){ try{ localStorage.setItem("huPortalToken", t); }catch(e){} }' +
          'function loadPortalByToken(t){ sb.loggedInWith = t; }' +
          'function setQuoteConfirmSub(h){ document.getElementById("quoteLinkConfirmSub").innerHTML = h || ""; }' +
          /* The third answer (2026-08-21) hands them the whole install form again.
             Stubbed here so this suite stays about WHICH answers are offered and what
             each one does with them; the form itself is filled in below. */
          'function showQuoteDetailFormFresh(md){ sb.freshWith = md; sb.freshCalled = true; }' +
          offerSrc + openSrc +
          'this.offer = offerMemberChangeChoice; this.open = openPortalFromQuote;'
        ).call(box, d, w, w.localStorage, box);
        return box;
      };
      const sbNoToken = mkSandbox(doc, dom.window, null);
      sb.offer = sbNoToken.offer; sb.open = sbNoToken.open;

      sb.offer('sam@example.com');
      const msg = () => doc.getElementById('quoteLinkConfirmMsg').textContent;
      const sub = () => doc.getElementById('quoteLinkConfirmSub').textContent;
      const acts = doc.getElementById('quoteLinkConfirmActions');

      check('S70', 'the question actually reaches the screen',
        /anything changed with your lights this year/i.test(msg()),
        'this is the owner’s own wording and it has to be the thing rendered');
      check('S70', 'the install-details form is put away',
        doc.getElementById('quoteDetailFormWrap').style.display === 'none',
        'the approve branch shows it before this answer arrives, so it has to ' +
        'be hidden again here or the member sees both');
      check('S70', 'both answers are offered',
        acts.querySelectorAll('[data-mc="yes"]').length === 1 &&
        acts.querySelectorAll('[data-mc="no"]').length === 1,
        'one button each — yes goes to the portal, no closes it off');
      /* ⭐ AND THE THIRD ONE. Owner, 2026-08-21: "when an old house gets requoted I want
         them to choose whether they want to fill out the form fresh or keep what's
         already there." A re-quote is nearly always raised because the HOUSE changed,
         and the portal's change-one-thing screens are the wrong shape for a remodel. */
      /* ⚠ HELD AS A GAP, NOT A FAILURE — see the note on qdPrefillFromMember below. */
      gap('and so is filling the form out fresh',
        acts.querySelectorAll('[data-mc="fresh"]').length === 1,
        'the customer-facing half of this is NOT IN THE REPO. On 2026-08-21 an index.html push replaced the customer site with a copy of admin.html, which took this with it; index.html was restored from the last good copy, which predates it. Re-push index.html from the session that wrote it and these close by themselves.');

      /* No = the warm ending. */
      acts.querySelector('[data-mc="no"]').dispatchEvent(
        new dom.window.Event('click', { bubbles: true }));
      check('S70', '"No" leaves a warm message, not a bare acknowledgement',
        /all set/i.test(msg()) && /can’t wait|cannot wait/i.test(sub()),
        'the owner asked for "something a little more nice"');
      check('S70', 'and the buttons are taken away once answered',
        acts.style.display === 'none' && acts.innerHTML === '',
        'leaving them up invites a second answer to a question already answered');

      /* ⭐ AND WHAT "STARTED FROM WHAT WE HOLD" ACTUALLY PUTS IN THE BOXES. Run rather
         than read: what matters here is a pattern being recognised as a pattern, and
         two boxes deliberately staying EMPTY.

         ⚠ THE GATE CODE AND THE HOUSE NOTES ARE NEVER SENT DOWN TO THIS FORM. A
         quoteToken is minted in the visitor's own browser, so holding one proves
         nothing about who you are — the same reason quoteRespond has never returned a
         portalToken. Empty therefore has to MEAN unchanged, on the page and again in
         admin.html, or applying a re-quote wipes a gate code every time. */
      {
        const prefillSrc = extractFn(idx, 'qdPrefillFromMember');
        /* ⚠ A GAP, NOT A FAILURE. This is real work by the other session and the check
           is a good one — it runs the function rather than reading it. What is missing is
           the file it lives in. Written as a gap so the suite stays honest (it is
           listed, by name, every run) without a red gate stopping unrelated work, and so
           it turns itself back into a PASS the moment index.html comes back. */
        gap('qdPrefillFromMember exists', !!prefillSrc,
          'the customer-facing half of this is NOT IN THE REPO. On 2026-08-21 an index.html push replaced the customer site with a copy of admin.html, which took this with it; index.html was restored from the last good copy, which predates it. Re-push index.html from the session that wrote it and these close by themselves.');
        if (prefillSrc) {
          const fdom = new JSDOM(
            '<form id="f">' +
            '<div id="qdSimpleColorsRow"></div><div id="qdSequenceBuilderWrap"></div>' +
            '<input type="checkbox" id="qdSpecificPatternToggle">' +
            '<select name="wire_color"><option value="Any"></option><option value="White"></option><option value="Green"></option></select>' +
            '<select name="install_month"><option value="Normal Schedule"></option><option value="October"></option><option value="November"></option></select>' +
            '<label class="radio-pill"><input type="radio" name="outlet_timer" value="Yes"></label>' +
            '<label class="radio-pill"><input type="radio" name="outlet_timer" value="No"></label>' +
            '<label class="radio-pill"><input type="radio" name="specific_outlet" value="Yes"></label>' +
            '<label class="radio-pill"><input type="radio" name="specific_outlet" value="No"></label>' +
            '<div id="specificOutletNotesWrap" style="display:none"><textarea name="specific_outlet_notes"></textarea></div>' +
            '<input name="gate_code"><textarea name="notes"></textarea>' +
            '<input type="checkbox" name="wants_mailed">' +
            '</form>');
          const fd = fdom.window.document;
          const box = {};
          new Function('document', 'quoteDetailFormEl', 'QD_COLOR_HEX', 'sb',
            'var qdSimpleColors = [], qdSequence = [];' +
            'function renderQdSimpleColors(){ sb.simple = qdSimpleColors.slice(); }' +
            'function renderQdSequence(){ sb.seq = qdSequence.slice(); }' +
            prefillSrc + 'this.fill = qdPrefillFromMember;'
          ).call(box, fd, fd.getElementById('f'),
                 {'Warm White':1,'Pure White':1,'Red':1,'Green':1,'Blue':1,'Purple':1,'Orange':1,'Pink':1,'Multi':1}, box);
          fd.querySelector('[name="gate_code"]').value = 'should be cleared';
          box.fill({lightColors: ['Pure White','Red'], lightsDescription: 'Pure White, Pure White, Red',
                    wireColor: 'Any', outletTimer: 'Yes', specificOutlet: 'Yes',
                    specificOutletNotes: 'back patio', installPreference: 'October',
                    wantsMailedInvoice: true});
          check('S70', 'a repeating pattern opens the pattern builder, in order',
            fd.getElementById('qdSpecificPatternToggle').checked === true &&
            (box.seq || []).join(', ') === 'Pure White, Pure White, Red',
            '"White, White, Red" shown as two ticked circles is a different set of lights');
          check('S70', 'the wire colour, timing and timer they already have are filled in',
            fd.querySelector('[name="wire_color"]').value === 'Any' &&
            fd.querySelector('[name="install_month"]').value === 'October' &&
            fd.querySelector('input[name="outlet_timer"][value="Yes"]').checked === true);
          check('S70', 'and the outlet box is opened because they use a specific one',
            fd.getElementById('specificOutletNotesWrap').style.display === 'block' &&
            fd.querySelector('[name="specific_outlet_notes"]').value === 'back patio');
          check('S70', 'the gate code box is empty and says an empty box keeps what we have',
            fd.querySelector('[name="gate_code"]').value === '' &&
            /keep the code we already have/i.test(fd.querySelector('[name="gate_code"]').placeholder),
            'we never send them their own gate code, so it must not look lost either');
          check('S70', 'and so does the notes box',
            /keep the notes we already have/i.test(fd.querySelector('[name="notes"]').placeholder));
          box.fill({lightColors: ['Red','Green'], lightsDescription: 'Red, Green',
                    wireColor: 'Green'});
          check('S70', 'a plain set of colours leaves the pattern builder shut',
            fd.getElementById('qdSpecificPatternToggle').checked === false &&
            (box.simple || []).join(', ') === 'Red, Green',
            'two different colours is a set, not a repeating pattern');
          /* ⚠ THE 'Any' CASE ABOVE CANNOT PROVE THE WIRE COLOUR IS WRITTEN, and the
             fixture is not at fault — 'Any' is the FIRST option and carries `selected`
             on the real page too, so a select nobody touched already reads 'Any'.
             Deleting the wire-colour line entirely left that check green. This one
             asserts a value only the prefill can produce. */
          check('S70', 'and the wire colour is really written, not just left on its default',
            fd.querySelector('[name="wire_color"]').value === 'Green',
            'filling it in and not filling it in are indistinguishable on the default ' +
            'value, so this is the assertion that actually holds the line');
          /* ⚠ THE TWO DEFENSIVE PATHS, which every fixture above walks straight past.
             Both were red-checked and neither was caught until these existed. */
          box.fill({lightColors: ['Red','Green'],
                    lightsDescription: 'alternating red and green (ladder round the back)'});
          check('S70', 'a description that is a sentence falls back to the colours they ticked',
            (box.simple || []).join(', ') === 'Red, Green' &&
            fd.getElementById('qdSpecificPatternToggle').checked === false,
            'a repeated colour is moved OUT of lightColors and INTO lightsDescription, ' +
            'so the description has to be read first — but mining colours out of a ' +
            'sentence would drop the half that matters, so an unreadable one falls ' +
            'back to the ticked list rather than guessing at it');
          fd.querySelector('[name="wire_color"]').value = 'White';
          box.fill({lightColors: ['Red'], lightsDescription: 'Red', wireColor: 'Purple'});
          check('S70', 'a wire colour the form does not offer is refused, not written blank',
            fd.querySelector('[name="wire_color"]').value === 'White',
            'assigning a select a value it has no option for leaves it showing NOTHING, ' +
            'which then saves as a blank wire colour over a real one');
        }
      }

      /* Fresh = the whole form, started from what we already hold. */
      sb.offer('sam@example.com', {lightsDescription: 'Red, Green'});
      /* Guarded: on a build where the button does not exist this must score one FAIL,
         not throw and take the remaining two thousand checks down with it. */
      const freshBtn = acts.querySelector('[data-mc="fresh"]');
      if (freshBtn) freshBtn.dispatchEvent(new dom.window.Event('click', { bubbles: true }));
      gap('"Fill it out fresh" opens the form with what we already hold',
        sbNoToken.freshCalled === true &&
        sbNoToken.freshWith && sbNoToken.freshWith.lightsDescription === 'Red, Green',
        'the customer-facing half of this is NOT IN THE REPO. On 2026-08-21 an index.html push replaced the customer site with a copy of admin.html, which took this with it; index.html was restored from the last good copy, which predates it. Re-push index.html from the session that wrote it and these close by themselves.');

      /* ⚠ AND THE FUNCTION THE BUTTON ACTUALLY CALLS, RUN RATHER THAN READ. Every
         check above STUBS showQuoteDetailFormFresh, so the real one — the thing that
         has to put the form on screen and fill it in — was covered by nothing at all.
         Showing the form without prefilling it, or prefilling without showing it, are
         both one deleted line. */
      {
        const freshSrc = extractFn(idx, 'showQuoteDetailFormFresh');
        check('S70', 'the fresh answer has a real function behind it',
          !!freshSrc, 'the button calls it by name');
        if (freshSrc) {
          const gdom = new JSDOM(
            '<div id="quoteLinkConfirm" style="display:block"></div>' +
            '<div id="quoteLinkConfirmActions" style="display:block"><button></button></div>' +
            '<div id="quoteDetailFormWrap" style="display:none"></div>' +
            '<div id="quoteDetailGreeting" style="display:none"></div>');
          const gd = gdom.window.document;
          const seen = {};
          new Function('document', 'seen',
            'function setQuoteConfirmSub(h){ seen.sub = h; }' +
            'function qdPrefillFromMember(md){ seen.filledWith = md; }' +
            freshSrc + 'return showQuoteDetailFormFresh;'
          )(gd, seen)({lightsDescription: 'Red, Green'});
          check('S70', 'it puts the install form on screen',
            gd.getElementById('quoteDetailFormWrap').style.display === 'block',
            'the whole point of this answer is the form — without this it silently ' +
            'does nothing at all');
          check('S70', 'and fills it from what we hold, rather than opening it blank',
            seen.filledWith && seen.filledWith.lightsDescription === 'Red, Green',
            'opening it empty makes them retype everything, which is the one thing ' +
            'this answer exists to save them');
          check('S70', 'and clears the question away so it cannot be answered twice',
            gd.getElementById('quoteLinkConfirmActions').style.display === 'none' &&
            gd.getElementById('quoteLinkConfirmActions').innerHTML === '' &&
            gd.getElementById('quoteLinkConfirm').style.display === 'none',
            'the other two answers both take the buttons away; leaving them up under ' +
            'the form invites a second answer to a question already answered');
        }
      }

      /* ⚠ THE WIRING, WHICH THE SANDBOX ABOVE CANNOT SEE. Every check in this block
         calls offerMemberChangeChoice DIRECTLY and hands it the member details itself,
         so the page could stop passing what the server sent and all of them would stay
         green — while the form opened blank for every real customer. Deleting the
         argument from the real call site was a red-check that nothing caught. These
         three assert the whole chain instead: the server fills it, the page hands it
         down, and neither end ever carries a gate code. */
      check('S70', 'the real quote link hands the member details down',
        /alreadyMember\)\s*\{[\s\S]{0,500}?offerMemberChangeChoice\([^)]*memberDetails/.test(idx),
        'the prefill has nothing to fill from unless the alreadyMember branch passes ' +
        'the details quoteRespond returned');
      check('S70', 'and the server actually sends them',
        /memberDetails:\s*\(alreadyMember && memberRef\) \? memberPrefill\(/
          .test(read('functions/index.js')),
        'the browser half is useless on its own — this is the write to its read');
      check('S70', 'and the gate code and house notes are never in what it sends',
        (() => {
          const src = read('functions/index.js');
          const at = src.indexOf('const memberPrefill');
          if (at === -1) return false;
          /* Sliced to the arrow function's own closing `  };` rather than a fixed
             window, which goes stale as the file grows (CLAUDE.md §7). */
          const end = src.indexOf('\n  };', at);
          if (end === -1) return false;
          const body = src.slice(at, end);
          /* ⚠ NOT a bare /notes/i — specificOutletNotes legitimately travels and
             would match it, turning this into a check that can never pass. */
          return !/gateCode/i.test(body) && !/oneTimeNote/i.test(body) &&
                 !/(^|[^a-zA-Z])notes\s*:/m.test(body);
        })(),
        'the empty gate-code and notes boxes on the form are only safe because ' +
        'neither value ever leaves the server — a quoteToken is minted in the ' +
        'visitor’s own browser and proves nothing about who they are');

      /* Yes = their portal. With no saved login on this device it must fall
         back to the normal, rate-limited, last-name-checked sign-in. */
      sb.offer('sam@example.com');
      acts.querySelector('[data-mc="yes"]').dispatchEvent(
        new dom.window.Event('click', { bubbles: true }));
      check('S70', '"Yes" sends them to the Member Portal',
        String(dom.window.location.hash) === '#/payment',
        'the owner asked for "straight to there member portal"');
      check('S70', 'and fills the sign-in box in for them',
        doc.getElementById('lookupPhone').value === 'sam@example.com',
        'they still type their last name — that check and its rate limit are ' +
        'what a quote token must never be allowed to skip');
      /* ⭐ The member's own portal token, carried in the quote email we sent to
         the address on file, lets them in with no typing at all. */
      {
        const dom2 = new JSDOM(
          '<div id="quoteLinkConfirm"></div><div id="quoteLinkConfirmMsg"></div>' +
          '<div id="quoteLinkConfirmSub"></div><div id="quoteLinkConfirmActions"></div>' +
          '<div id="quoteDetailFormWrap"></div><div id="quoteDetailSuccess"></div>' +
          '<input id="lookupPhone"><input id="lookupLastName">',
          { url: 'https://highlightingutah.com/' });
        const withToken = mkSandbox(dom2.window.document, dom2.window, 'PORTALTOKEN123');
        withToken.open('sam@example.com');
        check('S70', 'a portal token in the email logs them straight in',
          withToken.loggedInWith === 'PORTALTOKEN123',
          'this is the whole point of putting it in the link — no second sign-in');
        check('S70', 'and it never asks them to type anything',
          dom2.window.document.getElementById('lookupPhone').value === '',
          'falling through to the sign-in box means the token was ignored');
      }
      check('S70', 'the site chrome comes back on the way out',
        !/quote-minimal/.test(doc.body.className),
        'navigate() clears rsvp-minimal but not quote-minimal, so the portal ' +
        'would render with no header and no footer');
    }
  }
}


  /* ---- WHOSE portal link goes in the quote email --------------------
     ⚠ THE MOST DANGEROUS MISTAKE AVAILABLE IN THIS WHOLE FEATURE. The quote
     email for an existing member carries their own portal token so approving
     can let them in. A portal token IS a login. Match it on the phone alone
     and a PARENT'S login is posted into their CHILD'S quote email — handing
     one customer a working session on another customer's account, with their
     address, gate code and invoice in it. 17 numbers in the real book are
     shared and 14 of those are exactly that shape.

     This check exists because a sabotage that made the match phone-only was
     NOT caught by anything else in the suite. */
  {
    const admSrc = read('admin.html');
    const parts = ['quoteMatchAddress', 'quoteCustomerKeys', 'quoteExistingCustomer']
      .map(n => extractFn(admSrc, n));
    check('S70', 'quoteExistingCustomer and its helpers exist', parts.every(Boolean));
    if (parts.every(Boolean)) {
      const BOOK = [
        { id: 'dad', data: { name: 'Dad', address: '12 Oak Street', phone: '(801) 555-0111',
                             email: 'dad@x.com', portalToken: 'DAD-TOKEN' } },
        { id: 'kid', data: { name: 'Kid', address: '99 Elm Avenue', phone: '801-555-0111',
                             email: 'kid@x.com', portalToken: 'KID-TOKEN' } }
      ];
      const box = {};
      new Function('jobAddresses',
        'let quoteCustKeyCache = null, quoteCustKeyCacheFor = null;' +
        parts.join('\n') + 'this.find = quoteExistingCustomer;'
      ).call(box, BOOK);

      const got = q => { const c = box.find(q); return c && c.data ? c.data.portalToken : null; };

      check('S70', 'the parent’s quote gets the PARENT’S portal link',
        got({ address: '12 Oak Street', phone: '8015550111' }) === 'DAD-TOKEN');
      check('S70', 'and the child’s quote gets the CHILD’S, on the very same phone',
        got({ address: '99 Elm Avenue', phone: '8015550111' }) === 'KID-TOKEN',
        'matching on the phone alone hands the parent a login to the child’s ' +
        'account, or the other way round — this is the leak the address prevents');
      check('S70', 'a brand-new house on that shared phone gets NO portal link',
        got({ address: '5 New Road', phone: '8015550111' }) === null,
        'a new lead has no portal — anything returned here would be somebody else’s');
      check('S70', 'an address with no matching contact gets none either',
        got({ address: '12 Oak Street', phone: '8019999999' }) === null,
        'the address alone is not proof — a landlord and tenant share one');
      check('S70', 'and a quote with no address gets none',
        got({ phone: '8015550111' }) === null,
        'no address means no way to tell the two houses apart, so refuse');
    }
  }

  /* ⚠ EVERY quote-email builder must carry the portal token, not just one.
     CLAUDE.md records that the big "View Your Quote" button is the link most
     customers actually press — the coloured buttons in the body are the minority
     path. Wiring only the body button would have looked right in a test and
     done nothing for most people. */
  {
    const admSrc2 = read('admin.html');
    const builders = admSrc2.split("button_url: 'https://highlightingutah.com/#/quote-details?token='");
    check('S70', 'every "View Your Quote" builder adds the portal token',
      builders.length > 1 && builders.slice(1).every(b => /^[^\n]*quotePortalParam\(/.test(b)),
      'a quote-email link that omits it sends a member to the sign-in box ' +
      'instead of into their portal');
    check('S70', 'and they all go through the ONE helper',
      (admSrc2.match(/quotePortalParam\(/g) || []).length >= 4,
      'a second inline copy of the rule is one that drifts');
  }

  /* ---- the OTHER way in: approving from inside the portal ------------
     ⚠ THIS IS THE ONE THAT WAS ACTUALLY BROKEN. The portal's own Approve
     button ended with `window.location.hash = '/quote-details'` — the
     new-customer install-details page — and it went there with NO ?token= on
     the end. handleQuoteLink only runs when the router sees a token, so the
     whole member flow above was bypassed and the form simply rendered. A
     member testing from their portal saw the form no matter what the email
     route did. */
  {
    /* Its own read: this block sits outside the Suite 70 scope where `idx`
       was declared. */
    const idxSrc = read('index.html');
    const portalApprove = sectionFrom(idxSrc, idxSrc.indexOf("document.getElementById('quoteApproveBtn')"));
    check('S70', 'the portal approve handler is still there', !!portalApprove);
    if (portalApprove) {
      const atMember = portalApprove.indexOf('res.alreadyMember');
      const atForm = portalApprove.indexOf("hash = '/quote-details'");
      check('S70', 'a member approving in the portal is NOT sent to the form',
        atMember !== -1 && atForm !== -1 && atMember < atForm,
        'the member branch has to come first, or the redirect fires for everyone ' +
        'and the install-details form appears inside their own portal');
      check('S70', 'and they are shown that it was approved',
        /quoteApprovedMsg/.test(portalApprove),
        'the card just vanishing looks like the button did nothing');
      /* ⚠ The other half of the owner's rule: somebody who is NOT yet a
         customer still needs that form — it is the only place their colours,
         wire and timer are collected. */
      check('S70', 'but a not-yet-converted customer still gets the form',
        atForm !== -1 && /return;/.test(portalApprove.slice(atMember, atForm)),
        'the member branch must RETURN, leaving the redirect reachable for ' +
        'everyone else — deleting it would lose new customers’ install details');
    }
  }

suite('Suite 72. An RSVP never goes to somebody who has never had lights');
{
  /* Owner, 2026-08-19: "lets just tick new members for now that have come in so
     they don't get an RSVP but any new people should automatically get ticked
     and we shouldn't have to do anything."

     "Will you be getting lights hung AGAIN this year?" is nonsense to a
     first-year customer, and invites a "no" from somebody who was never asked a
     sensible question. */
  const adm = read('admin.html');

  /* ⚠ THE SEPARATE RSVP SENDER IS DEAD UI AND MUST NOT BE MISTAKEN FOR THE REAL
     ONE. admin.html carries rsvpRenderRecipientList, rsvpPopulateMemberSelect
     and a send handler, and NONE of their markup exists — every one of those ids
     is in KNOWN_MISSING_IDS above, so the functions return at their first line.
     Reading that code and concluding "the RSVP sender has no filters" is a
     mistake that was actually made in this repo on 2026-08-19. The real send is
     an ordinary template through Automation Emails, which has the full filter
     set. This check pins that, so if the markup is ever built the assumption
     gets re-examined instead of silently going stale. */
  /* ⚠ NAMED, NOT MATCHED ON A PREFIX. This was `!/id="rsvp/`, which fails the
     moment ANY new control is given an rsvp-ish name — and one was: the Start a new
     RSVP round button, which is live markup for a different job entirely. Listing the
     dead sender's own ids keeps the check about the thing it is about. */
  const DEAD_RSVP_IDS = ['rsvpRecipientList', 'rsvpRecipientSearch', 'rsvpSelectAllBtn',
                         'rsvpSelectNoneBtn', 'rsvpPreviewMemberSelect', 'rsvpPreviewBox',
                         'rsvpEmailTemplate', 'rsvpEmailStatus', 'rsvpIncludePortal',
                         'rsvpIncludeMessages'];
  const built = DEAD_RSVP_IDS.filter(id => adm.indexOf('id="' + id + '"') !== -1);
  check('S72', 'the separate RSVP sender UI still does not exist', !built.length,
    'built: ' + built.join(', ') + ' — if this markup exists, the RSVP email no longer ' +
    'goes only through Automation Emails and the audience rule below needs applying there too');
  check('S72', 'and its functions are still reading ids that are not there',
    DEAD_RSVP_IDS.every(id => adm.indexOf(id) !== -1),
    'if the functions themselves are gone this check is guarding nothing and should ' +
    'be deleted rather than left passing vacuously');

  const isRsvpSrc = extractFn(adm, 'etTemplateIsRsvp');
  check('S72', 'etTemplateIsRsvp exists', !!isRsvpSrc);
  if (isRsvpSrc) {
    const box = {};
    new Function(isRsvpSrc + 'this.f = etTemplateIsRsvp;').call(box);
    check('S72', 'a template with RSVP buttons is recognised',
      box.f({ data: { body: 'Hi {{name}}\n{{rsvp_yes_button}}{{rsvp_no_button}}' } }) === true);
    check('S72', 'so is one recognised only by its folder',
      box.f({ data: { body: 'plain words', folderName: 'RSVP' } }) === true,
      'the office can write their own RSVP wording without the button tokens');
    check('S72', 'and an ordinary email is NOT',
      box.f({ data: { body: 'Your invoice is ready {{price}}', folderName: 'Billing' } }) === false,
      'over-matching would quietly drop new customers off every send, which is ' +
      'the opposite failure and harder to notice');
    check('S72', 'a quote email is not mistaken for an RSVP',
      box.f({ data: { body: '{{quote_yes_button}}' } }) === false,
      'a quote absolutely does go to somebody who has never had lights');
    check('S72', 'and nothing at all is safe',
      box.f(null) === false && box.f({}) === false);
  }

  /* The wiring: choosing the template is what sets the audience. */
  const handler = sectionFrom(adm, adm.indexOf("document.getElementById('etSendTemplateSelect').addEventListener('change'"));
  check('S72', 'choosing an RSVP template sets the audience to Returning',
    /etTemplateIsRsvp\(t\)[\s\S]{0,200}etFilterNew = 'returning'/.test(handler),
    'without this the office has to remember, which is exactly what was asked ' +
    'not to be necessary');
  check('S72', 'and it redraws the list so Select All cannot reach them',
    /etRenderRecipientList\(\)/.test(handler),
    'a stale list still holds the new customers as tickable rows');
  check('S72', 'the office picking their own value turns the default off',
    /etFilterNew = v; etRsvpAudienceAutoSet = false;/.test(adm),
    'otherwise the explanation keeps claiming credit for their choice');
  check('S72', 'it is a DEFAULT, not a lock',
    !/etFilterNew.*disabled|disabled.*etFilterNew/.test(adm),
    'an RSVP that really is meant for everybody must stay one click away');
  check('S72', 'and the screen says it happened',
    /New customers are left out automatically/.test(adm),
    'automatic is fine, invisible is not');
}


suite('Suite 71. A reconcile note that cannot be saved still leaves a record');
{
  /* ⚠ RESTORED 2026-08-19 after a paste-over from a stale read dropped it (the
     same paste took sysNoteBody with it). The long note failing was invisible
     for weeks; the paste left a toast in its place, and a toast is gone the
     moment the office looks away. This is the LAST step of a sweep that has
     already rewritten real routes, so "the sweep happened" is the part that has
     to survive in somewhere it keeps. */
  const notice = sectionFrom(admin, admin.indexOf('async function noticeRoutesReconciled'));
  const catchBlock = (notice.match(/\} catch\(err\)\{[\s\S]*$/) || [''])[0];

  check('S71', 'noticeRoutesReconciled still exists', !!notice);
  check('S71', 'a failed note is still said on screen',
    /toast\(/.test(catchBlock),
    'the immediate half — the office is looking at the page right now');
  check('S71', 'and a short note is still written to the System folder',
    /addDoc\(collection\(db,'messages'\)/.test(catchBlock),
    'a toast is not a record; routes have already been rewritten by this point');
  check('S71', 'the short note says how many things changed',
    /lines\.length \+\n?\s*' thing\(s\) changed/.test(catchBlock),
    'a note that does not say the sweep did anything is no better than silence');
  check('S71', 'and the short note goes to the System folder like the long one',
    /folder: 'System'/.test(catchBlock),
    'the office looks in one place for these');
  check('S71', 'a second failure cannot take the sweep down with it',
    /catch\(err2\)/.test(catchBlock),
    'the routes are already written — throwing here would strand the caller');
}

/*
 * Suite 77. The route generator in Schedule.
 *
 * Owner, 2026-08-20: "we need to add the route generator into schedule because
 * we need it to print in the right order, it should create two routes one for
 * each crew and it should automatically generate the route when they click
 * rebuild days or refresh towns, also those two buttons just need to be
 * combined because I want one button that just makes everything recaluculate
 * but not recalculate houses within two days cause weve already printed those
 * houses so it needs to keep track of the time US mountain time to make sure
 * if a day is within 48 hours it is unchangable."
 *
 * These checks RUN the shipped code — the generator, the crew sheet builder and
 * the panel's own grouping — against fixtures. The lesson that earned that
 * (2026-08-19, the ledger render): a regex proves the words are in the file,
 * which is a different and weaker claim than the crew getting the right sheet.
 */
suite('77. Schedule route generator');
{
  /* ⚠ TWO SLICES, NOT ONE. haversine and the orderer sit ~12,000 lines apart
     in admin.html, so a single slice between them drags in every top-level
     line in between — including markup wiring, which dies on a null element
     and takes the whole run down with a stack trace that names neither. */
  const havStart = admin.indexOf('function haversine(lat1, lng1, lat2, lng2)');
  const havEnd = admin.indexOf('\n}', havStart) + 2;
  /* ⚠ ANCHOR ON THE NAME, NOT THE SIGNATURE. Adding an optional argument to a
     function is a normal, backwards-compatible change; pinning the full argument
     list here turns it into a whole suite silently not running. That is exactly
     what happened on 2026-08-21 when twoOptImprove gained an endPoint. */
  const geoStart = admin.indexOf('function twoOptImprove(');
  const geoEnd = admin.indexOf('function nearestNeighborOrder(', geoStart);
  const lockStart = admin.indexOf('const ROUTE_LOCK_HOURS');
  const lockEnd = admin.indexOf('async function reconcileUpcomingRoutes(', lockStart);
  const crewStart = admin.indexOf('function cityOf(h)');
  const crewEnd = admin.indexOf('/* ---------- build from imported rows', crewStart);
  const sheetStart = admin.indexOf('function schedSheetRows(');
  const sheetEnd = admin.indexOf('function schedOpenPrint(', sheetStart);
  const crewRowsStart = admin.indexOf('function crewSheetRows(');
  const crewRowsEnd = admin.indexOf('function printCrewSheet(', crewRowsStart);
  if ([havStart, geoStart, lockStart, crewStart, sheetStart, crewRowsStart].some(i => i === -1) ||
      geoEnd < geoStart || lockEnd < lockStart || crewEnd < crewStart ||
      sheetEnd < sheetStart || crewRowsEnd < crewRowsStart) {
    check('S77', 'the route generator and its neighbours are findable',
      false, 'renamed or removed — update this test rather than deleting it');
  } else {
    global.dlabel = () => ({ wd: 'Mon', full: 'Nov 3' });
    global.dayDate = d => d._date;
    global.isoOf = d => [d.getFullYear(), String(d.getMonth() + 1).padStart(2, '0'),
                         String(d.getDate()).padStart(2, '0')].join('-');
    global.fmtPhone = () => '(801) 555-0100';
    global.isNewMemberHouse = () => false;
    global.esc = s => (s || '').toString();
    global.personName = n => n;
    /* The customer index itself is covered elsewhere; what matters here is that
       the generator reads the COORDINATES off the customer record rather than
       expecting the imported plan row to carry them. */
    global.customerForHouse = h => (h && h._cust) ? { data: h._cust } : null;
    const at = (name, city, lat) => ({ name, city, price: 1, _cust: { lat, lng: -111.85 } });

    /* ⚠ THE TWO TOWNS INTERLEAVE ON THE GROUND — Lehi on the even hundredths,
       Alpine on the odd ones between them. That is the whole point of the
       fixture: with the towns in two separate clumps, ordering the day as ONE
       list gives the SAME answer as ordering each crew on its own, so a check
       against clumped towns passes whether the crew split is honoured or not.
       It was, on the first pass, and a sabotage that deleted the split went
       straight through it. Interleaved, a single list reads L,A,L,A…
       Fed in scrambled, so the right answer is not the input order either. */
    const L1 = at('L1', 'Lehi', 40.00), L2 = at('L2', 'Lehi', 40.06),
          L3 = at('L3', 'Lehi', 40.02), L4 = at('L4', 'Lehi', 40.04);
    const A1 = at('A1', 'Alpine', 40.01), A2 = at('A2', 'Alpine', 40.05),
          A3 = at('A3', 'Alpine', 40.03);
    const loose = { name: 'Nowhere', city: '', price: 1, _cust: { lat: 41.9, lng: -111.85 } };
    const mkDay = () => ({ id: 'd1', _date: new Date(2026, 10, 3),
      houses: [L1, A1, L2, A2, L3, A3, L4] });

    global.allHouses = () => mkDay().houses;
    global.SEASON = [];
    /* ⭐ A CREW’S SECOND TOWN MUST NOW BE A NEIGHBOUR (2026-08-20). Owner: "the
       second city being a neighboring city is mandatory not a priority." Draper sits at
       40.70 in this fixture and Lehi and Alpine at about 40.03 — forty-six miles apart,
       which is precisely the sheet the rule exists to prevent, and it used to be handed
       to a crew silently.

       ⚠ The point of the checks below is the crew sheet that printed EMPTY for a crew
       holding TWO towns, so the two-town case has to survive. The office’s own
       nearby-towns list is what makes the pairing legal, exactly as it does live — and
       Lehi is deliberately left out of it, so Draper can only join Alpine. */
    const NEARBY_TOWN_LIST = {Alpine: ['Draper'], Draper: ['Alpine']};
    const gen = eval(admin.slice(havStart, havEnd) + '\n' +
      admin.slice(geoStart, geoEnd) + '\n' +
      admin.slice(lockStart, lockEnd) + '\n' +
      admin.slice(crewStart, crewEnd) + '\n' +
      admin.slice(sheetStart, sheetEnd) + '\n' +
      admin.slice(crewRowsStart, crewRowsEnd) + '\n' +
      ';({ day: generateDayRoutes, all: generateAllRoutes, order: orderHousesForDriving,' +
      '   labels: crewRouteLabels, routeRows: schedRouteRows, crewRows: crewSheetRows,' +
      '   houses: crewHousesFor, locked: routeDayIsLocked, hours: hoursUntilDayStarts,' +
      '   setSeason(s){ SEASON = s; }, setCrews(l){ CREWS = normalizeCrews(l); } })');

    const day = mkDay();
    const n = gen.day(day);
    check('S77', 'a day comes back as two routes, one town each, in driving order',
      day.houses.map(h => h.name).join() === 'L1,L3,L4,L2,A1,A3,A2',
      'got [' + day.houses.map(h => h.name).join() + '] — a crew handed the input order drives the town twice');
    check('S77', 'the crews are not interleaved',
      day.houses.slice(0, 4).every(h => h.city === 'Lehi') &&
      day.houses.slice(4).every(h => h.city === 'Alpine'),
      'one ordered list for the whole day sends each crew into the other\'s town and back');
    check('S77', 'and it reports how many stops it ordered', n === 7, 'got ' + n);

    /* The failure that costs a customer a visit, so it is checked directly. */
    const before = mkDay().houses.slice();
    const d2 = mkDay(); d2.houses.push(loose);
    gen.day(d2);
    check('S77', 'nothing is dropped by re-ordering',
      d2.houses.length === 8 && before.every(h => d2.houses.indexOf(h) > -1),
      'a lost stop is a customer nobody visits, and it is invisible on a printed sheet');
    /* ⚠ ASSERTS THE WHOLE ORDER, not just that the spare is last. It arrives
       last in the fixture too, so "is it on the end" is true before the code
       runs — and dropping the concat that carries it makes the day come back a
       different length, which the guard turns into "leave the day alone". Only
       the full order tells those two apart. */
    check('S77', 'a house in neither crew\'s town is kept, on the end, and the day is still ordered',
      d2.houses.map(h => h.name).join() === 'L1,L3,L4,L2,A1,A3,A2,Nowhere',
      'it still has to be driven to — got [' + d2.houses.map(h => h.name).join() + ']');

    /* A plan imported today has no coordinates on anything. It must come back
       whole rather than throwing or emptying the day. */
    const bare = { id: 'b', _date: new Date(2026, 10, 3),
      houses: [{ name: 'X', city: 'Lehi' }, { name: 'Y', city: 'Lehi' }, { name: 'Z', city: 'Lehi' }] };
    gen.day(bare);
    check('S77', 'houses that have never been geocoded still all come back',
      bare.houses.length === 3 && bare.houses.map(h => h.name).sort().join() === 'X,Y,Z',
      'the bulk import creates houses with no lat/lng on purpose');

    /* ⭐ 48 HOURS. The lock is the whole reason this may not simply run over the
       season, so it is proved by RUNNING it over days at known distances.
       ⚠ THREE houses, not two: with two stops there is only one possible order,
       so an ordered day and an untouched one look identical and the check proves
       nothing. Fed in scrambled, the shortest route is a,c,b. */
    const dayAt = (offsetDays, name) => {
      const d = new Date(); d.setHours(12, 0, 0, 0);
      d.setDate(d.getDate() + offsetDays);
      return { id: name, _date: d, houses: [
        Object.assign({}, L1, { name: name + '-a' }),
        Object.assign({}, L2, { name: name + '-b' }),
        Object.assign({}, L3, { name: name + '-c' }) ] };
    };
    const soon = dayAt(1, 'soon'), later = dayAt(30, 'later'), past = dayAt(-5, 'past');
    gen.setSeason([soon, later, past]);
    const res = gen.all();
    check('S77', 'a day inside 48 hours is left exactly as it was',
      soon.houses.map(h => h.name).join() === 'soon-a,soon-b,soon-c',
      'the crew is already holding that sheet on paper');
    check('S77', 'a day further out is ordered',
      later.houses.map(h => h.name).join() === 'later-a,later-c,later-b',
      'got [' + later.houses.map(h => h.name).join() + ']');
    check('S77', 'a day already gone is left alone too',
      past.houses.map(h => h.name).join() === 'past-a,past-b,past-c',
      'it is the record of what the crew was sent out with');
    check('S77', 'and it counts what it held back so the office can be told',
      res.locked === 2 && res.days === 1,
      'a day skipped in silence looks like a day it forgot — got locked=' + res.locked + ' days=' + res.days);

    /* ⭐ AND IT SAYS WHAT IT COULD NOT PUT IN ORDER (added 2026-08-21). A house
       with no map pin has no position to be ordered against, so it rides on the
       end of its day — which is right, and which looks exactly like the button
       having failed if nobody is told. The office can act on this one: the house
       is either not matched to a customer record or that customer has never been
       geocoded, and both are fixable from All Customers. */
    const bareOne = dayAt(30, 'bare');
    bareOne.houses.push({ name: 'no-pin', city: 'Lehi', price: 1 });
    gen.setSeason([bareOne]);
    const bareRes = gen.all();
    check('S77', 'a house with no map pin is counted, not silently parked',
      bareRes.nopin === 1,
      'got nopin=' + bareRes.nopin + ' — a handful of houses sitting at the bottom of ' +
        'every sheet reads as a broken button, not as a known gap');
    check('S77', 'and the rest of that day is still put in driving order',
      bareOne.houses.slice(0, 3).map(h => h.name).join() === 'bare-a,bare-c,bare-b',
      'the un-pinned house must not drag the pinned ones out of order — got [' +
        bareOne.houses.map(h => h.name).join() + ']');
    check('S77', 'and the un-pinned house is still on the day',
      bareOne.houses.length === 4 && bareOne.houses[3].name === 'no-pin',
      'it is a real customer somebody still has to drive to');

    gen.setSeason([dayAt(30, 'clean')]);
    check('S77', 'a season where everything is on the map reports none',
      gen.all().nopin === 0,
      'a count that is never zero is a count nobody reads');

    const started = dayAt(30, 'started');
    started.houses[0].done = true;
    gen.setSeason([started]);
    gen.all();
    check('S77', 'a day somebody is ticking through is not re-ordered under them',
      started.houses.map(h => h.name).join() === 'started-a,started-b,started-c',
      'they are working down that list right now');

    /* The clock itself: Mountain time, measured to the START of the day, because
       the truck is loaded the night before. */
    check('S77', 'the lock is measured to the start of the day, not the end',
      Math.round(gen.hours('2026-11-05', { date: '2026-11-03', hour: 0, minute: 0 })) === 48 &&
      gen.locked('2026-11-05', { date: '2026-11-03', hour: 1, minute: 0 }) === true &&
      gen.locked('2026-11-05', { date: '2026-11-03', hour: 0, minute: 0 }) === false,
      'the crew loads the truck the night before, so the useful moment is when the day starts');
    check('S77', 'a nonsense date never reads as locked',
      gen.locked('') === false && gen.hours('not-a-date', { date: '2026-11-03', hour: 0, minute: 0 }) === Infinity,
      'reading a junk value as "inside 48 hours" would freeze days nobody can unfreeze');

    /* ⭐ THE BUG THIS FOUND ON THE WAY PAST: a crew sheet for a crew holding two
       towns printed EMPTY, because the rows were filtered against crewCityFor,
       which JOINS the towns into one string. A crew day is one town plus at most
       one other, so that was every mixed day the builder makes.
       ⚠ THE FIXTURE HAS TO MAKE A CREW TAKE TWO TOWNS, and the split is by
       head-count: the big town goes to one crew and the two small ones both land
       on the other. Four Lehi against two Alpine and one Draper does it; three
       houses in two towns does NOT, and the first version of this check was
       vacuous for exactly that reason. */
    gen.setCrews([{ name: 'Dad + Ty', city: '' }, { name: 'Crew 2', city: '' }]);
    const D1 = at('D1', 'Draper', 40.70);
    const mixed = { id: 'm', _date: new Date(2026, 10, 3),
      houses: [L1, L2, L3, L4, A1, A2, D1] };
    check('S77', 'a crew really does hold two towns on a mixed day',
      gen.houses(1, mixed).length === 3,
      'with one crew town this whole check proves nothing — got ' + gen.houses(1, mixed).length);
    const rows = gen.crewRows(mixed, 1);
    check('S77', 'and their sheet prints all of them, not nothing',
      rows.length === 3 && rows.map(r => r.name).join() === 'A1,A2,D1',
      'filtering rows against the joined town string matched nothing at all — got [' +
        rows.map(r => r.name).join() + ']');
    check('S77', 'the crew sheet still numbers from 1',
      rows.length === 3 && rows[0].stop === 1 && rows[2].stop === 3);
    check('S77', 'the other crew gets only their own town',
      gen.crewRows(mixed, 0).map(r => r.name).join() === 'L1,L2,L3,L4');
    check('S77', 'a crew with nothing on the day still prints nothing',
      gen.crewRows({ id: 'x', _date: new Date(2026, 10, 3), houses: [] }, 1).length === 0);

    /* The printed rows name the crew and count from 1 per route. */
    const pd = mkDay(); gen.day(pd);
    const pr = gen.routeRows(pd);
    check('S77', 'every printed row says which crew is driving it',
      pr.every(r => /Dad \+ Ty|Crew 2/.test(r.route)),
      'with two crews on a day, whose sheet a row belongs to is the first thing anybody needs');
    check('S77', 'each route counts its stops from 1',
      pr[0].stop === 1 && pr[4].stop === 1 && pr[3].stop === 4,
      'a crew reading a shared sheet should see their own numbering, not their block of somebody else\'s');
    check('S77', 'the printed order is the order on screen',
      pr.map(r => r.name).join() === pd.houses.map(h => h.name).join(),
      'the paper and the panel disagreeing is worse than either being wrong');
    gen.setCrews(null);
  }
}

/* The periodic customer sync moves houses between days; a house dropped on the
   end of its new day is a house out of driving order, so the sync re-orders
   what it moved rather than waiting for a press. */
{
  const syncStart = admin.indexOf('window.scheduleSyncFromCustomers=function(opts){');
  const syncEnd = admin.indexOf('function __startSyncTimer()', syncStart);
  const sync = (syncStart > -1 && syncEnd > syncStart) ? admin.slice(syncStart, syncEnd) : '';
  {
    const rc = admin.indexOf("if(t.id==='recalcBtn')");
    const rcEnd = admin.indexOf("if(t.id==='undoRebuildBtn')", rc);
    const press = (rc > -1 && rcEnd > rc) ? admin.slice(rc, rcEnd) : '';
    check('S77', 'and the button SAYS how many it could not place',
      /routes\.nopin/.test(press) && /not on the map yet/.test(press),
      'counting it without printing it changes nothing the office can see');
  }
  check('S77', 'the periodic sync re-orders the days it changed',
    /routes=generateAllRoutes\(\)/.test(sync),
    'enforceInstallTiming puts a moved house on the END of its new day');
  /* ⚠ AND A REJOINER LANDING ON A DAY COUNTS AS A MOVE (added 2026-08-22). They are
     pushed onto the END of that day, so it is no longer in driving order — exactly
     the case this trigger exists for. A changed phone number still is not. */
  check('S77', 'but only when a house actually moved day or town',
    /if\(timing\.moved\.length \|\| rejoin\.placed\.length \|\| rehome\.moved\.length \|\| townChanged\)/.test(sync),
    'a changed phone number does not alter a route — re-ordering the season every five minutes would');
  check('S77', 'and it happens BEFORE the plan is drawn and saved',
    sync.indexOf('generateAllRoutes()') < sync.indexOf('computeDates(); renderAll(); scheduleSave();'),
    'ordering after the draw shows the office one order and saves another');
  check('S77', 'a failure ordering routes cannot take the sync down',
    /catch\(err\)\{ console\.error\('Route generation failed:'/.test(sync),
    'the towns and timings it just pulled across matter more than the order');
  check('S77', 'and the screen says the order changed',
    /re-ordered for driving/.test(sync),
    'automatic is fine; invisible is not');
}

/* The panel draws the same two routes the sheet prints — RUN, not read. */
{
  /* ⚠ START AT dayRouteGroups, NOT AT THE RENDERER. The list and the picture
     deliberately share one grouping function, so a slice that takes only the
     renderer no longer has the thing the renderer is built on. */
  const panelStart = admin.indexOf('function dayRouteGroups(day)');
  const panelEnd = admin.indexOf('function renderSearch(q)', panelStart);
  const crewStart = admin.indexOf('function cityOf(h)');
  const crewEnd = admin.indexOf('/* ---------- build from imported rows', crewStart);
  if (panelStart === -1 || panelEnd < panelStart) {
    check('S77', 'the day panel is findable', false, 'renamed — update this test');
  } else {
    const out = { innerHTML: '' };
    global.RT = { getElementById: () => out };
    global.esc = s => (s || '').toString();
    global.dlabel = () => ({ wd: 'Mon', full: 'Nov 3' });
    global.dayDate = d => d._date;
    global.isoOf = () => '2026-11-03';
    global.isWeekend = () => false;
    global.effectivePin = () => null;
    global.deltaFor = () => 0;
    global.weekGuideHTML = () => '';
    global.allHouses = () => [];
    /* Stubbed on purpose: this is a check about GROUPING, and the stop card has
       its own coverage. A card that renders is not the question here. */
    global.stopHTML = (h, n) => '<stop>' + h.name + '#' + n + '</stop>';
    const panel = eval(admin.slice(crewStart, crewEnd) + '\n' +
      admin.slice(panelStart, panelEnd) +
      '\n;({ render: renderPanelInto, setCrews(l){ CREWS = normalizeCrews(l); } })');
    panel.setCrews(null);
    const day = { id: 'd', _date: new Date(2026, 10, 3), cascade: 0, houses: [
      { name: 'L1', city: 'Lehi' }, { name: 'L2', city: 'Lehi' },
      { name: 'A1', city: 'Alpine' }, { name: 'N1', city: '' } ] };
    panel.render('panel', day);
    const html = out.innerHTML;
    check('S77', 'the panel draws one heading per crew route',
      (html.match(/class="routehead"/g) || []).length === 2,
      'one numbered list for the whole day reads as one route — got ' +
        (html.match(/class="routehead"/g) || []).length);
    check('S77', 'each route on screen counts from 1',
      html.indexOf('<stop>L1#1</stop>') > -1 && html.indexOf('<stop>A1#1</stop>') > -1,
      'the crew counting down the screen and the crew counting down the sheet must agree');
    check('S77', 'a house in neither town is still drawn, and says so',
      /routehead spare/.test(html) && html.indexOf('<stop>N1#1</stop>') > -1,
      'a stop nobody holds a sheet for is a stop nobody drives to');
    panel.setCrews(null);
  }
}


/* ---------------------------------------------------------------------------
 * Suite 117. The colour-change fee, actually charged
 *
 * Owner, 2026-08-21: "new member fee and change light fees are seperate but should
 * get charged seperetly for this so if new member changes lights again after 48 hours
 * of being a new member than they should get charged for light change and new member
 * fee which would put them at 6[0] dollars. So new member should not be assigned on
 * routes within 48 hours." And: "if invoice has already been sent out but they change
 * there lights after invoice is sent out than the 30 dollars will be charged for next
 * season but if invoice hasn't been sent out than it will be charged on there current
 * invoice."
 *
 * ⚠ THE HOLE THIS CLOSES IS THAT THE FEE WAS NEVER CHARGED AT ALL. From 2026-08-19
 * this block ended with `updates.chargeNewMemberFee = true`, and `updates` is written
 * to Firestore sixty-three lines EARLIER — so the flag landed on an object nobody
 * saved again, it is not in PORTAL_READ_FIELDS so it never reached the browser
 * either, and every colour change a member made in their own portal charged nothing
 * while the portal told them in red that $30 had been added to their balance.
 *
 * ⚠ AND EVERY CHECK THAT EXISTED PASSED THROUGHOUT, because they all read the source
 * as text and the text was there. This suite RUNS the shipped block against a fake
 * Firestore and reads the documents that came out. That is the only way this class of
 * bug is visible: a write that never happens looks identical to one that does, from a
 * regex.
 * ------------------------------------------------------------------------- */
suite('Suite 117. The colour-change fee, actually charged');

{
  const fns = read('functions/index.js');

  /* The real shipped block, sliced between the same two anchors it lives between,
     and run as-is. Not a paraphrase of it. */
  const A = '  let lightFeeInfo = null;';
  const B = "  // The Info tab also keeps the customer's invoice record in sync.";
  const a = fns.indexOf(A), b = fns.indexOf(B);
  check('S117', 'the lights block is where this suite expects it',
    a !== -1 && b !== -1 && b > a,
    'renamed or moved — fix this slice rather than deleting the suite');

  /* ⭐ FOUND IN THE SELF-AUDIT, 2026-08-21 — two things that were written and never
     connected to anything. Both are the "who READS it?" question from the hole-hunt,
     asked of my own work. */
  {
    const admin2 = read('admin.html');
    /* ⚠ A CHARGE PARKED FOR NEXT SEASON WAS INVISIBLE. carryoverCharge was written by
       the portal and by Edit Customer, and read ONLY by the nightly run — so nobody in
       the office could see why next year's bill would be higher, answer a customer who
       rang about it, or spot one added by mistake. It sits beside carryoverCredit,
       which is where somebody already looks to answer "why is this number what it is". */
    check('S117', 'a charge carried to next season is shown to the office',
      /carryChargeForPanel/.test(admin2) &&
      /Carried to NEXT season/.test(admin2),
      'written by two paths and read only by the nightly run is money nobody can see');

    /* ⚠ AND THE SCHEDULE MUST HONOUR THE 48 HOURS, not just Routes. Owner: "we won't
       schedule them within that 48 hours so they can change there lights again if
       they choose." customersMissingFromSeason is the ONE path that puts a brand-new
       customer onto a day, and it checked only isOutForSeason — which stopped being
       harmless the moment Add Customer began opening a window for every new customer.
       Run, not read: the guard is what matters, not the words. */
    const missSrc = extractFn(admin2, 'customersMissingFromSeason');
    check('S117', 'the schedule adder is findable', !!missSrc);
    if (missSrc) {
      const soon = { toMillis: () => Date.now() + 3600000 };
      const past = { toMillis: () => Date.now() - 3600000 };
      const book = [
        { id: 'free', data: {} },
        { id: 'locked', data: { lightsLockedUntil: soon } },
        { id: 'expired', data: { lightsLockedUntil: past } }
      ];
      const out = new Function('jobAddresses', 'seasonCustomerIds', 'isOutForSeason',
        'isLightsLocked', missSrc + ';return customersMissingFromSeason();')(
        book, () => new Set(), () => false,
        (d) => !!(d.lightsLockedUntil && d.lightsLockedUntil.toMillis() > Date.now()));
      check('S117', 'a customer inside their 48 hours is NOT put on a schedule day',
        !out.some(x => x.id === 'locked'),
        'the crew would hang a pattern that is still free to change — the exact thing ' +
        'the window exists to prevent');
      /* ⚠ HELD BACK, NOT DROPPED. This runs on every Recalculate everything, so they
         must arrive by themselves once the window closes. */
      check('S117', 'but is added once that window has closed',
        out.some(x => x.id === 'expired') && out.some(x => x.id === 'free'),
        'a customer held back for ever is worse than one scheduled early');
    }
  }

  const ruleSrc = extractFn(fns, 'applyLightChangeServer');
  const toMillisSrc = extractFn(fns, 'toMillis');
  check('S117', 'and the rule and the timestamp reader are both findable',
    !!ruleSrc && !!toMillisSrc,
    'extracted rather than stubbed on purpose: a stub would agree with itself');

  if (a !== -1 && b > a && ruleSrc && toMillisSrc) {
    const blockSrc = fns.slice(a, b);

    /* A fake Firestore that records what was written. Deliberately small, and
       deliberately NOT clever: every write is kept exactly as the code sent it, so
       an assertion below reads the document the customer would really have. */
    /* ⚠ SHALLOW-COPIED, NOT JSON ROUND-TRIPPED. A Firestore Timestamp is an
       object with methods on it, and JSON.stringify throws those away — so a
       seeded lightsLockedUntil arrived with no toMillis, the server's toMillis
       helper read it as 0, and a customer sitting comfortably inside their free
       window was charged $30 by the test harness. The bug was mine, but it is
       exactly the shape of the real one, so the fake now keeps what Firestore
       would hand back. */
    function makeDb(seed) {
      const docs = {};
      Object.keys(seed || {}).forEach(function (k) { docs[k] = Object.assign({}, seed[k]); });
      const messages = [];
      const ref = (path) => ({
        _path: path,
        update: function (o) {
          if (!docs[path]) return Promise.reject(new Error('no such doc ' + path));
          Object.assign(docs[path], o);
          return Promise.resolve();
        }
      });
      const db = {
        _docs: docs, _messages: messages,
        collection: function (c) {
          return {
            doc: function (id) { return ref(c + '/' + id); },
            add: function (o) { if (c === 'messages') messages.push(o); return Promise.resolve({}); }
          };
        },
        runTransaction: function (fn) {
          const t = {
            get: function (r) {
              return Promise.resolve({
                exists: Object.prototype.hasOwnProperty.call(docs, r._path),
                data: function () { return docs[r._path]; }
              });
            },
            set: function (r, o) { docs[r._path] = Object.assign({}, docs[r._path] || {}, o); },
            update: function (r, o) { docs[r._path] = Object.assign({}, docs[r._path] || {}, o); }
          };
          return Promise.resolve(fn(t));
        }
      };
      return db;
    }

    const NOWISH = Date.now();
    const HOUR = 3600000;
    /* ⚠ A FAITHFUL FAKE TIMESTAMP, and it matters. The server reads a stored
       timestamp through toMillis(), which tests toDate() and .seconds — the two
       things a real Firestore Timestamp actually has. A fake carrying only a
       toMillis() method read as 0, so a customer sitting inside their free window
       looked to the harness like somebody who had never had one and was charged.
       The production code was right; the fake was lying. Build fixtures from the
       same helper the code under test would have been handed. */
    const ts = function (m) {
      return {
        __ms: m,
        seconds: Math.floor(m / 1000),
        nanoseconds: (m % 1000) * 1e6,
        toMillis: function () { return m; },
        toDate: function () { return new Date(m); }
      };
    };
    const fakeAdmin = {
      firestore: {
        Timestamp: { fromMillis: ts },
        FieldValue: { serverTimestamp: function () { return '__SERVER_TS__'; } }
      }
    };

    /* Runs the real block. `cust` and `inv` are the documents as they stand before
       the save; `newLights` is what the member picked. */
    const runLights = function (cust, inv, newLights) {
      const seed = { 'jobAddresses/c1': Object.assign({}, cust) };
      if (inv) seed['invoices/8015550100'] = Object.assign({}, inv);
      const db = makeDb(seed);
      const updates = { lightsDescription: newLights };
      return new Function('db', 'admin', 'toMillis', 'section', 'updates', 'oldData',
        'oldKey', 'match', 'console',
        ruleSrc + '\nconst LIGHT_CHANGE_FEE = 30;\nconst LIGHT_WINDOW_MS = 48*60*60*1000;\n' +
        'return (async function(){\n' + blockSrc + '\nreturn lightFeeInfo;\n})();')
        (db, fakeAdmin, new Function('return ' + toMillisSrc + ';toMillis')(),
         'lights', updates, cust, inv ? '8015550100' : '', { id: 'c1' }, console)
        .then(function (info) {
          return { info: info, cust: db._docs['jobAddresses/c1'],
                   inv: db._docs['invoices/8015550100'], messages: db._messages };
        });
    };

    pendingAsync.push((async function () {
      /* ---- 1. A returning member changes colours, bill not yet sent ---- */
      const r1 = await runLights(
        { name: 'Returning', lightsDescription: 'Warm White', invoiceEmailSent: false },
        { changeFees: 0, install: 400 }, 'Red, Green');

      check('S117', 'a colour change actually writes the $30 to the invoice',
        (r1.inv || {}).changeFees === 30,
        'this is the bug: the old code set the flag on an object that had already ' +
        'been written, so the fee never reached Firestore at all');
      check('S117', 'and it lands as its own line, naming itself',
        Array.isArray((r1.inv || {}).changeFeeNotes) &&
        r1.inv.changeFeeNotes.length === 1 &&
        r1.inv.changeFeeNotes[0].amount === 30,
        'a $30 movement in a total with no line against it is a support call');
      check('S117', 'and it does NOT set the new-member fee',
        (r1.cust || {}).chargeNewMemberFee === undefined,
        'the two fees are separate now — writing both would charge $60 for one change');
      check('S117', 'and the 48-hour route lock is set on the customer',
        !!(r1.cust || {}).lightsLockedUntil &&
        r1.cust.lightsLockedUntil.__ms > NOWISH + 47 * HOUR,
        'owner: they must not be scheduled while their pattern may still move');
      check('S117', 'and they are marked as a colour change',
        (r1.cust || {}).lightsChangedAt === '__SERVER_TS__',
        'this is what puts them on the Color Changes sheet');
      check('S117', 'and the portal is told the fee hit their current balance',
        r1.info && r1.info.feeCharged === true && r1.info.chargedToNextSeason === false,
        'the note the customer reads has to match the invoice they can open');

      /* ---- 2. The same change, but their invoice has already gone out ---- */
      const r2 = await runLights(
        { name: 'Billed', lightsDescription: 'Warm White', invoiceEmailSent: true },
        { changeFees: 0, install: 400 }, 'Red, Green');

      check('S117', 'once the bill has been sent the $30 goes to NEXT season',
        (r2.cust || {}).carryoverCharge === 30 && (r2.inv || {}).changeFees !== 30,
        'nothing re-opens a sent invoice — invoiceEmailSent is only cleared by Start ' +
        'New Season, so a fee added there would never be posted to anybody');
      check('S117', 'and it is parked on the CUSTOMER, which Start New Season does not wipe',
        Array.isArray((r2.cust || {}).carryoverChargeNotes) &&
        r2.cust.carryoverChargeNotes.length === 1,
        'Start New Season zeroes changeFees and changeFeeNotes on every invoice, so a ' +
        'charge parked there is deleted rather than carried');
      check('S117', 'and the portal says next season, not "added to your balance"',
        r2.info && r2.info.chargedToNextSeason === true,
        'they can open their invoice in thirty seconds and see the total has not moved');

      /* ---- 3. Inside the window: free, and the window does not move ---- */
      const lockAt = ts(NOWISH + 5 * HOUR);
      const r3 = await runLights(
        { name: 'New', lightsDescription: 'Warm White', invoiceEmailSent: false,
          lightsLockedUntil: lockAt },
        { changeFees: 0 }, 'Red, Green');

      check('S117', 'a change inside the 48-hour window is free',
        !((r3.inv || {}).changeFees) && !((r3.cust || {}).carryoverCharge),
        'owner: "we won\'t schedule them within that 48 hours so they can change ' +
        'there lights again if they choose"');
      check('S117', 'and it does not push the window further out',
        (r3.cust || {}).lightsLockedUntil.__ms === NOWISH + 5 * HOUR,
        'a window that renews on every free save never closes, and they are never ' +
        'scheduled at all');

      /* ---- 4. First-time colours: not a change, no fee, no Color Changes row ---- */
      const r4 = await runLights(
        { name: 'Brand New', lightsDescription: '', invoiceEmailSent: false },
        { changeFees: 0 }, 'Warm White');

      check('S117', 'filling colours in for the first time is not charged',
        !((r4.inv || {}).changeFees) && !((r4.cust || {}).carryoverCharge),
        'today\'s code charged them, because it tested only that the value differed');
      check('S117', 'and does not mark them as a colour change',
        (r4.cust || {}).lightsChangedAt === undefined,
        'this is what swept twelve ordinary new customers onto the Color Changes sheet');
      check('S117', 'and does not lock them off the routes',
        (r4.cust || {}).lightsLockedUntil === undefined,
        'they have not changed anything — locking them delays a house for no reason');

      /* ---- 5. Saving the same colours does nothing at all ---- */
      const r5 = await runLights(
        { name: 'Same', lightsDescription: 'Warm White', invoiceEmailSent: false },
        { changeFees: 0 }, 'Warm White');
      check('S117', 'saving the same colours charges nothing and locks nothing',
        !((r5.inv || {}).changeFees) && (r5.cust || {}).lightsLockedUntil === undefined &&
        (r5.cust || {}).lightsChangedAt === undefined,
        'opening the Lights tab and pressing Save must not cost anybody $30');

      /* ---- 6. Already on a route: exactly one System note ---- */
      const r6 = await runLights(
        { name: 'Routed', lightsDescription: 'Warm White', invoiceEmailSent: false,
          scheduled: true },
        { changeFees: 0 }, 'Red, Green');
      check('S117', 'a customer already on a route gets exactly one System note',
        r6.messages.length === 1 && r6.messages[0].folder === 'System' &&
        r6.messages[0].needsReassign === true,
        'the crew is holding a card that no longer matches the house');
      check('S117', 'and is flagged on their own record too',
        (r6.cust || {}).lightsChangedAfterAssign === true,
        'the note is in the inbox; the badge is on the customer, and Routes reads it');
      check('S117', 'while an unrouted customer gets no note at all',
        r1.messages.length === 0,
        'a note per colour change would make the System folder unreadable');

      /* ---- 7. No invoice document at all — still locked ---- */
      const r7 = await runLights(
        { name: 'No Contact', lightsDescription: 'Warm White', invoiceEmailSent: false },
        null, 'Red, Green');
      check('S117', 'a customer with no invoice is still locked off the routes',
        !!(r7.cust || {}).lightsLockedUntil,
        'no phone and no email means nothing to charge — but their pattern is still ' +
        'moving, and the lock is about the crew, not about money');

      /* ---- 8. Joining opens the window — and ONLY joining ----
         Owner: "48 hours will be from when they become a costumer and we won't
         schedule them within that 48 hours so they can change there lights again
         if they choose."

         ⚠ THE SECOND HALF IS THE DANGEROUS ONE. Six places create a jobAddresses
         document. If the bulk importers set this too, importing the existing book
         of ~960 customers locks the ENTIRE season out of the scheduler for two
         days — and it would look like the scheduler being broken, not like a
         flag being set. Counted, so a sixth caller cannot be added quietly. */
      const admin2 = read('admin.html');
      /* ⚠ MATCHED ON THE VALUE, NOT ON ONE SYNTAX. The first version of this counted
         the object-literal form only — `lightsLockedUntil: new Date(...)` — and a
         red-check that added the very thing it guards against, as an assignment
         (`doc2.lightsLockedUntil = new Date(...)`) in the bulk importer, sailed
         straight through it. Anything that opens a FRESH window from the clock is
         counted however it is spelled. The Edit Customer path is deliberately not
         caught: it writes a window the rule already worked out, not a new one. */
      const lockWrites = (admin2.match(/lightsLockedUntil[^\n]*Date\.now\(\)\s*\+\s*LIGHT_WINDOW_MS/g) || []).length;
      check('S117', 'exactly one place opens the window on joining',
        lockWrites === 1,
        'the bulk importers, the sheet sync and the two test builders must never ' +
        'set it — importing the book is not 960 people joining');
      check('S117', 'and it is the Add Customer form, not an importer',
        (function () {
          const at = admin2.indexOf("lightsLockedUntil: new Date(Date.now() + LIGHT_WINDOW_MS)");
          if (at === -1) return false;
          const before = admin2.slice(0, at);
          const form = before.lastIndexOf("document.getElementById('routeAddressForm')");
          const bulk = Math.max(before.lastIndexOf("rbImportBtn"), before.lastIndexOf("ibImportBtn"),
                                before.lastIndexOf("function rbApplyTickedAdds"),
                                before.lastIndexOf("function buildTestPerson"));
          return form > bulk;
        })(),
        'a test record that cannot be routed cannot be used to test routing');

      /* ---- 9. A fee never lands in both places at once ---- */
      check('S117', 'a fee is charged in exactly one place, never both',
        ((r1.inv || {}).changeFees === 30 && (r1.cust || {}).carryoverCharge === undefined) &&
        ((r2.cust || {}).carryoverCharge === 30 && !((r2.inv || {}).changeFees)),
        'billing the invoice AND next season for one change is $60 for a $30 fee');
    })());
  }
}

/*
 * Suite 120. A day is a cluster, not the top of a list.
 *
 * Owner, 2026-08-21: "in the schedule we want to try to organize it so in a
 * city and neighboring cities it picks houses for a day that are closer to each
 * other rather than miles apart although theyre technically in the same city."
 *
 * ⚠ THIS IS THE HALF NO AMOUNT OF RE-ORDERING CAN FIX. Suite 77 proves the
 * houses ON a day come back in driving order. That is only ever as good as the
 * SET of houses the day was given: twenty picked at random across a nine-mile
 * town have no short route, however well they are sorted afterwards. The pick
 * is what this suite guards.
 *
 * ⚠ AND IT MUST NOT HAVE BOUGHT THAT BY BREAKING HER ORDERING RULES. Distance
 * is the LAST word, never the first — October still empties before November is
 * touched. Both halves are checked below, because a version that clusters
 * beautifully and sends October houses out in December is worse than no change
 * at all.
 */
suite('120. A day is a cluster, not the top of a list');
{
  const start = admin.indexOf('function planNewCrewDays(waiting, taken, opts)');
  const end = admin.indexOf('/* Top every day up to the cap.', start);
  if (start === -1 || end < start) {
    check('S120', 'the day builder is findable', false,
      'renamed or removed — update this test rather than deleting it');
  } else {
    const LF_ = String.fromCharCode(10);
    global.toDateStr = dt => dt.getFullYear() + '-' +
      String(dt.getMonth() + 1).padStart(2, '0') + '-' + String(dt.getDate()).padStart(2, '0');
    const consts = admin.slice(admin.indexOf('const MAX_STOPS_PER_ROUTE'),
                               admin.indexOf('function installPriority'));
    const prelude = ['const NEARBY_TOWN_LIST = {};',
      extractFn(admin, 'haversine'), extractFn(admin, 'sameTownName'),
      extractFn(admin, 'townCentres'), extractFn(admin, 'nearbyTowns'),
      extractFn(admin, 'extractCleanCity'), extractFn(admin, 'thanksgivingDate')].join(LF_) + LF_;
    const api = eval(prelude + consts + LF_ + extractFn(admin, 'installPriority') + LF_ +
      admin.slice(start, end) + LF_ + ';({plan: planNewCrewDays, cap: MAX_STOPS_PER_ROUTE})');

    /* ⚠ THE TWO ENDS OF TOWN INTERLEAVE IN THE QUEUE, which is the whole point of
       the fixture. Clumped in the queue, "take the front twenty" gives a tidy day
       by accident and this suite passes whether the clustering exists or not.
       Interleaved, the old builder takes ten from each end — which is exactly the
       seven-mile day the owner was looking at. */
    const town = (n, latBase, tag) => {
      const out = [];
      for (let i = 0; i < n; i++) out.push({ id: tag + i, city: 'Provo', priority: 5,
        named: false, from: '2026-10-01', until: '',
        stop: { lat: latBase + i * 0.001, lng: -111.66 } });
      return out;
    };
    const interleave = (a, b) => a.flatMap((x, i) => [x, b[i]]);
    const spreadOf = (ids, pool) => {
      const lats = ids.map(id => pool.find(w => w.id === id).stop.lat);
      return (Math.max.apply(null, lats) - Math.min.apply(null, lats)) * 69;
    };

    const north = town(20, 40.30, 'N'), south = town(20, 40.20, 'S');
    const pool = interleave(north, south);
    const days = api.plan(pool.slice(), {}, { floorDate: '2026-10-01', maxDays: 10,
      horizonDays: 60, pack: false });

    check('S120', 'a town split across two ends gives one END a day, not a slice of both',
      days.length >= 2 && days[0].ids.every(id => id[0] === days[0].ids[0][0]),
      'got [' + (days[0] ? days[0].ids.join() : 'no day') + '] — ten from each end is the ' +
        'seven-mile day this exists to stop');
    check('S120', 'and the day it builds is a few miles across, not the whole town',
      days.length && spreadOf(days[0].ids, pool) < 3,
      'got ' + (days.length ? spreadOf(days[0].ids, pool).toFixed(1) : '?') + ' mi across');
    check('S120', 'the other end is not stranded — it gets the next day',
      days.length >= 2 && days[1].ids.length === 20 &&
        days[1].ids.every(id => id[0] !== days[0].ids[0][0]),
      'clustering must not cost anybody their place in the season');
    check('S120', 'and nobody is lost or scheduled twice on the way',
      (function () {
        const seen = days.flatMap(d => d.ids);
        return seen.length === new Set(seen).size && seen.length === 40;
      })(),
      'the pick splices out of a live queue — a mis-ordered splice removes the wrong houses');

    /* ⭐ THE RULE THAT OUTRANKS DISTANCE. One October house at the FAR end of town
       from where the clustering wants to be: it must still go out on day one.
       Owner, 2026-08-18: "we need to get everyone who requested Oct done in Oct". */
    const urgent = { id: 'OCT', city: 'Provo', priority: 1, named: false,
      from: '2026-10-01', until: '', stop: { lat: 40.20, lng: -111.66 } };
    const mixed = [urgent].concat(town(30, 40.30, 'N'));
    const d2 = api.plan(mixed.slice(), {}, { floorDate: '2026-10-01', maxDays: 10,
      horizonDays: 60, pack: false });
    check('S120', 'a more urgent house is never left behind for being far away',
      d2.length && d2[0].ids.indexOf('OCT') > -1,
      'distance is the tiebreak INSIDE a priority tier, never a way out of one');

    /* A named day still leads its tier — "try to do their house the next possible
       chance after that" (2026-08-20) — and clustering may not quietly undo it. */
    const named = { id: 'NAMED', city: 'Provo', priority: 5, named: true,
      from: '2026-10-01', until: '', stop: { lat: 40.20, lng: -111.66 } };
    const d3 = api.plan([named].concat(town(30, 40.30, 'N')), {},
      { floorDate: '2026-10-01', maxDays: 10, horizonDays: 60, pack: false });
    check('S120', 'somebody who named a day still leads their tier',
      d3.length && d3[0].ids.indexOf('NAMED') > -1,
      'they asked for that day; a shorter drive is not a reason to move them');

    /* A house with no map pin cannot be clustered. It must still get a day, and
       it must not drag the pinned ones out of their cluster on the way. */
    const bare = { id: 'NOPIN', city: 'Provo', priority: 5, named: false,
      from: '2026-10-01', until: '', stop: { lat: null, lng: null } };
    const withBare = [bare].concat(interleave(town(20, 40.30, 'N'), town(20, 40.20, 'S')));
    const d4 = api.plan(withBare.slice(), {}, { floorDate: '2026-10-01', maxDays: 10,
      horizonDays: 60, pack: false });
    const allIds = d4.flatMap(d => d.ids);
    check('S120', 'a house with no map pin is still scheduled', allIds.indexOf('NOPIN') > -1,
      'the bulk import creates these on purpose — it cannot be a reason to skip somebody');
    check('S120', 'and it does not scatter the day it lands on',
      d4.length && (function () {
        const pinned = d4[0].ids.filter(id => id !== 'NOPIN');
        return pinned.length > 1 && spreadOf(pinned, withBare) < 3;
      })(),
      'an un-clusterable house must be carried, not routed against');
  }
}

/*
 * Suite 121. A Utah address is already a map reference.
 *
 * Owner, 2026-08-21: "try to use math for the ones without geocode by checking
 * their street address, if their street address isnt a word then its a number
 * and if its a number in utah that is a location so you can find it that way",
 * and "any that you just dont know where a house is still because its a word
 * not a number or something put all them at the end of whatever route they end
 * up in".
 *
 * Measured on the real book of 960 addresses: 350 carry both grid numbers, 458
 * carry one, 152 carry none. So this is not a corner case — it is a third of
 * the book placed exactly and another half placed roughly.
 *
 * ⚠ THE DANGEROUS DIRECTION IS A CONFIDENT WRONG ANSWER, not a missing one. A
 * house left unplaced goes to the end of its route where somebody sees it; a
 * house placed two miles out is silently driven past. So most of what is
 * checked below is the REFUSALS.
 */
suite('121. A Utah address is already a map reference');
{
  const gridStart = admin.indexOf('function utahGridOf(address)');
  const gridEnd = admin.indexOf('/* Towns the office has said are close enough', gridStart);
  if (gridStart === -1 || gridEnd < gridStart) {
    check('S121', 'the address maths is findable', false,
      'renamed or removed — update this test rather than deleting it');
  } else {
    const LF_ = String.fromCharCode(10);
    const api = eval(extractFn(admin, 'haversine') + LF_ + admin.slice(gridStart, gridEnd) +
      LF_ + ';({grid: utahGridOf, street: streetNameKey, fit: fitTownGrid,' +
      '   MINPTS: GRID_MIN_POINTS, MAXERR: GRID_MAX_MEDIAN_ERR, hav: haversine})');

    /* ---- reading the address ---- */
    const g1 = api.grid('11528 S 840 W');
    check('S121', 'both numbers are read, with south and west going negative',
      g1 && g1.north === -11528 && g1.east === -840,
      'got ' + JSON.stringify(g1));
    const g2 = api.grid('247 W 1080 N');
    check('S121', 'and it does not care which axis is written first',
      g2 && g2.east === -247 && g2.north === 1080,
      'got ' + JSON.stringify(g2) + ' — the book writes it both ways round');
    const g3 = api.grid('1093 E Ranchero Dr');
    check('S121', 'a named street still gives up the one number it carries',
      g3 && g3.east === 1093 && g3.north === null,
      'that is a line, and a line is worth far more than nothing — got ' + JSON.stringify(g3));
    check('S121', 'a street with no number at all reads as nothing',
      api.grid('8387 Etienne Way') === null,
      'inventing a position for one of these is the mistake this whole suite guards');
    check('S121', 'and so does a blank',
      api.grid('') === null && api.grid(null) === null);

    /* ⚠ THE FIRST VALUE ON AN AXIS WINS. A unit number further along the line
       must not overwrite the street the house is actually on. */
    const g4 = api.grid('247 W 1080 N Apt 4 W');
    check('S121', 'a unit number later in the line cannot overwrite the street',
      g4 && g4.east === -247 && g4.north === 1080,
      'got ' + JSON.stringify(g4));

    /* ---- the street name, for borrowing the missing half ---- */
    check('S121', 'street names are normalised so Drive and Dr are one street',
      api.street('2387 Willow Hills Drive') === api.street('1450 N Willow Hills Dr') &&
      api.street('2387 Willow Hills Drive') === 'willow hills dr',
      'got "' + api.street('2387 Willow Hills Drive') + '" and "' +
        api.street('1450 N Willow Hills Dr') + '"');
    check('S121', 'a numbered street is not treated as a name',
      api.street('11528 S 840 W') === '',
      'the grid already reads those properly; naming them would group unrelated houses');

    /* ---- learning a town's grid ---- */
    /* Built from a REAL Utah grid — Lehi, Main & Center, about an eighth of a
       mile per hundred address units — with 40 ft of noise on every house so the
       fit is never handed a perfect answer. A QUARTER of them are held back and
       the fit never sees them. */
    const ORIGIN = { lat: 40.3916, lng: -111.8508 }, PER_UNIT_MI = 0.125 / 100;
    const truth = (e, n, seed) => ({
      lat: ORIGIN.lat + n * PER_UNIT_MI / 69 + ((seed * 37) % 11 - 5) * 0.00011,
      lng: ORIGIN.lng + e * PER_UNIT_MI / (69 * Math.cos(ORIGIN.lat * Math.PI / 180)) +
           ((seed * 53) % 11 - 5) * 0.00014 });
    const known = [], held = [];
    let seed = 0;
    for (let n = -1200; n <= 1200; n += 200) {
      for (let e = -1200; e <= 1200; e += 400) {
        seed++;
        const p = truth(e, n, seed);
        (seed % 4 === 0 ? held : known).push({ east: e, north: n, lat: p.lat, lng: p.lng });
      }
    }
    const fit = api.fit(known);
    check('S121', 'a town on a grid is learned from the houses already pinned',
      fit.ok === true, fit.why || '');
    const errs = held.map(p => api.hav(p.lat, p.lng,
      fit.latOf(p.east, p.north), fit.lngOf(p.east, p.north))).sort((a, b) => a - b);
    const median = errs[Math.floor(errs.length / 2)];
    /* 1/10 mile is 528 ft, about two houses. Well inside anything that changes
       a driving order, and this fixture actually lands near 170 ft. */
    check('S121', 'and it places houses it has never seen to within a tenth of a mile',
      median < 0.1,
      'median ' + (median * 5280).toFixed(0) + ' ft on ' + held.length + ' held-out houses');

    /* ---- and now the refusals, which are the point ---- */
    const scrambled = known.map((p, i) => ({ east: p.east, north: p.north,
      lat: ORIGIN.lat + ((i * 17) % 40) * 0.002, lng: ORIGIN.lng + ((i * 29) % 40) * 0.002 }));
    check('S121', 'a town whose addresses are NOT a grid is refused outright',
      api.fit(scrambled).ok === false,
      'this is the one that matters: a confident wrong position is driven past in silence');
    check('S121', 'a town with only a few known houses is refused',
      api.fit(known.slice(0, api.MINPTS - 1)).ok === false,
      'four houses can be fitted perfectly by a grid that is nonsense');
    check('S121', 'and every known house sitting on one street is refused',
      api.fit([0, 1, 2, 3, 4, 5, 6].map(i => ({ east: 500, north: i * 100,
        lat: ORIGIN.lat + i * 0.001, lng: ORIGIN.lng }))).ok === false,
      'there is no unique grid through a single line, so the cross-axis is a guess');
    check('S121', 'the refusal threshold is a quarter of a mile, and is not loosened quietly',
      api.MAXERR === 0.25 && api.MINPTS === 6,
      'these two numbers are the whole safety argument');
  }

  /* ---- wired into the things that actually order a day ---- */
  {
    const sp = sectionFrom(admin, admin.indexOf('function houseGeoPoint(h, d)'));
    check('S121', 'a real pin always beats a calculated one',
      sp.indexOf("typeof rec.lat === 'number'") < sp.indexOf('estimatedPinFromAddress'),
      'an estimate overwriting a surveyed position is a straight downgrade');
    check('S121', 'and an estimate is never written back to the customer',
      !/updateDoc|setDoc/.test(sp),
      'the record still says the house has not been geocoded, because it has not');
    /* ⚠ sectionFrom, NOT a character window. The suite has its own rule against
       fixed-length extraction windows and it is right: rebuildSeasonDays is long
       enough that a 6000-character window already missed the line below. */
    const rb = sectionFrom(admin, admin.indexOf('function rebuildSeasonDays()'));
    check('S121', 'the day builder clusters on the same answer',
      /stop:\(typeof houseGeoPoint==='function'/.test(rb),
      'without this a house is not merely last in the order — it lands on the wrong day');
    const ga = sectionFrom(admin, admin.indexOf('function generateAllRoutes()'));
    check('S121', 'the grids are relearned at the start of a run, not cached',
      /if\(typeof refreshTownGrids==='function'\) refreshTownGrids\(\);/.test(ga),
      'a grid learned an hour ago places houses from a book that has moved');
    const rt = sectionFrom(admin, admin.indexOf('function refreshTownGrids()'));
    check('S121', 'only a really-pinned house ever teaches the grid',
      /!isFinite\(d\.lat\) \|\| !isFinite\(d\.lng\)\) return;/.test(rt),
      'feeding estimates back in lets one bad guess drag every later one after it');
  }
}

/*
 * Suite 122. Out of the yard and back to it, and a picture of what that looks like.
 *
 * Owner, 2026-08-21: "also calculate the route knowing the starting spot is
 * always 209 S 850 W and the ending spot is alway 209 S 850 W as well", and
 * "at the bottom you should be able to see a picture of the route, or both
 * routes if theres two".
 */
suite('122. Out of the yard and back, and a picture of it');
{
  const LF_ = String.fromCharCode(10);
  const havStart = admin.indexOf('function haversine(lat1, lng1, lat2, lng2)');
  const havEnd = admin.indexOf(LF_ + '}', havStart) + 2;
  const geoStart = admin.indexOf('function twoOptImprove(');
  const geoEnd = admin.indexOf('function nearestNeighborOrder(', geoStart);
  if (geoStart === -1 || geoEnd < geoStart) {
    check('S122', 'the route orderer is findable', false, 'renamed — update this test');
  } else {
    const api = eval(admin.slice(havStart, havEnd) + LF_ + admin.slice(geoStart, geoEnd) +
      LF_ + ';({reorder: reorderFlatStops, hav: haversine})');
    const HOME = { lat: 40.3866, lng: -111.8616 };
    const stops = [];
    for (let i = 0; i < 20; i++) {
      stops.push({ id: 'h' + i, lat: 40.40 + ((i * 7) % 20) * 0.004,
                   lng: -111.87 + ((i * 11) % 20) * 0.004 });
    }
    const trip = list => {
      let m = api.hav(HOME.lat, HOME.lng, list[0].lat, list[0].lng);
      for (let i = 1; i < list.length; i++) m += api.hav(list[i-1].lat, list[i-1].lng, list[i].lat, list[i].lng);
      return m + api.hav(list[list.length-1].lat, list[list.length-1].lng, HOME.lat, HOME.lng);
    };
    const open = api.reorder(stops.slice(), null);
    const anchored = api.reorder(stops.slice(), HOME, HOME);
    check('S122', 'anchoring the day at the yard shortens the real round trip',
      trip(anchored) < trip(open),
      'got ' + trip(anchored).toFixed(1) + ' mi against ' + trip(open).toFixed(1) + ' mi');
    /* ⚠ THE END IS THE HALF THAT WAS MISSING. A start point alone was already
       possible; what nothing counted was the drive home, which is why days
       finished on the far side of town. */
    check('S122', 'and the day no longer finishes on the far side of town',
      api.hav(HOME.lat, HOME.lng, anchored[anchored.length-1].lat, anchored[anchored.length-1].lng) <
      api.hav(HOME.lat, HOME.lng, open[open.length-1].lat, open[open.length-1].lng),
      'the last leg of the day is a real drive and has to be paid for');
    check('S122', 'nothing is dropped by anchoring it',
      anchored.length === 20 && stops.every(s => anchored.indexOf(s) > -1));
    /* An optional argument must stay optional: every other caller passes two. */
    check('S122', 'a caller that names no finish gets exactly what it got before',
      JSON.stringify(api.reorder(stops.slice(), null).map(s => s.id)) ===
      JSON.stringify(open.map(s => s.id)),
      'twoOptImprove gained a third argument; the old two-argument behaviour must not move');
  }

  const home = sectionFrom(admin, admin.indexOf('function routeHomePoint()'));
  check('S122', 'the yard is 209 S 850 W, Lehi',
    /ROUTE_HOME_ADDRESS = '209 S 850 W'/.test(admin) && /ROUTE_HOME_CITY = 'Lehi'/.test(admin));
  check('S122', 'and it is found by ADDRESS, so nobody has to paste in a latitude',
    /estimatedPinFromAddress\(ROUTE_HOME_ADDRESS, ROUTE_HOME_CITY\)/.test(home),
    '209 S 850 W is itself a full grid reference — the town grid places it');
  check('S122', 'a real customer record at the yard still wins over the estimate',
    home.indexOf('custByAddrKey') < home.indexOf('estimatedPinFromAddress'),
    'same rule as everywhere else: measured beats calculated');
  const ord = sectionFrom(admin, admin.indexOf('function orderHousesForDriving(list)'));
  /* ⚠ THE YARD IS BOTH ENDS ON BOTH PATHS. Since Suite 124 the day may be
     ordered in two passes when somebody lives out on their own, and the SECOND
     pass is the one that has to finish at the yard — checking only the simple
     path would go green while every day with an outlier ended in the wrong place. */
  check('S122', 'every crew route is ordered yard-to-yard',
    /reorderFlatStops\(points, home, home\)/.test(ord),
    'both legs, or the day still ends wherever the last cluster happened to be');
  check('S122', 'and the far-houses pass finishes at the yard too',
    /reorderFlatStops\(split\.out,[\s\S]{0,120}home\);/.test(ord),
    'owner: "still remembering 209 s 850 w is the end point"');

  /* ---- the picture ---- */
  const pic = sectionFrom(admin, admin.indexOf('function routePictureHTML(day)'));
  check('S122', 'the picture is drawn, not fetched',
    !/google|maps\.|iframe|<img/i.test(pic) && /<svg/.test(pic),
    'a live map costs money per load, needs a key, and does not print');
  check('S122', 'longitude is squeezed by cos(lat) so the shape is honest',
    /Math\.cos\(/.test(pic),
    'without it a tidy day is drawn as a sprawling one and the picture misleads');
  check('S122', 'a house with no position is left OUT and counted, never drawn',
    /if\(!ok\)\{ missing\+\+; return; \}/.test(pic) && /not shown/.test(pic),
    'a dot in an invented place is a lie you cannot see through');
  check('S122', 'a calculated position is drawn differently from a measured one',
    /p\.est \?/.test(pic) && /stroke-dasharray/.test(pic),
    'the office should be able to see which pins are estimates');
  check('S122', 'the route drawn starts and ends at the yard',
    /home \? \[n1\(X\(home\.lng\)\)/.test(pic),
    'the two legs a stop list never shows are exactly the ones worth drawing');
  const panel = sectionFrom(admin, admin.indexOf('function renderPanelInto(elId,day)'));
  /* ⭐ THE DRAWING IS NOW THE FALLBACK, NOT THE FEATURE (2026-08-21). Owner:
     "the picture at the bottom isnt really what I want ... it should be a google
     maps thing that you can click on and move". It is kept, and checked above,
     because a blank rectangle when the Maps script fails to load is worse than
     a drawing — but what the office sees normally is a live map. */
  check('S122', 'the drawing is only reached when Google Maps is not',
    /if\(typeof google === 'undefined' \|\| !google\.maps \|\| !google\.maps\.Map\)/
      .test(sectionFrom(admin, admin.indexOf('function renderDayMaps(day)'))),
    'offline, or a key problem, must still show something');
  check('S122', 'and the maps are mounted after the panel is written',
    panel.indexOf('renderDayMaps(') > panel.indexOf('el.innerHTML=h'),
    'owner: "at the bottom you should be able to see a picture of the route"');
  check('S122', 'a map that throws cannot take the day panel down with it',
    /catch\(err\)\{ console\.error\('Route maps failed:'/.test(panel),
    'the stops matter more than the drawing of them');
  /* ---- the live maps ---- */
  {
    const maps = sectionFrom(admin, admin.indexOf('function renderDayMaps(day)'));
    const pane = sectionFrom(admin, admin.indexOf('function dayMapPaneAt(wrap, i)'));
    const doc = sectionFrom(admin, admin.indexOf('function dayMapDraw(pane, route, home)'));
    const routes = sectionFrom(admin, admin.indexOf('function dayMapRoutes(day)'));

    check('S122', 'one map per crew route, drawn from the same grouping as the list',
      /dayRouteGroups\(day\)\.forEach/.test(routes) && /routes\.forEach\(function\(r, i\)/.test(maps),
      'owner: "there is two different maps for each crew, unless its a one crew day"');
    /* ⚠ THE ONE-CREW RULE IS NOT WRITTEN DOWN ANYWHERE, and that is deliberate:
       dayRouteGroups already returns a single group for a one-crew day, so the
       maps inherit it. A second copy of that rule here is a second thing to keep
       in step with soloCrew. */
    check('S122', 'and a one-crew day gets one map without a rule of its own',
      !/soloCrew|oneCrew/.test(maps) && /routes\.length > 1 \?/.test(maps),
      'the grouping already answers this; restating it is how the two drift apart');

    /* ⚠ NO IFRAME. See Suite 123 — a srcdoc frame is `about:srcdoc`, which fails
       the Maps key's referrer check, and that is exactly what the owner hit. */
    check('S122', 'a map pane is a plain div in the ordinary document',
      /createElement\('div'\)/.test(pane) && !/iframe|srcdoc/.test(pane),
      'the Routes tab map works this way and has done for months');
    check('S122', 'and it uses the page’s own Maps script, not a second load of it',
      !/maps\.googleapis\.com/.test(pane) && !/maps\.googleapis\.com/.test(maps),
      'a second script tag is a second map load to pay for');

    /* ⚠ THE EXPENSIVE MISTAKE. renderPanelInto rebuilds its innerHTML on every
       render, and re-parenting an iframe reloads it in every browser. Maps are
       billed per load, and a reload also throws away wherever the office had
       panned to. Both are avoided by keeping the maps out of that innerHTML. */
    check('S122', 'the maps are NOT inside the html the panel rebuilds',
      /<div id="scheduleMaps"/.test(admin) && !/h\+=.*renderDayMaps/.test(panel),
      'a map that reloads on every tick costs money and loses where you had panned to');
    check('S122', 'a pane is built once and then reused',
      /if\(dayMapPanes\[i\]\) return dayMapPanes\[i\];/.test(pane),
      'switching day must not rebuild a single map');
    check('S122', 'a route this day does not have is hidden, not destroyed',
      /box\.style\.display = 'none'/.test(maps),
      'the map inside is worth keeping for the next day that needs it');

    check('S122', 'the view is only re-framed when the route itself changed',
      /if\(key !== pane\.key\)\{ pane\.key = key; pane\.map\.fitBounds/.test(doc),
      'ticking a house off would otherwise yank the map back from wherever the ' +
      'office had just panned to');

    check('S122', 'a house with no position is never given an invented pin',
      /if\(!ok\)\{ missing\+\+; return; \}/.test(routes) && /not on the map/.test(maps),
      'it is counted in the heading instead, where it reads as the gap it is');
    check('S122', 'a calculated position still looks different from a measured one',
      /fillOpacity: s\.est \? 0\.55 : 1/.test(doc),
      'the office should be able to see which pins are estimates');
    check('S122', 'the map draws the drive out of the yard and the drive home',
      /if\(home\) path\.push\(home\);/.test(doc) && /routeHomePoint/.test(maps),
      'those two legs are the ones a stop list never shows');
    check('S122', 'searching clears the maps rather than leaving yesterday’s up',
      /renderDayMaps\(null\)/.test(admin),
      'a map under a search result is about a day the office is no longer looking at');
    /* A tab with no day panel never calls renderPanelInto, so nothing would take
       the last day's maps down underneath it. */
    check('S122', 'and so do the tabs that have no day at all',
      /renderOneMan\(\);renderDayMaps\(null\)/.test(admin) &&
      /renderPrinting\(\);renderDayMaps\(null\)/.test(admin),
      'One Man Installs and Printing would otherwise sit under yesterday’s route');
  }
  check('S122', 'the list and the picture read ONE grouping',
    /dayRouteGroups\(day\)\.forEach/.test(panel) && /dayRouteGroups\(day\)/.test(pic),
    'a picture showing route two beside a list headed route one is worse than no picture');
}

/*
 * Suite 123. The two crew maps, actually rendered.
 *
 * Owner, 2026-08-21: "there is two different maps for each crew, unless its a one
 * crew day", then, on the first version shipped: "it says it didnt load google
 * maps correctly".
 *
 * ⚠ WHY THAT HAPPENED, because it is the trap this suite exists to keep shut.
 * The first version put each map in an <iframe srcdoc> to dodge the shadow DOM.
 * A srcdoc frame's document URL is `about:srcdoc`, so the Maps key's HTTP-referrer
 * check has nothing to match and Google refuses to load. Every check in the
 * previous version of this suite passed, because jsdom neither loads the frame
 * nor validates a referrer — the suite could not see the only thing that was
 * wrong. It is checked here as a source rule instead: no iframe, in the ordinary
 * document, exactly like the Routes tab map that demonstrably works.
 *
 * ⚠ AND IT STILL RUNS THE RENDERER. Google's classes are faked below, so the
 * checks are about what gets DRAWN — how many maps, how many markers, whether the
 * line goes home — not about what the source says.
 */
suite('123. The two crew maps, actually rendered');
{
  const noFrame = sectionFrom(admin, admin.indexOf('function dayMapPaneAt(wrap, i)'));
  check('S123', 'a map is a plain div in the ordinary page, never an iframe',
    !/iframe|srcdoc/.test(noFrame) && /createElement\('div'\)/.test(noFrame),
    'a srcdoc frame is about:srcdoc, which fails the key\'s referrer check — ' +
    'this is the bug the owner reported and it must not come back');
  check('S123', 'and the container lives outside the shadow widget',
    /<div id="scheduleMaps"/.test(admin) &&
    admin.indexOf('<div id="scheduleMaps"') > admin.indexOf('<div id="scheduleHost">'),
    'inside the shadow root the Maps stylesheet in document.head cannot reach it');

  if (!JSDOM) {
    note('jsdom not installed — skipping the crew-map render tests');
  } else {
    const mapStart = admin.indexOf('function dayRouteGroups(day)');
    const mapEnd = admin.indexOf('function renderPanelInto(elId,day)', mapStart);
    const crewStart = admin.indexOf('function cityOf(h)');
    const crewEnd = admin.indexOf('/* ---------- build from imported rows', crewStart);
    if (mapStart === -1 || mapEnd < mapStart) {
      check('S123', 'the crew maps are findable', false,
        'renamed or removed — update this test rather than deleting it');
    } else {
      const LF_ = String.fromCharCode(10);
      const dom = new JSDOM('<!doctype html><body><div id="scheduleMaps"></div></body>');
      const savedDoc = global.document, savedWin = global.window;
      global.window = dom.window;
      global.document = dom.window.document;

      /* A stand-in for Google's classes. Records what was asked for, so the
         checks below are about the map that gets built rather than the code. */
      const built = [];
      function FakeMap(el, opts){ this.el = el; this.opts = opts; this.fits = 0; built.push(this); }
      FakeMap.prototype.fitBounds = function(){ this.fits++; };
      function FakeMarker(o){ this.o = o; this.map = o.map; }
      FakeMarker.prototype.setMap = function(m){ this.map = m; };
      function FakeLine(o){ this.o = o; }
      FakeLine.prototype.setMap = function(m){ this.map = m; };
      function FakeBounds(){ this.pts = []; }
      FakeBounds.prototype.extend = function(p){ this.pts.push(p); };
      global.google = { maps: { Map: FakeMap, Marker: FakeMarker, Polyline: FakeLine,
        LatLngBounds: FakeBounds, SymbolPath: { CIRCLE: 0 } } };

      global.esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c =>
        ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
      global.dayDate = d => d._date;
      global.isoOf = () => '2026-11-03';
      global.dlabel = () => ({ wd: 'Mon', full: 'Nov 3' });
      global.customerForHouse = h => (h && h._cust) ? { data: h._cust } : null;
      global.estimatedPinFromAddress = () => null;

      const api = eval(extractFn(admin, 'haversine') + LF_ + admin.slice(crewStart, crewEnd) +
        LF_ + admin.slice(mapStart, mapEnd) + LF_ +
        ';({maps: renderDayMaps, routes: dayMapRoutes, panes: dayMapPanes,' +
        '  setCrews(l){ CREWS = normalizeCrews(l); }})');
      api.setCrews([{ name: 'Dad + Ty', city: '' }, { name: 'Crew 2', city: '' }]);

      const mk = (name, city, lat, lng) => ({ name, city, _cust: { lat, lng } });
      const twoCrew = { id: 'd', _date: new Date(2026, 10, 3), houses: [] };
      for (let i = 0; i < 10; i++) {
        twoCrew.houses.push(mk('Lehi ' + i, 'Lehi', 40.38 + i * 0.004, -111.86 + i * 0.003));
        twoCrew.houses.push(mk('Alpine ' + i, 'Alpine', 40.46 + i * 0.003, -111.78 + i * 0.003));
      }
      const wrap = dom.window.document.getElementById('scheduleMaps');
      const boxes = () => Array.from(wrap.querySelectorAll('.daymappane'));
      const visible = () => boxes().filter(b => b.style.display !== 'none');

      api.maps(twoCrew);
      check('S123', 'a two-crew day really does build two maps',
        built.length === 2 && visible().length === 2,
        'built ' + built.length + ', showing ' + visible().length);
      check('S123', 'each map gets its own crew’s stops and nobody else’s',
        api.panes[0].markers.length === 10 && api.panes[1].markers.length === 10,
        'got ' + api.panes.map(p => p.markers.length).join(' and ') +
        ' — no yard in this fixture, so ten each');
      check('S123', 'the pins are numbered from 1 for each crew',
        api.panes[0].markers[0].o.label.text === '1' &&
        api.panes[1].markers[0].o.label.text === '1',
        'a crew reads their own numbering, not their block of somebody else\'s');
      check('S123', 'each route is drawn as a line',
        !!api.panes[0].line && api.panes[0].line.o.path.length === 10);
      check('S123', 'the headings name each crew',
        /Route 1 . Dad \+ Ty/.test(boxes()[0].innerHTML) &&
        /Route 2 . Crew 2/.test(boxes()[1].innerHTML),
        boxes().map(b => b.textContent).join(' | '));

      /* ⚠ THE EXPENSIVE ONE. renderPanelInto redraws on every tick of a checkbox.
         Rebuilding the Map object is billed per load; re-fitting the bounds throws
         away wherever the office had just panned to. Neither may happen. */
      const fitsBefore = built.map(m => m.fits);
      api.maps(twoCrew);
      check('S123', 'a redraw does NOT build another map',
        built.length === 2,
        'got ' + built.length + ' — a map rebuilt on every checkbox is billed every time');
      check('S123', 'and does not yank the view back when nothing moved',
        built.map(m => m.fits).join() === fitsBefore.join(),
        're-fitting the bounds throws away wherever the office had panned to');

      /* But a route that really changed must re-frame. */
      twoCrew.houses.push(mk('Lehi far', 'Lehi', 40.55, -111.95));
      api.maps(twoCrew);
      check('S123', 'a route that really changed does re-frame',
        built[0].fits > fitsBefore[0],
        'a new stop off the edge would otherwise never come into view');

      const oneCrew = { id: 'e', _date: new Date(2026, 10, 4),
        houses: twoCrew.houses.filter(h => h.city === 'Lehi') };
      api.maps(oneCrew);
      check('S123', 'a one-crew day shows ONE map',
        visible().length === 1, 'got ' + visible().length);
      check('S123', 'and the spare pane is hidden, not destroyed',
        boxes().length === 2 && built.length === 2,
        'the map inside is worth keeping for the next day that needs it');

      const withBare = { id: 'f', _date: new Date(2026, 10, 5),
        houses: oneCrew.houses.concat([{ name: 'Etienne Way', city: 'Lehi' }]) };
      api.maps(withBare);
      const r = api.routes(withBare);
      check('S123', 'a house with no position is left off, not pinned somewhere invented',
        r[0].missing === 1 && r[0].stops.length === oneCrew.houses.length,
        'stops=' + r[0].stops.length + ' missing=' + r[0].missing);
      check('S123', 'and the heading owns up to it',
        /1 not on the map/.test(visible()[0].innerHTML),
        visible()[0].textContent);

      api.maps(null);
      check('S123', 'no day means the whole block goes away',
        wrap.style.display === 'none',
        'an empty map under an empty panel is a loading spinner forever');

      /* And with no Google at all, the drawing rather than a blank rectangle. */
      const savedGoogle = global.google;
      delete global.google;
      api.panes.length = 0;
      wrap.innerHTML = '';
      api.maps(twoCrew);
      check('S123', 'no Google Maps means the drawing, never an empty box',
        /<svg/.test(wrap.innerHTML),
        'this is what the owner would see if the key ever stopped working');
      global.google = savedGoogle;

      delete global.google;
      global.document = savedDoc;
      global.window = savedWin;
    }
  }
}

/*
 * Suite 124. The house out on its own goes last, on the way home.
 *
 * Owner, 2026-08-21: "if there are people that are a little furthur out than
 * everyone else than they fall at the end of the route while still remembering
 * 209 s 850 w is the end point ... we dont want a long drive in the middle of
 * the day we would rather that be at the end of the day on their way back home."
 *
 * ⚠ THIS IS DELIBERATELY NOT THE SHORTEST ROUTE. The orderer minimises total
 * miles and is perfectly happy to nip out to the far house at eleven in the
 * morning and come back into the cluster afterwards — same mileage, much worse
 * day. Measured on the fixture below: the far house moves from stop 10 of 17 to
 * last, the worst mid-day leg falls from 5.6 to 0.3 miles, and the whole day
 * costs 1.1 miles more. That trade is the feature, so a check that only asserted
 * "the route got shorter" would be asserting the opposite of what was asked for.
 *
 * ⚠ AND IT MUST REFUSE far more often than it fires. "Further out than everyone
 * else" needs an everyone else; a day that is simply spread out has no outlier
 * and splitting it would invent a two-part route out of one ordinary one. Most
 * of what is checked below is the refusals.
 */
suite('124. The house out on its own goes last, on the way home');
{
  const crewStart = admin.indexOf('function cityOf(h)');
  const crewEnd = admin.indexOf('/* ---------- build from imported rows', crewStart);
  const geoStart = admin.indexOf('function twoOptImprove(');
  const geoEnd = admin.indexOf('function nearestNeighborOrder(', geoStart);
  if (crewStart === -1 || crewEnd < crewStart || geoStart === -1) {
    check('S124', 'the route orderer is findable', false,
      'renamed or removed — update this test rather than deleting it');
  } else {
    const LF_ = String.fromCharCode(10);
    const HOME = { lat: 40.3866, lng: -111.8616 };        // 209 S 850 W, Lehi
    global.dayDate = d => d._date;
    global.isoOf = () => '2026-11-03';
    global.dlabel = () => ({ wd: 'Mon', full: 'Nov 3' });
    global.esc = s => String(s == null ? '' : s);
    global.customerForHouse = h => (h && h._cust) ? { data: h._cust } : null;
    global.estimatedPinFromAddress = () => HOME;          // so routeHomePoint answers

    const api = eval(extractFn(admin, 'haversine') + LF_ + admin.slice(geoStart, geoEnd) +
      LF_ + admin.slice(crewStart, crewEnd) + LF_ +
      ';({order: orderHousesForDriving, plain: reorderFlatStops, hav: haversine,' +
      '  split: outlyingStops, point: houseStopPoint, centre: stopsCentre,' +
      '  setCrews(l){ CREWS = normalizeCrews(l); }})');

    const mk = (name, lat, lng) => ({ name, city: 'Lehi', _cust: { lat, lng } });
    /* ⚠ THE FIXTURE HAS TO MAKE THE SHORTEST TOUR PUT THE FAR HOUSE IN THE MIDDLE,
       or the check passes whether the code does anything or not. Sixteen houses
       along one street with the odd one out five miles north of the MIDDLE of it
       does that: the cheapest detour is exactly halfway along. A far house off
       one END is visited last by the plain orderer anyway, and the first version
       of this fixture had precisely that flaw and proved nothing. */
    const street = [];
    for (let i = 0; i < 16; i++) street.push(mk('near' + i, 40.400, -111.900 + i * 0.0055));
    const far = mk('FAR', 40.475, -111.860);
    const day = street.concat([far]);

    const legs = order => {
      const out = [];
      let prev = HOME;
      order.forEach(h => { out.push(api.hav(prev.lat, prev.lng, h._cust.lat, h._cust.lng)); prev = h._cust; });
      out.push(api.hav(prev.lat, prev.lng, HOME.lat, HOME.lng));
      return out;
    };
    const worstMiddle = order => {
      const L = legs(order).slice(1, -2);          // neither the drive out nor the drive home
      return L.length ? Math.max.apply(null, L) : 0;
    };
    const total = order => legs(order).reduce((a, b) => a + b, 0);

    const plain = api.plain(day.map(api.point), HOME, HOME).map(s => s.ref);
    const held = api.order(day.slice());

    check('S124', 'the plain shortest tour really does bury the far house mid-day',
      plain.indexOf(far) > 2 && plain.indexOf(far) < plain.length - 2,
      'the fixture proves nothing unless it does — got position ' + plain.indexOf(far));
    check('S124', 'and the far house is now the last stop of the day',
      held[held.length - 1] === far,
      'got ' + held.map(h => h.name).join(',').slice(-40));
    check('S124', 'the long drive is off the middle of the day',
      worstMiddle(held) < worstMiddle(plain) / 2,
      'worst mid-day leg ' + worstMiddle(plain).toFixed(1) + ' mi -> ' +
        worstMiddle(held).toFixed(1) + ' mi');
    /* ⚠ AND THE PRICE IS NAMED. It IS longer, on purpose. If this ever grows past
       a mile or two on a fixture like this, the split has gone wrong rather than
       the trade having changed. */
    check('S124', 'and it costs a mile or so, not a detour of its own',
      total(held) > total(plain) && total(held) - total(plain) < 3,
      'cost ' + (total(held) - total(plain)).toFixed(1) + ' mi');
    check('S124', 'nothing is dropped or visited twice by splitting the day',
      held.length === day.length && day.every(h => held.indexOf(h) > -1) &&
      new Set(held).size === held.length);

    /* ---- the refusals ---- */
    const spread = [];
    for (let i = 0; i < 12; i++) spread.push(mk('s' + i, 40.30 + i * 0.02, -111.80 + i * 0.02));
    check('S124', 'a day that is simply spread out has no outlier at all',
      api.split(spread.map(api.point)).out.length === 0,
      'that is the shape of the day, not a house out on its own');
    const half = street.slice(0, 8).concat([
      mk('f1', 40.475, -111.860), mk('f2', 40.478, -111.858), mk('f3', 40.472, -111.864),
      mk('f4', 40.470, -111.866), mk('f5', 40.476, -111.862)]);
    check('S124', 'and neither does a day that is half-and-half',
      api.split(half.map(api.point)).out.length === 0,
      'more than a third being "far" means there are two clusters, not one and a stray');
    check('S124', 'a tiny day is left alone',
      api.split(street.slice(0, 3).map(api.point)).out.length === 0,
      'three stops have no "everyone else" to be further out than');
    /* ⚠ THE FIXTURE HAS TO BE GENUINELY TIGHT or it tests nothing. On the street
       above the median spread is already about a mile, so the factor alone puts the
       cut near 2.75 miles and a half-mile house is never flagged either way — the
       first version of this check was vacuous for exactly that reason. Sixteen
       houses inside a fifth of a mile puts the factor-only cut at ~0.1 miles, so
       ONLY the mileage floor keeps the half-mile house out of it. */
    const culdesac = [];
    for (let i = 0; i < 16; i++) culdesac.push(mk('c' + i, 40.4000 + i * 0.0002, -111.8600));
    check('S124', 'a house half a mile out of a very tight day is not an outlier',
      api.split(culdesac.concat([mk('n', 40.4072, -111.8600)]).map(api.point)).out.length === 0,
      'the factor alone would flag it; the mileage floor is what stops that');

    /* ⚠ THE CENTRE IS A MEDIAN, NOT A MEAN, and it matters: a mean is dragged
       towards the very house being looked for, which then makes its neighbours
       look far too. */
    const pulled = street.concat([mk('miles', 41.9, -111.86)]);
    const c = api.centre(pulled.map(api.point));
    check('S124', 'one house far away does not drag the middle of the day towards it',
      Math.abs(c.lat - 40.400) < 0.01,
      'centre came out at ' + c.lat.toFixed(3) + ' — a mean would sit near 40.49');
    check('S124', 'and only that house is called far, not half the street with it',
      api.split(pulled.map(api.point)).out.length === 1);

    /* A house with no position cannot be near or far; it stays after even the
       far ones, which is where the owner asked for it. */
    const withBare = day.concat([{ name: 'no pin', city: 'Lehi' }]);
    const ordered = api.order(withBare);
    check('S124', 'a house with no position at all is still the very last',
      ordered[ordered.length - 1].name === 'no pin' &&
      ordered[ordered.length - 2] === far,
      'got ' + ordered.slice(-2).map(h => h.name).join(' then '));
  }
}

/*
 * Suite 125. The schedule keeps off Thanksgiving, not just off weekends.
 *
 * Owner, 2026-08-21: "as crews begin to not finish their entire day and we get
 * more people ... when we recaluclate it will create days between nov 20 and
 * thanksgiving, but we dont work on the day of thanksgiving."
 *
 * ⚠ HALF OF THIS ALREADY WORKED AND HALF OF IT DID NOT, which is why it went
 * unnoticed. `isWorkingDay` has excluded the holiday since 2026-08-18, so
 * planNewCrewDays never puts a crew-day on it — a late-season rebuild lays out
 * Nov 20, 23, 24, 25 and steps over the 26th, and Suite 52 covers that. But the
 * builder hands its days back as OFFSETS, and layoutSequence turns those into
 * the dates the office actually sees while skipping weekends ONLY. Ten
 * consecutive crew-days from Mon 16 Nov came out on 16,17,18,19,20,23,24,25,
 * 26,27 — and the 26th is Thanksgiving. Every hand shift re-flows through the
 * same function, and so do fixer routes through nextWeekday.
 *
 * So the checks below drive the LAYOUT, not the builder. A check on the builder
 * passes today and proves nothing about the half that was broken.
 */
suite('125. The schedule keeps off Thanksgiving, not just off weekends');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);
  const parts = ['isWeekend', 'isThanksgiving', 'isDayOff', 'dayOffName', 'addDays',
                 'layoutSequence', 'nextWeekday', 'thanksgivingDate', 'isThanksgivingDay']
    .map(pick).filter(Boolean).join(LF_);
  if (!pick('layoutSequence') || !pick('isDayOff')) {
    check('S125', 'the schedule’s date layout is findable', false,
      'renamed or removed — update this test rather than deleting it');
  } else {
    const prelude = 'let BASE_START=new Date(2026,10,16), globalDelta=0, SEASON=[];' + LF_ +
      'function daysBetween(a,b){return Math.round((a-b)/86400000);}' + LF_ +
      'function deltaFor(){return globalDelta;}' + LF_ +
      'function effectivePin(d){return d && d.pin ? d.pin : null;}' + LF_ +
      'function desired(d){return addDays(BASE_START,d.base+d.cascade);}' + LF_;
    const api = eval(prelude + parts + LF_ +
      ';({layout: layoutSequence, next: nextWeekday, tg: thanksgivingDate,' +
      '  off: isDayOff, name: dayOffName})');

    const TG = api.tg(2026);
    const iso = d => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') +
      '-' + String(d.getDate()).padStart(2, '0');
    check('S125', 'Thanksgiving 2026 is Thursday 26 November',
      iso(TG) === '2026-11-26' && TG.getDay() === 4, 'got ' + iso(TG));

    /* Ten consecutive crew-days from Mon 16 Nov. Skipping weekends alone puts
       the ninth of them on the holiday — that is the bug, reproduced. */
    const days = [];
    for (let i = 0; i < 10; i++) days.push({ id: 'd' + i, base: i, cascade: 0, pin: null, houses: [] });
    api.layout(days);
    const dates = days.map(d => iso(d._date));
    check('S125', 'no crew-day is ever laid down on Thanksgiving',
      dates.indexOf('2026-11-26') === -1,
      'got ' + dates.join(', '));
    check('S125', 'the days either side of it are still worked',
      dates.indexOf('2026-11-25') > -1 && dates.indexOf('2026-11-27') > -1,
      'stepping over the holiday must not cost the whole week');
    /* ⚠ THE OWNER'S ACTUAL ASK: the run-up week has to be USED, not skipped past.
       A version that jumped the whole of Thanksgiving week would pass the check
       above and be useless. */
    check('S125', 'and the Nov 20 to Thanksgiving window is filled',
      ['2026-11-20', '2026-11-23', '2026-11-24', '2026-11-25']
        .every(d => dates.indexOf(d) > -1),
      'got ' + dates.join(', '));
    check('S125', 'weekends are still skipped',
      !dates.some(d => ['2026-11-21', '2026-11-22', '2026-11-28', '2026-11-29'].indexOf(d) > -1),
      'the older rule must survive the newer one');
    check('S125', 'and nothing is lost or doubled up on one date',
      days.length === 10 && new Set(dates).size === 10, dates.join(', '));

    /* ⚠ A PIN IS STILL A PIN. Force exact date deliberately overrides weekends,
       and must keep overriding — the office sometimes has to work a holiday. */
    const pinned = [{ id: 'p', base: 0, cascade: 0, pin: new Date(2026, 10, 26), houses: [] }];
    api.layout(pinned);
    check('S125', 'but Force exact date can still put a day on it deliberately',
      iso(pinned[0]._date) === '2026-11-26',
      'the override exists for weekends and must work the same way here');
    check('S125', 'and the screen names which kind of day off that is',
      api.name(new Date(2026, 10, 26)) === 'Thanksgiving' &&
      api.name(new Date(2026, 10, 21)) === 'weekend' &&
      api.name(new Date(2026, 10, 24)) === '',
      '"(weekend)" on a Thursday in late November would just be wrong');

    /* Fixer routes are placed through nextWeekday, not through the layout. */
    check('S125', 'a fixer route is not placed on Thanksgiving either',
      iso(api.next(new Date(2026, 10, 26))) === '2026-11-27',
      'got ' + iso(api.next(new Date(2026, 10, 26))));
    check('S125', 'nextWeekday still steps over a weekend',
      iso(api.next(new Date(2026, 10, 21))) === '2026-11-23');
  }

  /* The two-business-day "SET" lock walks the calendar too. A day nobody works
     is not one of the two, or a Wednesday in Thanksgiving week reads as set
     when the crew is not out again until Monday. */
  const horizon = sectionFrom(admin, admin.indexOf('function pinHorizon()'));
  check('S125', 'the two-business-day lock does not count Thanksgiving as a business day',
    /while\(isDayOff\(d\)\)/.test(horizon),
    'otherwise a day is frozen as SET on the strength of a day nobody works');
  const bar = sectionFrom(admin, admin.indexOf('function renderSeasonBar()'));
  check('S125', 'and the note explaining moved days names the holiday',
    /isThanksgiving\(desired\(d\)\)/.test(bar) && /Thanksgiving/.test(bar),
    'a day that moved off Thanksgiving moved for a different reason than a weekend');
}


/* ---------------------------------------------------------------------------
 * Suite 126. One place a job is marked done
 *
 * Owner, 2026-08-21: "Schedules should mark routes as complete automatically.
 * However that does not mean takedown is done." Asked whether ticking one stop or
 * finishing a day should do it: ticking ONE stop marks that customer complete.
 *
 * ⚠ WHAT THIS PROTECTS. Ticking a house in Schedule set `done` on the plan document
 * and nothing else — the tab's own footer said so. The nightly run bills on
 * `completed` on the CUSTOMER, so with the crew portal out of use this season,
 * working the season off Schedule billed nobody at all.
 *
 * Everything below RUNS the function and reads the write that came out. A check that
 * the call exists survives the result being dropped on the floor.
 * ------------------------------------------------------------------------- */
suite('Suite 126. One place a job is marked done');

{
  const admin = read('admin.html');

  const kindsSrc = admin.slice(admin.indexOf('const HLX_DONE_KINDS = {'),
                               admin.indexOf('async function hlxMarkJobDone('));
  const markSrc = extractFn(admin, 'hlxMarkJobDone');
  check('S126', 'the shared done-function and its field table are findable',
    !!kindsSrc && !!markSrc,
    'renamed or removed — update this suite rather than deleting it');
  check('S126', 'and it is async in the real file',
    /async function hlxMarkJobDone\(/.test(admin),
    'extractFn drops the async keyword, so the body alone cannot prove this');

  if (kindsSrc && markSrc) {
    /* Run it against a fake Firestore and keep what it wrote. */
    const runMark = function (kind, done, opts) {
      const writes = [];
      const logs = [];
      const fn = new (Object.getPrototypeOf(async function () {}).constructor)(
        'updateDoc', 'doc', 'db', 'serverTimestamp', 'logActivity', 'console', 'writes', 'logs',
        kindsSrc + 'async ' + markSrc +
        ';return hlxMarkJobDone(' + JSON.stringify(opts && opts.target || { id: 'c1' }) +
        ', ' + JSON.stringify(kind) + ', ' + JSON.stringify(done) + ', {});')
        ;
      return fn(
        async (ref, payload) => {
          if (opts && opts.breakWrite) throw new Error('Missing or insufficient permissions.');
          writes.push({ col: ref.col, id: ref.id, payload: payload });
        },
        (db, col, id) => ({ col: col, id: id }), {},
        () => 'NOW',
        async (what, area, refId) => { logs.push({ what, area, refId }); },
        { error: () => {} }, writes, logs)
        .then(res => ({ res: res, writes: writes, logs: logs }));
    };

    pendingAsync.push((async function () {
      const inst = await runMark('install', true);
      const p = (inst.writes[0] || {}).payload || {};
      check('S126', 'marking an install done writes completed and the timestamp',
        p.completed === true && p.completedAt === 'NOW');
      /* ⚠ THE ONE-OFF NOTE IS CLEARED. It is the "say this to them once" note the
         route editor and the crew portal both clear on completion; carrying it over
         repeats a one-off instruction next season. */
      check('S126', 'and clears the one-time note',
        p.oneTimeNote === '',
        'a one-off instruction that survives is repeated next season');
      /* ⭐ THE INDEPENDENCE RULE, BOTH DIRECTIONS. This is the whole reason the kinds
         are split, and the customer-row dropdown used to break it. */
      check('S126', 'and NEVER touches the takedown',
        !('removalDone' in p) && !('removalDoneAt' in p),
        'owner: "that does not mean takedown is done"');

      const take = await runMark('takedown', true);
      const tp = (take.writes[0] || {}).payload || {};
      check('S126', 'marking a takedown done writes removalDone and the timestamp',
        tp.removalDone === true && tp.removalDoneAt === 'NOW');
      check('S126', 'and NEVER touches the install',
        !('completed' in tp) && !('completedAt' in tp) && !('oneTimeNote' in tp),
        'a house whose lights came down has not un-had them hung');

      const undo = await runMark('install', false);
      const up = (undo.writes[0] || {}).payload || {};
      check('S126', 'unticking an install clears it and its timestamp',
        up.completed === false && up.completedAt === null);
      check('S126', 'and still leaves the takedown alone',
        !('removalDone' in up),
        'this is the exact pairing the customer-row dropdown used to break');

      const undoTake = await runMark('takedown', false);
      const utp = (undoTake.writes[0] || {}).payload || {};
      check('S126', 'unticking a takedown clears it and leaves the install alone',
        utp.removalDone === false && utp.removalDoneAt === null && !('completed' in utp));

      const fix = await runMark('fix', true);
      const fp = (fix.writes[0] || {}).payload || {};
      check('S126', 'marking a fix done clears the flag, the marker and the note',
        fp.needsFix === false && fp.fixScheduled === false && fp.fixNote === '',
        'clearing needsFix is also what releases the nightly billing HOLD on that ' +
        'payer\'s whole group');
      /* ⚠ JOB 4 OWNS THE PHOTO. Destroying a Cloudinary asset with no undo behind it
         is not something to slip into this job. */
      check('S126', 'and deliberately leaves the fix photo for Job 4',
        !('fixPhotoUrl' in fp),
        'park-then-destroy has not been built or decided — do not destroy an asset ' +
        'with no undo behind it');

      /* ⚠ THE HOUSE PHOTO. It prints on the new-hang crew sheets, so losing one is
         discovered on paper. Its own check, on every kind. */
      check('S126', 'no kind ever touches the house photo',
        [p, tp, up, utp, fp].every(x =>
          !('housePhotos' in x) && !('housePhotoUrl' in x) &&
          !('housePhotoOriginal' in x) && !('housePhotoMarkup' in x)),
        'the house photo is what prints on the crew sheet — losing it shows up on paper');

      check('S126', 'an unknown kind writes nothing at all',
        (await runMark('nonsense', true)).writes.length === 0,
        'a typo in a caller must not quietly write a half-record');

      /* ⚠ IT NEVER THROWS. Every caller is a click handler that has other things to
         finish; a rejected promise there loses the rest of the handler silently.

         ⚠ THE REJECTION IS CAUGHT HERE ON PURPOSE. Letting it escape makes the whole
         async suite die as "an async suite crashed", which fails the build but names
         nothing — a red-check that removed the catch went red on a DIFFERENT check
         and left this one looking untested. */
      const broke = await runMark('install', true, { breakWrite: true })
        .catch(() => ({ res: { ok: false, threw: true }, writes: [], logs: [] }));
      check('S126', 'a refused write is reported, not thrown',
        broke.res.ok === false && !broke.res.threw && !!broke.res.why,
        'a throw inside a click handler loses whatever the handler was doing next');

      check('S126', 'and a successful mark is written to the activity log',
        inst.logs.length === 1 && inst.logs[0].refId === 'c1',
        'two people in one admin panel: "who marked this done" has no other answer');
      check('S126', 'while a refused one logs nothing',
        broke.logs.length === 0,
        'a log line for a write that did not happen is worse than none');
    })());
  }

  /* ---- which customer a plan house is ---- */
  const resolveSrc = extractFn(admin, 'hlxResolvePlanHouse');
  check('S126', 'the plan-house resolver is findable', !!resolveSrc);
  if (resolveSrc) {
    const BOOK = [
      { id: 'abc123', data: { name: 'Real Customer', customerNumber: '479' } },
      { id: 'zzz999', data: { name: 'Reused Number', customerNumber: '479' } }
    ];
    const resolve = new Function('jobAddresses', 'customerForHouse',
      resolveSrc + ';return hlxResolvePlanHouse;')(
      BOOK,
      /* the imported-CSV fallback: number, then phone */
      (h) => BOOK.find(a => String(a.data.customerNumber) === String(h.cu)) || null);

    check('S126', 'a synced house resolves by its document id',
      (resolve({ id: 'cust-abc123', cu: '479' }) || {}).id === 'abc123',
      'houseFromCustomer builds cust-<id>; that is exact and everything else is a guess');
    /* ⚠ THE REUSED-NUMBER TRAP. Numbers go back to the pool on a recycle and are
       handed out again, so the number must never override an id that is present. */
    check('S126', 'and the id wins over a customer number that now belongs to somebody else',
      (resolve({ id: 'cust-zzz999', cu: '479' }) || {}).id === 'zzz999',
      'a stale row holding #479 must not mark a different household complete');
    check('S126', 'an imported row with no id falls back to the number',
      (resolve({ id: '17', cu: '479' }) || {}).id === 'abc123',
      'CSV rows have their own ids and no link — the number is all there is');
    /* ⚠ A DELETED CUSTOMER IS AN ANSWER, NOT A REASON TO GUESS. */
    check('S126', 'a cust- id nobody matches resolves to nothing, it does not fall through',
      resolve({ id: 'cust-gone', cu: '479' }) === null,
      'falling through to the number here would mark a different customer complete');
    check('S126', 'a row matching nothing at all reports nothing',
      resolve({ id: '17', cu: '0000' }) === null,
      'a tick that wrote nothing looks identical to one that worked — the caller has ' +
      'to be able to say so');
    /* ⭐ TAKEDOWN ROWS CARRY THE INSTALL HOUSE'S ID. seedTakedowns copies name,
       address and number off the install house; without srcId every takedown tick
       depended on the reused-number guess. */
    check('S126', 'a takedown copy resolves by the house it was copied from',
      (resolve({ id: 't3', srcId: 'cust-zzz999', cu: '479' }) || {}).id === 'zzz999',
      'a takedown must resolve exactly the way its install does');
    check('S126', 'and seedTakedowns actually puts that id on the copy',
      /srcId:h\.id/.test(admin),
      'the resolver can only use it if the copy carries it');
  }

  /* ---- the five doors all go through the one function ---- */
  {
    const doorFor = (needle, endNeedle) => {
      const a = admin.indexOf(needle);
      if (a === -1) return '';
      const b = endNeedle ? admin.indexOf(endNeedle, a) : a + 900;
      return admin.slice(a, b === -1 ? a + 900 : b);
    };
    /* ⚠ SCOPED TO EACH HANDLER. A bare search for the function name stays green when
       one call site is deleted, because the other four still match. */
    const doors = [
      ['the Schedule tick', doorFor("t.type==='checkbox'&&t.dataset.id!=null", 'return;}'), 'planTickCustomer'],
      ['Schedule All done', doorFor('if(t.dataset.allbtn)', 'return;}'), 'planTickCustomer'],
      ['the leftover flow', extractFn(admin, 'applyLeftoverPicks'), 'planTickCustomer'],
      ['the Routes stop', doorFor("listEl.querySelectorAll('[data-togglecomplete]')", 'renderTextOutSection'), 'hlxMarkJobDone'],
      ['the customer row', doorFor("container.querySelectorAll('.status-apply')", 'edithousedetails'), 'HLX_DONE_KINDS']
    ];
    doors.forEach(([name, src, needs]) => {
      check('S126', name + ' goes through the shared rule',
        !!src && src.indexOf(needs) !== -1,
        'a private copy of what "done" means is the copy that stops matching the others');
    });

    /* ⭐ THE TWO CONFIRMS, RUN RATHER THAN READ (2026-08-21). The first version of
       these matched `confirm(` and the word "invoiced" in the source — and a
       red-check that disabled the whole guard with `if(false && ...)` left every one
       of those words standing, so the checks stayed green while a whole day could be
       billed with no warning. The branches are lifted out and executed against fake
       controls, and what is asserted is whether the dialog was ASKED and whether the
       write happened after it was refused. */
    /* ⚠ INCLUDES THE TERMINATOR, unlike doorFor. These two slices are EXECUTED, so
       stopping just before the closing `return;}` leaves the `if` unclosed and the
       whole suite dies on a SyntaxError rather than reporting anything. */
    const branchFor = (needle, endNeedle) => {
      const a = admin.indexOf(needle);
      if (a === -1) return '';
      const b = admin.indexOf(endNeedle, a);
      return b === -1 ? '' : admin.slice(a, b + endNeedle.length);
    };
    const allBtn = branchFor('if(t.dataset.allbtn)', 'renderAll();return;}');
    /* ⚠ STARTS AT `if(`, not at the condition. Slicing from the condition alone
       begins the source mid-expression and the compile fails on the stray `)`. */
    const oneTick = branchFor("if(t.type==='checkbox'&&t.dataset.id!=null)", 'renderAll();}return;}');

    const runBranch = function (src, ctx) {
      const asked = [];
      const ticked = [];
      const env = Object.assign({
        confirm: (m) => { asked.push(m); return ctx.answer !== false; },
        planTickCustomer: (h, done) => ticked.push({ id: h.id, done: done }),
        planAlreadyBilled: () => !!ctx.billed,
        /* The real one reads h.isFix / h.isTakedown; the fixture sets those, so this
           mirrors it rather than hard-coding 'install' — otherwise the takedown case
           below would be testing nothing. */
        planHouseKind: (h) => (h && h.isFix) ? 'fix' : ((h && h.isTakedown) ? 'takedown' : 'install'),
        renderAll: () => {},
        findHouse: (id) => ctx.house ? { house: ctx.house } : null,
        getDay: () => ctx.day
      }, ctx.extra || {});
      const names = Object.keys(env);
      new Function('t', ...names, 'function __b(){ ' + src + ' } __b();')(
        ctx.t, ...names.map(n => env[n]));
      return { asked: asked, ticked: ticked };
    };

    if (allBtn && oneTick) {
      const day = { id: 'd1', houses: [{ id: 1, done: false }, { id: 2, done: false }] };
      const allYes = runBranch(allBtn, { t: { dataset: { allbtn: 'd1' } }, day: day });
      check('S126', 'All done confirms and says they will be invoiced tonight',
        allYes.asked.length === 1 && /invoiced/i.test(allYes.asked[0]) &&
        /\b2\b/.test(allYes.asked[0]),
        'one press can bill forty people — that is the intent, and it is new');
      check('S126', 'and marks them once it is agreed to',
        allYes.ticked.length === 2 && allYes.ticked.every(x => x.done === true));

      const day2 = { id: 'd1', houses: [{ id: 1, done: false }, { id: 2, done: false }] };
      const allNo = runBranch(allBtn, { t: { dataset: { allbtn: 'd1' } }, day: day2, answer: false });
      check('S126', 'and cancelling it writes nothing at all',
        allNo.ticked.length === 0 && day2.houses.every(h => h.done === false),
        'a confirm whose answer is ignored is worse than no confirm');

      /* The single tick is deliberately silent — the office is looking straight at
         the one house, and a dialog per tick is noise. */
      const one = runBranch(oneTick, { t: { type: 'checkbox', checked: true, dataset: { id: '1' } },
        house: { id: 1, name: 'A', done: false } });
      check('S126', 'the single tick stays silent and marks the customer',
        one.asked.length === 0 && one.ticked.length === 1 && one.ticked[0].done === true,
        'a dialog on every tick is what makes people stop reading dialogs');

      /* ⚠ UNTICKING CANNOT UN-SEND. invoiceEmailSent is only cleared by Start New
         Season, so without a warning the screen and their inbox quietly disagree. */
      const untickBilled = runBranch(oneTick, {
        t: { type: 'checkbox', checked: false, dataset: { id: '1' } },
        house: { id: 1, name: 'A', done: true }, billed: true, answer: false });
      check('S126', 'unticking a billed house warns first',
        untickBilled.asked.length === 1 && /invoice/i.test(untickBilled.asked[0]),
        'unticking cannot un-send an invoice that has already gone');
      check('S126', 'and refusing that warning leaves them ticked and unwritten',
        untickBilled.ticked.length === 0,
        'the warning has to be able to stop the change, or it is decoration');
      const untickPlain = runBranch(oneTick, {
        t: { type: 'checkbox', checked: false, dataset: { id: '1' } },
        house: { id: 1, name: 'A', done: true }, billed: false });
      check('S126', 'while unticking an unbilled house asks nothing',
        untickPlain.asked.length === 0 && untickPlain.ticked.length === 1,
        'most unticks are an ordinary correction and must not be interrogated');

      /* ⚠ THE INVOICE WARNING IS ABOUT THE INSTALL, AND ONLY THE INSTALL. One
         listener and one row renderer serve all three tabs, so this branch also runs
         for takedowns and fixes — where "you have already been invoiced for this" is
         simply untrue: removal is not billed at all, and a fix is a visit rather
         than a charge. Said on the two kinds where it would come up most often. */
      const untickTakedown = runBranch(oneTick, {
        t: { type: 'checkbox', checked: false, dataset: { id: '9' } },
        house: { id: 9, name: 'T', done: true, isTakedown: true }, billed: true });
      check('S126', 'unticking a TAKEDOWN never claims they were invoiced for it',
        untickTakedown.asked.length === 0 && untickTakedown.ticked.length === 1,
        'removal is not billed — warning about an invoice here is telling them ' +
        'something that is not true');
      const untickFix = runBranch(oneTick, {
        t: { type: 'checkbox', checked: false, dataset: { id: '8' } },
        house: { id: 8, name: 'F', done: true, isFix: true }, billed: true });
      check('S126', 'and neither does unticking a FIX',
        untickFix.asked.length === 0 && untickFix.ticked.length === 1,
        'a fix is a visit, not a charge');
    }

    /* ⭐ INSTALL AND TAKEDOWN ARE INDEPENDENT ON THE CUSTOMER ROW TOO. */
    const row = doorFor("container.querySelectorAll('.status-apply')", 'edithousedetails');
    /* ⚠ COMMENTS STRIPPED. The old expression is quoted in two comments — one over
       the handler and one over hlxMarkJobDone — precisely where somebody would be
       tempted to put it back, so a plain search finds the warning and reports it as
       the violation it is warning about. */
    check('S126', 'the customer row no longer nests removal under completed',
      !/removalDone: completed \? removalDone : false/.test(stripComments(admin)),
      'unticking Install Complete used to silently clear the removal as well');
    /* ⚠ SCOPED TO THAT ONE LABEL. A file-wide search for "disabled" matches dozens of
       unrelated controls, and the first version of this used a regex that did not
       match the real markup at all — so a red-check that put the greying-out back
       sailed through it. This slices the removalDone label and asks whether anything
       in it can disable the box. */
    const rmLabel = (function () {
      const a = admin.indexOf('data-field="removalDone"');
      if (a === -1) return '';
      const b = admin.indexOf('Removal Done</label>', a);
      return b === -1 ? '' : admin.slice(a, b);
    })();
    check('S126', 'the removal checkbox markup was found', !!rmLabel);
    check('S126', 'and the removal box is not greyed out when the install is unticked',
      !!rmLabel && rmLabel.indexOf('disabled') === -1,
      'greying it out was the visible half of the same wrong assumption');
  }
}


/* ---------------------------------------------------------------------------
 * Suite 127. Whether a house is done is the customer's answer (Job 3)
 *
 * Job 2 made ticking a house write `completed` to the customer. That left TWO
 * copies of one fact — the plan's own `done` flag and the customer record — and
 * they disagree the first time somebody uses the other screen: mark a house
 * complete from Routes or the customer row, and Schedule still showed it
 * outstanding, counted it in "left", put it back in the movable pile and printed
 * it on a crew sheet.
 *
 * ⚠ THE REGRESSION IS THE POINT OF THIS SUITE. Two dozen callers read h.done —
 * the crew split, the hand-back that makes the sheets 20/20, the near-empty-day
 * rescue, One Man Installs, unfinishedOn, the leftover flow, the day progress
 * bar, the CSV and every print sheet. None of them was touched; the value is
 * refreshed before they read it. What has to be proved is that they all still
 * behave exactly as they did.
 * ------------------------------------------------------------------------- */
suite('Suite 127. Whether a house is done is the customer\'s answer');

{
  const admin = read('admin.html');
  const derivedSrc = extractFn(admin, 'derivedDoneFor');
  const refreshSrc = extractFn(admin, 'refreshDerivedDone');
  const kindSrc = extractFn(admin, 'planHouseKind');
  check('S127', 'the derivation and the per-render refresh are findable',
    !!derivedSrc && !!refreshSrc && !!kindSrc,
    'renamed or removed — update this suite rather than deleting it');

  if (derivedSrc && refreshSrc && kindSrc) {
    /* One place builds the sandbox, so every check below runs the real code
       against a resolver we control. `looks` counts resolutions so the
       once-per-render claim can be asserted rather than assumed. */
    const build = function (book) {
      const looks = { n: 0 };
      const env = new Function('SEASON', 'BOOK', 'looks',
        kindSrc + derivedSrc + refreshSrc +
        'function hlxResolvePlanHouse(h){ looks.n++; ' +
        '  const id = String((h.srcId != null && h.srcId !== "") ? h.srcId : h.id);' +
        '  if(id.indexOf("cust-") === 0){ const k = id.slice(5);' +
        '    return BOOK[k] ? {id: k, data: BOOK[k]} : null; }' +
        '  return null; }' +
        ';return {refresh: refreshDerivedDone, derived: derivedDoneFor, looks: looks};');
      return env;
    };

    const season = () => ([{
      id: 'd1', houses: [
        { id: 'cust-a', done: false },
        { id: 'cust-b', done: true },
        { id: 'imported-9', cu: '77', done: true },     // nobody behind it
        { id: 'cust-t', srcId: 'cust-a', isTakedown: true, done: false },
        { id: 'cust-f', srcId: 'cust-b', isFix: true, done: false }
      ]
    }]);

    /* ---- 1. the customer's answer wins, in both directions ---- */
    {
      const S = season();
      const BOOK = {
        a: { completed: true,  removalDone: false, needsFix: false },
        b: { completed: false, removalDone: false, needsFix: true }
      };
      const api = build(BOOK)(S, BOOK, { n: 0 });
      api.refresh();
      const byId = (id) => S[0].houses.find(h => h.id === id);
      check('S127', 'a house completed on another screen reads as done in Schedule',
        byId('cust-a').done === true,
        'marking it complete from Routes or the customer row used to leave Schedule ' +
        'still counting it as outstanding');
      check('S127', 'and one un-completed there reads as NOT done',
        byId('cust-b').done === false,
        'the correction has to travel both ways or the plan drifts the other way');
    }

    /* ---- 2. the three kinds read three different fields ---- */
    {
      const S = season();
      /* ⚠ EACH FIELD IS SET SO THAT READING THE WRONG ONE GIVES THE WRONG ANSWER.
         A fixture where completed/removalDone/needsFix happen to agree would pass
         against a derivation that read the same field for all three kinds. */
      const BOOK = {
        a: { completed: false, removalDone: true,  needsFix: false },
        /* ⚠ needsFix:true WITH completed:true, and that pairing is the whole check.
           The first version had needsFix:false here, so `!needsFix` and `completed`
           both came out true — a sabotage swapping the fix rule for the install one
           gave the identical answer and the check stayed green. The two fields must
           DISAGREE for the fix row's customer or this proves nothing. */
        b: { completed: true,  removalDone: false, needsFix: true }
      };
      const api = build(BOOK)(S, BOOK, { n: 0 });
      api.refresh();
      const byId = (id) => S[0].houses.find(h => h.id === id);
      check('S127', 'an install reads completed',
        byId('cust-a').done === false && byId('cust-b').done === true);
      check('S127', 'a takedown reads removalDone, not completed',
        byId('cust-t').done === true,
        'its source customer has completed:false and removalDone:true — reading ' +
        'completed here would say not done');
      check('S127', 'and a fix reads needsFix, inverted',
        byId('cust-f').done === false,
        'its source customer has completed:true but still needsFix — a fix is done ' +
        'when the house no longer needs one, so this must read NOT done');
    }

    /* ---- 3. a house with nobody behind it keeps the plan's own flag ---- */
    {
      const S = season();
      const api = build({})(S, {}, { n: 0 });
      api.refresh();
      const byId = (id) => S[0].houses.find(h => h.id === id);
      /* ⚠ THE WHOLE IMPORTED PLAN DEPENDS ON THIS. An imported CSV row never
         matched anybody, so there is nothing to derive from. Returning false for
         those instead of null would un-tick every one of them on the next render —
         on an imported plan, that is most of the season's progress. */
      check('S127', 'an unmatched imported row keeps its stored flag',
        byId('imported-9').done === true,
        'returning false for "nobody behind it" would blank an imported season');
      check('S127', 'and so does every house while the customer list is still loading',
        byId('cust-a').done === false && byId('cust-b').done === true,
        'before jobAddresses arrives nothing resolves — the screen must be exactly ' +
        'what it was, not blanked for the second between login and the first snapshot');
      check('S127', 'derivedDoneFor says "no answer" rather than "not done"',
        api.derived({ id: 'cust-nobody' }) === null,
        'null and false are different answers and only one of them is safe');
    }

    /* ---- 4. resolved once per render, not once per read ---- */
    {
      const S = season();
      const BOOK = { a: { completed: true }, b: { completed: false } };
      const looks = { n: 0 };
      const api = build(BOOK)(S, BOOK, looks);
      api.looks.n = 0;
      api.refresh();
      /* Five houses, five resolutions. A dozen readers each asking for themselves
         would be a lookup per house PER READER — the shape that once locked the
         screen up on every keystroke, which is why custById exists. */
      check('S127', 'one resolution per house per render, not one per reader',
        api.looks.n === 5,
        'resolved ' + api.looks.n + ' times for 5 houses — a lookup per house per ' +
        'caller is what the customer indexes exist to prevent');
    }

    /* ---- 5. THE REGRESSION. Everything that reads h.done still behaves. ---- */
    {
      /* The readers are unchanged code, so what has to be proved is that the value
         they read is the same one they would have read before. Two fixtures: one
         where the customer agrees with the stored flag (the ordinary case — output
         must be byte-identical), and one where nobody resolves (the imported case —
         output must be byte-identical too). */
      const shape = (S) => S[0].houses.map(h => h.id + ':' + (h.done ? 'done' : 'left')).join(',');

      const agreeing = season();
      const before = shape(agreeing);
      const BOOK = {
        a: { completed: false, removalDone: false, needsFix: true },
        b: { completed: true,  removalDone: false, needsFix: true }
      };
      build(BOOK)(agreeing, BOOK, { n: 0 }).refresh();
      check('S127', 'a plan already agreeing with the customers is left untouched',
        shape(agreeing) === before,
        'the ordinary case must produce exactly what it produced before: ' +
        before + '  ->  ' + shape(agreeing));

      const orphaned = season();
      const beforeOrphan = shape(orphaned);
      build({})(orphaned, {}, { n: 0 }).refresh();
      check('S127', 'and an imported plan nobody resolves is left untouched too',
        shape(orphaned) === beforeOrphan,
        'every counter, the crew split and the printed sheets read this — an ' +
        'imported season must look exactly as it did');

      check('S127', 'the refresh reports how many it actually changed',
        (function () {
          const S = season();
          const B = { a: { completed: true }, b: { completed: true } };
          return build(B)(S, B, { n: 0 }).refresh() === 1;
        })(),
        'only cust-a moves (false->true); cust-b is already true, the takedown has ' +
        'no removalDone, and the fix row is left alone because its customer carries ' +
        'no needsFix at all');

      /* ⭐ A PLAN-ONLY FIX KEEPS ITS OWN FLAG, and this is the sharpest edge in the
         whole job. Job 3's plan says a fix derives from `!needsFix` — but that
         assumes Job 4 has already made Schedule's fix list derive from that flag,
         and it has not. Today a fix reaches the plan through FIXLIST, which is
         plan-only: nothing in the Schedule module writes needsFix to a customer.

         So the plain inversion would read `!undefined` as TRUE and render EVERY
         outstanding fix as already done — out of the fix counters, out of
         unfinishedOn, and off the printed fix sheets, silently. */
      /* ⚠ THE TWO CASES START FROM OPPOSITE STORED FLAGS, and that is what makes
         each one sensitive to its own sabotage. Both assert `false`, but for
         different reasons: the first keeps a stored false (so the plain !needsFix
         inversion, which returns true, flips it and goes red), the second overrides
         a stored true (so returning null, which keeps it, goes red). Starting both
         from the same flag left one of them green against the very bug it names. */
      {
        const S = season();                                     // fix row starts done:false
        const B = { b: { completed: true } };                   // never flagged for a fix
        build(B)(S, B, { n: 0 }).refresh();
        check('S127', 'a fix whose customer was never flagged keeps the plan\'s flag',
          S[0].houses.find(h => h.id === 'cust-f').done === false,
          'the plain !needsFix inversion reads a missing field as DONE and hides ' +
          'every outstanding fix on the schedule');
      }
      {
        const S = season();
        S[0].houses.find(h => h.id === 'cust-f').done = true;   // same starting point
        const B = { b: { completed: true, needsFix: true } };
        build(B)(S, B, { n: 0 }).refresh();
        check('S127', 'but an explicitly flagged customer overrides it',
          S[0].houses.find(h => h.id === 'cust-f').done === false,
          'needsFix:true is a real answer and means there is still a fix outstanding, ' +
          'whatever the plan had ticked');
      }
    }
  }

  /* ---- wired into the one render entry point, before anything reads ---- */
  {
    const ra = extractFn(admin, 'renderAll');
    check('S127', 'renderAll refreshes before it counts, draws or saves',
      !!ra && /refreshDerivedDone\(\)\s*;\s*computeDates\(\)/.test(ra),
      'renderStats counts what is left and scheduleSave writes the plan back — ' +
      'refreshing after either is refreshing too late');
    /* ⚠ THE OPTIMISTIC MIRROR. The Firestore write is asynchronous and the tick is
       now DERIVED, so without this renderAll re-derives from the stale cache and the
       tick visibly springs back — and the office presses it again. */
    const tick = extractFn(admin, 'planTickCustomer');
    check('S127', 'a tick mirrors into the local customer cache before awaiting',
      !!tick && /cust\.data\.completed = done/.test(tick) &&
      /cust\.data\.removalDone = done/.test(tick) &&
      /cust\.data\.needsFix = !done/.test(tick),
      'the panel repaints from the cache, not from Firestore — without the mirror ' +
      'the tick springs back and gets pressed twice');
    /* ⚠ AND THE MIRROR HAS TO COVER ALL THREE KINDS, or ticking a takedown looks
       like it did nothing. */
    check('S127', 'and the mirror is by kind, not always completed',
      !!tick && tick.indexOf("kind === 'takedown'") !== -1 &&
      tick.indexOf("kind === 'fix'") !== -1,
      'mirroring completed for a takedown tick shows the wrong row changing');
  }

  /* ⭐ THE BULK TICKS REPORT ONCE, NOT ONCE PER HOUSE. All done and the leftover
     flow run planTickCustomer over every house on a day, and on an imported plan
     that has not been through Recalculate everything NOTHING resolves — so a loud
     toast per house was forty identical messages stacked for one press, which is
     how a warning stops being read at all. The single tick stays loud: one house,
     and the office is looking straight at it. */
  {
    const tick = extractFn(admin, 'planTickCustomer');
    check('S127', 'planTickCustomer can be told to stay quiet, and reports back',
      !!tick && /opts && opts\.quiet/.test(tick) && /return false;/.test(tick) &&
      /return true;/.test(tick),
      'a caller that runs it over forty houses needs to know how many missed');
    const allBtn = admin.slice(admin.indexOf('if(t.dataset.allbtn)'),
                               admin.indexOf('renderAll();return;}', admin.indexOf('if(t.dataset.allbtn)')));
    check('S127', 'All done counts the unlinked stops and says it once',
      /\{quiet:true\}/.test(allBtn) && /unlinked\+\+/.test(allBtn) &&
      /if\(unlinked\)/.test(allBtn),
      'forty identical toasts for one press is how a warning stops being read');
    const leftover = extractFn(admin, 'applyLeftoverPicks');
    check('S127', 'and so does the leftover flow',
      !!leftover && /\{quiet:true\}/.test(leftover) && /leftoverUnlinked/.test(leftover),
      'it runs over every house on the day, so it has the same problem');
    /* ⚠ A FAILED WRITE IS STILL ALWAYS SAID. It is rare, and it means the money did
       not move — only the "nobody behind this row" case is summarised. */
    check('S127', 'but a failed write is never silenced',
      !!tick && /could not be updated/.test(tick) &&
      tick.indexOf('could not be updated') > tick.indexOf('opts.quiet'),
      'a write that failed is rare and means the money did not move');
  }

  /* ---- the id index that keeps this cheap ---- */
  check('S127', 'customers are indexed by document id',
    /custById\.set\(a\.id, a\)/.test(admin) && /let custById = new Map\(\)/.test(admin),
    'this runs once per house per render; a .find() over ~1,000 customers is the ' +
    'lock-up the other customer indexes were built to stop');
  check('S127', 'and the resolver uses it',
    /custById\.has\(docId\)/.test(admin),
    'an index nothing reads is just memory');
}


/* ---------------------------------------------------------------------------
 * Suite 128. The do-not-send list — automation emails only.
 *
 * Owner, 2026-08-21: "This is only for automation emails filters. I should be
 * able to choose who not to send it too."
 *
 * Every other filter in Preview & Send says who TO write to. This is the only
 * one that says who never gets written to, whatever the other nine say — and it
 * STICKS, which is the whole reason it exists. Unticking somebody already skips
 * them for one send; the failure this closes is Select All quietly picking them
 * back up on the next one.
 *
 * ⚠ THE SAFETY PROPERTY IS THE FIELD NAME. It is `noAutomationEmails`, not
 * `emailOptedOut`, because the obvious name invites the next person to wire it
 * into the nightly invoice run — and a customer who asked to stop being
 * marketed at would silently stop being BILLED. Nobody chases an invoice that
 * was never sent. The checks below assert that the billing and SMS paths have
 * never heard of the field, which is the half that protects money.
 *
 * ⚠ THESE CHECKS RUN THE RENDERER. A regex proving the words are in the file is
 * a weaker claim and this repo has been burned by it repeatedly — most recently
 * the ledger row whose message was built correctly and then overwritten by a
 * default on the line below (CLAUDE.md §5). The list is rendered against a fake
 * DOM and the HTML it produces is what gets asserted.
 * ------------------------------------------------------------------------- */
suite('Suite 128. The do-not-send list — automation emails only');

{
  const flagSrc = extractFn(admin, 'etNoAutomationEmails');
  const renderSrc = extractFn(admin, 'etRenderRecipientList');
  check('S128', 'the flag reader and the recipient renderer are findable',
    !!flagSrc && !!renderSrc,
    'renamed or removed — update this suite rather than deleting it');

  if (flagSrc && renderSrc) {
    /* One builder, so every check runs the REAL renderer. The helpers stubbed
       here (invoice status, billing group, "is new") are not what this suite is
       about and every filter that reads them is left on 'all'; the do-not-send
       logic itself is the shipped code, unmodified. */
    const render = function (book, mode) {
      const list = { innerHTML: '', querySelectorAll: () => [] };
      const countEl = { textContent: '' };
      const doc = {
        getElementById: function (id) {
          if (id === 'etRecipientList') return list;
          if (id === 'etRecipientCount') return countEl;
          return null;
        }
      };
      /* ⚠ LIFTED REAL, NOT STUBBED. The renderer takes the no-email people out at the
         end and counts them, and this is the rule that decides who those are — a stub
         would make the count untestable while reporting green (CLAUDE.md §3). */
      const canEmailSrc = extractFn(admin, 'custCanBeEmailed') || '';
      const env = new Function('document', 'MEMBERS', 'MODE',
        canEmailSrc + flagSrc +
        'let etRecipientSearchTerm = "";' +
        'let etFilterGateCode = "all", etFilterPayment = "all", etFilterRsvp = "all";' +
        'let etFilterPaidLast = "all", etFilterOrderedLast = "all", etFilterNew = "all";' +
        'let etFilterGroup = "all", etFilterOutlet = "all", etFilterInstalled = "all";' +
        'let etRsvpAudienceAutoSet = false;' +
        'let etFilterDoNotSend = MODE;' +
        'function etGetMembers(){ return MEMBERS; }' +
        'function etRsvpAnswered(){ return true; }' +
        'function getLiveInvoiceStatus(){ return "Paid in Full"; }' +
        'function audienceBillingGroup(){ return "own"; }' +
        'function audienceIsNew(){ return false; }' +
        'function audiencePaidLastYear(){ return "paid"; }' +
        'function audienceHasLastSeason(){ return true; }' +
        'function esc(s){ return String(s == null ? "" : s); }' +
        renderSrc +
        ';return etRenderRecipientList;');
      env(doc, book, mode)();
      return { html: list.innerHTML, count: countEl.textContent };
    };

    /* Ann is excluded, Bob is not. Both are otherwise identical and both have an
       email, so nothing except the flag can account for a difference. */
    const book = () => ([
      { id: 'a1', data: { name: 'Ann Excluded', email: 'ann@x.com', phone: '8015550001', noAutomationEmails: true } },
      { id: 'b2', data: { name: 'Bob Sendable', email: 'bob@x.com', phone: '8015550002' } }
    ]);

    /* ---- 1. the normal list leaves them out, and says that it did ---- */
    {
      const r = render(book(), 'hide');
      check('S128', 'somebody on the do-not-send list is not in the normal list',
        r.html.indexOf('Ann Excluded') === -1,
        'the whole point — they must not be selectable, because Select All ticks ' +
        'every row that renders');
      check('S128', 'and everybody else still is',
        r.html.indexOf('Bob Sendable') !== -1,
        'the filter must not take out anyone it was not asked to');
      /* ⚠ SILENTLY SHORTER IS THE FAILURE THIS PANEL ALREADY HAS with missing
         email addresses. Left out, but never left unsaid. */
      check('S128', 'the count line says how many it left out',
        /1 left out: on the do-not-send list/.test(r.count),
        'a list quietly shorter than expected is indistinguishable from a filter bug');
      check('S128', 'and still reports the people who DID match',
        /^1 member matches these filters\./.test(r.count),
        'the exclusion note must not replace the count it is annotating');
    }

    /* ---- 2. the manage view shows exactly the other half ---- */
    {
      const r = render(book(), 'only');
      check('S128', 'the manage view lists the excluded person',
        r.html.indexOf('Ann Excluded') !== -1,
        'there has to be a way to see who is on the list');
      check('S128', 'and nobody else',
        r.html.indexOf('Bob Sendable') === -1,
        'it is a list of the excluded, not a list with them highlighted');
      /* ⚠ THE SELECT ALL SAFETY. A tickable row in the manage view is one press
         of Select All away from mailing exactly the people it records as never
         to be mailed. */
      check('S128', 'the manage view renders NO send checkbox',
        r.html.indexOf('et-recipient-cb') === -1,
        'a tickable row here is one Select All away from mailing the people on ' +
        'the do-not-send list');
      check('S128', 'and offers to put them back',
        /data-dnsval="0"/.test(r.html),
        'a list you cannot get off is a trap, not a feature');
      check('S128', 'the manage count explains itself and disclaims the invoice',
        /on the do-not-send list/.test(r.count) && /does not affect their invoice/.test(r.count),
        'the office has to be able to tell this apart from stopping somebody being billed');
    }

    /* ---- 2b. the people with no address to send to are COUNTED, not just gone ---- */
    /* Owner asked for this to be said at the moment of sending rather than only being
       findable in Customers. Excluding them is right; doing it silently meant an RSVP
       could miss forty people and read exactly like one that reached everybody. */
    {
      const book2 = () => ([
        { id: 'b2', data: { name: 'Bob Sendable',  email: 'bob@x.com',      phone: '2' } },
        { id: 'c3', data: { name: 'Cara Noemail',                           phone: '3' } },
        /* ⚠ NOTHING IN THE APP SENDS TO email2 — it exists so a customer can sign in
           with it — so this person cannot be written to either, and the shared rule
           has to say so here exactly as it does in the Customers filter. */
        { id: 'd4', data: { name: 'Dan Secondary', email2: 'dan@x.com',     phone: '4' } }
      ]);
      const r = render(book2(), 'hide');
      check('S128', 'somebody with no email is not offered as a recipient',
        r.html.indexOf('Cara Noemail') === -1 && r.html.indexOf('Bob Sendable') !== -1,
        'there is nothing to send to — excluding them is right, it is the silence ' +
        'that was the bug');
      check('S128', 'and so is somebody holding only a SECONDARY address',
        r.html.indexOf('Dan Secondary') === -1,
        'no sender in the app reads email2, so this person cannot be written to ' +
        'either — the send panel and the Customers filter share one rule');
      check('S128', 'the count line says how many were left out for that',
        /2 left out: no email address on file/.test(r.count),
        'the whole point: "312 members match" read the same whether it dropped ' +
        'nobody or forty');
      check('S128', 'and says where to go and fix it',
        /Customers . Filters . Email/.test(r.count),
        'a bare number says something is wrong and not what to do about it');
      check('S128', 'the people who DID match are still counted correctly',
        /^1 member matches these filters\./.test(r.count),
        'the exclusion note annotates the count, it does not replace it');
    }

    /* ⚠ THE TRAP THIS GUARD EXISTS FOR. Somebody with no email who is ALSO on the
       do-not-send list must still appear in the manage view, or they are stuck on
       that list for ever with no screen able to release them. */
    {
      const r = render([
        { id: 'e5', data: { name: 'Eve Stuck', phone: '5', noAutomationEmails: true } }
      ], 'only');
      check('S128', 'a no-email person on the list can still be taken off it',
        r.html.indexOf('Eve Stuck') !== -1 && /data-dnsval="0"/.test(r.html),
        'the manage view is not a send list; filtering it by sendability would hide ' +
        'them from the one screen that could release them');
    }

    /* ⚠ AN EMPTY LIST WITH A REASON. "No members match these filters" is actively
       untrue when they DID match and simply cannot be written to. */
    {
      const r = render([{ id: 'f6', data: { name: 'Fay Only', phone: '6' } }], 'hide');
      check('S128', 'an empty list explains itself when everyone lacked an address',
        /no email address on file/.test(r.html) && r.html.indexOf('No members match') === -1,
        'they did match — saying they did not sends the office looking at the filters');
    }

    /* ---- 3. the control that adds somebody, and where it sits ---- */
    {
      const r = render(book(), 'hide');
      check('S128', 'a normal row offers a way onto the list',
        /data-dnsval="1"/.test(r.html),
        'the owner asked to be able to choose who not to send to; this is that control');
      /* ⚠ A BUTTON INSIDE A <label> TOGGLES THAT LABEL'S CHECKBOX. Nested, the
         "Don't send" button would tick the very person it is removing on its way
         out — which renders perfectly and is wrong. */
      const label = r.html.slice(r.html.indexOf('<label'), r.html.indexOf('</label>'));
      check('S128', 'and that control sits OUTSIDE the row label',
        label.indexOf('data-dns') === -1,
        'a button inside a label toggles that label checkbox, so excluding ' +
        'somebody would tick them at the same time');
    }
  }

  /* ---- 4. both LIVE senders honour it ---- */
  /* ⚠ TWO DOORS, ONE LIST. Preview & Send and the older Send Template modal are
     separate senders over the same customers, so a guard in only one means the
     list works or not depending which button was pressed — and nobody would find
     out which. */
  {
    const previewSend = sectionFrom(admin, admin.indexOf("document.getElementById('etSendToSelectedBtn')"));
    const templateSend = sectionFrom(admin, admin.indexOf("document.getElementById('etSendConfirmBtn')"));
    check('S128', 'Preview & Send refuses to mail somebody on the list',
      /etNoAutomationEmails\(member\.data\)/.test(previewSend),
      'the checkboxes are read out of the DOM at send time, so a row ticked just ' +
      'before somebody was added to the list is still a ticked id');
    check('S128', 'and counts them apart from real failures',
      /optedOut\+\+/.test(previewSend) && /do-not-send list/.test(previewSend),
      'a deliberate exclusion is not a failure, and reading it as one hides both');
    check('S128', 'the Send Template modal refuses too',
      /etNoAutomationEmails\(customer\.data\)/.test(templateSend),
      'a guard on one of two doors is a list that works by accident');
    check('S128', 'and its member list leaves them out to begin with',
      /etNoAutomationEmails\(addr\.data\)/.test(sectionFrom(admin, admin.indexOf('function openEmailSendModal'))),
      'being told after pressing send that they were skipped reads as a broken button');
  }

  /* ---- 5. THE MONEY GUARD: billing has never heard of the field ---- */
  /* ⚠ THIS IS THE CHECK THAT PROTECTS THE BUSINESS, not the customer. If this
     ever fails, somebody has wired a marketing preference into billing and a
     customer has stopped being invoiced without anyone deciding that. */
  {
    const fns = read('functions/index.js');
    check('S128', 'the server has never heard of noAutomationEmails',
      fns.indexOf('noAutomationEmails') === -1,
      'nightly invoicing, the quote nudge and the SMS path all live here — a ' +
      'refusal to be marketed at is not a refusal to be told what you owe');
    /* The invoice the customer is actually shown and emailed. Anchored on a
       function that really exists, so this cannot pass by slicing nothing. */
    const invDoc = sectionFrom(admin, admin.indexOf('function buildInvoiceDocHtml'));
    check('S128', 'the invoice document builder is findable',
      invDoc.length > 200,
      'renamed — repoint this check rather than dropping it, it is the money guard');
    check('S128', 'and no invoice path in admin consults it either',
      invDoc.indexOf('noAutomationEmails') === -1,
      'same reason — this list must never be able to stop a bill going out');
  }

  /* ---- 6. it opens honoured, every time ---- */
  {
    const openSrc = extractFn(admin, 'openSendModal');
    check('S128', 'opening the modal resets the list filter to "hide", not "all"',
      /etFilterDoNotSend = 'hide'/.test(openSrc || ''),
      '"I forgot to re-apply it" must never be a way somebody on the list gets mailed');
    check('S128', 'and it is kept out of the reset-everything-to-all loop',
      !/'etFilterDoNotSend'[^\]]*\]\.forEach/.test(openSrc || '') &&
      (openSrc || '').indexOf("'etFilterInstalled'].forEach") !== -1,
      'that loop sets every id it names to "all"; there is no "all" here on purpose');
  }

  /* ---- 7. the control survives a re-render ---- */
  /* ⚠ THE ROW IS REBUILT BY innerHTML ON EVERY KEYSTROKE. A listener bound to the
     button is thrown away with the row it was attached to, leaving a button that
     renders perfectly and does nothing — which has shipped in this file before
     (the recycle "bin says" box, 2026-08-21). */
  {
    const delegated = sectionFrom(admin, admin.indexOf("document.getElementById('etRecipientList')?.addEventListener"));
    check('S128', 'the add/remove control is delegated to the list container',
      delegated.indexOf('[data-dns]') !== -1,
      'a per-button listener dies with the row on the next keystroke');
    check('S128', 'it writes the field the renderer reads',
      /updateDoc\(doc\(db,'jobAddresses',id\), \{noAutomationEmails: turnOn\}\)/.test(delegated),
      'something must write what something else reads — CLAUDE.md §1');
    /* ⚠ THE PANEL REPAINTS FROM THE CACHE, NOT FROM FIRESTORE. Without the mirror
       the row springs back and the office presses it again, putting two writes in
       flight for one decision. */
    /* ⚠ THE PRESENCE TEST IS LOAD-BEARING, and this check was caught being vacuous
       by its own red-check: with the mirror line DELETED, indexOf returns -1, and
       -1 is less than the position of the await, so an ordering-only comparison
       reported PASS against code that had no mirror at all. */
    const mirrorAt = delegated.indexOf('member.data.noAutomationEmails = turnOn');
    const awaitAt = delegated.indexOf('await updateDoc');
    check('S128', 'and mirrors into the local cache before awaiting the write',
      mirrorAt !== -1 && awaitAt !== -1 && mirrorAt < awaitAt,
      'this panel repaints from jobAddresses, so an unmirrored tick springs back');
    check('S128', 'a failed write puts it back',
      /member\.data\.noAutomationEmails = before/.test(delegated),
      'a failed write that leaves the change on screen is how somebody gets mailed ' +
      'after being told they never would be');
  }

  /* ---- 8. the preference is VISIBLE where the office works ---- */
  /* Owner: "we should be able to tick those in costumers and it should show on
     invoice and costumers if there is a certain way they don't want to be
     contacted." One array feeds all three screens, so a preference cannot show up
     on one and be missing from another. */
  {
    const prefsFor = extractFn(admin, 'contactPrefsFor');
    const note = extractFn(admin, 'contactPrefsNote');
    const chips = extractFn(admin, 'contactPrefChips');
    check('S128', 'the contact-preference helpers exist',
      !!prefsFor && !!note && !!chips,
      'renamed — the invoice, the customer row and Edit Customer all read these');

    if (prefsFor && note && chips) {
      const constSrc = (admin.match(/const CONTACT_PREFS = \[[\s\S]*?\n\];/) || [''])[0];
      const run = new Function('esc',
        constSrc + prefsFor + note + chips +
        ';return {note: contactPrefsNote, chips: contactPrefChips};')(s => String(s == null ? '' : s));

      check('S128', 'somebody who has asked for nothing gets no line at all',
        run.note({}) === '' && run.chips({}) === '',
        '"Contact preferences: none" on every invoice trains the eye to skip the ' +
        'place the real ones appear');
      check('S128', 'the no-texts preference is named',
        /no text messages/.test(run.note({ smsOptedOut: true })),
        'the owner asked for ANY way they do not want to be contacted, not just email');
      check('S128', 'the no-marketing-email preference is named',
        /no marketing emails/.test(run.note({ noAutomationEmails: true })),
        'this is the flag the do-not-send list sets');
      check('S128', 'and both together read as one sentence',
        (run.note({ smsOptedOut: true, noAutomationEmails: true }).match(/no /g) || []).length === 2,
        'somebody can refuse both, and the invoice has to say so once');
      /* ⚠ THE WORDING IS THE SAFETY FEATURE HERE. The dangerous misreading of a
         no-contact note on a BILL is that it stopped the bill. */
      check('S128', 'the tickbox says what it does not stop',
        /still get their invoice and account notices/.test(admin),
        'the one dangerous misreading of this box is that it stops their bill too');
    }

    /* ⚠ THE INVOICE IS HANDED A STRING, NEVER THE FLAGS. This is what makes the
       printed line structurally incapable of becoming a reason not to bill
       somebody — the builder cannot branch on what it never receives. */
    const invDoc2 = sectionFrom(admin, admin.indexOf('function buildInvoiceDocHtml'));
    check('S128', 'the invoice prints the preference',
      invDoc2.indexOf('contactPrefsNote(d)') !== -1,
      'the owner asked for it to show on the invoice');
    check('S128', 'and is never handed the raw flags to branch on',
      invDoc2.indexOf('smsOptedOut') === -1 && invDoc2.indexOf('noAutomationEmails') === -1,
      'a builder that can see the flag is a builder that can be made to gate a bill');

    check('S128', 'the customer row shows it too',
      sectionFrom(admin, admin.indexOf('function renderAllCustomersTable')).indexOf('contactPrefChips(r.d)') !== -1,
      'a preference nobody can see from the customer list gets broken by whoever ' +
      'is looking at the screen that does not say');

    /* The tick the owner asked for, and the write behind it. */
    check('S128', 'Edit Customer offers the tickbox',
      admin.indexOf('id="editCustNoAutoEmails"') !== -1,
      'owner: "we should be able to tick those in costumers"');
    check('S128', 'it is filled in from the record when the form opens',
      /editCustNoAutoEmails'\)\.checked = d\.noAutomationEmails === true/.test(admin),
      'a box that never shows the saved value reads as the setting not sticking');
    check('S128', 'and saving writes the same field the send panel reads',
      /noAutomationEmails: newNoAutoEmails/.test(admin),
      'two doors onto one fact — a second field here is the one that drifts');
  }

  /* ---- 9. finding who has no email, from Customers ---- */
  /* Owner: "just make a filter in costumer were i can see who has no email."
     An invoice only ever goes by email and Automation Emails drops these people
     before any other filter runs, so somebody with no address silently misses their
     bill AND every RSVP — and no screen in Customers could name them. */
  {
    const canSrc = extractFn(admin, 'custCanBeEmailed');
    const chipSrc = extractFn(admin, 'custEmailChip');
    check('S128', 'the can-we-email-them rule and its chip are findable',
      !!canSrc && !!chipSrc,
      'renamed — the Customers filter and the row badge both read these');

    if (canSrc && chipSrc) {
      const api = new Function('esc', canSrc + chipSrc +
        ';return {can: custCanBeEmailed, chip: custEmailChip};')(s => String(s == null ? '' : s));

      check('S128', 'a customer with an email can be emailed',
        api.can({ email: 'a@b.com' }) === true);
      check('S128', 'a blank one cannot',
        api.can({}) === false && api.can({ email: '   ' }) === false,
        'whitespace is not an address; the send would fail on it');
      /* ⚠ THE WHOLE POINT OF THE RULE. Nothing in the app sends to email2 — it
         exists so a customer can SIGN IN with it — so a record holding only a
         secondary address cannot be emailed by anything at all. Counting it as
         reachable puts exactly the people this filter was asked for back into the
         reachable pile, still silently missing their bill. */
      check('S128', 'a SECONDARY-only address still counts as unreachable',
        api.can({ email2: 'only@secondary.com' }) === false,
        'no sender in the app reads email2 — the nightly invoice run, both ' +
        'automation-email senders and the quote nudge all read `email`');
      check('S128', 'and that case is badged differently, not just as "No email"',
        /Secondary email only/.test(api.chip({ email2: 'only@secondary.com' })) &&
        /No email/.test(api.chip({})),
        '"no email" beside a record with a visible address reads as a bug rather ' +
        'than as a field that needs moving up');
      check('S128', 'somebody reachable gets no chip at all',
        api.chip({ email: 'a@b.com' }) === '',
        'a badge on every row is a badge nobody reads');
    }

    const render = sectionFrom(admin, admin.indexOf('function renderAllCustomersTable()'));
    check('S128', 'the Customers table reads the Email filter',
      /allCustFilterEmail/.test(render) && /custCanBeEmailed\(r\.d\)/.test(render),
      'the control has to be read where the rows are filtered, not just exist');
    check('S128', 'and shows the chip on the row',
      /custEmailChip\(r\.d\)/.test(render),
      'the filter finds them; the chip is how you spot one without filtering');

    /* ⚠ A SELECT WITH NO LISTENER RENDERS PERFECTLY AND DOES NOTHING. This is not
       hypothetical: allCustFilterLights shipped that way and was found here, on
       2026-08-21, while the Email one was being added — picking "On soft" redrew
       nothing unless you happened to touch another filter afterwards. Every select
       in that panel is asserted wired, so the next one cannot repeat it. */
    const wiring = (admin.match(/\['allCustFilterCity'[\s\S]*?\]\.forEach/) || [''])[0];
    ['allCustFilterEmail', 'allCustFilterLights', 'allCustFilterPin', 'allCustFilterMap',
     'allCustFilterCity', 'allCustFilterDifficulty', 'allCustFilterInvStatus', 'allCustFilterRoute']
      .forEach(function (id) {
        check('S128', 'the ' + id.replace('allCustFilter', '') + ' filter actually redraws when changed',
          wiring.indexOf("'" + id + "'") !== -1,
          'it is in the markup and read by the renderer, but nothing listens to it');
      });

    const clear = sectionFrom(admin, admin.indexOf("document.getElementById('allCustFilterClear')"));
    ['allCustFilterEmail', 'allCustFilterLights', 'allCustFilterPin'].forEach(function (id) {
      check('S128', 'Clear Filters resets ' + id.replace('allCustFilter', ''),
        clear.indexOf(id) !== -1,
        'a filter left applied by Clear Filters leaves the list mysteriously short');
    });
  }

  /* ---- 10. the four dead senders are still dead ---- */
  /* ⚠ NOT DECORATION. sendRsvpEmailBtn, sendBulkUpdateEmailBtn and the two pib*
     buttons all send email to customers and NONE of them has any markup — every
     id is in KNOWN_MISSING_IDS, so the handlers return at their first line. That
     is the only reason they need no guard. If one is ever built, this check fails
     and whoever builds it has to decide about the do-not-send list first.
     Same pattern as Suite 72 and for the same reason. */
  {
    ['sendRsvpEmailBtn', 'sendBulkUpdateEmailBtn', 'pibSendUnpaidBtn', 'pibSendPaidBtn'].forEach(function (id) {
      check('S128', 'the dead sender ' + id + ' still has no markup',
        admin.indexOf('id="' + id + '"') === -1,
        'it sends email to customers. Building it means deciding whether the ' +
        'do-not-send list applies — see this suite, section 4');
    });
  }
}

/* ⚠ RENUMBERED 2026-08-21 ON A MERGE. These arrived as Suites 128-130; a
   parallel session landed its own Suite 128 (the do-not-send list, just
   above) on main first, so theirs keeps the number and these moved up.
   BOTH SURVIVE — a numbering collision must never cost a suite, exactly as
   it must never cost a checklist row. The check labels moved with them
   (S128-S130 -> S137-S139) so a failure still names one suite, not two.
   ⚠ The lone `}` after this region closes the LAST block only, so the one
   added just above closes theirs. Concatenating two open blocks under one
   brace is what made the first two attempts at this merge fail to parse. */
/* =====================================================================
 * Suite 137. A decline asks a question, it does not cancel their season
 *
 * HOLE A, fixed 2026-08-21 — and REWRITTEN the same day, because the first fix
 * over-reached and the owner caught it.
 *
 * What the hole was: declining set quoteArchived and NOTHING else. An existing
 * member who pressed Decline kept rsvpStatus 'yes', was never recycled, and
 * stayed on any route already built, so a crew drove to a house that had said
 * no — and nobody in the office was told.
 *
 * ⚠ WHAT THE FIRST FIX GOT WRONG, and why this suite was inverted rather than
 * deleted: it treated a decline as an RSVP "no" — out for the season, lights
 * flagged to come back, off the routes. Owner: "if an existing costumer denies
 * a requote, than can we mark them as email or something like that were we can
 * ask them if they just want us to do what we did last year of there house",
 * and "we can email them asking them if they want to do there normal lights
 * with there normal bill instead."
 *
 * She is right, and it is obvious once said: somebody turning down a NEW price
 * or a NEW scope has not said they want no lights. Most of them want exactly
 * what they had last year. Recycling their set and cancelling their season is
 * the one answer nobody asked for, and it is expensive to undo.
 *
 * ⚠ SO NO DECLINE ANYWHERE RECYCLES ANY MORE. Leaving the season is said
 * through the RSVP, and portalRsvp('no') still does all of it. The checks below
 * that assert nothing moved USED to assert the opposite; they are inverted, not
 * removed, so the old behaviour cannot come back unnoticed.
 *
 * ⚠ THIS SUITE RUNS THE SHIPPED FUNCTION against a fake Firestore and reads the
 * document the customer would really have been left with. A regex over the
 * source proves the words exist, which is a weaker claim: this repo has already
 * shipped a fee written 63 lines after the write meant to save it, with every
 * text check green. Nothing is stubbed — quoteCustomerRef,
 * quoteMatchesExistingCustomer, quoteMatchAddressServer, tryFirestore,
 * flagQuoteFollowUp and digitsOnly are all the real ones.
 * ===================================================================== */
suite('Suite 137. A decline asks a question, it does not cancel their season');
{
  const fns = read('functions/index.js');

  const NEEDED = ['declineAsksAboutLastYear', 'quoteCustomerRef',
    'quoteMatchesExistingCustomer', 'quoteMatchAddressServer', 'digitsOnly',
    'tryFirestore', 'flagQuoteFollowUp'];
  const src = {};
  NEEDED.forEach(n => { src[n] = extractFn(fns, n); });
  const missing = NEEDED.filter(n => !src[n]);
  check('S137', 'every function this suite runs is findable',
    !missing.length,
    'missing: ' + missing.join(', ') + ' — fix the extraction list rather than ' +
    'stubbing, or the suite passes on code it never supplied');

  /* ⚠ THE OLD NAME MUST BE GONE, not left beside the new one. Two functions
     both claiming to answer "what does a decline do" is how one of them starts
     recycling people again. */
  check('S137', 'the old cancel-the-season path is gone, not left alongside',
    !/async function declineReachesCustomer/.test(fns),
    'a second answer to the same question is the one that goes wrong');

  const ASYNC = ['declineAsksAboutLastYear', 'quoteCustomerRef',
    'quoteMatchesExistingCustomer', 'tryFirestore', 'flagQuoteFollowUp'];
  ASYNC.forEach(n => {
    check('S137', n + ' is still async in the real file',
      new RegExp('async function ' + n + '\\(').test(fns),
      'extractFn drops the keyword and the lift below puts it back — if it ' +
      'stops being async there, this suite runs a different shape');
  });

  const statusDecl = fns.match(/const QUOTE_RAISED_STATUSES_SERVER = \[[^\]]*\];/);
  check('S137', 'the quote-raised status list is findable', !!statusDecl);

  if (!missing.length && statusDecl) {
    /* HU_RETRY_PAUSE_MS zeroed: the real 400ms fires on every failure fixture
       and the whole run has to stay under a minute (CLAUDE.md §9.8). Asserted
       non-zero in the real file by Suite 139. */
    const body = 'const HU_RETRY_PAUSE_MS = 0;\n' + statusDecl[0] + '\n' +
      NEEDED.map(n => (ASYNC.indexOf(n) !== -1 ? 'async ' : '') + src[n]).join('\n');

    function makeWorld(opts) {
      const o = opts || {};
      const customers = {};
      Object.keys(o.customers || {}).forEach(k => {
        customers[k] = Object.assign({}, o.customers[k]);
      });
      const messages = [], quoteWrites = [], errors = [];

      const db = {
        collection: (c) => {
          if (c === 'jobAddresses') {
            return {
              doc: (id) => ({
                get: () => Promise.resolve({
                  exists: Object.prototype.hasOwnProperty.call(customers, id),
                  id: id, data: () => customers[id]
                }),
                update: (patch) => {
                  if (o.failCustomerUpdate) return Promise.reject(new Error('boom'));
                  Object.assign(customers[id], patch);
                  return Promise.resolve();
                }
              }),
              /* ⚠ where(field, OP, value) — THREE arguments. A fake reading the
                 second as the value compares everything against "==" and matches
                 nobody; that cost a debugging round once and is written down so
                 it does not cost another. */
              where: (field, op, value) => ({
                limit: () => ({
                  get: () => Promise.resolve({
                    docs: Object.keys(customers)
                      .filter(k => customers[k][field] === value)
                      .map(k => ({ id: k, data: () => customers[k] }))
                  })
                })
              })
            };
          }
          if (c === 'messages') {
            return { add: (m) => {
              if (o.failMessage) return Promise.reject(new Error('too long'));
              messages.push(m); return Promise.resolve({});
            } };
          }
          if (c === 'quotes') {
            return { doc: (id) => ({ update: (patch) => {
              quoteWrites.push({ id, patch }); return Promise.resolve();
            } }) };
          }
          throw new Error('the fake was asked for an unexpected collection: ' + c);
        }
      };

      const run = new Function('db', 'admin', 'console',
        body + ';return declineAsksAboutLastYear;')(db,
        { firestore: { FieldValue: { serverTimestamp: () => '@ts' } } },
        { error: (...a) => errors.push(a.join(' ')), log: () => {} });

      return { run, customers, messages, quoteWrites, errors };
    }

    /* A member mid-season: lights going up, on a route, and sitting in Needs
       Changes because a re-quote asked them a question. */
    const member = (extra) => Object.assign({
      name: 'Rachel Oslund', phone: '(801) 555 0100', phoneDigits: '8015550100',
      address: '209 S 850 W', rsvpStatus: 'yes', seasonStatus: 'needs_changes',
      needsLightRecycle: false, needsLightBuild: true,
      scheduled: true, scheduledDate: '2099-12-01', assignedCrew: 'Crew 1'
    }, extra || {});

    pendingAsync.push((async () => {

      /* ---- 1. the whole point: they are marked to be asked ------------- */
      {
        const w = makeWorld({ customers: { c1: member() } });
        const before = JSON.stringify(w.customers.c1);
        const res = await w.run({ existingCustomerId: 'c1', name: 'Rachel Oslund' }, 'q1');

        check('S137', 'a decline reaches the linked customer record',
          res.reached === true && res.askedAboutLastYear === true,
          'the original hole: the quote was archived and the customer never ' +
          'heard about it');
        check('S137', 'they are marked to be asked about last year',
          w.customers.c1.askSameAsLastYear === true &&
          !!w.customers.c1.askSameAsLastYearAt,
          'this is the flag the Automation Emails audience picker reads, so the ' +
          'office can mail everyone waiting on that one question at once');
        check('S137', 'and the re-quote question is closed',
          w.customers.c1.seasonStatus === 'confirmed',
          'the portal sets needs_changes when it raises a re-quote and only an ' +
          'ANSWER clears it — left set they sit in Needs Changes for ever');

        /* ⚠ EVERY ONE OF THESE USED TO ASSERT THE OPPOSITE. Inverted, not
           deleted, so a return to "a decline cancels the season" goes red. */
        check('S137', 'they are still in for the season',
          w.customers.c1.rsvpStatus === 'yes' && !w.customers.c1.rsvpRespondedAt,
          'turning down a new price is not saying you want no lights — most of ' +
          'them want exactly what they had last year');
        check('S137', 'their lights are NOT flagged to come back',
          w.customers.c1.needsLightRecycle === false,
          'recycling breaks a real bundle back into stock; if they only wanted ' +
          'last year repeated, somebody has to build it all again');
        check('S137', 'their build is left alone',
          w.customers.c1.needsLightBuild === true,
          'cancelling a queued build nobody cancelled');
        check('S137', 'and they stay scheduled, on their crew, on their date',
          w.customers.c1.scheduled === true &&
          w.customers.c1.scheduledDate === '2099-12-01' &&
          w.customers.c1.assignedCrew === 'Crew 1',
          'their route is expensive to rebuild and they never asked to leave it');

        /* Byte-identical apart from the two fields it may touch. Stronger than
           naming them: it also catches a field added later that nobody thought
           to assert. */
        const after = JSON.parse(JSON.stringify(w.customers.c1));
        const start = JSON.parse(before);
        ['askSameAsLastYear', 'askSameAsLastYearAt', 'seasonStatus']
          .forEach(k => { delete after[k]; delete start[k]; });
        check('S137', 'and NOTHING else on the record moved at all',
          JSON.stringify(after) === JSON.stringify(start),
          'a decline may set the question flag and close the re-quote, nothing more');

        /* ---- the inbox notification the owner asked for ---------------- */
        check('S137', 'exactly one System note is raised',
          w.messages.length === 1 && w.messages[0].folder === 'System',
          'nothing else about this customer moved, so without a note there is ' +
          'no trace anywhere that a question is outstanding');
        check('S137', 'and it says this is not a cancellation, and what to do',
          /not a cancellation/i.test(w.messages[0].message || '') &&
          /Rachel Oslund/.test(w.messages[0].message || '') &&
          /normal lights/i.test(w.messages[0].message || '') &&
          /normal bill/i.test(w.messages[0].message || ''),
          'owner: "we can email them asking them if they want to do there normal ' +
          'lights with there normal bill instead" — a note that says "declined" ' +
          'and stops is one somebody acts on as a cancellation');
        check('S137', 'and no unread flag, so it counts on the sidebar badge',
          w.messages[0].read === undefined,
          'the badge counts every unread message whatever its folder — that is ' +
          'the inbox notification, and a note marked read on arrival is invisible');
      }

      /* ---- 2. a new lead has nothing to be asked about ------------------ */
      {
        const w = makeWorld({ customers: { c1: member() } });
        const res = await w.run({
          name: 'Somebody New', phone: '801 555 0199', address: '1 New St'
        }, 'q1');
        check('S137', 'a first-time lead is not touched at all',
          res.reached === false && w.customers.c1.rsvpStatus === 'yes' &&
          !w.messages.length && !w.customers.c1.askSameAsLastYear,
          'owner: "we won\'t have an info for them yet" — the quote is archived ' +
          'and that is the whole of it');
      }

      /* ---- 3. NEVER BY PHONE ALONE -------------------------------------
         The sharpest edge, and the reason quoteCustomerRef exists. 17 numbers in
         the real book are shared and 14 of those are two genuinely DIFFERENT
         houses — a parent paying for a child's place. The fixture is built so a
         phone match gives the wrong answer: one phone, two real houses, and the
         quote is for the SECOND address. */
      {
        const w = makeWorld({
          customers: {
            parent: Object.assign(member(), { name: 'Parent', address: '10 Elm St' }),
            child: Object.assign(member(), { name: 'Child', address: '99 Oak Ave' })
          }
        });
        const res = await w.run({
          quotedPrice: 400, phone: '(801) 555-0100', address: '99 Oak Ave'
        }, 'q1');
        check('S137', 'a shared phone resolves by ADDRESS, not by whoever comes first',
          res.reached === true &&
          w.customers.child.askSameAsLastYear === true &&
          !w.customers.parent.askSameAsLastYear,
          'the parent would be marked, and mailed, about a question their ' +
          'child was asked — two different households on one number');
      }
      {
        /* ⚠ ONLY ON A PRICED QUOTE. firestore.rules stops a public create from
           setting quotedPrice, so a price is proof staff touched it. Without the
           gate the address fallback is a free "is this address one of your
           customers?" oracle for anybody who can submit the public form — and
           this path WRITES. */
        const w = makeWorld({
          customers: { c1: Object.assign(member(), { address: '99 Oak Ave' }) }
        });
        const res = await w.run({ phone: '(801) 555-0100', address: '99 Oak Ave' }, 'q1');
        check('S137', 'an unpriced quote cannot reach a customer by address',
          res.reached === false && !w.customers.c1.askSameAsLastYear,
          'anyone can create a quote — an unpriced one must never write to a ' +
          'real customer record');
      }

      /* ---- 4. nothing fails silently ----------------------------------- */
      {
        const w = makeWorld({ customers: { c1: member() }, failCustomerUpdate: true });
        const res = await w.run({ existingCustomerId: 'c1' }, 'q1')
          .catch(err => ({ threw: (err && err.message) || 'threw' }));
        check('S137', 'a failed customer write raises no note, only a flag',
          res.reached === false && !w.messages.length &&
          w.quoteWrites.length === 1 && w.quoteWrites[0].patch.followUpNeeded === true,
          'a note claiming a question was raised, when it was not, leaves ' +
          'somebody waiting on an email nobody is going to send');
      }
      {
        const w = makeWorld({ customers: { c1: member() }, failMessage: true });
        const res = await w.run({ existingCustomerId: 'c1' }, 'q1')
          .catch(err => ({ threw: (err && err.message) || 'threw' }));
        check('S137', 'a note that will not write does not sink the answer',
          res.reached === true && w.customers.c1.askSameAsLastYear === true &&
          w.quoteWrites.length === 1,
          'the messages collection caps a body at 5000 characters and reports ' +
          'the refusal as a permissions error (CLAUDE.md) — the flag is what ' +
          'stops that being silent');
      }
      {
        const w = makeWorld({ customers: {} });
        const res = await w.run({ existingCustomerId: 'deleted-since' }, 'q1');
        check('S137', 'a link to a deleted customer is not an error',
          res.reached === false && !w.errors.length,
          'a customer really can have been removed since the quote was raised — ' +
          'that must be handled, not caught');
      }
    })());
  }

  /* ---- the wiring, which no fixture above can see -------------------- */
  const respondSrc = fns.slice(fns.indexOf('exports.quoteRespond = onCall'));
  check('S137', 'the decline branch actually calls it',
    /await declineAsksAboutLastYear\(quoteData, quoteId\)/.test(stripComments(respondSrc)),
    'the best-tested function in the world does nothing if the button does not ' +
    'press it');

  const declSrc = stripComments(extractFn(fns, 'declineAsksAboutLastYear') || '');
  check('S137', 'a decline never goes through the back-next-year path',
    !/pullCustomerFromSeason/.test(declSrc),
    'that path marks them maybeNextYear and clears their build — it is the ' +
    'answer to a different question');
  /* ⚠ AND IT TOUCHES NEITHER WAREHOUSE FLAG. Asserted on the source as well as
     by the fixture above, because a fixture only proves the fields it names. */
  check('S137', 'and writes neither warehouse flag',
    !/needsLightRecycle/.test(declSrc) && !/needsLightBuild/.test(declSrc),
    'leaving the season is said through the RSVP, and portalRsvp is where the ' +
    'recycle belongs');

  /* ---- the office side: the flag has to be readable and reachable ----- */
  const admin = read('admin.html');
  /* ⚠ SCOPED TO THE FILTER ITSELF. A file-wide /declinedrequote/ passed with the
     filter deleted outright, because the word still appears in the dropdown
     markup — the red-check caught it. The option and the code behind it are two
     different things and an option that filters nothing is worse than none. */
  check('S137', 'the office can pick them as an email audience',
    /etFilterRsvp === 'declinedrequote'\) members = members\.filter\(m => !!m\.data\.askSameAsLastYear\)/
      .test(stripComments(admin)) &&
    /<option value="declinedrequote">/.test(admin),
    'owner asked to be able to EMAIL them — a flag with no audience filter is ' +
    'a fact nobody can act on in bulk, and an option with no filter behind it ' +
    'silently mails the wrong people');
  check('S137', 'and sees it on their row',
    /Ask about last year/.test(admin),
    'the one place somebody looking at that customer would expect to find out');
  /* ⚠ THE QUESTION NEEDS A WAY OUT, or they stay on the list for ever and get
     mailed again after they have already replied. An RSVP answer IS the reply. */
  check('S137', 'answering the RSVP clears the question',
    /askSameAsLastYear: false/.test(stripComments(fns)),
    'a state with no exit is the hole this whole job exists to close');
  check('S137', 'and the portal can read it',
    /'askSameAsLastYear'/.test(fns),
    'in PORTAL_READ_FIELDS so the portal cannot contradict the office about a ' +
    'question that is still open');
}

/* =====================================================================
 * Suite 138. Declining an add-on refuses the add-on, not the season
 *
 * Owner, 2026-08-21: "they can choose to say no to peice of there house or keep
 * all of it... I don't want a decline on a garage to decline full quote just
 * garage."
 *
 * Hole A (Suite 128) made a decline reach the customer record — mark them out
 * for the season, flag their lights to come back, pull them off the routes.
 * That is right for every decline EXCEPT an add-on: somebody quoted for a back
 * garage on a house that is already lit is answering a question about the
 * garage. Doing the season thing to them cancels a customer who is staying, and
 * sends a crew's house to the recycle list while the crew is still going to it.
 *
 * ⚠ TWO COPIES OF THE KIND RULE, ONE ON EACH SIDE OF THE WIRE, and this suite
 * RUNS both over every kind rather than reading either. Same reasoning as
 * money-parity: the browser renders the quote card, the bulk nudge and
 * Automation Emails; the server renders the nightly nudge; and the copy nobody
 * looks at is the one on the email the customer actually gets.
 * ===================================================================== */
suite('Suite 138. Declining an add-on refuses the add-on, not the season');
{
  const fns = read('functions/index.js');
  const admin = read('admin.html');
  const idx = read('index.html');

  const lift = (src, name) => {
    const i = src.indexOf('function ' + name + '(');
    if (i === -1) return null;
    let d = 0;
    for (let j = src.indexOf('{', i); j < src.length; j++) {
      if (src[j] === '{') d++;
      else if (src[j] === '}') { d--; if (!d) return src.slice(i, j + 1); }
    }
    return null;
  };

  /* ---- 1. the two copies of "is this an add-on" agree ----------------- */
  const isAddOnB = lift(admin, 'quoteIsAddOn');
  const isAddOnS = lift(fns, 'quoteIsAddOn');
  const labelsB = lift(admin, 'quoteButtonLabels');
  const labelsS = lift(fns, 'quoteButtonLabelsServer');
  check('S138', 'both copies of the kind rule and the labels are findable',
    !!isAddOnB && !!isAddOnS && !!labelsB && !!labelsS,
    'renamed or moved — fix the lift rather than deleting the parity check');

  if (isAddOnB && isAddOnS && labelsB && labelsS) {
    const runB = new Function(isAddOnB + '\n' + labelsB +
      '\nreturn {is: quoteIsAddOn, labels: quoteButtonLabels};')();
    const runS = new Function(isAddOnS + '\n' + labelsS +
      '\nreturn {is: quoteIsAddOn, labels: quoteButtonLabelsServer};')();

    /* Every shape a real quote can arrive in, plus the ones that have caused
       trouble in this file before: a missing field, a stray case, whitespace
       from a paste, and a value nobody has invented yet. */
    const KINDS = [
      {}, { requoteKind: 'addition' }, { requoteKind: 'address' },
      { requoteKind: 'price' }, { requoteKind: '' }, { requoteKind: null },
      { requoteKind: 'ADDITION' }, { requoteKind: ' addition ' },
      { requoteKind: 'Addition' }, { requoteKind: 'additional' },
      { requoteKind: 'something-new' },
      /* ⚠ A LINKED CUSTOMER IS NOT AN ADD-ON. Every re-quote has one, so a
         looser test would turn every decline into an add-on decline and nobody
         would ever leave the season again. */
      { existingCustomerId: 'c1' },
      { existingCustomerId: 'c1', convertedToCustomerAt: 'x' }
    ];
    const disagreed = KINDS.filter(q => runB.is(q) !== runS.is(q));
    check('S138', 'the browser and the server agree what an add-on is',
      !disagreed.length,
      'disagreed on: ' + JSON.stringify(disagreed) + ' — the office would word ' +
      'the email one way and the server would act the other');

    const labelDiff = KINDS.filter(q =>
      JSON.stringify(runB.labels(q)) !== JSON.stringify(runS.labels(q)));
    check('S138', 'and they put the same words on the same three buttons',
      !labelDiff.length,
      'disagreed on: ' + JSON.stringify(labelDiff) + ' — the nightly nudge and ' +
      'the office send are the SAME email to the customer');

    /* ⚠ AND THE ANSWERS ARE RIGHT, not merely equal. Two copies wrong in the
       same way agree perfectly — the lesson money-parity already carries. */
    check('S138', 'only an addition counts',
      runS.is({ requoteKind: 'addition' }) === true &&
      runS.is({ requoteKind: 'address' }) === false &&
      runS.is({ requoteKind: 'price' }) === false &&
      runS.is({}) === false &&
      runS.is({ existingCustomerId: 'c1' }) === false,
      'a move and a price change are about the whole job, so a no there is a ' +
      'no to the season, exactly as it has always been');
    check('S138', 'and a stray case or a pasted space does not change the answer',
      runS.is({ requoteKind: 'ADDITION' }) === true &&
      runS.is({ requoteKind: ' addition ' }) === true &&
      runS.is({ requoteKind: 'additional' }) === false,
      'the value is written by one dropdown today, but a value that misses ' +
      'silently cancels somebody\'s season');

    check('S138', 'the add-on decline button says what it does',
      /just my usual lights/.test(runS.labels({ requoteKind: 'addition' }).decline) &&
      runS.labels({}).decline === 'Decline Quote',
      '"Decline Quote" on an add-on reads as declining the whole thing — which ' +
      'is the confusion this job exists to remove');
    check('S138', 'and the approve button does too',
      runS.labels({ requoteKind: 'addition' }).approve === 'Yes, add it' &&
      runS.labels({}).approve === 'Approve Quote',
      'they are approving an addition, not signing up');
  }

  /* ---- 2. declineAddOnOnly, RUN ---------------------------------------- */
  const NEED = ['declineAddOnOnly', 'quoteCustomerRef', 'quoteMatchesExistingCustomer',
    'quoteMatchAddressServer', 'digitsOnly', 'tryFirestore', 'flagQuoteFollowUp'];
  const parts = {};
  NEED.forEach(n => { parts[n] = lift(fns, n); });
  const gone = NEED.filter(n => !parts[n]);
  check('S138', 'every function the behaviour checks run is findable',
    !gone.length, 'missing: ' + gone.join(', '));

  /* The statuses list is read OUT of the file rather than retyped, so tightening
     the real rule cannot leave this check agreeing with a stale copy. */
  const statusDecl = fns.match(/const QUOTE_RAISED_STATUSES_SERVER = \[[^\]]*\];/);
  check('S138', 'the quote-raised status list is findable', !!statusDecl);

  if (!gone.length && statusDecl) {
    const ASYNC = ['declineAddOnOnly', 'quoteCustomerRef', 'quoteMatchesExistingCustomer',
      'tryFirestore', 'flagQuoteFollowUp'];
    ASYNC.forEach(n => {
      check('S138', n + ' is still async in the real file',
        new RegExp('async function ' + n + '\\(').test(fns),
        'the lift below puts the keyword back — if it stops being async there, ' +
        'this suite is running a different shape from production');
    });
    const body = 'const HU_RETRY_PAUSE_MS = 0;\n' + statusDecl[0] + '\n' + NEED.map(n =>
      (ASYNC.indexOf(n) !== -1 ? 'async ' : '') + parts[n]).join('\n');

    function makeWorld(seed, opts) {
      const o = opts || {};
      const customers = {};
      Object.keys(seed || {}).forEach(k => { customers[k] = Object.assign({}, seed[k]); });
      const messages = [], errors = [];
      const db = {
        collection: (c) => {
          if (c === 'jobAddresses') {
            return {
              doc: (id) => ({
                get: () => Promise.resolve({
                  exists: Object.prototype.hasOwnProperty.call(customers, id),
                  id: id, data: () => customers[id]
                }),
                update: (patch) => {
                  if (o.failUpdate) return Promise.reject(new Error('boom'));
                  Object.assign(customers[id], patch);
                  return Promise.resolve();
                }
              }),
              /* where('phoneDigits','==',v) — THREE arguments. A fake that reads
                 the second as the value compares everything against "==" and
                 silently matches nobody; that cost a debugging round in Suite
                 128 and is written down here so it does not cost another. */
              where: (field, op, value) => ({
                limit: () => ({
                  get: () => Promise.resolve({
                    docs: Object.keys(customers)
                      .filter(k => customers[k][field] === value)
                      .map(k => ({ id: k, data: () => customers[k] }))
                  })
                })
              })
            };
          }
          if (c === 'messages') {
            return { add: (m) => { if (o.failMessage) return Promise.reject(new Error('too long')); messages.push(m); return Promise.resolve({}); } };
          }
          throw new Error('unexpected collection: ' + c);
        }
      };
      const adminNs = { firestore: { FieldValue: { serverTimestamp: () => '@ts' } } };
      const run = new Function('db', 'admin', 'console',
        body + ';return declineAddOnOnly;')(db, adminNs,
        { error: (...a) => errors.push(a.join(' ')), log: () => {} });
      return { run, customers, messages, errors };
    }

    /* A customer mid-season with a garage on order: lights up, on a route, and
       sitting in Needs Changes because the re-quote asked them a question. */
    const inSeason = (extra) => Object.assign({
      name: 'Rachel Oslund', phone: '(801) 555 0100', phoneDigits: '8015550100',
      address: '209 S 850 W', rsvpStatus: 'yes', seasonStatus: 'needs_changes',
      needsLightRecycle: false, needsLightBuild: true,
      scheduled: true, scheduledDate: '2099-12-01', assignedCrew: 'Crew 1'
    }, extra || {});

    pendingAsync.push((async () => {

      /* ---- the whole point: the season is untouched ------------------- */
      {
        const w = makeWorld({ c1: inSeason() });
        const before = JSON.stringify(w.customers.c1);
        const res = await w.run({ existingCustomerId: 'c1', requoteKind: 'addition' });

        check('S138', 'the customer is still in for the season',
          w.customers.c1.rsvpStatus === 'yes' && !w.customers.c1.rsvpRespondedAt,
          'this is the whole job — turning down a garage must not cancel a ' +
          'customer whose house is being lit next week');
        check('S138', 'their lights are NOT flagged to come back',
          w.customers.c1.needsLightRecycle === false,
          'a set that is going up this season would be listed for collection');
        check('S138', 'and their build is left alone',
          w.customers.c1.needsLightBuild === true,
          'needsLightBuild and buildTopUpFromFeet are written when the office ' +
          'APPLIES a re-quote, which has not happened to one being declined — ' +
          'clearing them "to be safe" cancels a build nobody cancelled');
        check('S138', 'and they stay scheduled, on their crew, on their date',
          w.customers.c1.scheduled === true &&
          w.customers.c1.scheduledDate === '2099-12-01' &&
          w.customers.c1.assignedCrew === 'Crew 1',
          'the crew is still going to that house');

        /* ---- but the question is closed --------------------------------- */
        check('S138', 'the re-quote question is answered and cleared',
          w.customers.c1.seasonStatus === 'confirmed' && res.seasonStatusCleared === true,
          'the portal sets needs_changes when it raises a re-quote and only an ' +
          'ANSWER clears it — "no thanks" is an answer. Left set they sit in ' +
          'Needs Changes for ever with nothing anywhere to clear it');

        /* Everything except seasonStatus is byte-identical to what we started
           with. Stronger than naming the fields: it also catches a field added
           later that nobody thought to assert. */
        const after = JSON.parse(JSON.stringify(w.customers.c1));
        const start = JSON.parse(before);
        delete after.seasonStatus; delete start.seasonStatus;
        check('S138', 'and NOTHING else on the record moved at all',
          JSON.stringify(after) === JSON.stringify(start),
          'seasonStatus is the only field an add-on decline may touch');

        check('S138', 'exactly one System note is raised',
          w.messages.length === 1 && w.messages[0].folder === 'System',
          'nothing else about this customer moved, so without a note the office ' +
          'goes on expecting a garage that is not coming');
        check('S138', 'and it says plainly that this is not a cancellation',
          /not a cancellation/i.test(w.messages[0].message || '') &&
          /Rachel Oslund/.test(w.messages[0].message || ''),
          'a note headed "declined" beside a customer who is staying is worse ' +
          'than no note — somebody acts on it');
      }

      /* ---- address_changed is cleared too; a cancellation is NOT ------- */
      {
        const w = makeWorld({ c1: inSeason({ seasonStatus: 'address_changed' }) });
        await w.run({ existingCustomerId: 'c1', requoteKind: 'addition' });
        check('S138', 'address_changed is a quote-raised status and clears',
          w.customers.c1.seasonStatus === 'confirmed',
          'portalSave writes either of the two depending on what changed');
      }
      {
        /* ⚠ ONLY THOSE TWO VALUES. A cancellation request was put there by
           something that is not this quote, and clearing it would be this
           reaching well past what it was pressed to do — it would silently
           un-cancel somebody who asked to cancel. */
        const w = makeWorld({ c1: inSeason({ seasonStatus: 'cancellation_requested' }) });
        const res = await w.run({ existingCustomerId: 'c1', requoteKind: 'addition' });
        check('S138', 'a cancellation request is NOT cleared',
          w.customers.c1.seasonStatus === 'cancellation_requested' &&
          res.seasonStatusCleared !== true,
          'that was not put there by this quote — clearing it un-cancels ' +
          'somebody who asked to cancel');
      }
      {
        const w = makeWorld({ c1: inSeason({ seasonStatus: 'confirmed' }) });
        await w.run({ existingCustomerId: 'c1', requoteKind: 'addition' });
        check('S138', 'a customer with nothing to clear is not written to',
          w.customers.c1.seasonStatus === 'confirmed' && w.messages.length === 1,
          'the note still goes — the office needs telling either way');
      }

      /* ---- a new lead, and the best-effort guards ---------------------- */
      {
        const w = makeWorld({ c1: inSeason() });
        const res = await w.run({ requoteKind: 'addition', phone: '801 555 0199', address: '1 New St' });
        check('S138', 'a lead who is not a customer is not touched',
          res.reached === false && !w.messages.length &&
          w.customers.c1.seasonStatus === 'needs_changes',
          'an add-on re-quote always has a customer behind it, but the resolver ' +
          'must still answer safely when it cannot name one');
      }
      {
        const w = makeWorld({ c1: inSeason() }, { failUpdate: true });
        const res = await w.run({ existingCustomerId: 'c1', requoteKind: 'addition' })
          .catch(err => ({ threw: (err && err.message) || 'threw' }));
        check('S138', 'a failed status write still tells the office',
          res.reached === true && res.seasonStatusCleared === false &&
          w.messages.length === 1,
          'the customer answered; a write that would not save must not swallow it');
      }
      {
        const w = makeWorld({ c1: inSeason() }, { failMessage: true });
        const res = await w.run({ existingCustomerId: 'c1', requoteKind: 'addition' })
          .catch(err => ({ threw: (err && err.message) || 'threw' }));
        check('S138', 'and a note that will not write does not sink it',
          res.reached === true && w.customers.c1.seasonStatus === 'confirmed',
          'the messages collection caps a body at 5000 characters and reports ' +
          'the refusal as a permissions error — see CLAUDE.md');
      }

      /* ---- 3. the ROUTING, run rather than read ------------------------
         The branch itself is what decides which of the two very different
         answers a customer gets, and it is three lines that a regex would
         happily pass while they did the opposite. Sliced out and run with the
         two handlers replaced by spies — legitimate here because what is under
         test is WHICH ONE IS CALLED; both are exercised for real above and in
         Suite 137. */
      {
        /* ⚠ ANCHORED ON THE DECLARATION, NOT ON "if (action === 'decline')".
           There are TWO of those inside quoteRespond — the first sets
           quoteUpdates.quoteArchived — and taking the first one lifted a block
           full of references this sandbox does not supply. It failed loudly,
           which is the good direction, but the slice has to name the block it
           means. */
        const A = '  let declinedCustomer = false;';
        const B = "  if (action === 'maybe_next_year' || action === 'maybe') {";
        const a = fns.indexOf(A, fns.indexOf('exports.quoteRespond = onCall'));
        const b = fns.indexOf(B, a);
        check('S138', 'the decline branch is where this suite expects it',
          a !== -1 && b > a,
          'moved or renamed — fix the slice rather than deleting the check');
        if (a !== -1 && b > a && isAddOnS) {
          const branch = fns.slice(a, b);
          const route = async (action, quoteData) => {
            const called = [];
            let declinedCustomer = false, declinedAddOnOnly = false;
            const fn = new Function('action', 'quoteData', 'quoteId', 'called',
              'declineAddOnOnly', 'declineAsksAboutLastYear',
              isAddOnS + '\nreturn (async () => {\n' +
              'let declinedCustomer = false; let declinedAddOnOnly = false;\n' +
              branch.replace(/^\s*let declined[\s\S]*?= false;\s*$/gm, '') +
              '\nreturn {declinedCustomer, declinedAddOnOnly};})();');
            /* ⚠ THE SPIES TAKE THE QUOTE ID TOO, and the routing block passes
               it — that is how the office finds out when something did not
               happen, so a version that dropped it would report nothing. */
            const out = await fn(action, quoteData, 'q1', called,
              async (q, id) => { called.push('addOnOnly:' + id); return { addOnOnly: true }; },
              async (q, id) => { called.push('season:' + id); return { reached: true }; });
            return { called, out };
          };

          const addOn = await route('decline', { requoteKind: 'addition', existingCustomerId: 'c1' });
          check('S138', 'an add-on decline goes to the add-on handler ONLY',
            addOn.called.join(',') === 'addOnOnly:q1' &&
            addOn.out.declinedAddOnOnly === true && addOn.out.declinedCustomer === false,
            'calling both would refuse the garage AND cancel the season');

          const move = await route('decline', { requoteKind: 'address', existingCustomerId: 'c1' });
          /* ⚠ RENAMED WITH THE BEHAVIOUR IT DESCRIBES. A move or price re-quote no
             longer cancels anybody's season — it marks them to be asked whether
             last year's job will do (Suite 128). What matters HERE is only that
             it takes the other branch, which is what this check has always been
             about. */
          check('S138', 'a move re-quote goes to the ask-about-last-year path',
            move.called.join(',') === 'season:q1' && move.out.declinedCustomer === true,
            'an add-on is the exception; every other decline still goes the other way');

          const plain = await route('decline', { name: 'A new lead' });
          check('S138', 'and an ordinary quote takes that path too',
            plain.called.join(',') === 'season:q1',
            'a first-time quote has no requoteKind at all');

          const appr = await route('approve', { requoteKind: 'addition' });
          check('S138', 'approving calls neither',
            appr.called.length === 0,
            'the branch is guarded on the action, not just the kind');
        }
      }
    })());
  }

  /* ---- 4. the link marker, in BOTH renderers -------------------------- */
  check('S138', 'the office renderer marks an add-on decline link',
    /quoteIsAddOn\(quote\.data\) \? '&addon=1'/.test(admin),
    'the page cannot ask the server before showing "are you sure?", so the ' +
    'link is what tells it which question it is asking');
  check('S138', 'and so does the nightly nudge renderer',
    /quoteIsAddOn\(q\) \? '&addon=1'/.test(fns),
    'the nightly nudge is the same email — a customer who gets chased would ' +
    'see the season wording on an add-on');
  /* ⚠ COSMETIC ONLY, AND THAT IS THE SECURITY ARGUMENT. quoteRespond must
     decide what a decline means from the QUOTE, never from the link — anybody
     who can submit the public quote form can put anything in a URL. */
  /* ⚠ sectionFrom, NOT slice-to-end-of-file. The first version ran to EOF and so
     included the nudge renderer, which legitimately writes &addon=1 — the check
     failed against perfectly correct code. Suite 70 uses the same helper for the
     same reason. */
  const respond = sectionFrom(fns, fns.indexOf('exports.quoteRespond = onCall'));
  /* ⚠ SCOPED TO WHAT IT MEANS, not to the word. The first version was
     /addon/i over the whole function and failed against correct code, because
     the local flag `declinedAddOnOnly` contains "AddOn". What must never happen
     is the server taking the DECISION from something the caller sent — so this
     names the two places a caller's value can arrive from. */
  check('S138', 'the server never reads the link marker',
    !/\b(?:body|request\.data)\s*\.\s*addon/i.test(stripComments(respond)) &&
    !/addon['"]\s*\]/i.test(stripComments(respond)),
    'a decision taken from a URL parameter is a decision the customer can forge — ' +
    'the kind must come off the quote document');
  check('S138', 'and it decides from the quote document instead',
    /quoteIsAddOn\(quoteData\)/.test(stripComments(respond)),
    'reading the kind off anything the caller controls is the whole risk here');

  /* ---- 5. what the customer is actually told -------------------------- */
  if (!JSDOM) {
    note('S138', 'jsdom missing — the confirmation-screen checks did not run');
  } else {
    const src = lift(idx, 'confirmQuoteDecline');
    check('S138', 'the decline confirmation screen is findable', !!src);
    if (src) {
      const screen = (isAddOn) => {
        const dom = new JSDOM(
          '<div id="quoteLinkConfirm"></div><div id="quoteLinkConfirmMsg"></div>' +
          '<div id="quoteLinkConfirmActions"></div><div id="quoteDetailFormWrap"></div>');
        const d = dom.window.document;
        let sub = '';
        new Function('document', 'quoteLinkIsAddOn', 'setQuoteConfirmSub', 'handleQuoteLink',
          src + ';confirmQuoteDecline("tok");')(
          d, isAddOn, (t) => { sub = t; }, () => {});
        return {
          msg: d.getElementById('quoteLinkConfirmMsg').textContent,
          sub: sub,
          buttons: d.getElementById('quoteLinkConfirmActions').innerHTML
        };
      };
      const on = screen(true), off = screen(false);

      /* ⚠ RUN, NOT GREPPED. This repo has already shipped a correct message
         that never reached the screen because a default overwrote it at the end
         of the branch — "griner is a duplicate here but its not finding her",
         a working detector behind a broken renderer. */
      check('S138', 'an add-on is not asked whether to "close it out"',
        !/close this out/i.test(on.msg) && !/close it out/i.test(on.buttons),
        'that describes ending the relationship, and this customer is having ' +
        'their house lit next week');
      check('S138', 'it says the usual lights are unaffected',
        /usual lights/i.test(on.sub + on.buttons) && /extra/i.test(on.sub),
        'this is the sentence that stops somebody clicking away believing they ' +
        'have just cancelled their season');
      check('S138', 'and the ordinary decline screen is unchanged',
        /close this out/i.test(off.msg) && /close it out/i.test(off.buttons) &&
        !/usual lights/i.test(off.sub),
        'the season decline is still a season decline');
      check('S138', 'both screens still offer all three answers',
        ['approve', 'maybe_next_year', 'decline'].every(a =>
          on.buttons.indexOf('data-qd="' + a + '"') !== -1 &&
          off.buttons.indexOf('data-qd="' + a + '"') !== -1),
        'the second chance is the point of this screen');
    }

    /* The message AFTER the answer is recorded, run the same way. It reads the
       SERVER's answer, not the link — if the two ever disagree, the one that
       wrote to the database is the one telling the truth. */
    const mStart = idx.indexOf("    if(action === 'maybe_next_year'){");
    const mEnd = idx.indexOf('  }).catch(function(){', mStart);
    check('S138', 'the after-answer message block is findable',
      mStart !== -1 && mEnd > mStart);
    if (mStart !== -1 && mEnd > mStart) {
      const blk = idx.slice(mStart, mEnd);
      /* ⚠ quoteLinkIsAddOn IS PASSED IN, set independently of res. That is what
         makes the next three checks able to tell the two sources apart — and it
         also stops a sabotage pointing at the link throwing ReferenceError,
         which would kill the whole run with an unattributable stack instead of
         failing as itself. */
      const said = (action, res, linkFlag) => {
        let msg = '', sub = '';
        try {
          new Function('action', 'res', 'quoteLinkIsAddOn', 'confirmMsg', 'setQuoteConfirmSub',
            blk)(action, res, !!linkFlag, { set textContent(v) { msg = v; } }, (t) => { sub = t; });
        } catch (err) { return 'threw: ' + (err && err.message); }
        return msg + ' || ' + sub;
      };
      const addOnSaid = said('decline', { ok: true, addOnOnly: true }, false);
      const seasonSaid = said('decline', { ok: true, addOnOnly: false }, false);
      check('S138', 'an add-on decline is not sent a goodbye message',
        !/hard feelings/i.test(addOnSaid) && /usual lights/i.test(addOnSaid),
        '"no hard feelings, Merry Christmas" to somebody whose lights go up on ' +
        'Tuesday reads as a cancellation they did not ask for');
      check('S138', 'and a real decline still gets the warm goodbye',
        /hard feelings/i.test(seasonSaid),
        'that message is right for somebody who is actually leaving');
      /* ⚠ THE TWO SOURCES ARE SET AGAINST EACH OTHER, deliberately. Comparing
         two calls that differ only in res.addOnOnly proved NOTHING — a version
         reading the link gives the same answer to both, so the check passed
         either way. The red-check caught it. These two set the link flag
         OPPOSITE to the server's answer, so only the right source gives the
         right words. */
      check('S138', 'the add-on wording comes from the SERVER answer',
        /usual lights/i.test(addOnSaid),
        'addOnOnly was true and the link said no — the link marker picks the ' +
        'words BEFORE the call, but afterwards only what the server actually ' +
        'did may decide');
      check('S138', 'and a link marker alone cannot claim it was only an add-on',
        /hard feelings/i.test(said('decline', { ok: true, addOnOnly: false }, true)),
        'anybody can put addon=1 in a URL — telling a customer who really has ' +
        'left "your usual lights are still going up" is the forgeable direction');
      check('S138', 'maybe-next-year is untouched by any of it',
        /check back next year/i.test(said('maybe_next_year', { ok: true, addOnOnly: true }, true)),
        'a third branch added above it must not swallow the second');
    }
  }
}

/* =====================================================================
 * Suite 139. Nothing a customer's answer sets off may fail silently
 *
 * Owner, 2026-08-21: "for server call is there a way we can't have that fail
 * silently or what would you do?"
 *
 * Every write after a customer answers their quote is best-effort on purpose —
 * the ANSWER is already recorded and must not be lost because a follow-on write
 * failed. That was right, and it was also the whole problem: best-effort meant
 * console.error, which goes to Cloud Logging, which nobody in the office reads.
 * A recycle never flagged, or a house left on a route after a "no", was
 * invisible until somebody physically noticed.
 *
 * ⚠ THE WORST CASE WAS NOT A FAILED WRITE, IT WAS A FAILED READ. quoteCustomerRef
 * caught its own errors and returned null — the identical answer it gives for
 * "this is a first-time lead". So a Firestore blip during a decline made a real
 * member look like a stranger and NOTHING happened, with no error anywhere a
 * human would see. Those are opposite outcomes and they shared a line of code.
 * ===================================================================== */
suite('Suite 139. Nothing a customer\'s answer sets off may fail silently');
{
  const fns = read('functions/index.js');
  const lift = (name) => {
    const i = fns.indexOf('function ' + name + '(');
    if (i === -1) return null;
    let d = 0;
    for (let j = fns.indexOf('{', i); j < fns.length; j++) {
      if (fns[j] === '{') d++;
      else if (fns[j] === '}') { d--; if (!d) return fns.slice(i, j + 1); }
    }
    return null;
  };

  /* ---- 1. the retry ---------------------------------------------------- */
  const trySrc = lift('tryFirestore');
  const flagSrc = lift('flagQuoteFollowUp');
  check('S139', 'the retry helper and the follow-up flag are findable',
    !!trySrc && !!flagSrc,
    'renamed or moved — fix the lift rather than deleting the suite');

  /* ⚠ ZEROED IN THE SANDBOX, ASSERTED NON-ZERO HERE. Two attempts fired at the
     same instant is not a retry — the point of the pause is to let a transient
     blip pass. The suites run with it at 0 so a run stays under a minute
     (CLAUDE.md §9.8), which is exactly why the real value needs its own check. */
  const pause = fns.match(/const HU_RETRY_PAUSE_MS = (\d+);/);
  check('S139', 'the retry actually pauses between attempts',
    !!pause && Number(pause[1]) > 0,
    'retrying instantly hits the same blip and reports the same failure, ' +
    'having achieved nothing but a second write attempt');

  if (trySrc && flagSrc) {
    const mk = () => {
      const errs = [];
      return new Function('console', 'HU_RETRY_PAUSE_MS',
        'async ' + trySrc + '\nreturn tryFirestore;')(
        { error: (...a) => errs.push(a.join(' ')), log: () => {} }, 0);
    };

    pendingAsync.push((async () => {
      const tryFn = mk();

      /* A blip on the first attempt is the common case and must clear without
         anybody hearing about it. */
      {
        let n = 0;
        const r = await tryFn('x', async () => {
          n++; if (n === 1) throw new Error('blip');
          return 'value';
        });
        check('S139', 'a transient failure is retried and succeeds',
          r.ok === true && r.value === 'value' && n === 2,
          'a single blip is the commonest failure by far — flagging the office ' +
          'for one is noise, and noise is how a real flag gets ignored');
      }
      {
        let n = 0;
        const r = await tryFn('x', async () => { n++; throw new Error('down'); });
        check('S139', 'but it gives up after two and says it failed',
          r.ok === false && n === 2,
          'retrying for ever holds the customer\'s page open on a spinner');
      }
      /* ⚠ A REFUSAL IS NOT RETRIED. A permission-denied never becomes allowed on
         a second go — and that INCLUDES the messages 5000-character cap, which
         Firestore reports as permission-denied (CLAUDE.md). Retrying it just
         doubles the wait for the same answer. */
      {
        let n = 0;
        const err = new Error('nope'); err.code = 'permission-denied';
        const r = await tryFn('x', async () => { n++; throw err; });
        check('S139', 'a permission refusal is not retried',
          r.ok === false && n === 1,
          'it will never be allowed on a second attempt — including the ' +
          'messages size cap, which Firestore reports this way');
      }
      {
        let n = 0;
        const err = new Error('nope'); err.code = 'unavailable';
        const r = await tryFn('x', async () => {
          n++; if (n === 1) throw err; return 1;
        });
        check('S139', 'but an ordinary outage code still is',
          r.ok === true && n === 2,
          '"unavailable" is precisely the transient one worth a second go');
      }

      /* ---- 2. the flag ------------------------------------------------- */
      const mkFlag = (opts) => {
        const o = opts || {};
        const written = [];
        const db = {
          collection: (c) => ({
            doc: (id) => ({
              update: (patch) => {
                if (o.fail) return Promise.reject(new Error('boom'));
                written.push({ c, id, patch });
                return Promise.resolve();
              }
            })
          })
        };
        const fn = new Function('db', 'admin', 'console',
          'async ' + flagSrc + '\nreturn flagQuoteFollowUp;')(db,
          { firestore: { FieldValue: { serverTimestamp: () => '@ts' } } },
          { error: () => {}, log: () => {} });
        return { fn, written };
      };
      {
        const w = mkFlag();
        const ok = await w.fn('q1', ['route sweep failed', 'note failed']);
        check('S139', 'what did not happen is written onto the quote',
          ok === true && w.written.length === 1 && w.written[0].c === 'quotes' &&
          w.written[0].id === 'q1' && w.written[0].patch.followUpNeeded === true,
          'the quote is the one document known to be writable — it was written ' +
          'seconds earlier, and a failure THERE throws back to the customer');
        check('S139', 'and it names every thing that went wrong, not just the first',
          /route sweep failed/.test(w.written[0].patch.followUpReason) &&
          /note failed/.test(w.written[0].patch.followUpReason),
          'fixing one problem and finding a second one you were never told ' +
          'about is how somebody stops trusting the flag');
      }
      {
        const w = mkFlag();
        const ok = await w.fn('q1', []);
        check('S139', 'nothing wrong writes no flag at all',
          ok === false && !w.written.length,
          'a flag on every quote is a flag on none of them');
      }
      {
        /* ⚠ IT NEVER THROWS. This is the thing that REPORTS failures — it must
           not become a new way for the whole call to fail. */
        const w = mkFlag({ fail: true });
        const ok = await w.fn('q1', ['something'])
          .catch(() => 'THREW');
        check('S139', 'and a flag that cannot be written does not throw',
          ok === false,
          'the reporter becoming the failure is the worst possible shape');
      }

      /* ---- 3. the read that used to shrug ------------------------------ */
      const refSrc = lift('quoteCustomerRef');
      check('S139', 'the resolver is findable', !!refSrc);
      if (refSrc) {
        /* ⚠ RUN, NOT GREPPED, and the distinction under test is between two
           things that LOOK the same from outside: "there is no such customer"
           and "I could not find out". Both used to return null. */
        const mkRef = (mode) => {
          const db = {
            collection: () => ({
              doc: () => ({
                get: () => mode === 'boom'
                  ? Promise.reject(new Error('unavailable'))
                  : Promise.resolve({ exists: mode === 'found', id: 'c1', data: () => ({ name: 'R' }) })
              })
            })
          };
          return new Function('db', 'quoteMatchesExistingCustomer', 'console',
            'async ' + refSrc + '\nreturn quoteCustomerRef;')(db,
            async () => null, { error: () => {}, log: () => {} });
        };
        const found = await mkRef('found')({ existingCustomerId: 'c1' });
        check('S139', 'a customer who exists still comes back',
          !!found && found.id === 'c1',
          'the ordinary path must be untouched by any of this');

        const gone = await mkRef('missing')({ existingCustomerId: 'c1' })
          .catch(err => ({ threw: (err && err.message) || 'threw' }));
        check('S139', 'a link to a deleted customer is still a plain null',
          gone === null,
          'that is an ANSWER — there is no such customer — not a failure, and ' +
          'flagging the office for it would cry wolf on every deleted record');

        const blew = await mkRef('boom')({ existingCustomerId: 'c1' })
          .then(v => ({ returned: v }), e => ({ threw: true }));
        check('S139', 'but a read that could not run FAILS instead of shrugging',
          blew.threw === true,
          'this is the whole bug: it used to catch and return null, which is ' +
          'the same answer as "not a customer" — so a blip made a real member ' +
          'look like a stranger and the decline silently did nothing');
      }
    })());
  }

  /* ---- 4. the callers act on it --------------------------------------- */
  const decl = stripComments(lift('declineAsksAboutLastYear') || '');
  const addOn = stripComments(lift('declineAddOnOnly') || '');
  check('S139', 'both decline paths flag a lookup they could not run',
    /flagQuoteFollowUp/.test(decl) && /flagQuoteFollowUp/.test(addOn) &&
    /tryFirestore\('decline customer lookup'/.test(decl) &&
    /tryFirestore\('add-on decline customer lookup'/.test(addOn),
    'catching the error is only half of it — somebody has to be told');
  /* ⚠ maybe_next_year SHARES THE RESOLVER, so it shared the silence. */
  const respond = sectionFrom(fns, fns.indexOf('exports.quoteRespond = onCall'));
  check('S139', 'maybe-next-year reports a failure too',
    /flagQuoteFollowUp\(quoteId/.test(stripComments(respond)),
    'a member who chose Maybe Next Year could stay on the routes for a season ' +
    'they declined, with nobody any the wiser');

  /* ⚠ NOTHING IS CLAIMED THAT DID NOT HAPPEN. When the customer write itself
     fails there is no System note — saying "we took them out of the season"
     when we did not sends the office looking for a bin that is not coming. */
  check('S139', 'a failed customer write raises no note, only a flag',
    /return \{ reached: false, followUpFlagged: true \};/.test(decl),
    'a note describing something that did not happen is worse than no note');

  /* ---- 5. the office can see it --------------------------------------- */
  const admin = read('admin.html');
  /* ⚠ SCOPED TO THE CARD. A file-wide /followUpNeeded/ passed with the strip
     switched off entirely, because the badge and the clear button mention the
     same field — the red-check caught it. This reads the card render alone. */
  const cardStart = admin.indexOf('// ---- Something the server could not finish');
  const cardEnd = admin.indexOf('// ---- Re-quoted by hand', cardStart);
  const cardStrip = cardStart !== -1 && cardEnd > cardStart ? admin.slice(cardStart, cardEnd) : '';
  check('S139', 'the office sees the flag on the quote card',
    /\(d\.followUpNeeded \? \(/.test(cardStrip) &&
    /esc\(d\.followUpReason/.test(cardStrip) &&
    /did not go through/.test(cardStrip),
    'a field written by the server and read by nobody is the same silence in ' +
    'a different place');
  /* ⭐ THE BUTTON IS PRESSED, not read. Owner has asked for this class of check
     by name: "just make sure to double check that if i click a button the
     function that is supposed to happen actually does." A control that renders
     perfectly and does nothing looks identical on screen to a working one, and
     this repo has shipped exactly that — the bin-number box whose listener
     patch silently did not apply. */
  if (!JSDOM) {
    note('S139', 'jsdom missing — the clear button was not actually clicked');
  } else {
    /* ⚠ ANCHORED ON list.innerHTML, NOT ON THE SELECTOR. Anchoring on
       '[data-clearfollowup]' meant a sabotage that renamed the selector — the
       exact "button with no listener" case this exists to catch — destroyed the
       anchor, so a DIFFERENT check went red and this one never ran. */
    const wStart = admin.indexOf('  list.innerHTML = html;') +
      '  list.innerHTML = html;'.length;
    const wEnd = admin.indexOf("  list.querySelectorAll('[data-previewquoteaddr]')", wStart);
    check('S139', 'the clear-follow-up wiring is findable',
      admin.indexOf('  list.innerHTML = html;') !== -1 && wEnd > wStart);
    if (wStart !== -1 && wEnd > wStart) {
      pendingAsync.push((async () => {
        const dom = new JSDOM('<div id="l"><button data-clearfollowup="q1">Done</button></div>');
        const list = dom.window.document.getElementById('l');
        const wrote = [];
        let repainted = 0;
        const cache = [{ id: 'q1', data: { followUpNeeded: true, followUpReason: 'x' } }];
        new Function('list', 'updateDoc', 'doc', 'db', 'serverTimestamp',
          'quotesCache', 'toast', 'renderQuotesList',
          admin.slice(wStart, wEnd))(
          list,
          (ref, patch) => { wrote.push({ ref, patch }); return Promise.resolve(); },
          (dbArg, col, id) => col + '/' + id, {}, () => '@ts',
          cache, () => {}, () => { repainted++; });

        const btn = list.querySelector('[data-clearfollowup]');
        check('S139', 'the clear button is actually listened to',
          !!btn, 'the markup is there — this proves a handler was attached to it');
        btn.dispatchEvent(new dom.window.Event('click'));
        await new Promise(r => setTimeout(r, 0));

        check('S139', 'clicking it writes the flag off, on the right quote',
          wrote.length === 1 && wrote[0].ref === 'quotes/q1' &&
          wrote[0].patch.followUpNeeded === false,
          'a button that renders and does nothing looks identical on screen to ' +
          'one that works');
        /* ⚠ IT CLEARS THE FLAG AND NOTHING ELSE. It must never try to re-run
           what failed: the server could not reach that record a moment ago, and
           guessing which half landed is how somebody's lights get recycled
           twice, or a real decline gets undone. */
        check('S139', 'and it does not try to re-run whatever failed',
          Object.keys(wrote[0].patch).every(k => /^followUp/.test(k)),
          'wrote: ' + Object.keys(wrote[0].patch).join(', ') + ' — the office ' +
          'has already fixed it by hand; this only records that they did');
        check('S139', 'the local copy is mirrored so the card repaints',
          cache[0].data.followUpNeeded === false && repainted === 1,
          'the list draws from the cache, not from Firestore — without the ' +
          'mirror the strip springs back and it reads as a button that failed');
      })());
    }
  }

  check('S139', 'and it is counted in the sidebar badge',
    /followUpNeeded/.test(admin.slice(admin.indexOf('let newCount = 0;'),
      admin.indexOf('renderQuotesList();', admin.indexOf('let newCount = 0;')))),
    'the badge is what makes somebody open the tab in the first place');
}
// A check that scores after this summary is a check that cannot fail the build.

suite('126. Measure Roof — sky view and Street View are one set of points');
{
  /* ⚠ THIS SUITE RUNS THE MATHS, it does not read it. Every earlier version of
     a check on this feature matched source text and passed while the two views
     were on scales 0.25% apart — see the earth-model note in rmFeetBetween.
     CLAUDE.md §5: a message that is in the source is not a message on screen,
     and a number that is in the source is not a number that was computed. */
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);
  const NAMES = ['rmMetresPerDeg', 'rmToLocal', 'rmToWorld', 'rmFeetBetween',
                 'rmFovDeg', 'rmBasis', 'rmRay', 'rmGroundHit', 'rmWallHit',
                 'rmSvProject', 'rmMercator', 'rmPointOnStatic'];
  const missing = NAMES.filter(n => !pick(n));
  if (missing.length) {
    check('S126', 'the Measure Roof maths is findable', false,
      'missing: ' + missing.join(', ') + ' — renamed or removed; update this test rather than deleting it');
  } else {
    /* rmOrigin is module state the lifted functions close over, so it is
       declared in the sandbox rather than stubbed — a stub would make the
       frame untestable while reporting green. */
    const prelude = 'let rmOrigin = {lat: 40.2969, lng: -111.6946};' + LF_ +
      'const RM_M_TO_FT = 3.280839895;' + LF_ +
      'const RM_CAM_HEIGHT_M = 2.5;' + LF_ +
      'const rmRad = d => d * Math.PI / 180;' + LF_;
    const api = new Function(prelude + NAMES.map(pick).join(LF_) + LF_ +
      'return {rmToLocal, rmToWorld, rmFeetBetween, rmRay, rmGroundHit, rmWallHit,' +
      ' rmSvProject, rmFovDeg, rmMetresPerDeg, rmPointOnStatic};')();

    const near = (a, b, tol) => Math.abs(a - b) <= tol;
    const M_TO_FT = 3.280839895;

    /* ---- one earth model ------------------------------------------------
       ⚠ THE REGRESSION THIS EXISTS FOR. The frame places points with the
       ELLIPSOID (85,023 m per degree of longitude at this latitude) and
       rmFeetBetween once measured them with a haversine on a SPHERE (84,832).
       Ten metres came back as 32.73 ft instead of 32.81 — 0.25%, three inches
       per hundred feet, and only ever in the direction that made a wall
       measured from the street disagree with the same wall traced from above.
       Nothing on screen would have said a word. */
    const origin = api.rmToWorld({e: 0, n: 0, u: 0});
    const tenEast = api.rmToWorld({e: 10, n: 0, u: 0});
    check('S126', 'ten metres east measures ten metres, not 0.25% short',
      near(api.rmFeetBetween(origin, tenEast), 10 * M_TO_FT, 0.01),
      'got ' + api.rmFeetBetween(origin, tenEast).toFixed(4) + ' ft, expected ' + (10 * M_TO_FT).toFixed(4) +
      ' — the frame and the ruler are on different earths again');
    const tenNorth = api.rmToWorld({e: 0, n: 10, u: 0});
    check('S126', 'and ten metres north measures the same as ten east',
      near(api.rmFeetBetween(origin, tenNorth), api.rmFeetBetween(origin, tenEast), 0.001),
      'a frame that is not square makes a diagonal wall measure differently from a straight one');

    /* ---- height is part of the distance -------------------------------- */
    const tenUpAndOut = api.rmToWorld({e: 10, n: 0, u: 6});
    check('S126', 'a run that rises is measured as the hypotenuse, not the flat run',
      near(api.rmFeetBetween(origin, tenUpAndOut), Math.hypot(10, 6) * M_TO_FT, 0.01),
      'a sloping peak measured as its flat run is short by exactly the thing Street View was added to see');
    check('S126', 'a pure rise is not zero',
      near(api.rmFeetBetween(origin, api.rmToWorld({e: 0, n: 0, u: 6})), 6 * M_TO_FT, 0.01),
      'two points one above the other must not measure as the same place');

    /* ---- the frame round-trips ------------------------------------------ */
    const rt = api.rmToWorld(api.rmToLocal(40.29712, -111.69488, 5.4));
    check('S126', 'world to local and back is the same place',
      near(rt.lat, 40.29712, 1e-11) && near(rt.lng, -111.69488, 1e-11) && near(rt.h, 5.4, 1e-11),
      'a point drifts every time it crosses between the views');

    /* ---- Street View: pixel to ray -------------------------------------- */
    const W = 1000, H = 600, POV = {heading: 0, pitch: 0, zoom: 1};
    check('S126', 'zoom 1 is 90 degrees across', near(api.rmFovDeg(1), 90, 1e-9));
    const centre = api.rmRay(W / 2, H / 2, W, H, POV);
    check('S126', 'a click dead centre points exactly where the camera faces',
      near(centre.n, 1, 1e-9) && near(centre.e, 0, 1e-9) && near(centre.u, 0, 1e-9));
    const right45 = api.rmRay(W / 2 + 500, H / 2, W, H, POV);
    check('S126', '500 px right at 90 degrees across is exactly 45 degrees round',
      near(Math.atan2(right45.e, right45.n) * 180 / Math.PI, 45, 1e-6),
      'the lens model is wrong, so every street measurement is wrong with it');

    /* ---- the ground, which is what pins the wall ------------------------ */
    const cam = {e: 0, n: -12, u: 2.5};   /* camera across the street, on the road */
    const down45 = api.rmRay(W / 2, H / 2 + 500, W, H, POV);
    const hit = api.rmGroundHit(down45, cam);
    check('S126', '45 degrees down lands one camera-height out',
      hit && near(hit.n - cam.n, 2.5, 1e-6) && near(hit.u, 0, 1e-9),
      'the ground plane is the only thing giving a photograph any depth at all');
    check('S126', 'a ray at the horizon is refused rather than landing at infinity',
      api.rmGroundHit(centre, cam) === null,
      'a horizon click must not silently produce a point miles away');
    check('S126', 'and a ray above the horizon is refused too',
      api.rmGroundHit(api.rmRay(W / 2, H / 2 - 300, W, H, POV), cam) === null);
    /* ⚠ THE CASE THE HORIZON GUARD ACTUALLY EXISTS FOR, and the one a naive
       sabotage misses: a ray at EXACTLY the horizon is already caught by the
       t<=0 guard below it, so removing the horizon test looks harmless. A ray
       a hair BELOW the horizon is not - it divides by almost nothing and lands
       a couple of billion metres away, with a positive t, sailing through both
       guards. That is a wall pinned on the far side of the planet. */
    const grazing = api.rmGroundHit({e: 0, n: Math.sqrt(1 - 1e-18), u: -1e-9}, cam);
    check('S126', 'a ray grazing just under the horizon is refused, not landed billions of metres away',
      grazing === null,
      grazing ? 'came back ' + Math.round(Math.hypot(grazing.e, grazing.n - cam.n) / 1000) +
                ' km from the camera' : '');

    /* ---- the wall, and the round trip that proves the views agree ------- */
    const gL = api.rmGroundHit(api.rmRay(W / 2 - 300, H / 2 + 180, W, H, POV), cam);
    const gR = api.rmGroundHit(api.rmRay(W / 2 + 300, H / 2 + 180, W, H, POV), cam);
    const de = gR.e - gL.e, dn = gR.n - gL.n, len = Math.hypot(de, dn);
    const nrm = {e: dn / len, n: -de / len};
    const plane = {a: gL, b: gR, normal: nrm, d: nrm.e * gL.e + nrm.n * gL.n, lengthM: len};
    const eave = api.rmWallHit(api.rmRay(W / 2, H / 2 - 220, W, H, POV), cam, plane);
    check('S126', 'a click above the wall line lands on the wall',
      !!eave && near(nrm.e * eave.e + nrm.n * eave.n, plane.d, 1e-9),
      'without this a Street View click has nothing to land on and no length can exist');
    check('S126', 'and it is above the ground, not on it',
      eave && eave.u > 1, 'an eave that comes back at ground level is the plane maths collapsing');

    /* ⚠ THIS IS THE WHOLE CLAIM OF THE FEATURE. A point marked in one view is
       a place in the world, so projecting it back must return the pixel that
       was clicked. If this drifts, the two views are two drawings again. */
    const back = api.rmSvProject(api.rmToWorld(eave), W, H, POV, cam);
    check('S126', 'a Street View point projects back to the exact pixel clicked',
      back && near(back.x, W / 2, 1e-5) && near(back.y, H / 2 - 220, 1e-5),
      'got ' + (back ? Math.round(back.x) + ',' + Math.round(back.y) : 'null') +
      ' — a point marked in Street View no longer lands where it was put');

    /* A point that exists only as lat/lng/height — the sky-view case — must
       appear in Street View at the right place. This is the other direction of
       the same claim, and it is the one a sky-view click actually exercises. */
    const skyMarked = {lat: api.rmToWorld(eave).lat, lng: api.rmToWorld(eave).lng, h: eave.u};
    const inStreet = api.rmSvProject(skyMarked, W, H, POV, cam);
    check('S126', 'a point marked on the sky view shows up in Street View',
      inStreet && near(inStreet.x, W / 2, 1e-5) && near(inStreet.y, H / 2 - 220, 1e-5),
      'marking a corner from above does not appear on the photograph');

    /* ---- turning your head must not move the house --------------------- */
    const TURNED = {heading: 31, pitch: -7, zoom: 2};
    const moved = api.rmSvProject(api.rmToWorld(eave), W, H, TURNED, cam);
    check('S126', 'looking elsewhere moves the point on screen',
      moved && Math.abs(moved.x - back.x) > 5,
      'the overlay is painted in screen coordinates and is not following the view');
    const eaveWorld = api.rmToWorld(eave);
    const eave2 = api.rmToWorld(eave);
    check('S126', 'but the measurement itself is unchanged by where you look',
      near(api.rmFeetBetween(eaveWorld, api.rmToWorld({e: eave.e + 3, n: eave.n, u: eave.u})),
           3 * M_TO_FT, 0.01),
      'a length that depends on the point of view is not a length');

    /* ---- a point behind the camera is dropped, not drawn wrong ---------- */
    check('S126', 'a point behind the camera is refused rather than mirrored in front',
      api.rmSvProject(api.rmToWorld({e: 0, n: cam.n - 5, u: 0}), W, H, POV, cam) === null,
      'a house behind you drawn in front of you is worse than not drawn');

    /* ---- the captured picture puts the lines where they were drawn ------ */
    const centreOfShot = api.rmPointOnStatic({lat: 40.2969, lng: -111.6946},
      {lat: 40.2969, lng: -111.6946}, 20, 640, 400, 2);
    check('S126', 'the map centre lands dead centre of the captured picture',
      near(centreOfShot.x, 640, 1e-6) && near(centreOfShot.y, 400, 1e-6),
      'the traced lines will be burned into the wrong part of the image');
  }

  /* ---- the pricing multiplier ------------------------------------------
     ⚠ The doubling is a business rule, not a measurement. It has to be a
     named constant so the number can be found and changed, and BOTH figures
     have to reach the screen — a total twice the size of the line just drawn,
     with no working shown, reads as a bug in the measuring. */
  const mult = admin.match(/const RM_FEET_MULTIPLIER = (\d+)/);
  check('S126', 'the doubling is a named constant, not a bare 2 in the sum',
    !!mult, 'RM_FEET_MULTIPLIER is gone — the rule is now buried where nobody will find it');
  /* ⚠ WAS "and it is set to 2". The doubling is GONE - the owner's real
     numbers killed it: an average house is ~150 ft and should come out at
     $280-300, and 150 doubled at $2 is $600. Left at 1 rather than deleted so
     the lever still exists, and asserted at 1 so it cannot creep back
     unnoticed and silently double every quote in the system. */
  check('S126', 'the footage is NOT doubled any more', mult && mult[1] === '1',
    'a multiplier other than 1 doubles every price on this screen and disagrees with the rest of the admin');
  /* ⚠ sectionFrom takes an INDEX, not a string. Handed a string it coerces to
     0 and slices from the top of the file — which still contains enough words
     to make a loose check pass. Two of these three were doing exactly that. */
  const useFeet = sectionFrom(admin, admin.indexOf("document.getElementById('rmUseFeetBtn').addEventListener"));
  check('S126', 'Estimated Feet is saved as the measured run times that constant',
    /RM_FEET_MULTIPLIER/.test(useFeet) && /estimatedFeet:\s*feet/.test(useFeet),
    'the button either stopped doubling or started doubling somewhere else');
  check('S126', 'and it reports the measured figure alongside the doubled one',
    /measured/.test(useFeet),
    'a number twice the size of the traced line, with no working, reads as a fault');

  /* ---- the button actually does something ------------------------------
     Owner's standing request: "just make sure that if i click a button the
     function that is supposed to happen actually does." */
  check('S126', 'the quote card carries a Measure Roof button',
    /data-measureroof="'\+item\.id\+'/.test(admin),
    'the button is gone from the card, so nothing can open the tool');
  const wiring = sectionFrom(admin, admin.indexOf("list.querySelectorAll('[data-measureroof]')"));
  check('S126', 'and it is wired to a function that exists',
    /openRoofMeasure\(btn\.dataset\.measureroof\)/.test(wiring) && !!extractFn(admin, 'openRoofMeasure'),
    'a button with no handler, or a handler calling something that is not there');

  /* ---- two keys, and the one that works wins ---------------------------
     ⚠ THE BUG THIS EXISTS FOR. admin.html carries TWO Google keys in
     different Cloud projects: the map's, on the Maps script tag, and
     Firebase's own. On 2026-08-21 the static-image APIs were switched on for
     the Firebase one and not the map one, so capture kept refusing while the
     map rendered perfectly six inches above the error. Trying only one key
     makes that unfixable from here. */
  const keysFn = extractFn(admin, 'rmMapsKeys');
  check('S126', 'both Google keys on the page are collected, not just the map one',
    !!keysFn && /script\[src\*="maps\.googleapis/.test(keysFn) && /firebaseConfig/.test(keysFn),
    'only one key is looked at, so a permission on the other is unreachable');
  const fetchFn = extractFn(admin, 'rmFetchStatic');
  check('S126', 'a refused key falls through to the next one',
    !!fetchFn && /for\s*\(let i = 0; i < keys\.length/.test(fetchFn),
    'the first refusal ends it, and the key that would have worked is never tried');
  check('S126', 'but only a permission refusal is retried, not a 404',
    !!fetchFn && /not authorized\|not enabled/.test(fetchFn) && /break/.test(fetchFn),
    'retrying every failure on every key just makes a missing photo slower to report');
  check('S126', 'and the key that worked is remembered for the next capture',
    !!fetchFn && /rmGoodKey = keys\[i\]/.test(fetchFn),
    'every capture pays for the refusal again');
  const failMsg = extractFn(admin, 'rmStaticFailMessage');
  check('S126', 'and the refusal message says there is more than one key',
    !!failMsg && /more than one key/.test(failMsg) && /different Google Cloud projects/.test(failMsg),
    'a message naming "the key" sends somebody to fix the one they can see — which is the trap that cost a round of this');

  /* ---- the freeze, which is the control complaint this was built for ---- */
  const setDrawing = extractFn(admin, 'rmSetDrawing');
  check('S126', 'starting a line freezes the sky view',
    !!setDrawing && /rmMap\.setOptions\(\{draggable: !skyLock/.test(setDrawing),
    'the map can pan under a half-drawn line again');
  check('S126', 'and freezes Street View',
    !!setDrawing && /rmPano\.setOptions\(/.test(setDrawing) && /stLock/.test(setDrawing),
    'the panorama can swing away mid-trace again — the exact thing that was reported');

  /* ---- placed points stay editable ------------------------------------- */
  const dot = extractFn(admin, 'rmDot');
  check('S126', 'a placed point can be dragged afterwards',
    !!dot && /draggable:\s*true/.test(dot),
    'a corner put slightly wrong means starting the line again');
  check('S126', 'and dragging it moves the world point, so both views follow',
    !!dot && /run\.path\[idx\]\.lat/.test(dot) && /rmPaintStreet\(\)/.test(dot),
    'dragging on the sky view would move the line there and leave Street View behind');
}

/* =====================================================================
 * Suite 131. An outstanding add-on rides along with the RSVP
 *
 * Owner, 2026-08-21: "Can we have an approve or decline button for RSVP for add
 * ons to? I don't want a decline on a garage to decline full quote just garage."
 *
 * The RSVP is the one email everybody gets each season, so it is where a garage
 * somebody was quoted for and never answered can finally be settled. Season
 * yes/no at the top, add-on yes/no underneath.
 *
 * ⚠ THE SHARP EDGE IS WHOSE ADD-ON IT IS. Every other quote-email builder in
 * this file finds its quote by PHONE. That is wrong here and worse than
 * anywhere else: 17 numbers in the real book are shared and 14 of those are two
 * genuinely different households, so a phone match would print a child's quote
 * and price inside a parent's RSVP email — and hand the parent the buttons that
 * answer it. A re-quote is always raised against a live record, so the explicit
 * link is always available and nothing has to be guessed.
 * ===================================================================== */
suite('Suite 131. An outstanding add-on rides along with the RSVP');
{
  const admin = read('admin.html');
  const lift = (name) => {
    const i = admin.indexOf('function ' + name + '(');
    if (i === -1) return null;
    let d = 0;
    for (let j = admin.indexOf('{', i); j < admin.length; j++) {
      if (admin[j] === '{') d++;
      else if (admin[j] === '}') { d--; if (!d) return admin.slice(i, j + 1); }
    }
    return null;
  };

  const NEED = ['pendingAddOnFor', 'addOnEmailBlock', 'rsvpTemplateHasAddOn',
    'quoteIsAddOn', 'quoteButtonLabels', 'quoteStage', 'quotePortalParam'];
  const src = {};
  NEED.forEach(n => { src[n] = lift(n); });
  const gone = NEED.filter(n => !src[n]);
  check('S131', 'every function this suite runs is findable',
    !gone.length, 'missing: ' + gone.join(', '));

  check('S131', 'addOnEmailBlock is async in the real file',
    /async function addOnEmailBlock\(/.test(admin),
    'extractFn drops the keyword, so the lift below puts it back — if it stops ' +
    'being async there, this suite runs a different shape from production');

  if (!gone.length) {
    /* quoteStage and quotePortalParam are the REAL ones. quoteStage in
       particular decides "still waiting for an answer", and a stub of it would
       agree with itself about the one thing most worth getting wrong. */
    const body = NEED.map(n =>
      (n === 'addOnEmailBlock' ? 'async ' : '') + src[n]).join('\n');

    const QUOTE = (over) => Object.assign({
      requoteKind: 'addition', quotedPrice: 780, quoteToken: 'tok1',
      existingCustomerId: 'child', requoteKindNote: 'wants the back garage doing as well'
    }, over || {});

    const world = (quotes, customers) => {
      const writes = [];
      const fn = new Function('quotesCache', 'jobAddresses', 'esc', 'fmtMoney',
        'updateDoc', 'doc', 'db', 'console', 'quoteExistingCustomer',
        body + ';return {block: addOnEmailBlock, pending: pendingAddOnFor, has: rsvpTemplateHasAddOn};')(
        quotes, customers,
        (t) => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;'),
        (n) => '$' + Number(n || 0).toFixed(2),
        (ref, patch) => { writes.push({ ref, patch }); return Promise.resolve(); },
        (dbArg, col, id) => col + '/' + id, {},
        { error: () => {}, log: () => {} },
        /* quotePortalParam calls it; a member with no portal token is the
           ordinary case and yields no &p=. */
        () => null);
      return { fn, writes };
    };

    /* One phone, two real houses — the fixture that makes the trap visible.
       The add-on belongs to the CHILD. */
    const CUSTOMERS = [
      { id: 'parent', data: { name: 'Parent', phone: '(801) 555-0100', address: '10 Elm St', housePrice: 500 } },
      { id: 'child', data: { name: 'Child', phone: '(801) 555-0100', address: '99 Oak Ave', housePrice: 600 } }
    ];

    pendingAsync.push((async () => {
      /* ---- 1. whose add-on it is ------------------------------------- */
      {
        const w = world([{ id: 'q1', data: QUOTE() }], CUSTOMERS);
        check('S131', 'the add-on is found for the customer it was raised against',
          (w.fn.pending('child') || {}).id === 'q1',
          'the explicit link is exact — a re-quote always has one');
        check('S131', 'and NOT for the other household on the same phone',
          w.fn.pending('parent') === null,
          'this is the whole risk: a phone match would print the child\'s quote ' +
          'and price in the parent\'s email, with buttons that answer it');

        const forChild = await w.fn.block('child');
        const forParent = await w.fn.block('parent');
        check('S131', 'so the block renders for one of them and not the other',
          /back garage/.test(forChild) && forParent === '',
          'rendered for the parent: ' + JSON.stringify(forParent.slice(0, 120)));
      }

      /* ---- 2. only a live, priced, unanswered add-on --------------- */
      {
        const cases = [
          ['a move re-quote', { requoteKind: 'address' }],
          ['a price-only re-quote', { requoteKind: 'price' }],
          ['an ordinary first quote', { requoteKind: '' }],
          ['one nobody has priced yet', { quotedPrice: undefined }],
          ['one they already approved', { approvalStatus: 'approved', formCompleted: true }],
          ['one they already declined', { approvalStatus: 'declined' }],
          ['one they answered maybe', { approvalStatus: 'maybe_next_year' }],
          ['an archived one', { quoteArchived: true }],
          ['a closed one', { status: 'closed' }]
        ];
        for (const [label, over] of cases) {
          const w = world([{ id: 'q1', data: QUOTE(over) }], CUSTOMERS);
          const out = await w.fn.block('child');
          check('S131', 'no offer for ' + label, out === '',
            'asking again about something already settled — or offering a price ' +
            'that does not exist yet — is worse than not asking');
        }
        /* ⚠ AND THE ONE THAT MUST STILL WORK, so the checks above cannot pass
           by the block being broken outright. */
        const live = world([{ id: 'q1', data: QUOTE() }], CUSTOMERS);
        check('S131', 'but a live priced add-on IS offered',
          (await live.fn.block('child')).length > 100,
          'if this fails, every "no offer for..." check above proves nothing');
      }

      /* ---- 3. what it says --------------------------------------------- */
      {
        const w = world([{ id: 'q1', data: QUOTE() }], CUSTOMERS);
        const html = await w.fn.block('child');

        check('S131', 'it carries both buttons, pointed at this quote',
          html.indexOf('token=tok1&action=approve') !== -1 &&
          html.indexOf('token=tok1&action=decline&addon=1') !== -1,
          'the decline must carry the add-on marker or the confirmation page ' +
          'asks them whether to close out their whole season');
        check('S131', 'and they are worded as an add-on, not a whole quote',
          /Yes, add it/.test(html) && /just my usual lights/.test(html) &&
          !/Decline Quote/.test(html),
          'the same labels the add-on quote email uses — one rule, read here ' +
          'through quoteButtonLabels rather than retyped');

        /* ⚠ quotedPrice ON A RE-QUOTE IS THE NEW TOTAL, NOT THE ADDITION.
           showApplyRequoteChoice compares it against their current housePrice to
           say "up $X". Printing it as "+$780" would tell a customer on $600 that
           a garage costs $780. */
        check('S131', 'the price is given as the new total, against their current one',
          /\$780\.00/.test(html) && /\$600\.00/.test(html),
          'quotedPrice is what the house would cost, not what the extra costs — ' +
          'shown as a delta it reads as a wildly higher quote');
        check('S131', 'and it does not dress it up as a surcharge',
          !/\+\s*\$780/.test(html),
          'a "+" in front of a total is a different number entirely');

        /* ⚠ SAID IN WORDS. Two sets of yes/no buttons in one email is exactly
           where somebody assumes the second one cancels everything. */
        check('S131', 'it says plainly that no here is not no to the season',
          /does not change your answer above/i.test(html),
          'this sentence is the whole reason the block can safely sit under the ' +
          'season buttons');
        check('S131', 'their own note travels with it',
          /wants the back garage doing as well/.test(html),
          'without it the customer is asked to approve "the extra lights" with ' +
          'no reminder of which extra lights');
      }

      /* ---- 4. a customer with no add-on gets nothing at all ------------ */
      {
        const w = world([], CUSTOMERS);
        check('S131', 'nothing outstanding renders nothing',
          (await w.fn.block('child')) === '',
          'a paragraph saying "you have no outstanding add-ons" is noise on ' +
          'nine hundred emails');
      }
      {
        /* ⚠ THE FIXTURE THAT MAKES THE EMPTY-ID GUARD MEAN SOMETHING. With every
           quote carrying a link, an empty customerId matches nobody anyway and
           deleting the guard changes nothing — the red-check caught that. A quote
           holding NO link is the case the guard is actually for: without it,
           '' === '' matches, and the preview picker sitting on no member at all
           would render somebody's add-on offer. */
        const w = world([{ id: 'q1', data: QUOTE({ existingCustomerId: '' }) }], CUSTOMERS);
        check('S131', 'and no customer id renders nothing',
          (await w.fn.block('')) === '' && (await w.fn.block(null)) === '' &&
          w.fn.pending('') === null,
          'an unlinked quote must not match an empty id — that is how a preview ' +
          'with no member picked shows a real customer\'s offer');
      }

      /* ---- 5. the token ------------------------------------------------ */
      {
        const w = world([{ id: 'q1', data: QUOTE({ quoteToken: '' }) }], CUSTOMERS);
        const html = await w.fn.block('child');
        check('S131', 'a quote with no token gets one, written to the right doc',
          w.writes.length === 1 && w.writes[0].ref === 'quotes/q1' &&
          !!w.writes[0].patch.quoteToken &&
          html.indexOf(w.writes[0].patch.quoteToken) !== -1,
          'the send only mints tokens for templates using {{quote_, by PHONE — ' +
          'which could mint one on the wrong household\'s quote');
      }
      {
        /* ⚠ A BLOCK WHOSE BUTTONS DO NOTHING IS WORSE THAN NO BLOCK. */
        const w = world([{ id: 'q1', data: QUOTE({ quoteToken: '' }) }], CUSTOMERS);
        const fn = new Function('quotesCache', 'jobAddresses', 'esc', 'fmtMoney',
          'updateDoc', 'doc', 'db', 'console', 'quoteExistingCustomer',
          body + ';return addOnEmailBlock;')(
          [{ id: 'q1', data: QUOTE({ quoteToken: '' }) }], CUSTOMERS,
          (t) => String(t == null ? '' : t), (n) => '$' + Number(n || 0).toFixed(2),
          () => Promise.reject(new Error('denied')), () => 'x', {},
          { error: () => {}, log: () => {} }, () => null);
        const out = await fn('child').catch(() => 'THREW');
        check('S131', 'and a token that will not save drops the block, not the email',
          out === '',
          'buttons with no token lead nowhere; the RSVP itself must still go');
      }

      /* ---- 6. escaping ------------------------------------------------- */
      {
        const w = world([{ id: 'q1', data: QUOTE({ requoteKindNote: '<script>x</script>' }) }], CUSTOMERS);
        const html = await w.fn.block('child');
        check('S131', 'the office note is escaped',
          html.indexOf('<script>') === -1,
          'the note is free text typed into a box and lands in an email');
      }
    })());
  }

  /* ---- 7. where it is appended, and where it must NOT be -------------- */
  check('S131', 'the office can place the token by hand',
    /\{\{addon_block\}\}/.test(admin) &&
    /Outstanding add-on/.test(admin),
    'a token nothing lists is a token nobody knows exists');
  check('S131', 'the renderer resolves it from the record id, never the phone',
    /addOnEmailBlock\(opts\.customerId\)/.test(stripComments(admin)),
    'opts.phone is right there and is the wrong answer on a shared number');
  check('S131', 'and the vars carry that id',
    /customerId: item\.id/.test(stripComments(admin)),
    'without it the token silently resolves to nothing for everybody');

  /* ⚠ THE SEND AND THE PREVIEW MUST AGREE. An offer that appears only in the
     real email is one nobody proof-read; one that appears only in the preview
     is a promise that never arrives. Both ask the same two questions, which is
     why rsvpTemplateHasAddOn exists rather than the test being written twice. */
  const appends = stripComments(admin).match(
    /etTemplateIsRsvp\(template\) && !rsvpTemplateHasAddOn\(template\.data\.body\)/g) || [];
  check('S131', 'the send, the preview and the test send all append it the same way',
    appends.length === 3,
    'found ' + appends.length + ' of 3 — the on-screen preview, the test send ' +
    'and the real send must produce the same email');

  /* ⚠ ONLY ON AN RSVP. An add-on offer at the foot of an invoice or a receipt
     is not what either of those emails is for, and a second set of yes/no
     buttons on a bill is genuinely confusing. */
  check('S131', 'and only onto an RSVP template',
    !/^\s*const addOnBlock = await addOnEmailBlock/m.test(stripComments(admin)),
    'appended unconditionally it would ride on invoices and receipts too');
}

/* =====================================================================
 * Suite 132. Back Next Year neither creates a recycle nor destroys one
 *
 * HOLE G, fixed 2026-08-21. Owner, asked what should happen to the bin of
 * somebody who says Back Next Year: keep it made up.
 *
 * ⚠ "DO NOT CREATE ONE" AND "WRITE FALSE" ARE NOT THE SAME THING, and that gap
 * is the whole bug. Every Back Next Year path wrote needsLightRecycle: false
 * unconditionally, so it silently CANCELLED a recycle that was already owed.
 * The way in is ordinary: somebody answers no — the recycle is set and the
 * warehouse is queued to collect their bin — and then changes to Back Next
 * Year. The flag is wiped, the bin stays on the shelf, and nobody is ever told
 * to collect it. A set of lights lost for a year with nothing on any screen to
 * say why.
 *
 * ⚠ FOUR PATHS, THREE OF THEM COPIES OF ONE DECISION. setCustomerSeason
 * describes itself as "the one place that flips a customer between Confirmed
 * and Maybe Next Year" and it is not: the server has its own copy and the Edit
 * Customer save has a third. The fourth is a different route to the same harm —
 * moving an RSVP from 'no' to 'backnextyear' hit a branch meant for somebody
 * coming back IN. All four are RUN below rather than read.
 * ===================================================================== */
suite('Suite 132. Back Next Year neither creates a recycle nor destroys one');
{
  const fns = read('functions/index.js');
  const admin = read('admin.html');

  /* ---- 1. the server path, run ---------------------------------------- */
  const pullSrc = extractFn(fns, 'pullCustomerFromSeason');
  check('S132', 'the server Back Next Year path is findable', !!pullSrc);
  check('S132', 'and is still async in the real file',
    /async function pullCustomerFromSeason\(/.test(fns),
    'the lift below puts the keyword back');

  if (pullSrc) {
    pendingAsync.push((async () => {
      const runPull = (seed) => {
        const doc = Object.assign({}, seed);
        const db = { collection: () => ({ doc: () => ({
          update: (patch) => { Object.assign(doc, patch); return Promise.resolve(); }
        }) }) };
        const fn = new Function('db', 'admin', 'removeCustomerFromUpcomingRoutes',
          'async ' + pullSrc + '\nreturn pullCustomerFromSeason;')(db,
          { firestore: { FieldValue: { serverTimestamp: () => '@ts' } } },
          async () => 0);
        return fn('c1').then(() => doc);
      };

      /* ⚠ THE FIXTURE THAT MATTERS: a recycle ALREADY OWED. With it false to
         begin with, writing false and writing nothing look identical and the
         check proves nothing — which is exactly why this bug survived. */
      const owed = await runPull({ needsLightRecycle: true, needsLightBuild: true });
      check('S132', 'a recycle already owed survives Back Next Year',
        owed.needsLightRecycle === true,
        'they said no first, the warehouse was queued to collect their bin, and ' +
        'then they said back next year — the collection is still owed');

      const intact = await runPull({ needsLightRecycle: false, needsLightBuild: true });
      check('S132', 'and Back Next Year does not create one',
        intact.needsLightRecycle === false,
        'owner: keep the bin made up — breaking it back into stock means ' +
        'building the whole thing again if they do return');

      /* ⚠ THE BUILD IS STILL CANCELLED, and that is the difference. You do not
         make a set for somebody sitting the season out. A fix that spared both
         flags would leave them in the warehouse queue. */
      check('S132', 'but a queued build IS still cancelled',
        owed.needsLightBuild === false && intact.needsLightBuild === false,
        'nothing to build for a season they are not in');
      check('S132', 'and they are still taken out of the season',
        owed.rsvpStatus === 'backnextyear' && owed.maybeNextYear === true &&
        owed.scheduled === false && owed.assignedCrew === null,
        'the rest of Back Next Year is unchanged — only the recycle was wrong');
    })());
  }

  /* ---- 2. the office toggle, run --------------------------------------- */
  const seasonSrc = extractFn(admin, 'setCustomerSeason');
  check('S132', 'the office Back Next Year toggle is findable', !!seasonSrc);
  if (seasonSrc) {
    pendingAsync.push((async () => {
      const runToggle = (toMaybe) => {
        let patch = null;
        const fn = new Function('updateDoc', 'doc', 'db', 'serverTimestamp',
          'jobAddresses', 'renderJobAddressPanels', 'toast',
          'async ' + seasonSrc + '\nreturn setCustomerSeason;')(
          (ref, p) => { patch = p; return Promise.resolve(); },
          () => 'ref', {}, () => '@ts', [], () => {}, () => {});
        return fn('c1', toMaybe).then(() => patch, () => patch);
      };
      const on = await runToggle(true);
      check('S132', 'the office toggle writes no recycle flag either way',
        on && !('needsLightRecycle' in on),
        'wrote: ' + JSON.stringify(Object.keys(on || {})) + ' — the badge, the ' +
        'Edit Customer toggle and the server must not disagree about this');
      check('S132', 'but still clears the build and the schedule',
        on && on.needsLightBuild === false && on.scheduled === false &&
        on.rsvpStatus === 'backnextyear',
        'the rest of what the toggle does is unchanged');
    })());
  }

  /* ---- 3. the Edit Customer save's own copy, run ----------------------- */
  {
    const a = admin.indexOf('    if(newSeasonMaybe){');
    const b = admin.indexOf('    } else if(item.data.maybeNextYear){', a);
    check('S132', 'the Edit Customer Back Next Year branch is findable',
      a !== -1 && b > a,
      'moved or renamed — fix the slice rather than deleting the check');
    if (a !== -1 && b > a) {
      const branch = admin.slice(a, b) + '    }';
      const runBranch = (newSeasonMaybe, data) => {
        const addrUpdates = {};
        new Function('newSeasonMaybe', 'item', 'addrUpdates', 'serverTimestamp',
          branch)(newSeasonMaybe, { data: data }, addrUpdates, () => '@ts');
        return addrUpdates;
      };
      const out = runBranch(true, { needsLightRecycle: true, maybeNextYear: false });
      check('S132', 'the Edit Customer branch writes no recycle flag',
        !('needsLightRecycle' in out),
        'wrote: ' + JSON.stringify(Object.keys(out)) + ' — this is the THIRD ' +
        'copy of the same decision and the one most easily missed');
      check('S132', 'and still does the rest of Back Next Year',
        out.rsvpStatus === 'backnextyear' && out.needsLightBuild === false &&
        out.scheduled === false && out.assignedCrew === null,
        'a fix that gutted the branch would pass the check above for the wrong reason');
    }
  }

  /* ---- 4. the same harm by another route ------------------------------
     Moving an RSVP from 'no' to 'backnextyear' hit a branch written for
     somebody coming back IN. Both are ways of saying not this season, so moving
     between them changes nothing about whether the lights need collecting. */
  {
    const a = admin.indexOf("    if(newRsvp === 'no' && oldRsvpForRecycle !== 'no'){");
    const b = admin.indexOf('/* Rejoining AFTER the recycle', a);
    check('S132', 'the RSVP recycle branch is findable', a !== -1 && b > a);
    if (a !== -1 && b > a) {
      const branch = admin.slice(a, b);
      const runRsvp = (newRsvp, oldRsvp, had) => {
        const addrUpdates = {};
        new Function('newRsvp', 'oldRsvpForRecycle', 'item', 'addrUpdates',
          branch)(newRsvp, oldRsvp, { data: { needsLightRecycle: had } }, addrUpdates);
        return addrUpdates;
      };
      check('S132', 'moving from No to Back Next Year keeps an owed recycle',
        !('needsLightRecycle' in runRsvp('backnextyear', 'no', true)),
        'the same bug by another route — they are still not doing this season, ' +
        'so their lights still need collecting');
      /* ⚠ AND THE BRANCH MUST STILL WORK FOR ITS REAL CASE, or the check above
         passes because the whole thing was gutted. */
      check('S132', 'but coming back in still cancels it',
        runRsvp('yes', 'no', true).needsLightRecycle === false,
        'they are in for the season again, so the recycle their no created goes ' +
        'with it — that is what this branch is FOR');
      check('S132', 'and answering No still raises one',
        runRsvp('no', 'yes', false).needsLightRecycle === true,
        'the RSVP is the one place that decides somebody is out, and this is ' +
        'where the recycle actually belongs');
    }
  }

  /* ---- 5. no Back Next Year path anywhere writes it -------------------- */
  /* ⚠ A BACKSTOP FOR A FOURTH COPY NOBODY HAS WRITTEN YET. The three above are
     checked by running them; this fails if a new one appears with the old
     mistake in it. Scoped to the same object literal / assignment run, so an
     unrelated recycle write elsewhere in the file cannot trip it. */
  /* ⚠ SPLIT ON THE ASSIGNMENT, NOT THE WORD. Splitting on 'backnextyear' alone
     flagged the branch that CORRECTLY excludes it — `newRsvp !== 'backnextyear'`
     mentions the status in order to skip it, and the legitimate clear-on-rejoin
     write sits three lines below. A path that SETS the status is what this is
     about, so that is what it looks for. */
  const bnyWrites = (stripComments(admin) + stripComments(fns))
    .split(/rsvpStatus\s*[:=]\s*'backnextyear'/)
    .slice(1)
    .filter(function (chunk) {
      return /needsLightRecycle\s*[:=]\s*false/.test(chunk.slice(0, 260));
    });
  check('S132', 'no Back Next Year path clears the recycle flag',
    bnyWrites.length === 0,
    bnyWrites.length + ' path(s) still write needsLightRecycle: false within a ' +
    'few lines of setting backnextyear — "do not create one" is not the same ' +
    'thing as "write false"');

  /* ⚠ AND A FIFTH PATH THE BACKSTOP ABOVE COULD NEVER SEE, found when the owner
     traced the sequence herself. portalRsvp writes `rsvpStatus: response` — a
     VARIABLE — so no literal 'backnextyear' sits near its recycle write, and
     `needsLightRecycle: response === 'no'` reads as harmless while quietly
     writing FALSE for backnextyear. A pattern that only catches literals cannot
     catch the one written as an expression, so this asserts the shape directly. */
  check('S132', 'the portal does not decide the recycle from a bare comparison',
    !/needsLightRecycle:\s*response === 'no'/.test(stripComments(fns)),
    'that expression is false for backnextyear as well as for yes, so it wipes ' +
    'an owed collection for somebody who never said their lights could come back');
  /* ⚠ THE YES HALF MOVED, THE RULE DID NOT (merge, 2026-08-22). This required both
     halves inline: `if (response === 'no') ... else if (response === 'yes') ...`. A
     parallel change gave a yes ONE server-side definition — seasonYesUpdates, shared
     by the RSVP link and quote approval — so the cancel now lives there and portalRsvp
     keeps only the answer that CREATES a collection. Same behaviour, and season-state
     RUNS the helper to prove it; what is asserted here is that neither half went
     missing in the move. */
  check('S132', 'it writes the recycle only for the two answers that decide it',
    /if \(response === 'no'\) updates\.needsLightRecycle = true;/.test(stripComments(fns)) &&
    /needsLightRecycle: false,/.test(stripComments(extractFn(fns, 'seasonYesUpdates') || '')),
    "'no' owes a collection, 'yes' cancels the one their no created, and " +
    "'backnextyear' says nothing either way");
  /* ⚠ AND backnextyear STILL SAYS NOTHING. The whole point of hole G, asserted from
     the other side: nothing in that door may write the flag for it. */
  /* ⚠ SCOPED TO portalRsvp'S OWN BODY. A file-wide count catches an unrelated write
     in another function and reports a violation that is not one — which it did on the
     first run. */
  check('S132', 'and back next year writes no recycle at all, either way',
    (function () {
      const at = fns.indexOf('exports.portalRsvp');
      const body = at === -1 ? '' : stripComments(fns.slice(at, fns.indexOf('\n});', at)));
      return (body.match(/updates\.needsLightRecycle\s*=/g) || []).length === 1;
    })(),
    'portalRsvp should write it in exactly one place — the "no" branch');

  /* ---- 6. the flag may not outlive the answer that set it -------------
     maybeNextYear was sticky: a search of the whole codebase found ONE thing
     that ever cleared it (the office badge toggle) while rsvpStatus moved
     freely. Two fields describing one fact, drifting apart. */
  check('S132', 'unticking Back Next Year in the office clears the flag itself',
    /addrUpdates\.maybeNextYear = false;/.test(stripComments(admin)),
    'that branch nulled maybeNextYearAt and left maybeNextYear true, so ' +
    'unticking it did not untick it — badge said Confirmed, Contact 2027 still ' +
    'held them, and the Yes sheet did not');
  check('S132', 'and approving a quote clears it too',
    /maybeNextYear: false,\s*\r?\n\s*maybeNextYearAt: null/.test(stripComments(fns)),
    'the RSVP reset leaves the flag standing while setting everyone to ' +
    'unanswered, so somebody who sat last season out can reach the approve ' +
    'path still carrying it');
}

/* =====================================================================
 * Suite 133. A wire or timer change reaches the warehouse
 *
 * Known holes C and D. Owner: "Can you make sure it hits the warehouse that is
 * very important."
 *
 * ⚠ THE HOLE: only a COLOUR change ever set needsLightBuild. A member could
 * change their WIRE COLOUR or their TIMER in their own portal, the record
 * updated, an inbox message went up — and they never appeared in Needs
 * Building. needsLightBuild appeared ZERO times in index.html. The office side
 * was no better: Edit Customer computed the flag from lightsDescription alone.
 *
 * ⚠ AND BOTH GENUINELY CHANGE WHAT GETS MADE, which is why this is not cosmetic:
 *   - whGroupKey(lightsDescription, wireColor) — the same pattern on white wire
 *     and on green wire are two different bundles on two different shelves.
 *   - whBuildQueueGroups collects timerHouses while walking the QUEUE, so
 *     somebody not in the queue is not on the timer list at all.
 * ===================================================================== */
suite('Suite 133. A wire or timer change reaches the warehouse');
{
  const fns = read('functions/index.js');
  const admin = read('admin.html');

  /* ---- 1. the two copies of the rule agree ---------------------------- */
  const bSrc = extractFn(admin, 'warehouseRebuildFields');
  const sSrc = extractFn(fns, 'warehouseRebuildFields');
  const bList = admin.match(/const WAREHOUSE_BUILD_FIELDS = (\[[^\]]*\]);/);
  const sList = fns.match(/const WAREHOUSE_BUILD_FIELDS = (\[[^\]]*\]);/);
  check('S133', 'both copies of the rule and its field list are findable',
    !!bSrc && !!sSrc && !!bList && !!sList,
    'renamed or moved — fix the lift rather than deleting the parity check');

  if (bSrc && sSrc && bList && sList) {
    check('S133', 'and both build from the same three fields',
      bList[1].replace(/\s/g, '') === sList[1].replace(/\s/g, ''),
      'browser: ' + bList[1] + ' server: ' + sList[1] + ' — a field on one side ' +
      'only is a change the other half of the app never notices');

    const mk = (src, list) => new Function('WAREHOUSE_BUILD_FIELDS',
      src + ';return warehouseRebuildFields;')(JSON.parse(list.replace(/'/g, '"')));
    const B = mk(bSrc, bList[1]), S = mk(sSrc, sList[1]);

    /* Every shape that has caused trouble in this file: a partial update, a
       blank, a stray case, whitespace from a paste, and the timer's three
       spellings of two states. */
    const CASES = [
      [{}, {}],
      [{ wireColor: 'White' }, { wireColor: 'Green' }],
      [{ wireColor: 'White' }, { wireColor: 'white' }],
      [{ wireColor: 'White' }, { wireColor: ' White ' }],
      [{ wireColor: '' }, { wireColor: 'Green' }],
      [{ wireColor: 'Green' }, { wireColor: '' }],
      [{ outletTimer: 'No' }, { outletTimer: 'Yes' }],
      [{ outletTimer: 'Yes' }, { outletTimer: 'No' }],
      [{ outletTimer: '' }, { outletTimer: 'No' }],
      [{ outletTimer: undefined }, { outletTimer: 'No' }],
      [{ outletTimer: 'No' }, { outletTimer: '' }],
      [{ lightsDescription: 'Warm White' }, { lightsDescription: 'Red, Green' }],
      [{ lightsDescription: 'Warm White', wireColor: 'White' }, { notes: 'hi' }],
      [{ lightsDescription: 'Warm White' }, { wireColor: 'Green', outletTimer: 'Yes' }],
      [{ wireColor: 'White', outletTimer: 'No', lightsDescription: 'A' },
       { wireColor: 'Green', outletTimer: 'Yes', lightsDescription: 'B' }],
      [null, null], [undefined, { wireColor: 'Green' }]
    ];
    const tryRun = (fn, c) => { try { return JSON.stringify(fn(c[0], c[1])); } catch (e) { return 'THREW: ' + (e && e.message); } };
    const disagreed = CASES.filter(c => tryRun(B, c) !== tryRun(S, c));
    check('S133', 'the browser and the server agree what needs rebuilding',
      !disagreed.length,
      'disagreed on: ' + JSON.stringify(disagreed) + ' — the office would ' +
      'requeue and the portal would not, or the other way round');

    /* ⚠ AND THE ANSWERS ARE RIGHT, not merely equal. Two copies wrong in the
       same way agree perfectly — the lesson money-parity already carries. */
    check('S133', 'a wire change needs a rebuild',
      S({ wireColor: 'White' }, { wireColor: 'Green' }).join() === 'wireColor',
      'wire is part of whGroupKey, so the bundle already made is on the wrong shelf');
    check('S133', 'a timer change needs a rebuild',
      S({ outletTimer: 'No' }, { outletTimer: 'Yes' }).join() === 'outletTimer',
      'the Timers list is collected while walking the build queue, so somebody ' +
      'not in the queue never gets a timer put in their bundle');
    check('S133', 'and a colour change still does',
      S({ lightsDescription: 'A' }, { lightsDescription: 'B' }).join() === 'lightsDescription',
      'the one case that already worked must keep working');

    /* ⚠ hasOwnProperty IS LOAD-BEARING. Every caller sends a PARTIAL update —
       the portal's preferences section carries no lightsDescription at all — and
       reading an absent field as "" would report a cleared pattern on every
       save and re-queue the entire book. */
    check('S133', 'a field the update does not mention is not a change',
      S({ lightsDescription: 'Warm White', wireColor: 'White' }, { notes: 'hi' }).length === 0,
      'every save is partial; an absent field read as blank re-queues everybody');
    check('S133', 'nor is re-saving the same values',
      S({ wireColor: 'White', outletTimer: 'No' },
        { wireColor: 'white', outletTimer: ' NO ' }).length === 0,
      'case and pasted whitespace are not a decision anybody made');
    /* ⚠ A BLANK TIMER IS "NO", not a third state — index.html has always
       compared it as (outletTimer || 'No'). Treating them as different makes an
       untouched record look changed for ever. */
    check('S133', 'a blank timer and No are the same thing',
      S({ outletTimer: '' }, { outletTimer: 'No' }).length === 0 &&
      S({}, { outletTimer: 'No' }).length === 0,
      'otherwise every customer who never answered the timer question re-queues ' +
      'on their next save, for ever');
    check('S133', 'but a blank wire and a real wire are not',
      S({ wireColor: '' }, { wireColor: 'Green' }).join() === 'wireColor',
      'their bundle was made on whatever the default was; green is a real change');
    check('S133', 'and several at once are all reported',
      S({ wireColor: 'White', outletTimer: 'No', lightsDescription: 'A' },
        { wireColor: 'Green', outletTimer: 'Yes', lightsDescription: 'B' }).length === 3,
      'reporting only the first would hide the other two from anything that ' +
      'later wants to say WHAT changed');
    /* ⚠ CAUGHT, so this fails AS ITSELF. Dropping the `|| {}` guards makes the
       call THROW, and an uncaught throw in a synchronous suite takes the whole
       run down with a stack trace that names neither the suite nor the rule —
       the red-check hit exactly that. CLAUDE.md carries the same lesson from
       the workbook-writer suite. */
    const safely = (a, b) => { try { return S(a, b); } catch (e) { return { threw: String(e && e.message) }; } };
    check('S133', 'and a missing record either side does not throw',
      Array.isArray(safely(null, null)) && safely(null, null).length === 0 &&
      Array.isArray(safely(undefined, { wireColor: 'Green' })) &&
      safely(undefined, { wireColor: 'Green' }).join() === 'wireColor',
      'a save must never die because a cache was still loading');
  }

  /* ---- 2. the portal actually sets the flag, run ---------------------- */
  {
    /* ⚠ LINE ENDINGS, AND THIS IS WHY main WENT RED (fixed 2026-08-22).
       functions/index.js is stored with CRLF — 3,778 of them, in the git blob
       itself, so CI sees them too and this was NOT a Windows-only artifact. A
       multi-line anchor written with \n therefore matched nothing, indexOf returned
       -1, and the check failed on main for everybody while pointing at a block of
       code that had never moved.
       CLAUDE.md §7 says it in as many words: measure the line endings, do not
       believe them, and write \r?\n in every pattern. An indexOf cannot express
       that, so the haystack is normalised instead — the slice offsets below are
       taken from the SAME normalised string, so they stay consistent. */
    const fnsLF = fns.replace(/\r\n/g, '\n');
    const A = '  {\n    const rebuild = warehouseRebuildFields(oldData, updates);';
    const a = fnsLF.indexOf(A);
    check('S133', 'the portal rebuild block is where this suite expects it', a !== -1);
    if (a !== -1 && sSrc && sList) {
      /* ⚠ SAME STRING AS `a` CAME FROM. Mixing a normalised offset with the raw
         file slices at the wrong byte and hands `new Function` a fragment that
         either throws or, worse, runs a different rule than the one on disk. */
      const b = fnsLF.indexOf("  if (section === 'lights'", a);
      const blk = fnsLF.slice(a, b);
      const run = (oldData, updates) => {
        new Function('oldData', 'updates', 'warehouseRebuildFields',
          blk)(oldData, updates,
          new Function('WAREHOUSE_BUILD_FIELDS', sSrc + ';return warehouseRebuildFields;')(
            JSON.parse(sList[1].replace(/'/g, '"'))));
        return updates;
      };
      check('S133', 'changing the wire in the portal queues the warehouse',
        run({ wireColor: 'White' }, { wireColor: 'Green' }).needsLightBuild === true,
        'this is the hole: the record changed, a note went to the inbox, and ' +
        'they never appeared in Needs Building');
      check('S133', 'and so does changing the timer',
        run({ outletTimer: 'No' }, { outletTimer: 'Yes' }).needsLightBuild === true,
        'no timer would ever be put in their bundle');
      check('S133', 'but an unrelated save does not',
        run({ wireColor: 'White' }, { notes: 'gate code is 1234' }).needsLightBuild === undefined,
        're-queueing on every save would drown the real ones');
      /* ⚠ IT MAY ONLY EVER TURN THE FLAG ON. The lights block below it carries
         its own hard-won rule — blank colours mean the build cannot be DONE yet,
         not that it is not owed — and this must not overwrite it. */
      check('S133', 'and it never turns the flag off',
        run({ wireColor: 'White' }, { wireColor: 'White', needsLightBuild: true })
          .needsLightBuild === true,
        'writing false here would bring back the bug where saving a customer ' +
        'with no colours silently cleared the build they were owed');
    }
  }

  /* ---- 3. and the office side does too -------------------------------- */
  check('S133', 'the office save asks the same question',
    /if\(warehouseRebuildFields\(item\.data, addrUpdates\)\.length\) addrUpdates\.needsLightBuild = true;/
      .test(stripComments(admin)),
    'a member can change their wire in the portal and the office can change it ' +
    'on their record — both have to reach the same queue');
  /* ⚠ AFTER the existing lights expression, never before or instead of it. */
  const admStripped = stripComments(admin);
  const iLights = admStripped.indexOf('addrUpdates.needsLightBuild = newLightsDescription');
  const iWire = admStripped.indexOf('if(warehouseRebuildFields(item.data, addrUpdates).length)');
  check('S133', 'and does it after the colour rule, not instead of it',
    iLights !== -1 && iWire > iLights,
    'that expression is what keeps a build OWED for a customer with no colours ' +
    'on file; running before it, or replacing it, loses that');
}

/* =====================================================================
 * Suite 134. Everyone added from the sheet gets a number and a build
 *
 * Known hole B. Owner: "everyone new should get a number so we want to build
 * everyone but everyone should also have a number."
 *
 * ⚠ SIX PLACES CREATE A CUSTOMER RECORD AND ONLY Add Customer SET
 * needsLightBuild. Somebody added from the master sheet arrived with their
 * colours, their wire and their feet, and never appeared in Needs Building — no
 * bundle was ever made and the crew turns up at a house with nothing for it.
 * A row with no CU# also arrived with no number at all, so there was no label
 * for their bin.
 *
 * ⚠ THE DANGEROUS HALF IS THE NUMBERING, NOT THE FLAG. cnNextAvailable answers
 * from the caches — availableCustomerNumbers and jobAddresses — refreshed by a
 * Firestore listener that does NOT fire between two iterations of a tight loop.
 * Called twelve times in a row it returns the SAME number twelve times, and
 * twelve customers are labelled for one bin. The pool keeps no record of it and
 * the collision surfaces only as two houses wearing one label on a shelf. That
 * is what cnAllocator exists for and what most of this suite is about.
 * ===================================================================== */
suite('Suite 134. Everyone added from the sheet gets a number and a build');
{
  const admin = read('admin.html');
  const allocSrc = extractFn(admin, 'cnAllocator');
  check('S134', 'the allocator is findable', !!allocSrc,
    'renamed or moved — fix the lift rather than deleting the suite');

  if (allocSrc) {
    /* Seeded through the same two helpers the real one uses, stubbed only as
       DATA SOURCES — the allocation logic itself is the shipped code. */
    const mk = (poolReg, poolDbl, highReg, highDbl) => new Function(
      'cnFreePool', 'cnHighestAssigned',
      allocSrc + ';return cnAllocator();')(
      (t) => (t === 'double' ? poolDbl : poolReg).map(id => ({ id: String(id) })),
      (t) => (t === 'double' ? highDbl : highReg));

    /* ---- 1. the collision this exists to prevent -------------------- */
    {
      /* An empty pool is the ordinary case mid-season: numbers come from
         highest+1, and THAT is where a cache that never refreshes bites. */
      const a = mk([], [], 900, 5100);
      const got = [a.take('regular').number, a.take('regular').number,
                   a.take('regular').number, a.take('regular').number];
      check('S134', 'four customers in one run get four different numbers',
        new Set(got).size === 4,
        'got ' + JSON.stringify(got) + ' — calling cnNextAvailable in a loop ' +
        'returns the same number every time, and that is twelve houses on one ' +
        'bin label with nothing recording it');
      check('S134', 'and they run on from the highest already assigned',
        got.join() === '901,902,903,904',
        'starting anywhere else hands out a number somebody already holds');
    }
    {
      const a = mk([481, 729], [], 900, 5100);
      const got = [a.take('regular').number, a.take('regular').number, a.take('regular').number];
      check('S134', 'the pool is emptied before any new number is minted',
        got.join() === '481,729,901',
        'got ' + JSON.stringify(got) + ' — a freed number left unused while new ' +
        'ones are minted is how the series climbs for no reason');
      check('S134', 'and each pooled number is handed out only once',
        new Set(got).size === 3);
    }
    {
      /* ⚠ THE TWO SERIES ARE SEPARATE, and a two-bin house must take a
         5000-series number. `>= 2`, never `=== 2`. */
      const a = mk([481], [5101], 900, 5100);
      check('S134', 'a two-bin house takes a 5000-series number',
        a.take('double').number === '5101' && a.take('regular').number === '481',
        'a three-bin house handed a regular number is labelled for a bin that ' +
        'does not exist');
    }
    {
      /* ⚠ AND A NUMBER ALREADY GIVEN OUT THIS RUN IS SKIPPED even when the
         counter would land on it — the two series can otherwise collide. */
      const a = mk([], [], 5100, 5100);
      const one = a.take('regular').number, two = a.take('double').number;
      check('S134', 'the two series never hand out the same number',
        one !== two,
        'got ' + one + ' and ' + two + ' — both counters can sit on the same ' +
        'value, and two bins wearing one label is the whole failure this file ' +
        'keeps warning about');
    }

    /* ---- 2. taking a number and keeping it are two steps ------------- */
    {
      const a = mk([481, 729], [], 900, 5100);
      const first = a.take('regular').number;
      const second = a.take('regular').number;
      a.confirm(first);
      check('S134', 'only a number whose customer really saved leaves the pool',
        a.taken().map(h => h.number).join() === String(first),
        'a number pulled from the pool for a row that then failed to save is ' +
        'a number lost, with nothing on any screen to explain it');
      check('S134', 'but the failed one is still not offered again this run',
        a.take('regular').number !== second,
        'a wasted number costs the next number up; a repeated one puts two ' +
        'houses on one bin label');
      /* ⚠ A MINTED NUMBER WAS NEVER IN THE POOL, so it must never be deleted
         from it — that delete would silently do nothing today and remove a
         real entry the day the series wraps onto a freed number. */
      const b = mk([], [], 900, 5100);
      const minted = b.take('regular').number;
      b.confirm(minted);
      check('S134', 'a freshly minted number is not deleted from the pool',
        b.taken().length === 0,
        'it was never in it');
    }

    /* ---- 3. the loop uses it correctly ------------------------------- */
    const body = extractFn(admin, 'rbApplyTickedAdds') || '';
    check('S134', 'the sheet-add loop is findable', !!body);
    if (body) {
      const stripped = stripComments(body);
      check('S134', 'the allocator is seeded once, outside the loop',
        /const cnAlloc = cnAllocator\(\);/.test(stripped) &&
        stripped.indexOf('const cnAlloc = cnAllocator();') < stripped.indexOf('for(let n = 0'),
        'seeding it per row is the same bug as calling cnNextAvailable per row');
      check('S134', 'and cnNextAvailable is never called in the loop',
        !/cnNextAvailable/.test(stripped),
        'that is the function that cannot be used here at all');
      check('S134', 'a row that already has a CU# keeps it',
        /if\(!doc2\.customerNumber && !r\.pairedSite\)/.test(stripped),
        'the sheet is the office\'s own record of who holds which number');
      /* ⚠ AND AN EXISTING RECORD IS NEVER RENUMBERED. A pairedSite row is a
         correction to somebody already here, whose bin is on a shelf under
         their old label. */
      check('S134', 'and an existing record is never renumbered',
        /&& !r\.pairedSite\)/.test(stripped),
        'renumbering somebody whose bin is already labelled is exactly the harm ' +
        'binLabelNumber exists to describe');
      check('S134', 'the series follows the bin count',
        /\(Number\(doc2\.numberOfBins\) \|\| 1\) >= 2 \? 'double' : 'regular'/.test(stripped),
        'never === 2, or a three-bin house gets a regular number');
      check('S134', 'every added customer is queued for building',
        /needsLightBuild: true,/.test(stripped),
        'owner: "we want to build everyone" — this is the hole, and without it ' +
        'the crew arrives at a house with no bundle made for it');
      /* ⚠ THE POOL CLEANUP RUNS AFTER THE LOOP, not inside it. */
      check('S134', 'the pool is emptied after the loop, of confirmed numbers only',
        /for\(const h of cnAlloc\.taken\(\)\)/.test(stripped) &&
        stripped.indexOf('cnAlloc.taken()') > stripped.lastIndexOf('addDoc(collection(db,\'jobAddresses\')'),
        'deleting as each number is handed out loses one whenever the write ' +
        'that follows it fails');
      check('S134', 'and it confirms only after the customer is written',
        /await addDoc\(collection\(db,'jobAddresses'\), doc2\);\s*\r?\n\s*if\(doc2\.customerNumber\) cnAlloc\.confirm\(doc2\.customerNumber\);/
          .test(stripped),
        'confirming first would take the number out of the pool for a customer ' +
        'who never existed');
      check('S134', 'each pool delete is guarded on its own',
        /cnAlloc\.taken\(\)[\s\S]{0,400}?\.catch\(/.test(stripped),
        'half a cleanup is better than none, and a pool entry that survives is ' +
        'found again by Find conflicts — one deleted in error is simply gone');
    }
  }

  /* ---- 4. what the office is told -------------------------------------- */
  /* ⚠ MATCHED AS ONE EXPRESSION, not as a loose phrase. A bare
     /all queued for building/ passed with the whole thing wrapped in a
     `(false ? ...)` — the words survive, unreachable. Comments are stripped
     first and the concatenation must run straight on from the added.done
     branch, so anything inserted between them breaks the match. */
  check('S134', 'the report says they were queued and numbered',
    /added\.done \+ ' customer\(s\) added' \+\s*' \(all queued for building'/
      .test(stripComments(admin)) &&
    /given a customer number/.test(admin),
    'a number handed out is a bin label somebody has to write and a build ' +
    'queued is a bundle somebody has to make — automatic is fine, invisible is not');
}

/* =====================================================================
 * Suite 135. A house that cannot be invoiced is a job, not a statistic
 *
 * Known hole H. The nightly run used to hit a bare `continue` for a payer with
 * no email — not counted as sent, skipped or errored — so the summary read
 * "0 sent, 0 errors" while an installed house went unbilled all season. That
 * half was already fixed: they are counted and the first three are named in the
 * nightly text.
 *
 * ⚠ COUNTED IS NOT ACTIONABLE. It is the same number every night, so it reads
 * as background noise; nothing sat on the customer, so the office could not
 * find out WHO; and nothing changed when an email was finally added. Meanwhile
 * the materials, the crew's day and the bundle are already spent.
 *
 * ⚠ AND THE FLAG MUST NOT GO STICKY. maybeNextYear had exactly one way out and
 * cost a customer a whole season (Suite 132). This one is set AND cleared by
 * the same nightly run — one writer, one rule — and the office screen does not
 * even wait for that: the tag checks live that they still have no email, so it
 * disappears the moment one is typed. Stored fact, derived display.
 * ===================================================================== */
suite('Suite 135. A house that cannot be invoiced is a job, not a statistic');
{
  const fns = read('functions/index.js');
  const admin = read('admin.html');

  /* ---- 1. the rule the office screen reads, RUN ----------------------- */
  const ruleSrc = extractFn(admin, 'custCannotBeBilled');
  check('S135', 'the office rule is findable', !!ruleSrc);
  if (ruleSrc) {
    const R = new Function(ruleSrc + ';return custCannotBeBilled;')();
    check('S135', 'flagged and still no email reads as cannot-be-billed',
      R({ cannotBillNoEmail: true }) === true &&
      R({ cannotBillNoEmail: true, email: '', email2: '  ' }) === true,
      'this is the state the nightly run left them in');
    /* ⚠ THE LIVE HALF. The flag is written once a night, so on the stored value
       alone the tag would sit there all day after somebody typed an email in —
       and the office would go looking for a gap that is already closed. */
    check('S135', 'but an email typed since clears it on screen at once',
      R({ cannotBillNoEmail: true, email: 'a@b.com' }) === false &&
      R({ cannotBillNoEmail: true, email2: 'a@b.com' }) === false,
      'waiting until tomorrow night to stop showing it is how a fixed thing ' +
      'keeps being worked on');
    /* ⚠ AND IT NEVER SHOWS FOR SOMEBODY WHO SIMPLY HAS NO EMAIL YET. The flag is
       what says the run actually tried and failed. Plenty of records have no
       email; tagging all of them would bury the dozen that matter. */
    check('S135', 'and a customer the run never tried is not tagged',
      R({ email: '' }) === false && R({}) === false &&
      R({ cannotBillNoEmail: false, email: '' }) === false,
      'a tag on every record with a blank email is a tag on nothing');
    /* ⚠ CAUGHT, so this fails AS ITSELF. Dropping the `|| {}` makes the call
       THROW, and an uncaught throw in a synchronous suite takes the whole run
       down with a stack trace naming neither the suite nor the rule — the
       red-check hit exactly that, for the fourth time in this session. */
    const safeR = v => { try { return R(v); } catch (e) { return 'THREW: ' + (e && e.message); } };
    check('S135', 'a missing record does not throw',
      safeR(null) === false && safeR(undefined) === false,
      'the row draws while the cache is still loading');
  }

  /* ---- 2. the nightly run: the skip path, RUN ------------------------- */
  /* ⚠ CRLF AGAIN — see the note in Suite 133. `B` spans two lines, so against the
     real file (which is stored with CRLF, in the blob, so CI too) it matched
     nothing and this check failed on main for everybody. Normalised haystack, and
     every offset below is taken from the same normalised string. */
  const fnsLF = fns.replace(/\r\n/g, '\n');
  const A = '        if (!email) {';
  const B = '          continue;\n        }';
  const a = fnsLF.indexOf(A);
  const b = fnsLF.indexOf(B, a);
  check('S135', 'the no-email skip block is where this suite expects it',
    a !== -1 && b > a,
    'moved or renamed — fix the slice rather than deleting the suite');

  if (a !== -1 && b > a) {
    /* ⚠ Same normalised string `a` and `b` came from — see above. Slicing the raw
       file with normalised offsets hands `new Function` a fragment cut at the wrong
       byte, which is how this suite went from failing to crashing outright. */
    const blk = fnsLF.slice(a, b) + '\n        }';
    const runSkip = (payerData) => {
      const writes = [], msgs = [];
      let skippedNoEmail = 0; const noEmailNames = [];
      const db = {
        collection: (c) => c === 'messages'
          ? { add: (m) => { msgs.push(m); return Promise.resolve({}); } }
          : { doc: (id) => ({ update: (p) => { writes.push({ id, p }); return Promise.resolve(); } }) }
      };
      /* tryFirestore is the real contract: it returns, never throws. */
      const tryFirestore = async (label, fn) => {
        try { return { ok: true, value: await fn() }; } catch (e) { return { ok: false }; }
      };
      const body = 'return (async () => { let skippedNoEmail = 0; const noEmailNames = [];' +
        blk.replace('continue;', '') +
        ' return {skippedNoEmail, noEmailNames}; })();';
      return new Function('email', 'payer', 'db', 'admin', 'tryFirestore', body)(
        '', { id: 'c1', data: payerData }, db,
        { firestore: { FieldValue: { serverTimestamp: () => '@ts' } } }, tryFirestore
      ).then(counts => ({ counts, writes, msgs }));
    };

    pendingAsync.push((async () => {
      {
        const r = await runSkip({ name: 'Phone Only', phone: '8015550100' });
        check('S135', 'a payer with no email is still counted and named',
          r.counts.skippedNoEmail === 1 && r.counts.noEmailNames[0] === 'Phone Only',
          'the half that was already fixed must keep working — it is what stops ' +
          'the summary reading "0 sent, 0 errors"');
        check('S135', 'and now the flag lands on their record',
          r.writes.length === 1 && r.writes[0].id === 'c1' &&
          r.writes[0].p.cannotBillNoEmail === true,
          'without it the office cannot find out WHO could not be billed');
        check('S135', 'and a note names them and says how to clear it',
          r.msgs.length === 1 && r.msgs[0].folder === 'System' &&
          /Phone Only/.test(r.msgs[0].message) &&
          /Cannot Be Billed/.test(r.msgs[0].message) &&
          /clears this by itself/.test(r.msgs[0].message),
          'a note that reports a problem without naming the screen to fix it on ' +
          'is one more thing to work out at 7pm');
        check('S135', 'and it counts on the sidebar badge',
          r.msgs[0].read === undefined,
          'the badge counts unread messages whatever the folder — a note marked ' +
          'read on arrival is invisible');
      }
      /* ⚠ ONCE, NOT NIGHTLY. The same note every night for the same house is how
         somebody learns to ignore the folder — and this runs 365 times a year. */
      {
        const r = await runSkip({ name: 'Already Flagged', cannotBillNoEmail: true });
        check('S135', 'a customer already flagged is not written to again',
          r.writes.length === 0 && r.msgs.length === 0,
          'a nightly repeat trains the office to ignore the one folder that ' +
          'carries real work');
        check('S135', 'but they are still counted in the nightly summary',
          r.counts.skippedNoEmail === 1,
          'the count is tonight\'s truth; the note is the first-time alert. ' +
          'Suppressing the count too would put the "0 errors" lie straight back');
      }
      /* ⚠ AND THE REPORTER CANNOT BECOME THE FAILURE. Everything here runs
         through tryFirestore, so a refused write is reported, never thrown —
         one un-billable customer must not stop the other 959 being invoiced. */
      {
        const writes = [];
        const blown = new Function('email', 'payer', 'db', 'admin', 'tryFirestore',
          'return (async () => { let skippedNoEmail = 0; const noEmailNames = [];' +
          blk.replace('continue;', '') + ' return skippedNoEmail; })();')(
          '', { id: 'c1', data: { name: 'X' } },
          { collection: () => ({ doc: () => ({ update: () => Promise.reject(new Error('denied')) }),
                                 add: () => Promise.reject(new Error('denied')) }) },
          { firestore: { FieldValue: { serverTimestamp: () => '@ts' } } },
          async (l, fn) => { try { return { ok: true, value: await fn() }; } catch (e) { return { ok: false }; } });
        const out = await blown.catch(e => 'THREW: ' + e.message);
        check('S135', 'a refused write does not stop the rest of the run',
          out === 1,
          'got ' + JSON.stringify(out) + ' — one un-billable customer must never ' +
          'take the other 959 invoices down with it');
      }
    })());
  }

  /* ---- 3. the same run clears it -------------------------------------- */
  /* ⚠ ANCHORED ON THE COMMENT, NOT ON THE GUARD. Slicing from
     'if (payer.data.cannotBillNoEmail) {' meant a sabotage of that very line —
     the "clears unconditionally" case this exists to catch — destroyed the
     anchor, so the findability check went red instead and the real one never
     ran. The slice has to survive the change it is watching for. */
  const clearStart = fns.indexOf('⚠ THE SAME RUN CLEARS IT');
  const clearSrc = clearStart === -1 ? '' : fns.slice(
    fns.lastIndexOf('        /*', clearStart),
    fns.indexOf('        const phone = digitsOnly(payer.data.phone);', clearStart));
  check('S135', 'the clear block is findable', clearSrc.length > 50 && clearSrc.length < 900);
  if (clearSrc.length > 50 && clearSrc.length < 900) {
    pendingAsync.push((async () => {
      const runClear = (payerData) => {
        const writes = [];
        return new Function('payer', 'db', 'tryFirestore',
          'return (async () => {' + clearSrc + '})();')(
          { id: 'c1', data: payerData },
          { collection: () => ({ doc: (id) => ({ update: (p) => { writes.push({ id, p }); return Promise.resolve(); } }) }) },
          async (l, fn) => { try { return { ok: true, value: await fn() }; } catch (e) { return { ok: false }; } }
        ).then(() => writes);
      };
      check('S135', 'a payer who now has an email is cleared',
        (await runClear({ cannotBillNoEmail: true }))[0].p.cannotBillNoEmail === false,
        'a flag with only one way in is the sticky bug maybeNextYear already ' +
        'cost a customer a whole season for');
      /* ⚠ AND AN ORDINARY NIGHT WRITES NOTHING EXTRA. Clearing unconditionally
         would be ~960 pointless writes every single night. */
      check('S135', 'but an ordinary payer is not written to at all',
        (await runClear({})).length === 0,
        'clearing a flag nobody has is a write to every customer, nightly');
    })());
  }

  /* ---- 4. the office can work the list -------------------------------- */
  check('S135', 'there is a filter for them in All Customers',
    /id="filterCannotBill"/.test(admin) &&
    /activeCannotBillFilter = document\.getElementById\('filterCannotBill'\)\.checked;/.test(stripComments(admin)) &&
    /if\(activeCannotBillFilter\) filtered = filtered\.filter\(a => custCannotBeBilled\(a\.data\)\);/.test(stripComments(admin)),
    'a checkbox with no filter behind it, or a filter no checkbox reaches, is ' +
    'worse than neither — this repo has shipped both');
  check('S135', 'the filter and the row tag ask the same question',
    (stripComments(admin).match(/custCannotBeBilled\(/g) || []).length >= 3,
    'the tag, the filter and the rule itself — a second definition is how a row ' +
    'shows a tag the filter cannot find');
  check('S135', 'and the active-filter line names it',
    /parts\.push\('Cannot Be Billed'\)/.test(stripComments(admin)),
    'a filter silently narrowing the list is how somebody concludes half their ' +
    'customers have vanished');
  check('S135', 'the portal can read the flag',
    /'cannotBillNoEmail'/.test(fns),
    'in PORTAL_READ_FIELDS so the portal cannot show a customer as settled while ' +
    'the office is chasing them for an address');
}

/* =====================================================================
 * Suite 136. The three the mutation sweep found unguarded
 *
 * A sweep on 2026-08-21 neutered 44 real functions one at a time — inserting an
 * early return so each still parses but does nothing — and asked whether the
 * gates noticed. Three did not: every check that mentioned them read source
 * text, so the words were still there and the suite stayed green while the
 * function did nothing at all.
 *
 * That is the exact failure this repo keeps re-learning: a regex over a file
 * proves the code EXISTS, which is a weaker claim than it works. All three are
 * RUN here.
 * ===================================================================== */
suite('Suite 136. The three the mutation sweep found unguarded');
{
  const money = read('js/money.js');
  const fns = read('functions/index.js');
  const admin = read('admin.html');

  /* ---- enrollmentYearOf: which season a customer joined in ------------ */
  {
    const src = extractFn(money, 'enrollmentYearOf');
    check('S136', 'enrollmentYearOf is findable', !!src);
    if (src) {
      const F = new Function(src + ';return enrollmentYearOf;')();
      /* ⚠ FIVE SHAPES, because a createdAt reaches this from five places: a
         live Firestore Timestamp, one rehydrated from a plain object, a real
         Date, a millisecond number, and a string from an import. Getting any
         of them wrong silently mis-dates when somebody joined. */
      check('S136', 'it reads a Firestore Timestamp',
        F({ toDate: () => new Date('2024-11-03T12:00:00Z') }) === 2024,
        'the ordinary case — everything written by the app arrives like this');
      check('S136', 'and one rehydrated as a plain {seconds} object',
        F({ seconds: Math.floor(Date.UTC(2023, 10, 3) / 1000) }) === 2023,
        'a Timestamp that has been through JSON loses its methods and keeps ' +
        'only seconds — that is how a saved snapshot comes back');
      check('S136', 'and a real Date, and a millisecond number',
        F(new Date('2022-01-05T00:00:00Z')) === 2022 &&
        F(Date.UTC(2021, 5, 1)) === 2021,
        'both turn up from imports and from code that has already converted');
      check('S136', 'and a date typed as text',
        F('2020-12-25') === 2020,
        'the master sheet is text all the way down');
      /* ⚠ NULL, NOT A GUESS. This decides which season somebody joined in, and
         a wrong year is a wrong answer about whether they are a new member —
         which is $30. Unreadable must mean "I do not know", never a year. */
      check('S136', 'and anything unreadable is null, never a year',
        F(null) === null && F(undefined) === null && F('') === null &&
        F('not a date') === null && F({}) === null,
        'a guessed year decides whether somebody is charged a join fee');
      check('S136', 'and it never throws',
        (function () {
          try { F({ toDate: function () { throw new Error('boom'); } }); return true; }
          catch (e) { return false; }
        })(),
        'a broken timestamp on one record must not take down the render');
    }
  }

  /* ---- todayStrInDenver: what "today" means to the route sweep -------- */
  {
    const src = extractFn(fns, 'todayStrInDenver');
    check('S136', 'todayStrInDenver is findable', !!src);
    if (src) {
      const F = new Function(src + ';return todayStrInDenver;')();
      const got = F();
      /* ⚠ THIS DECIDES PAST FROM UPCOMING. removeCustomerFromUpcomingRoutes
         compares a route's date string against it, so a format that does not
         sort — or an off-by-one timezone — either rewrites a route the crew
         has already driven or leaves somebody on one they have not. */
      check('S136', 'it answers in sortable YYYY-MM-DD',
        /^\d{4}-\d{2}-\d{2}$/.test(got),
        'got ' + JSON.stringify(got) + ' — the route sweep compares date ' +
        'strings with <, so any other shape silently compares wrong');
      check('S136', 'zero-padded, so string order is date order',
        got.slice(5, 7).length === 2 && got.slice(8, 10).length === 2 &&
        '2026-02-09' < '2026-02-10' && got > '2020-01-01',
        'an unpadded month makes "2026-9-01" sort after "2026-10-01"');
      /* ⚠ MOUNTAIN TIME, NOT THE SERVER'S. Cloud Functions run in UTC, so for
         the seven hours after 5pm Denver the two calendars disagree — and that
         window covers the 7pm nightly run. */
      check('S136', 'and in Denver time, not the server\'s',
        /America\/Denver/.test(src),
        'Cloud Functions run UTC; after 5pm Denver the date differs, and the ' +
        'nightly run is at 7pm');
      const denver = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Denver' });
      check('S136', 'and it agrees with the platform about what day that is',
        got === denver,
        'got ' + got + ', platform says ' + denver);
    }
  }

  /* ---- rsvpTemplateHasAddOn: whether to append the add-on offer ------- */
  {
    const src = extractFn(admin, 'rsvpTemplateHasAddOn');
    check('S136', 'rsvpTemplateHasAddOn is findable', !!src);
    if (src) {
      const F = new Function(src + ';return rsvpTemplateHasAddOn;')();
      /* ⚠ NEUTERING THIS RETURNED undefined — falsy — which means "the template
         does not place the token itself", so the block is APPENDED as well as
         substituted and the customer gets the offer twice. Every check on it
         read the source, so nothing noticed. */
      check('S136', 'a template that places the token itself says so',
        F('Hi {{name}} {{addon_block}} bye') === true,
        'appending on top of a template that already has the token sends the ' +
        'same offer, with the same two buttons, twice in one email');
      check('S136', 'and one that does not, does not',
        F('Hi {{name}}, will you be getting lights again?') === false,
        'this is the ordinary RSVP template, and it must still get the offer ' +
        'appended for it');
      check('S136', 'a missing or empty template does not throw',
        F('') === false && F(null) === false && F(undefined) === false,
        'the picker can sit on no template at all');
      /* ⚠ AND IT MUST NOT MATCH A NEAR MISS, or a template mentioning the token
         in prose would silently lose its offer. */
      check('S136', 'and a near miss is not a match',
        F('{{addon_blocks}}') === false && F('addon_block') === false,
        'only the real token counts');
    }
  }
}

/* =====================================================================
 * Suite 140. A finished fix takes its photo with it
 *
 * Job 4. Owner, 2026-08-21: "we want the picture destroyed on the spot. There
 * is no need for it after we fix the house."
 *
 * ⚠ CLEARING fixPhotoUrl WAS NEVER DELETING ANYTHING. Two paths already blanked
 * the field, which only forgets the address — the image stayed on Cloudinary,
 * on a public URL, with nothing in the app pointing at it any more. Still out
 * there AND invisible to the office is the worst of both.
 *
 * ⚠ THE DANGEROUS PART IS THE public_id, not the deleting. The caller hands
 * over a URL and the server works out what to destroy; get that derivation
 * wrong by one segment and it deletes somebody else's picture, permanently,
 * with no undo. Most of this suite is that one function, RUN over every URL
 * shape this app actually produces.
 * ===================================================================== */
suite('Suite 140. A finished fix takes its photo with it');
{
  const fns = read('functions/index.js');
  const admin = read('admin.html');
  const CLOUD = 'highlighting-utah';
  const base = 'https://res.cloudinary.com/' + CLOUD + '/image/upload/';

  /* ---- 1. which asset, exactly ---------------------------------------- */
  const idSrc = extractFn(fns, 'cloudinaryPublicId');
  check('S140', 'the public_id reader is findable', !!idSrc);
  if (idSrc) {
    const F = new Function('CLOUDINARY_CLOUD_NAME',
      idSrc + ';return cloudinaryPublicId;')(CLOUD);

    check('S140', 'a plain upload URL gives its public_id',
      F(base + 'abc123.jpg') === 'abc123');
    /* cloudThumb inserts w_440,c_limit,q_auto,f_auto — and the office may have
       stored a URL that already went through it. */
    check('S140', 'a transformation segment is not part of it',
      F(base + 'w_440,c_limit,q_auto,f_auto/abc123.jpg') === 'abc123',
      'left in, the destroy names an asset that does not exist and the real ' +
      'photo survives while the record says it is gone');
    check('S140', 'nor is the version segment',
      F(base + 'v1712345678/abc123.jpg') === 'abc123');
    check('S140', 'nor both together',
      F(base + 'w_440,c_limit/v1712345678/abc123.jpg') === 'abc123');
    /* ⚠ BUT THE FOLDER IS. Dropping it would name a DIFFERENT asset at the
       root — the single most expensive way to get this wrong. */
    check('S140', 'a folder IS part of it',
      F(base + 'v1/fixes/abc123.jpg') === 'fixes/abc123' &&
      F(base + 'fixes/2026/abc123.png') === 'fixes/2026/abc123',
      'dropping the folder names a different asset entirely, and destroys it');
    check('S140', 'the extension is dropped, a dot in the name is not',
      F(base + 'my.house.jpg') === 'my.house',
      'only the last dot is the extension');
    check('S140', 'a query string or fragment is ignored',
      F(base + 'abc123.jpg?v=2') === 'abc123' && F(base + 'abc123.jpg#x') === 'abc123');

    /* ---- and what it must REFUSE ------------------------------------- */
    check('S140', 'a URL on somebody else\'s cloud is refused',
      F('https://res.cloudinary.com/someone-else/image/upload/abc.jpg') === '',
      'the caller passes a URL and the server decides what to delete — this is ' +
      'the only thing standing between that and deleting another account\'s asset');
    check('S140', 'and anything that is not a Cloudinary upload URL',
      F('https://example.com/abc.jpg') === '' && F('/local/abc.jpg') === '' &&
      F('not a url') === '',
      'photos predate Cloudinary on some records');
    check('S140', 'blank, null and undefined are refused quietly',
      F('') === '' && F(null) === '' && F(undefined) === '',
      'most customers have no fix photo at all — that is not an error');
    /* ⚠ A .. COULD REACH OUTSIDE THE FOLDER IT NAMES. Nothing we upload makes
       one; refusing beats reasoning about what Cloudinary would do with it. */
    check('S140', 'a traversal is refused rather than reasoned about',
      F(base + 'fixes/../secret.jpg') === '',
      'nothing we upload produces one, so a URL carrying one was not made here');
    check('S140', 'and a URL with no name at all',
      F(base) === '' && F(base + 'v1/') === '');
  }

  /* ---- 2. the callable's own rules, RUN -------------------------------- */
  {
    const a = fns.indexOf('exports.destroyFixPhoto = onCall');
    const h = fns.indexOf('async (request) => {', a);
    const end = fns.indexOf('\n);', h);
    check('S140', 'the destroy callable is where this suite expects it',
      a !== -1 && h > a && end > h);
    if (a !== -1 && h > a && end > h && idSrc) {
      const body = fns.slice(fns.indexOf('{', h) + 1, fns.lastIndexOf('}', end));
      const run = (request, fetchImpl) => {
        const calls = [];
        const fn = new Function('request', 'HttpsError', 'crypto', 'fetch', 'console',
          'CLOUDINARY_CLOUD_NAME', 'CLOUDINARY_API_KEY', 'CLOUDINARY_API_SECRET',
          'cloudinaryPublicId', 'URLSearchParams',
          'return (async () => {' + body + '})();')(
          request,
          function (code, msg) { const e = new Error(msg); e.code = code; return e; },
          require('crypto'),
          (url, opts) => { calls.push({ url, opts }); return fetchImpl(url, opts); },
          { error: () => {}, log: () => {} },
          CLOUD, { value: () => 'KEY' }, { value: () => 'SECRET' },
          new Function('CLOUDINARY_CLOUD_NAME', idSrc + ';return cloudinaryPublicId;')(CLOUD),
          URLSearchParams);
        return fn.then(r => ({ r, calls }), e => ({ threw: e, calls }));
      };
      const okFetch = (body) => async () => ({ json: async () => body });

      pendingAsync.push((async () => {
        /* ⚠ STAFF ONLY. Every other Cloudinary callable here hands out an upload
           token; this one DESTROYS, so it is the one that must never be
           reachable without a login. */
        const anon = await run({ data: { url: base + 'abc.jpg' } }, okFetch({ result: 'ok' }));
        check('S140', 'an unauthenticated caller is refused',
          !!anon.threw && !anon.calls.length,
          'a destroy endpoint open to the internet is somebody deleting every ' +
          'photo they can guess a URL for');

        const auth = { auth: { uid: 'u1' } };
        const good = await run(Object.assign({ data: { url: base + 'v1/fixes/abc.jpg' } }, auth),
          okFetch({ result: 'ok' }));
        check('S140', 'a signed-in caller destroys the right asset',
          good.r && good.r.ok === true && good.r.destroyed === true &&
          good.calls.length === 1 &&
          good.calls[0].url.indexOf('/v1_1/' + CLOUD + '/image/destroy') !== -1 &&
          good.calls[0].opts.body.get('public_id') === 'fixes/abc',
          'sent: ' + (good.calls[0] && good.calls[0].opts.body.get('public_id')));
        /* The signature is what Cloudinary checks; a wrong one is a refusal
           that would read as "the photo would not delete". */
        check('S140', 'and signs public_id and timestamp, in that order',
          (function () {
            const b = good.calls[0].opts.body;
            const want = require('crypto').createHash('sha1')
              .update('public_id=' + b.get('public_id') + '&timestamp=' + b.get('timestamp') + 'SECRET')
              .digest('hex');
            return b.get('signature') === want && b.get('api_key') === 'KEY';
          })(),
          'Cloudinary sorts the params alphabetically before signing');

        /* ⚠ "not found" IS SUCCESS — the asset is gone, which is all that was
           wanted. Calling it a failure leaves the URL on the record for ever,
           pointing at nothing. */
        const missing = await run(Object.assign({ data: { url: base + 'abc.jpg' } }, auth),
          okFetch({ result: 'not found' }));
        check('S140', 'an asset already gone counts as done',
          missing.r && missing.r.ok === true && missing.r.destroyed === false,
          'otherwise the record keeps a URL that points at nothing, for ever');

        const refused = await run(Object.assign({ data: { url: base + 'abc.jpg' } }, auth),
          okFetch({ result: 'error' }));
        check('S140', 'a refusal is reported, not swallowed',
          refused.r && refused.r.ok === false,
          'the field must stay put so the picture can still be found');

        const blew = await run(Object.assign({ data: { url: base + 'abc.jpg' } }, auth),
          async () => { throw new Error('network'); });
        check('S140', 'and a network failure does not throw at the caller',
          blew.r && blew.r.ok === false && !blew.threw,
          'marking a fix done must not fail because Cloudinary was unreachable');

        const foreign = await run(Object.assign({ data: { url: 'https://example.com/x.jpg' } }, auth),
          okFetch({ result: 'ok' }));
        check('S140', 'a URL that is not ours is answered without calling out',
          foreign.r && foreign.r.ok === true && foreign.r.destroyed === false &&
          !foreign.calls.length,
          'nothing of ours to delete is a clean answer, not an error — and no ' +
          'request should leave the building for it');
      })());
    }
  }

  /* ---- 3. the browser helper, RUN -------------------------------------- */
  {
    const src = extractFn(admin, 'hlxRetireFixPhoto');
    check('S140', 'the browser helper is findable', !!src);
    check('S140', 'and is async in the real file',
      /async function hlxRetireFixPhoto\(/.test(admin));
    if (src) {
      pendingAsync.push((async () => {
        const call = (impl) => new Function('destroyFixPhotoFn', 'console',
          'async ' + src + ';return hlxRetireFixPhoto;')(impl, { error: () => {} });

        const okd = await call(async () => ({ data: { ok: true, destroyed: true } }))(base + 'a.jpg');
        check('S140', 'a destroyed photo may have its field cleared',
          okd.cleared === true && okd.destroyed === true);
        /* ⚠ A FAILED DESTROY KEEPS THE URL. The picture still exists, so the
           record should still say where it is and the next Mark Done can try
           again. Clearing it anyway orphans exactly the asset the owner asked
           to be rid of. */
        const bad = await call(async () => ({ data: { ok: false } }))(base + 'a.jpg');
        check('S140', 'a photo that would not delete keeps its field',
          bad.cleared === false,
          'clearing it anyway leaves the picture on Cloudinary with nothing in ' +
          'the app pointing at it — the exact state this job exists to end');
        const threw = await call(async () => { throw new Error('offline'); })(base + 'a.jpg')
          .catch(e => ({ threw: String(e) }));
        check('S140', 'and a call that throws is caught, not propagated',
          threw.cleared === false && !threw.threw,
          'the office is marking a fix done; a dead network must not stop that');
        const none = await call(async () => { throw new Error('should not be called'); })('');
        check('S140', 'no photo at all is nothing to do',
          none.cleared === true && none.destroyed === false,
          'most fixes have no photo; that must not cost a round trip');
      })());
    }
  }

  /* ---- 4. where it is wired -------------------------------------------- */
  const doneSrc = stripComments(extractFn(admin, 'hlxMarkJobDone') || '');
  check('S140', 'the one done-function retires the photo',
    /kind === 'fix' && done/.test(doneSrc) && /hlxRetireFixPhoto\(url\)/.test(doneSrc),
    'five doors call hlxMarkJobDone; wiring any one of them instead would leave ' +
    'the other four keeping photos for ever');
  /* ⚠ AFTER THE WRITE, NEVER BEFORE. Destroying first and then failing to save
     loses the picture for a fix that is not marked done — no undo, and the
     office would not even know. */
  check('S140', 'and does it AFTER the record is written',
    doneSrc.indexOf("updateDoc(doc(db, 'jobAddresses', id), fields)") <
    doneSrc.indexOf('hlxRetireFixPhoto'),
    'the done state is what matters; the photo is cleaned up behind it');
  check('S140', 'only when marking done, never when unticking',
    /kind === 'fix' && done\b/.test(doneSrc) && !/kind === 'fix'\s*\)/.test(doneSrc),
    'unticking a fix must not destroy the photo the office is about to look at');
  check('S140', 'and the field is cleared only if the picture really went',
    /if \(gone\.cleared\) \{/.test(doneSrc),
    'clearing regardless is how the orphan is created');
  /* ⚠ AND THE OTHER TWO PATHS GO THROUGH THE SAME HELPER. Both used to blank
     the field on their own; a path that still does keeps making orphans. */
  const stripped = stripComments(admin);
  check('S140', 'no path blanks the field without destroying first',
    (stripped.match(/fixPhotoUrl\s*=\s*''/g) || []).length ===
    (stripped.match(/if\(gone\.cleared\) updates\.fixPhotoUrl = ''/g) || []).length +
    (stripped.match(/fields\.fixPhotoUrl = ''/g) || []).length +
    (stripped.match(/cached\.data\.fixPhotoUrl = ''/g) || []).length,
    'every clear must sit behind a successful destroy — a leftover one is a ' +
    'photo on Cloudinary that nothing in the app can reach any more');
  /* ⚠ AND IT NEVER TOUCHES THE HOUSE PHOTO, which prints on the new-hang crew
     sheets. CLAUDE.md calls this out by name. */
  check('S140', 'and nothing here touches the house photo',
    !/housePhotoUrl|frontPhotoUrl/.test(doneSrc) &&
    !/housePhotoUrl|frontPhotoUrl/.test(stripComments(extractFn(admin, 'hlxRetireFixPhoto') || '')),
    'that one prints on the crew sheet and is not the office\'s to delete here');
}


suite('128. Measure Roof — depth, the derived wall, and the height that follows the type');
{
  /* ⚠ RUNS THE MATHS. The whole claim of Street View measuring is that it is
     NOT pixel distance, and only executing it can show that. */
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);
  const NAMES = ['rmMetresPerDeg', 'rmToLocal', 'rmToWorld', 'rmFeetBetween', 'rmFovDeg',
                 'rmBasis', 'rmRay', 'rmGroundHit', 'rmWallHit', 'rmSvProject', 'rmAutoWall',
                 'rmActiveWall', 'rmHeightForType'];
  const missing = NAMES.filter(n => !pick(n));
  if (missing.length) {
    check('S128', 'the Measure Roof geometry is findable', false, 'missing: ' + missing.join(', '));
  } else {
    const prelude =
      'let rmOrigin = {lat: 40.2969, lng: -111.6946};' + LF_ +
      'let rmWall = null, rmBuilding = null, rmRoofM = null;' + LF_ +
      'let __cam = null;' + LF_ +
      'function rmCamLocal(){ return __cam; }' + LF_ +
      'const RM_M_TO_FT = 3.280839895;' + LF_ +
      'const RM_CAM_HEIGHT_M = 2.5;' + LF_ +
      'const rmRad = d => d * Math.PI / 180;' + LF_;
    const api = new Function(prelude + NAMES.map(pick).join(LF_) + LF_ +
      'return {set:function(o){ if("wall" in o) rmWall=o.wall; if("building" in o) rmBuilding=o.building;' +
      ' if("roof" in o) rmRoofM=o.roof; if("cam" in o) __cam=o.cam; },' +
      ' rmToLocal, rmToWorld, rmFeetBetween, rmRay, rmGroundHit, rmWallHit, rmSvProject,' +
      ' rmAutoWall, rmActiveWall, rmHeightForType};')();

    const near = (a, b, t) => Math.abs(a - b) <= t;
    const FT = 3.280839895;
    const W = 1000, H = 600;

    /* ================= DEPTH =================================
       ⚠ THE OWNER'S OWN WORDING: "two dots might look close but really they
       are far apart because of depth". A wall running AWAY from the camera is
       exactly that case - the far end is squashed into a handful of pixels.
       If this ever became pixel distance the number would collapse and a house
       would be under-quoted, silently, in the direction that loses money. */
    const cam = {e: 0, n: 0, u: 2.5};
    api.set({cam: cam});
    /* A wall running north-east, starting 8 m ahead and receding hard. */
    /* ⚠ The wall must RECEDE from the camera without running nearly PARALLEL
       to the sight line — parallel is degenerate, the rays cross it far away or
       behind, and the check fails for a reason that is nothing to do with the
       maths. This one is at 45 degrees to the view: properly foreshortened, and
       properly crossed. */
    const gA = {e: -2, n: 6, u: 0}, gB = {e: 18, n: 26, u: 0};
    const len = Math.hypot(gB.e - gA.e, gB.n - gA.n);
    const nrm = {e: (gB.n - gA.n) / len, n: -(gB.e - gA.e) / len};
    const plane = {a: gA, b: gB, normal: nrm, d: nrm.e * gA.e + nrm.n * gA.n, lengthM: len};

    /* Two pixels deliberately CLOSE together, aimed down the receding wall. */
    const POV = {heading: 20, pitch: 0, zoom: 1};
    const p1 = api.rmWallHit(api.rmRay(W / 2 + 40, H / 2, W, H, POV), cam, plane);
    const p2 = api.rmWallHit(api.rmRay(W / 2 + 90, H / 2, W, H, POV), cam, plane);
    if (!p1 || !p2) {
      check('S128', 'two nearby pixels on a receding wall both land on it', false,
        'the plane maths refused a ray it should have accepted');
    } else {
      const pixelGap = 50;
      const worldFt = api.rmFeetBetween(api.rmToWorld(p1), api.rmToWorld(p2));
      const depth1 = Math.hypot(p1.e - cam.e, p1.n - cam.n);
      const depth2 = Math.hypot(p2.e - cam.e, p2.n - cam.n);
      check('S128', 'fifty pixels apart on a receding wall is many feet apart in the world',
        worldFt > 8,
        pixelGap + ' px -> ' + worldFt.toFixed(1) + ' ft, at depths ' +
        depth1.toFixed(1) + ' m and ' + depth2.toFixed(1) + ' m — if this ever reads as a couple of feet it has become pixel distance');
      check('S128', 'and the two points really are at different depths',
        Math.abs(depth1 - depth2) > 1,
        'a wall that does not recede cannot test foreshortening at all');
      /* The killer comparison: the SAME pixel gap square-on is much shorter. */
      const flatA = {e: -10, n: 12, u: 0}, flatB = {e: 10, n: 12, u: 0};
      const flen = Math.hypot(flatB.e - flatA.e, flatB.n - flatA.n);
      const fnrm = {e: (flatB.n - flatA.n) / flen, n: -(flatB.e - flatA.e) / flen};
      const fplane = {a: flatA, b: flatB, normal: fnrm, d: fnrm.e * flatA.e + fnrm.n * flatA.n};
      const SQUARE = {heading: 0, pitch: 0, zoom: 1};
      const f1 = api.rmWallHit(api.rmRay(W / 2 + 40, H / 2, W, H, SQUARE), cam, fplane);
      const f2 = api.rmWallHit(api.rmRay(W / 2 + 90, H / 2, W, H, SQUARE), cam, fplane);
      const flatFt = api.rmFeetBetween(api.rmToWorld(f1), api.rmToWorld(f2));
      check('S128', 'the same fifty pixels square-on is a much smaller distance',
        flatFt < worldFt / 2,
        'square-on ' + flatFt.toFixed(1) + ' ft vs receding ' + worldFt.toFixed(1) +
        ' ft — identical on screen, and they must not be identical in feet');
    }

    /* ================= THE CAMERA MAY WALK =====================
       ⚠ "if im at my neighbors house the dots at the house im working on isnt
       offset". Points are stored against the HOUSE, so moving the camera can
       only change where they are DRAWN, never what they measure. */
    const wp1 = api.rmToWorld({e: 4, n: 14, u: 3});
    const wp2 = api.rmToWorld({e: 12, n: 14, u: 3});
    const fromHere = api.rmFeetBetween(wp1, wp2);
    api.set({cam: {e: -35, n: -6, u: 2.5}});     /* walked down to the neighbour */
    const fromThere = api.rmFeetBetween(wp1, wp2);
    check('S128', 'walking the camera to the neighbour does not change the measurement',
      near(fromHere, fromThere, 1e-9),
      'here ' + fromHere.toFixed(3) + ' ft, from next door ' + fromThere.toFixed(3) + ' ft');
    const drawnHere = api.rmSvProject(wp1, W, H, {heading: 0, pitch: 0, zoom: 1}, {e: 0, n: 0, u: 2.5});
    const drawnThere = api.rmSvProject(wp1, W, H, {heading: 0, pitch: 0, zoom: 1}, {e: -35, n: -6, u: 2.5});
    check('S128', 'but it IS drawn somewhere else on screen, which is what keeps it on the house',
      drawnHere && drawnThere && Math.abs(drawnHere.x - drawnThere.x) > 20,
      'a dot that lands on the same pixel from a different place has stopped following the building');

    /* ================= THE WALL IS DERIVED ===================== */
    api.set({cam: {e: 0, n: -14, u: 2.5}, building: null, wall: null});
    check('S128', 'with no footprint there is no derived wall, rather than a wrong one',
      api.rmAutoWall() === null,
      'guessing a wall from nothing puts every Street View point in the wrong place');
    /* A footprint straddling the origin, camera to the south. */
    const m = (function () { const f = new Function('return ' + extractFn(admin, 'rmMetresPerDeg')
      .replace('function rmMetresPerDeg', 'function') + ';')(); return f(40.2969); })();
    const d2ll = (e, n) => ({lat: 40.2969 + n / m.lat, lng: -111.6946 + e / m.lng});
    api.set({building: {sw: d2ll(-8, -6), ne: d2ll(8, 6)}});
    const auto = api.rmAutoWall();
    check('S128', 'a footprint plus a camera position derives the front wall by itself',
      !!auto && auto.auto === true,
      'the manual Set the Wall step is back in front of every Street View trace');
    if (auto) {
      const la = api.rmToLocal(auto.a.lat, auto.a.lng, 0);
      const lb = api.rmToLocal(auto.b.lat, auto.b.lng, 0);
      check('S128', 'and it is the SOUTH edge — the one the camera can actually see',
        near(la.n, -6, 0.5) && near(lb.n, -6, 0.5),
        'derived n = ' + la.n.toFixed(1) + ' and ' + lb.n.toFixed(1) +
        ' — picking a face the camera is behind puts the whole trace through the back of the house');
    }
    /* Move the camera round to the east; the derived wall must follow. */
    api.set({cam: {e: 30, n: 0, u: 2.5}});
    const east = api.rmAutoWall();
    if (east) {
      const ea = api.rmToLocal(east.a.lat, east.a.lng, 0);
      check('S128', 'stand somewhere else and it derives the wall you can see from there',
        near(Math.abs(ea.e), 8, 0.5),
        'derived e = ' + ea.e.toFixed(1) + ' — the wall did not follow the camera round the building');
    }
    /* A hand-pinned wall always wins. */
    api.set({wall: {a: d2ll(-3, 2), b: d2ll(3, 2)}});
    const active = api.rmActiveWall();
    check('S128', 'a wall pinned by hand overrides the derived one',
      active && active.auto !== true,
      'the manual override is ignored, so a bumped-out garage can never be corrected');

    /* ================= HEIGHT FOLLOWS THE TYPE ================= */
    api.set({roof: null});
    check('S128', 'with no roof model the height is left alone, not zeroed',
      api.rmHeightForType('perimeter') === null,
      'returning 0 would silently put a roofline trace on the lawn');
    api.set({roof: {eave: 3.2, ridge: 5.6}});
    check('S128', 'a perimeter run sits at the eave', near(api.rmHeightForType('perimeter'), 3.2, 1e-9));
    check('S128', 'a ridge run sits at the peak', near(api.rmHeightForType('ridge'), 5.6, 1e-9));
    check('S128', 'and only a ground run sits at zero', api.rmHeightForType('ground') === 0,
      'this is "always measuring the house, never the ground" — the roof types must never read zero');
    /* And the height genuinely changes the answer. */
    const flat1 = api.rmToWorld({e: 0, n: 0, u: 0}), flat2 = api.rmToWorld({e: 6, n: 0, u: 0});
    const up1 = api.rmToWorld({e: 0, n: 0, u: 3.2}), up2 = api.rmToWorld({e: 6, n: 0, u: 5.6});
    check('S128', 'a run that climbs from eave to ridge is longer than the same run on the ground',
      api.rmFeetBetween(up1, up2) > api.rmFeetBetween(flat1, flat2) + 1,
      'ground ' + api.rmFeetBetween(flat1, flat2).toFixed(1) + ' ft vs sloping ' +
      api.rmFeetBetween(up1, up2).toFixed(1) + ' ft');
  }

  /* ---- the panes, and the loading state ------------------------------- */
  /* ⚠ ASSERTED AS BEHAVIOUR, NOT AS A NUMBER. This used to match the literal
     `flex:1 1 430px`, so widening the panes so the office can actually SEE the
     house failed a check about something else entirely. What matters is that
     two panes still fit across the window, not what their basis happens to be. */
  {
    const bases = (admin.match(/class="rm-pane" style="flex:1 1 (\d+)px/g) || [])
      .map(m => Number((m.match(/(\d+)px/) || [])[1]));
    const popup = Number((admin.match(/editcust-popup" style="max-width:min\((\d+)px/) || [])[1]);
    check('S128', 'the two views sit side by side rather than stacked',
      bases.length === 2 && popup > 0 && (bases[0] + bases[1] + 40) <= popup,
      'panes ' + bases.join(' + ') + ' must fit across a ' + popup + 'px window, or the street ' +
      'pane wraps below the fold and the window opens showing one view');
  }
  check('S128', 'each pane says what it is doing while its imagery loads',
    /id="rmSkyBusy"/.test(admin) && /id="rmStreetBusy"/.test(admin) &&
    !!extractFn(admin, 'rmPaneBusy') && !!extractFn(admin, 'rmPaneReady'),
    'a blank grey rectangle on open reads as broken — it was reported as broken within a minute of shipping');
  const load = sectionFrom(admin, admin.indexOf('async function rmLoadAddress'));
  check('S128', 'and it is cleared by the map itself, not by a timer',
    /addListenerOnce\(rmMap, 'idle', function\(\)\{ rmPaneReady\('sky'\)/.test(load),
    'a timer either uncovers a still-grey pane or makes a fast connection wait for nothing');
  check('S128', 'a street with no imagery says so instead of spinning for ever',
    /Google has never driven this street/.test(load),
    'an endless spinner on a house Street View has never visited is a hang, not an answer');
}


suite('129. Measure Roof — the guessed roofline, the grade, and the price');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* ---- the grade, RUN, because it was miles out and now sets prices ----- */
  const gradeFn = pick('gradeRoof');
  if (!gradeFn) {
    check('S129', 'gradeRoof is findable', false, 'renamed or removed');
  } else {
    /* ⚠ THE THRESHOLDS ARE LIFTED OUT OF THE SOURCE, NOT RESTATED HERE.
       Written into this sandbox they were a second copy: the first version of
       this suite held 80/55 while admin.html had moved to 75/45, so it was
       testing its own numbers and reported a failure against code that was
       right. A constant asserted from a copy of itself is not asserted. */
    const constLines = (admin.match(/^const RM_(?:HARD_GRADE|MEDIUM_GRADE|BUSY_SECTIONS|TWO_STOREY_FT|DIFFICULTY_RATE)\s*=.*$/gm) || []);
    check('S129', 'the grading constants are findable in the source', constLines.length === 5,
      'found ' + constLines.length + ' of 5 — this suite would silently fall back to guessing them');
    const g = new Function(constLines.join(LF_) + LF_ + gradeFn + LF_ + 'return gradeRoof;')();
    /* ⚠ THE BUG THIS EXISTS FOR: the old thresholds were 37% for Hard and 25%
       for Medium. Grade is a PERCENT — 37% is a 4.4/12 pitch. An ordinary 6/12
       house is 50%, so it graded Hard, and so did nearly every house. */
    check('S129', 'an ordinary 6/12 roof is NOT called Hard',
      g({maxGrade: 50, peakCount: 2}).level === 'Medium',
      'got ' + g({maxGrade: 50, peakCount: 2}).level + ' — this is the miscalibration that called every house Hard');
    check('S129', 'a low 4/12 roof is Easy', g({maxGrade: 33, peakCount: 2}).level === 'Easy');
    check('S129', 'a genuinely steep 10/12 roof is Hard', g({maxGrade: 83, peakCount: 2}).level === 'Hard');
    check('S129', 'a busy roof is bumped up a grade',
      g({maxGrade: 33, peakCount: 6}).level === 'Medium',
      'lots of separate sections is more ladder moves, whatever the pitch');
    check('S129', 'and a two-storey eave bumps it too',
      g({maxGrade: 33, peakCount: 2, eaveFt: 19}).level === 'Medium');
    check('S129', 'but nothing goes past Hard',
      g({maxGrade: 95, peakCount: 9, eaveFt: 24}).level === 'Hard',
      'a fourth grade would appear that no rate multiplier knows about');
    check('S129', 'Medium leaves the office rate alone',
      g({maxGrade: 60, peakCount: 2}).rateMultiplier === 1,
      'Medium must be x1 or the configured Per Foot Pricing stops meaning what it says');
    check('S129', 'and the grade says WHY, so a wrong one can be argued with',
      /grade/.test(g({maxGrade: 50, peakCount: 2}).why),
      'a difficulty with no reason attached is one nobody can check');
  }

  /* ---- the eave is picked off the azimuth, not guessed ------------------ */
  const eaveFn = pick('rmFaceEave');
  const NAMES2 = ['rmMetresPerDeg', 'rmToLocal', 'rmToWorld', 'rmFeetBetween'];
  if (!eaveFn || NAMES2.some(n => !pick(n))) {
    check('S129', 'the roofline guesser is findable', false, 'rmFaceEave renamed or removed');
  } else {
    const api = new Function(
      'let rmOrigin={lat:40.2969,lng:-111.6946};' + LF_ +
      'const RM_M_TO_FT=3.280839895;' + LF_ +
      /* rmFaceEave asks rmFaceEdgePick which edge is the gutter - that rule was
         extracted so the photo solver could ask for the RIDGE with the same
         answer. Lift it, never stub it: a stub here would make the suite agree
         with itself about the one thing it is checking. */
      NAMES2.map(pick).join(LF_) + LF_ + pick('rmFaceEdgePick') + LF_ +
      pick('rmFaceEdgeLine') + LF_ + pick('rmFaceRidge') + LF_ + eaveFn + LF_ +
      'return {rmFaceEave, rmFaceRidge, rmToLocal, rmToWorld, rmFeetBetween};')();
    const m = new Function('return ' + pick('rmMetresPerDeg').replace('function rmMetresPerDeg', 'function') + ';')()(40.2969);
    const ll = (e, n) => ({lat: 40.2969 + n / m.lat, lng: -111.6946 + e / m.lng});
    const box = {sw: ll(-6, -4), ne: ll(6, 4)};
    /* ⚠ AZIMUTH IS THE WHOLE TRICK. A box has four edges and only the azimuth
       says which one is the gutter. Facing south (180) the eave is the SOUTH
       edge; facing north (0) it is the north one. Get this wrong and half the
       suggested lines run along the ridge. */
    const south = api.rmFaceEave({sw: box.sw, ne: box.ne, azimuth: 180, pitch: 26});
    const north = api.rmFaceEave({sw: box.sw, ne: box.ne, azimuth: 0, pitch: 26});
    if (!south || !north) {
      check('S129', 'a sloping face yields an eave line', false, 'no edge was chosen');
    } else {
      const sMid = api.rmToLocal((south.a.lat + south.b.lat) / 2, (south.a.lng + south.b.lng) / 2, 0);
      const nMid = api.rmToLocal((north.a.lat + north.b.lat) / 2, (north.a.lng + north.b.lng) / 2, 0);
      check('S129', 'a south-facing roof gives the SOUTH edge as its eave',
        sMid.n < -3, 'got n=' + sMid.n.toFixed(1) + ' — the gutter line is on the wrong side of the roof');
      check('S129', 'and a north-facing roof gives the north one',
        nMid.n > 3, 'got n=' + nMid.n.toFixed(1));
      check('S129', 'the two are opposite edges, not the same one',
        Math.abs(sMid.n - nMid.n) > 6,
        'azimuth is being ignored, so every face offers the same line');
      check('S129', 'and the eave has a real length',
        api.rmFeetBetween(south.a, south.b) > 20,
        'a zero-length suggestion is a dot, not a run');
    }
    /* ⚠ THE FIRST VERSION OF THIS PASSED A NaN AZIMUTH AND PROVED NOTHING:
       fetchRoofDetails already filters those out, and a box always has an edge
       within 45 degrees of any direction, so no azimuth can rule an eave out.
       PITCH is the real signal, and testing it found a guard that could never
       fire. */
    check('S129', 'a flat roof offers no eave rather than a wrong one',
      api.rmFaceEave({sw: box.sw, ne: box.ne, azimuth: 180, pitch: 1}) === null,
      'a flat roof has no gutter line, and offering one puts a suggestion along a random edge');
    check('S129', 'but a pitched one does',
      !!api.rmFaceEave({sw: box.sw, ne: box.ne, azimuth: 180, pitch: 26}),
      'the pitch guard is now refusing real roofs');
  }

  /* ---- switched-off runs are excluded but NOT deleted ------------------- */
  const totalsFn = pick('rmTotals'), onFn = pick('rmRunIsOn');
  if (totalsFn && onFn) {
    const t = new Function(
      'let rmRuns=[], rmPhotoExtraFeet=0;' + LF_ +
      'function rmRunFeet(r){ return r.feet; }' + LF_ +
      onFn + LF_ + totalsFn + LF_ +
      'return function(runs, extra){ rmRuns=runs; rmPhotoExtraFeet=extra||0; return rmTotals(); };')();
    const runs = [{type: 'perimeter', feet: 50}, {type: 'perimeter', feet: 30, on: false}];
    check('S129', 'a switched-off run is not counted',
      t(runs, 0).all === 50, 'got ' + t(runs, 0).all + ' — picking a line off must change the total');
    check('S129', 'but it is still in the list, not deleted',
      runs.length === 2, 'an accidental click would be unrecoverable');
    check('S129', 'and footage traced on a photo is counted too',
      t(runs, 40).all === 90,
      'the back of the house has no map position, so it has to be added as a number or it is lost');
  } else {
    check('S129', 'the totals rule is findable', false, 'rmTotals or rmRunIsOn renamed');
  }

  /* ---- the price ------------------------------------------------------- */
  const priceFn = pick('rmRenderPrice');
  check('S129', 'the price is built from the office per-foot rate, not a number written here',
    !!priceFn && /perFootRate/.test(priceFn) && !/\b[12]\.\d\d\b/.test(priceFn.replace(/RM_DIFFICULTY_RATE/g, '')),
    'a rate written into this screen is a second rate to keep in step with Finance -> Per Foot Pricing');
  check('S129', 'and the difficulty only tilts it',
    !!priceFn && /RM_DIFFICULTY_RATE/.test(priceFn));
  check('S129', 'every step of the sum is shown, not just the total',
    !!priceFn && /Suggested price/.test(priceFn) && /\/ft/.test(priceFn),
    'the owner called her own figures ballparks — a total with no working is one nobody can correct');
  check('S129', 'and nothing is written to the quote until the button is pressed',
    !!priceFn && /Use /.test(priceFn) && !!pick('rmUsePrice'),
    'a price that saves itself is a price nobody agreed to');

  /* ---- the photo answers with a range ---------------------------------- */
  const photoRes = pick('rmPhotoRenderResults');
  check('S129', 'a photo measurement is reported as a RANGE',
    !!photoRes && /Expected range/.test(photoRes) && /RM_PHOTO_SPREAD/.test(photoRes),
    'a phone photo has no depth — a single confident number off one scale line is precision it does not have');
  check('S129', 'and it says a scale must be set before anything means feet',
    !!photoRes && /Set the scale first/.test(photoRes));
  check('S129', 'the photo itself is queued onto the quote, not just its footage',
    !!pick('rmPhotoAdd') && /rmShots\.push/.test(pick('rmPhotoAdd')),
    'the whole point was that the back of the house reaches the quote too');

  /* ---- controls -------------------------------------------------------- */
  check('S129', 'placing points by hand still exists as the fallback',
    /id="rmDrawBtn"/.test(admin) && !!pick('rmAddPoint'),
    'the guess will miss a side sometimes, and there has to be a way to draw it');
  check('S129', 'the shortcuts are named on screen, not just bound',
    /<kbd>Enter<\/kbd>/.test(admin) && /<kbd>Esc<\/kbd>/.test(admin),
    'a shortcut nobody can discover is a feature for one person');
  check('S129', 'and typing in a box never fires them',
    /t\.tagName === 'INPUT'/.test(admin),
    'without this, typing an address triggers half the shortcuts');
}


suite('130. Measure Roof — a triangle is not a flat line');
{
  /* ⚠ THE COMPLAINT THIS EXISTS FOR, in the owner's words: "when we measure
     sky view it reads it like a flat line when most houses roof have triangles
     and dimensions that dont stay flat". Looking straight down, a RAKE — the
     sloping edge of a gable — is foreshortened to its horizontal run, and it
     used to be given one flat height for its whole length. */
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);
  /* ⚠ rmRoofHeightAt was SPLIT when the sea-level datum was removed: it now
     calls rmRoofRelativeAt (the exact shape) and rmDatum (how high the lowest
     eave is). Lifting only the outer one gave "rmRoofRelativeAt is not
     defined" — the exact trap CLAUDE.md records. LIFT, never stub: a stub
     would make the branch untestable while reporting green. */
  const NAMES = ['rmMetresPerDeg', 'rmToLocal', 'rmToWorld', 'rmFeetBetween',
                 'rmFaceEaveM', 'rmLowestPlaneM', 'rmDatum', 'rmRoofRelativeAt', 'rmRoofHeightAt'];
  const missing = NAMES.filter(n => !pick(n));
  if (missing.length) {
    check('S130', 'the roof-plane model is findable', false, 'missing: ' + missing.join(', '));
  } else {
    const api = new Function(
      'let rmOrigin={lat:40.2969,lng:-111.6946};' + LF_ +
      'let rmFaces=[], rmRoofDatumM=null, rmDatumSource="";' + LF_ +
      'const RM_M_TO_FT=3.280839895, RM_ASSUMED_EAVE_M=3;' + LF_ +
      /* The datum is handed in as a "typed" height so these fixtures keep
         asserting absolute heights the way they always did. */
      'let __typed=0; function rmWorkingHeightM(){ return __typed; }' + LF_ +
      NAMES.map(pick).join(LF_) + LF_ +
      'return {set:function(f,groundToEave){rmFaces=f; __typed=groundToEave||0;},' +
      ' rmRoofHeightAt, rmRoofRelativeAt, rmDatum, rmToLocal, rmToWorld, rmFeetBetween};')();
    const m = new Function('return ' + pick('rmMetresPerDeg').replace('function rmMetresPerDeg', 'function') + ';')()(40.2969);
    const ll = (e, n) => ({lat: 40.2969 + n / m.lat, lng: -111.6946 + e / m.lng});

    /* A gable facing south. Ground at 1400 m. The face runs 6 m from ridge to
       eave, at a 6/12 pitch (26.57 deg), with its centre plane height 1408 m —
       so the ridge is ~1409.5 and the eave ~1406.5, i.e. 6.5 m and 3.5 m up. */
    const PITCH = 26.565;
    const face = {
      sw: ll(-8, -6), ne: ll(8, 6),
      azimuth: 180, pitch: PITCH,
      center: ll(0, 0), planeHeightM: 1408, areaSqFt: 600
    };
    api.set([face], 8);   /* 8 m from ground to the lowest plane */

    const atRidge = api.rmRoofHeightAt(ll(0, 3).lat, ll(0, 3).lng);   /* 3 m uphill */
    const atEave  = api.rmRoofHeightAt(ll(0, -3).lat, ll(0, -3).lng); /* 3 m downhill */
    check('S130', 'the roof is higher at the ridge than at the eave',
      atRidge !== null && atEave !== null && atRidge > atEave + 2,
      'ridge ' + (atRidge === null ? 'null' : atRidge.toFixed(2)) + ' m, eave ' +
      (atEave === null ? 'null' : atEave.toFixed(2)) + ' m — a roof read as one flat height is the whole bug');
    const expectedRise = 6 * Math.tan(PITCH * Math.PI / 180);
    check('S130', 'and the rise across it matches the pitch',
      Math.abs((atRidge - atEave) - expectedRise) < 0.05,
      'got ' + (atRidge - atEave).toFixed(3) + ' m over 6 m, expected ' + expectedRise.toFixed(3) +
      ' — the plane is not being tilted by the pitch');

    /* NOW THE ACTUAL COMPLAINT. A rake traced across that gable: 4 m sideways
       and 6 m up the slope in plan. Flat, it is the horizontal run. With real
       heights it is the hypotenuse. */
    const a = {lat: ll(-4, -3).lat, lng: ll(-4, -3).lng, h: api.rmRoofHeightAt(ll(-4, -3).lat, ll(-4, -3).lng)};
    const b = {lat: ll(0, 3).lat,  lng: ll(0, 3).lng,  h: api.rmRoofHeightAt(ll(0, 3).lat, ll(0, 3).lng)};
    const flatA = {lat: a.lat, lng: a.lng, h: 3}, flatB = {lat: b.lat, lng: b.lng, h: 3};
    const sloped = api.rmFeetBetween(a, b);
    const flat = api.rmFeetBetween(flatA, flatB);
    check('S130', 'a rake measured with real heights is LONGER than the flat run',
      sloped > flat + 0.5,
      'sloped ' + sloped.toFixed(1) + ' ft vs flat ' + flat.toFixed(1) +
      ' ft — if these are equal the triangle is being read as a flat line again');
    check('S130', 'and it is longer by roughly the rise, not by some arbitrary amount',
      Math.abs(sloped - Math.hypot(flat, (b.h - a.h) * 3.280839895)) < 0.2,
      'the extra length must be the actual climb, not a fudge factor');

    /* ⚠ AND THE THINGS THAT WERE NEVER WRONG MUST STAY RIGHT. An eave and a
       ridge are both LEVEL, so their flat measurement was always correct — a
       "fix" that started adding rise to them would break working behaviour. */
    const e1 = ll(-6, -6), e2 = ll(6, -6);      /* along the eave, same downhill distance */
    const h1 = api.rmRoofHeightAt(e1.lat, e1.lng), h2 = api.rmRoofHeightAt(e2.lat, e2.lng);
    check('S130', 'two points along the same eave come out at the same height',
      h1 !== null && h2 !== null && Math.abs(h1 - h2) < 0.02,
      'got ' + h1 + ' and ' + h2 + ' — a level gutter that slopes is the model tilting the wrong way');
    const r1 = ll(-6, 6), r2 = ll(6, 6);
    const rh1 = api.rmRoofHeightAt(r1.lat, r1.lng), rh2 = api.rmRoofHeightAt(r2.lat, r2.lng);
    check('S130', 'and so do two points along the ridge',
      rh1 !== null && rh2 !== null && Math.abs(rh1 - rh2) < 0.02);
    check('S130', 'the ridge sits above the eave', rh1 > h1 + 2);

    /* ---- it refuses rather than inventing -------------------------------- */
    api.set([], 8);
    check('S130', 'with no roof model it returns null instead of a made-up height',
      api.rmRoofHeightAt(ll(0, 0).lat, ll(0, 0).lng) === null,
      'a guessed height silently changes every footage on the quote');
    /* ⚠ THIS CHECK WAS RETIRED ON PURPOSE, and its opposite is now asserted.
       It used to demand that a missing GROUND ELEVATION make the height refuse
       — which was right when heights were sea-level minus ground. That design
       is the bug: the Elevation API refuses referrer-restricted keys, so the
       ground never arrived and every line sat on the lawn. Needing no ground
       at all is the fix, so the roof must still have a height without one. */
    api.set([face], 0);
    check('S130', 'with no measured or typed datum the roof is STILL off the ground',
      api.rmRoofHeightAt(ll(0, 0).lat, ll(0, 0).lng) > 2,
      'this is the regression that shipped: no ground elevation meant every point at h = 0');
    /* A nonsense plane must not produce a nonsense height. */
    /* Two planes 80 m apart is not a house. Relative heights make this the
       right test now — one plane alone carries no absolute claim. */
    api.set([{sw: ll(-8, -6), ne: ll(8, 6), azimuth: 180, pitch: PITCH,
              center: ll(0, 0), planeHeightM: 1400, areaSqFt: 600},
             {sw: ll(-8, -6), ne: ll(8, 6), azimuth: 0, pitch: PITCH,
              center: ll(0, 5), planeHeightM: 1480, areaSqFt: 600}], 8);
    check('S130', 'a plane 80 m above the lowest one is refused as nonsense',
      api.rmRoofHeightAt(ll(0, 5).lat, ll(0, 5).lng) === null,
      'a bad plane height would put a traced point 260 ft up and wreck the footage silently');
  }

  /* ---- and the sky-view click actually uses it ------------------------- */
  const px2w = pick('rmMapPixelToWorld');
  check('S130', 'a sky-view click takes its height from the roof, not one flat number',
    !!px2w && /rmRoofHeightAt/.test(px2w),
    'this is the fix — without it every point on a run shares one height again');
  check('S130', 'but falls back to the typed height when Google has no plane there',
    !!px2w && /rmWorkingHeightM/.test(px2w),
    'a number the office chose beats refusing to place the point at all');
  const dot = extractFn(admin, 'rmDot');
  /* ⚠ THIS CHECK WAS VACUOUS AT FIRST and a red-check caught it: matching
     `rmRoofHeightAt` alone stayed green when the ASSIGNMENT below it was
     disabled, because the call on the line above survived. The lookup happening
     is not the claim — the height being STORED is. */
  check('S130', 'and dragging a point up the roof updates its height',
    !!dot && /if\(dragH !== null\)\s*run\.path\[idx\]\.h = dragH;/.test(dot),
    'otherwise dragging a point from the eave to the ridge keeps the eave height');
}


suite('131. Measure Roof — the roof is never on the ground');
{
  /* ⚠ THE BUG THIS EXISTS FOR, reported off a real house: "when you did sky
     view to guess where the lines should be the lines were on the ground."
     Google's plane heights are metres above SEA LEVEL, and the old code asked
     the Elevation API for the ground to subtract. That API refuses
     referrer-restricted keys — "API keys with referer restrictions cannot be
     used with this API" — and ours is referrer-locked, correctly. So the
     ground never arrived, every height returned null, and every point fell
     back to h = 0.

     The fix removes the need for sea level entirely: face-to-face differences
     are exact on their own, and the one missing number — how high the lowest
     eave is — comes from Street View, from a typed height, or from an assumed
     one-storey eave. NEVER from zero. */
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);
  const NAMES = ['rmMetresPerDeg', 'rmToLocal', 'rmToWorld', 'rmFaceEaveM', 'rmLowestPlaneM',
                 'rmDatum', 'rmRoofRelativeAt', 'rmRoofHeightAt', 'rmSetDatumFromStreet'];
  const missing = NAMES.filter(n => !pick(n));
  if (missing.length) {
    check('S131', 'the roof-height model is findable', false, 'missing: ' + missing.join(', '));
  } else {
    const mk = typedFt => new Function(
      'let rmOrigin={lat:40.2969,lng:-111.6946};' + LF_ +
      'let rmFaces=[], rmRoofDatumM=null, rmDatumSource="";' + LF_ +
      'const RM_ASSUMED_EAVE_M=3, RM_M_TO_FT=3.280839895;' + LF_ +
      'function rmWorkingHeightM(){ return ' + (typedFt / 3.280839895) + '; }' + LF_ +
      NAMES.map(pick).join(LF_) + LF_ +
      'return {set:function(f){rmFaces=f;}, rmDatum, rmRoofRelativeAt, rmRoofHeightAt,' +
      ' rmSetDatumFromStreet, rmLowestPlaneM, rmToWorld, rmToLocal,' +
      ' datumSource:function(){return rmDatumSource;}};')();

    const m = new Function('return ' + pick('rmMetresPerDeg').replace('function rmMetresPerDeg', 'function') + ';')()(40.2969);
    const ll = (e, n) => ({lat: 40.2969 + n / m.lat, lng: -111.6946 + e / m.lng});
    /* Two faces of one gable, straight off the shape of the real Solar data:
       plane heights in the 1460s above sea level, a real pitch, real azimuths. */
    const FACES = [
      {sw: ll(-8, -6), ne: ll(8, 0), azimuth: 180, pitch: 26.5, center: ll(0, -3), planeHeightM: 1462.0},
      {sw: ll(-8, 0), ne: ll(8, 6), azimuth: 0, pitch: 26.5, center: ll(0, 3), planeHeightM: 1462.0}
    ];

    /* ---- the shape is exact without sea level ------------------------- */
    const api = mk(0);
    api.set(FACES);
    /* ⚠ NOT the plane's CENTRE height. The reference is the lowest real EAVE,
       which sits below the centre by half the face's depth times the pitch -
       three feet on an ordinary roof, and using the centre made every eave a
       negative height and dragged the datum down with it. */
    const lowest = api.rmLowestPlaneM();
    const drop = 3 * Math.tan(26.5 * Math.PI / 180);   /* half of the 6 m face */
    check('S131', 'the reference is the lowest EAVE, not the plane centre',
      lowest !== null && Math.abs(lowest - (1462.0 - drop)) < 0.15,
      'got ' + (lowest === null ? 'null' : lowest.toFixed(3)) + ', expected about ' +
      (1462.0 - drop).toFixed(3) + ' - a centre-height reference is wrong by feet at the gutter');
    const atEave = api.rmRoofRelativeAt(ll(0, -6).lat, ll(0, -6).lng);
    const atRidge = api.rmRoofRelativeAt(ll(0, 0).lat, ll(0, 0).lng);
    check('S131', 'the ridge is higher than the eave WITHOUT any ground elevation',
      atEave !== null && atRidge !== null && atRidge > atEave + 1,
      'eave ' + atEave + ' m, ridge ' + atRidge + ' m — this is the half that never needed sea level');

    /* ---- ⚠ THE REGRESSION: nothing may land on the ground -------------- */
    const noDatum = mk(0);            /* nothing typed, nothing measured */
    noDatum.set(FACES);
    const h = noDatum.rmRoofHeightAt(ll(0, -6).lat, ll(0, -6).lng);
    check('S131', 'with NO datum at all the eave is still off the ground',
      h !== null && h > 2,
      'got ' + h + ' — this is the exact failure that shipped: every guessed line on the lawn');
    check('S131', 'and it says the height is only assumed, not measured',
      noDatum.rmDatum().source === 'assumed',
      'a guessed height that presents itself as measured is worse than no height');
    check('S131', 'a typed height beats the assumption',
      mk(14).rmDatum().source === 'typed' && Math.abs(mk(14).rmDatum().m - 14 / 3.280839895) < 0.01);

    /* ---- Street View pins it, and outranks both ----------------------- */
    const sv = mk(14);
    sv.set(FACES);
    /* A point really observed on the eave, 11 ft up. */
    const eaveLL = ll(0, -6);
    const observed = {lat: eaveLL.lat, lng: eaveLL.lng, h: 11 / 3.280839895};
    check('S131', 'one Street View measurement pins the whole roof',
      sv.rmSetDatumFromStreet(observed) === true && sv.datumSource() === 'street',
      'this is the "use street view to figure out where the lines go" half');
    const pinned = sv.rmRoofHeightAt(eaveLL.lat, eaveLL.lng);
    check('S131', 'and that point then reads back at the height it was measured at',
      Math.abs(pinned - 11 / 3.280839895) < 0.05,
      'got ' + (pinned * 3.280839895).toFixed(2) + ' ft, measured 11 ft');
    const ridgeAfter = sv.rmRoofHeightAt(ll(0, 0).lat, ll(0, 0).lng);
    check('S131', 'while the ridge rises above it by the roof’s own shape',
      ridgeAfter > pinned + 1,
      'ridge ' + (ridgeAfter * 3.280839895).toFixed(1) + ' ft vs eave ' + (pinned * 3.280839895).toFixed(1) + ' ft');

    /* ---- a bad click must not drag the roof ---------------------------- */
    const bad = mk(0);
    bad.set(FACES);
    check('S131', 'a click on the road does not become the datum',
      bad.rmSetDatumFromStreet({lat: eaveLL.lat, lng: eaveLL.lng, h: 0.2}) === false,
      'one stray click would otherwise put the whole roof underground');
    check('S131', 'nor does a click on the sky',
      bad.rmSetDatumFromStreet({lat: eaveLL.lat, lng: eaveLL.lng, h: 30}) === false);
    check('S131', 'and after refusing, the assumed datum still stands',
      bad.rmDatum().source === 'assumed' && bad.rmDatum().m > 2,
      'a refused measurement must not leave the roof with no datum at all');
  }

  /* ---- the dead API is gone, not merely unused ---------------------- */
  check('S131', 'the Elevation lookup is switched off, since it can never answer',
    /if\(false\)\{/.test(admin) && /referrer-restricted key/.test(admin),
    'asking an API that refuses our key on every load is a red herring in the console');
  const build = extractFn(admin, 'rmBuildSuggestions');
  /* ⚠ COMMENTS STRIPPED FIRST. The reason `?? 0` is forbidden is written down
     right beside the code, so a plain search finds the EXPLANATION and calls it
     a violation - which is exactly what happened here, and CLAUDE.md records
     the same trap in Suite 58. */
  const buildCode = (build || '')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\/\/[^\n]*/g, '');
  check('S131', 'a suggested line never falls back to zero height',
    !!build && !/\?\?\s*0\b/.test(buildCode) && /rmDatum\(\)\.m/.test(buildCode),
    'the `?? 0` fallback is exactly how every guessed line ended up on the lawn');

  /* ---- Street View is a working surface, not a picture --------------- */
  check('S131', 'a point can be dragged in Street View, not only on the sky view',
    /rmWallHit\(dir, cam, plane\)/.test(admin) && /streetMeasured/.test(admin),
    'seeing a line an inch off the gutter and being unable to fix it there is the whole complaint');
  const refresh = extractFn(admin, 'rmRefreshHeights');
  check('S131', 'changing the datum moves every guessed line at once',
    !!refresh && /rmRoofHeightAt/.test(refresh),
    'a measured datum that does not reach the lines it should correct has done nothing');
  check('S131', 'but a point measured in Street View is never re-derived over',
    !!refresh && /if\(r\.streetMeasured\) return;/.test(refresh),
    'throwing away a real observation to keep the guess tidy is backwards');
  check('S131', 'and the panel says which datum is in force',
    /id="rmDatumNote"/.test(admin) && /ASSUMED at/.test(admin),
    'a height nobody can trace back is a height nobody can argue with');
}


suite('132. Measure Roof - both views feed one length, and the front is the default');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* ================= ONE LENGTH, BOTH VIEWS =========================
     Owner: "make sure that calculations use both views though, length, depth,
     and height to calculate the actual length using both views."
     Sky view knows where a point is on the ground exactly; Street View is the
     only place its height can be observed. A length has to carry both, or a
     roofline that climbs measures as its shadow. */
  const NAMES = ['rmMetresPerDeg', 'rmToLocal', 'rmToWorld', 'rmFeetBetween'];
  if (NAMES.some(n => !pick(n))) {
    check('S132', 'the distance maths is findable', false, 'renamed or removed');
  } else {
    const api = new Function(
      'let rmOrigin={lat:40.2969,lng:-111.6946};' + LF_ +
      'const RM_M_TO_FT=3.280839895;' + LF_ +
      NAMES.map(pick).join(LF_) + LF_ +
      'return {rmToWorld, rmFeetBetween};')();
    const FT = 3.280839895;
    /* A run 8 m along the wall (sky view's answer), 5 m further from the road
       (sky view again - depth), and climbing 4 m (only Street View can say). */
    const a = api.rmToWorld({e: 0, n: 0, u: 3});
    const b = api.rmToWorld({e: 8, n: 5, u: 7});
    const got = api.rmFeetBetween(a, b);
    const want = Math.hypot(8, 5, 4) * FT;
    check('S132', 'length carries width, depth AND height in one number',
      Math.abs(got - want) < 0.05,
      'got ' + got.toFixed(2) + ' ft, expected ' + want.toFixed(2) +
      ' - if these differ, one of the three is being dropped');
    /* Each component must actually move the answer - a length that ignores any
       one of them is the bug, and it is invisible unless tested separately. */
    /* Asserted EXACTLY rather than against a threshold. The first version
       demanded the climb add 3 ft; it adds 2.65, so a correct answer failed a
       round number I had picked out of the air. The real claim is that the
       flat run is exactly the horizontal hypotenuse and the full run is longer
       - both of which can be stated without inventing a margin. */
    const flat = api.rmFeetBetween(api.rmToWorld({e:0,n:0,u:3}), api.rmToWorld({e:8,n:5,u:3}));
    check('S132', 'with the climb removed it is exactly the horizontal run',
      Math.abs(flat - Math.hypot(8, 5) * FT) < 0.02,
      'got ' + flat.toFixed(2) + ' ft, expected ' + (Math.hypot(8, 5) * FT).toFixed(2));
    check('S132', 'and the real run is longer, so height really counts',
      got > flat + 1,
      'climbing ' + (4 * FT).toFixed(1) + ' ft adds ' + (got - flat).toFixed(2) +
      ' ft - if it adds nothing, height is not reaching the length');
    const noDepth = api.rmFeetBetween(api.rmToWorld({e:0,n:0,u:3}), api.rmToWorld({e:8,n:0,u:7}));
    check('S132', 'and dropping the depth makes it shorter too',
      got > noDepth + 1, 'depth is not reaching the length');
    const noWidth = api.rmFeetBetween(api.rmToWorld({e:0,n:0,u:3}), api.rmToWorld({e:0,n:5,u:7}));
    check('S132', 'and dropping the width as well',
      got > noWidth + 2, 'width is not reaching the length');
  }

  /* ================= FRONT BY DEFAULT ================================
     Owner: "you should only do it for front of house by default but there
     should be buttons for multiple sides if they want multiple sides." */
  const sideFn = pick('rmEaveSide');
  if (!sideFn || !pick('rmToLocal')) {
    check('S132', 'the side-of-house rule is findable', false, 'rmEaveSide renamed or removed');
  } else {
    const sapi = new Function(
      'let rmOrigin={lat:40.2969,lng:-111.6946};' + LF_ +
      'let __cam=null; function rmCamLocal(){ return __cam; }' + LF_ +
      pick('rmMetresPerDeg') + LF_ + pick('rmToLocal') + LF_ + pick('rmToWorld') + LF_ +
      /* rmEaveSide now asks rmCamOnRoad, not rmCamLocal - a camera still sitting
         at the house is not a road. Lift it in or the sandbox dies undefined. */
      'const RM_ROAD_MIN_M = 4;' + LF_ + (pick('rmCamOnRoad') || '') + LF_ +
      /* The road is now decided ONCE and remembered, so the variable holding it
         and the function that sets it both have to come in. */
      'let rmRoadDir = null; let rmBuilding = null;' + LF_ + (pick('rmRoadDirection') || '') + LF_ +
      /* rmEaveSide now measures how far across the house a DEEP line sits, so
         the width helper comes in too. rmBuilding stays null here, which is
         the no-footprint case the rule has to tolerate. */
      (pick('rmHouseHalfWidth') || '') + LF_ + sideFn + LF_ +
      'return {setCam:function(c){__cam=c;}, newHouse:function(){ rmRoadDir = null; }, rmEaveSide, rmToWorld};')();
    /* Camera due south of the house, i.e. the road is south. */
    sapi.setCam({e: 0, n: -20, u: 2.5});
    const eaveAt = (e, n) => ({a: sapi.rmToWorld({e: e - 3, n: n, u: 0}),
                               b: sapi.rmToWorld({e: e + 3, n: n, u: 0})});
    check('S132', 'the eave nearest the road is the FRONT',
      sapi.rmEaveSide(eaveAt(0, -6)) === 'front',
      'got ' + sapi.rmEaveSide(eaveAt(0, -6)));
    check('S132', 'the far one is the BACK',
      sapi.rmEaveSide(eaveAt(0, 6)) === 'back',
      'got ' + sapi.rmEaveSide(eaveAt(0, 6)));
    const east = sapi.rmEaveSide({a: sapi.rmToWorld({e: 6, n: -3, u: 0}), b: sapi.rmToWorld({e: 6, n: 3, u: 0})});
    const west = sapi.rmEaveSide({a: sapi.rmToWorld({e: -6, n: -3, u: 0}), b: sapi.rmToWorld({e: -6, n: 3, u: 0})});
    /* ⭐ A LINE THAT RUNS DEEP IS SORTED BY WHERE IT SITS ACROSS THE HOUSE.
       Owner: "when you have a line that runs deep have it check where its
       located on the roof so it can check if its the left or right side
       because if it is we dont want to inclide that on default."
       A rake out on the left flank still has its middle roughly in front of
       the centre of the house, so judging it the way a gutter is judged calls
       it FRONT and switches it on. */
    const deepApi = new Function(
      'let rmOrigin={lat:40.2969,lng:-111.6946};' + LF_ +
      'let __cam={e:0,n:-20,u:2.5}; function rmCamLocal(){ return __cam; }' + LF_ +
      'const RM_ROAD_MIN_M = 4; let rmRoadDir = null; let rmBuilding = null;' + LF_ +
      ['rmMetresPerDeg','rmToLocal','rmToWorld','rmCamOnRoad','rmRoadDirection','rmHouseHalfWidth']
        .map(pick).join(LF_) + LF_ + sideFn + LF_ +
      'return {side: rmEaveSide, house:function(b){ rmBuilding = b; }, toWorld: rmToWorld};')();
    {
      /* A house 20 m across the front and 10 m deep. */
      const c1 = deepApi.toWorld({e: -10, n: -5, u: 0}), c2 = deepApi.toWorld({e: 10, n: 5, u: 0});
      deepApi.house({sw: {lat: c1.lat, lng: c1.lng}, ne: {lat: c2.lat, lng: c2.lng}});
      const deepAt = e => ({a: deepApi.toWorld({e: e, n: -4, u: 0}),
                            b: deepApi.toWorld({e: e, n: 3, u: 0})});
      check('S132', 'a deep line near the middle of the front is a FRONT line',
        deepApi.side(deepAt(1.5)) === 'front',
        'got ' + deepApi.side(deepAt(1.5)) + ' - the dormer and gable rakes live here');
      const farLeft = deepApi.side(deepAt(9));
      const farRight = deepApi.side(deepAt(-9));
      check('S132', 'but one out on the flank is a side, and the two flanks differ',
        (farLeft === 'left' || farLeft === 'right') && (farRight === 'left' || farRight === 'right') &&
        farLeft !== farRight,
        'got ' + farLeft + ' and ' + farRight);
      /* ⚠ And a line ACROSS the front is still judged the old way, however far
         out it sits - that is a gutter, and the front gutter reaches the
         corners by definition. */
      const wideGutter = {a: deepApi.toWorld({e: 6, n: -5, u: 0}), b: deepApi.toWorld({e: 10, n: -5, u: 0})};
      check('S132', 'a gutter across the front stays front even out at the corner',
        deepApi.side(wideGutter) === 'front',
        'got ' + deepApi.side(wideGutter) + ' - the front gutter runs the whole width');
    }

    /* ⚠ A WALL YOU CAN SEE IS NOT THE FRONT OF THE HOUSE. Owner: "the left
       side should not be included just because it is visible from street
       view." The threshold was 63 degrees either way, so a face turned sixty
       degrees off the road came on by itself. Forty-five is the honest
       quadrant, and this fixture sits at fifty - visible from the road, and
       not the front. */
    const fifty = sapi.rmEaveSide({a: sapi.rmToWorld({e: 5, n: -4.2, u: 0}),
                                   b: sapi.rmToWorld({e: 7, n: -5.9, u: 0})});
    check('S132', 'a wall turned fifty degrees off the road is a SIDE, not the front',
      fifty === 'left' || fifty === 'right',
      'got ' + fifty + ' - being able to see a wall is not the same as it facing the road');
    check('S132', 'and the two in between are left and right, not both the same',
      (east === 'left' || east === 'right') && (west === 'left' || west === 'right') && east !== west,
      'got ' + east + ' and ' + west + ' - sides are described from the road, the way a person would');
    /* ⚠ THE SIDES ARE NAMED FROM THE ROAD, AND THE ROAD IS DECIDED ONCE.
       This check used to assert the opposite - that moving the camera moved
       the front with it - which was true and was the bug. Owner: "no matter
       what angle your looking at it should look at every angle to know where
       to put the lines, the angle we see is just so we can see it and take a
       picture." Looking at a house from further down the street is not a
       statement about which side of it faces the road, and re-deciding on
       every camera move reshuffled the Front/Left/Right/Back counts and
       changed which run was switched on underneath her. */
    sapi.setCam({e: 0, n: 20, u: 2.5});      /* camera walks round to the back */
    check('S132', 'walking the camera round does NOT move the front of the house',
      sapi.rmEaveSide(eaveAt(0, -6)) === 'front' && sapi.rmEaveSide(eaveAt(0, 6)) === 'back',
      'the front followed the camera: got ' + sapi.rmEaveSide(eaveAt(0, -6)) +
      ' and ' + sapi.rmEaveSide(eaveAt(0, 6)));
    /* But a NEW house starts the question again, or every address after the
       first would inherit the last one's road. */
    sapi.newHouse();
    check('S132', 'though a new address decides its own road afresh',
      sapi.rmEaveSide(eaveAt(0, 6)) === 'front',
      'with the camera now north, the north eave is the front one');
  }
  const facesFn = pick('rmFaceFacesTheRoad');
  check('S132', 'only the front is switched on without being asked',
    !!facesFn && /rmEaveSide\(eave\) === 'front'/.test(facesFn),
    'anything else on by default is work to undo on every quote');
  check('S132', 'and the other sides are offered as buttons, not hidden',
    /data-rmside="left"/.test(admin) && /data-rmside="back"/.test(admin) && /id="rmAllSides"/.test(admin),
    'a line nobody can see is a line nobody knows to ask for');
  check('S132', 'each side button counts what it holds',
    /mine\.length \? ' \(' \+ mine\.length \+ '\)' : ''/.test(admin),
    'a button that appears to do nothing is worse than one that says it is empty');
  check('S132', 'and a hand-traced line is never swept up by a side button',
    /if\(!r\.suggested \|\| r\.side !== side\) return;/.test(admin),
    'having your own work vanish because a side was toggled is its own small betrayal');

  /* ================= NOT A FOOT OFF ==================================
     Owner: "the lines should not look offset from the house by a single foot
     so make sure to be very exact." Google's face boxes are AXIS-ALIGNED, so a
     house turned off the compass gets a box bigger than its roof. */
  /* rmFaceEave is now a one-line delegate: the gutter and the ridge are drawn
     by the same builder, so the inset lives there and this must look there. */
  const eaveFn = pick('rmFaceEdgeLine');
  check('S132', 'the eave line is pulled in to the face true area',
    !!eaveFn && /areaSqFt/.test(eaveFn) && /Math\.sqrt\(trueArea \/ boxArea\)/.test(eaveFn),
    'used raw, an axis-aligned box hangs the line past the end of the house');
  check('S132', 'but never shrunk past 70%',
    !!eaveFn && /Math\.max\(0\.7,/.test(eaveFn),
    'a complicated face would otherwise be pulled in until the line is far too short');
  check('S132', 'and the honest limit is written down, not glossed',
    !!eaveFn && /correction, not a cure/.test(eaveFn),
    'a box cannot say which way a house is turned, and pretending otherwise is how a guess gets trusted too far');
}


suite('141. Measure Roof - the street decides, and it is allowed to be late');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Found by opening the tool on a real house rather than by reading the code.
     Google answers twice, at its own speed: once with the roof model, once with
     the road photo. The lines used to be drawn the instant the ROOF MODEL
     landed - whichever arrived first - so on that house every line was placed
     with no camera in existence. Owner: "the lines were already positioned
     before street view got there meaning that its using the sky map to
     determine where lines should go, not the street view." */

  /* ---- 1. a camera still sitting at the house is not a road ------------- */
  const onRoad = pick('rmCamOnRoad');
  if (!onRoad) {
    check('S141', 'the road test is findable', false, 'rmCamOnRoad renamed or removed');
  } else {
    const api = new Function(
      'let __cam=null; const RM_ROAD_MIN_M = 4;' + LF_ +
      'function rmCamLocal(){ return __cam; }' + LF_ + onRoad + LF_ +
      'return {set:function(c){__cam=c;}, rmCamOnRoad};')();
    api.set(null);
    check('S141', 'no camera at all is not a road', api.rmCamOnRoad() === null);
    api.set({e: 0.4, n: -0.3, u: 2.5});
    check('S141', 'a camera still standing at the house is not a road either',
      api.rmCamOnRoad() === null,
      'this is the state the panorama opens in, and it is why all eight lines came out "front"');
    api.set({e: 0, n: -18, u: 2.5});
    check('S141', 'a camera out on the street IS a road',
      !!api.rmCamOnRoad(), 'the real camera must still count, or nothing is ever sided');
  }

  /* ---- 2. nothing is drawn until BOTH answers are in -------------------- */
  const gate = pick('rmBuildWhenReady');
  check('S141', 'the lines wait for the roof model AND the street',
    !!gate && /!rmFacesReady/.test(gate) && /!rmStreetSettled/.test(gate),
    'drawing on whichever lands first is the bug this suite exists for');
  check('S141', 'and they are drawn once, not once per answer',
    !!gate && /rmSuggestionsBuilt/.test(gate),
    'both answers arriving would otherwise redraw over picks already made');
  check('S141', 'the sides are settled after the camera exists, not before',
    !!gate && gate.indexOf('rmBuildSuggestions') < gate.indexOf('rmResideSuggestions'),
    'siding before the camera is what produced Front (8) and three empty sides');

  /* ⚠ THE WAIT MUST BE BOUNDED. A street photo that never settles must not
     leave somebody looking at an empty panel forever. */
  check('S141', 'the wait gives up after a while and draws anyway',
    /setTimeout\(rmStreetSettle, 10000\)/.test(admin),
    'an unbounded wait on a third party is a hang with better manners');
  /* ⚠ RETIRED, NOT LOST. Nothing is guessed from the map any more - the owner
     asked for the automatic lines to be taken out entirely ("delete everything
     for now and give me a tool that I can show you what it should look like by
     placing dots"), so there is no map-only line left to warn about. The
     builder and its warning are still in the file and still tested; they are
     simply not run. If automatic lines ever come back, so must this. */
  /* The WARNING went with the status line it lived on - there is no map-only
     line left to warn about. What must survive is the builder itself, so
     turning guessing back on is one line rather than a rewrite. */
  check('S141', 'the roofline builder is kept, ready for guessing to return',
    !!pick('rmBuildSuggestions') && /NOTHING IS GUESSED ANY MORE/.test(admin),
    'the automatic path is switched off, not deleted, and the file should say which');

  /* ---- 3. a picked line is never re-picked ----------------------------- */
  const reside = pick('rmResideSuggestions');
  check('S141', 're-siding never overrules a line somebody has already touched',
    !!reside && /if\(!r\.touched\)/.test(reside),
    'the camera arriving late must not undo work done while it was loading');
  check('S141', 'and it does nothing at all until there is a road to reason from',
    !!reside && /if\(!rmCamOnRoad\(\)\) return false;/.test(reside));

  /* ---- 4. one bad lookup is not "no Street View" ------------------------ */
  /* Watched live: radius 60 answered fine and radius 100 came back
     UNKNOWN_ERROR seconds later, same street, same key. */
  check('S141', 'a transient failure is retried, wider',
    /const RADII = \[60, 100, 160\];/.test(admin) &&
    /st !== 'ZERO_RESULTS' && i < RADII\.length - 1/.test(admin),
    'one hiccup used to be reported as "Google has never driven this street"');
  check('S141', 'but a real ZERO_RESULTS is taken as the answer it is',
    /if\(st !== 'ZERO_RESULTS' && i < RADII\.length - 1\)\{ askStreetView\(i \+ 1\); return; \}/.test(admin),
    'retrying a definite no is just a slower no');
  check('S141', 'and a no still lets the lines be drawn from the map',
    /rmPaneBusy\('street', 'Google has never driven this street\.', false\);[\s\S]{0,220}rmStreetSettle\(\);/.test(admin),
    'otherwise a house with no street photo gets no lines at all');

  /* ---- 5. listen before you look --------------------------------------- */
  /* The panorama had loaded - three canvases, thirteen tiles - with a spinner
     sitting on top of it saying "Looking for a street-level photo". The
     listener was attached on the line AFTER setPano, so the event had already
     gone by. */
  const iListen = admin.indexOf("addListenerOnce(rmPano, 'pano_changed'");
  const iSet = admin.indexOf('rmPano.setPano(data.location.pano)');
  check('S141', 'the pano_changed listener is attached BEFORE setPano',
    iListen !== -1 && iSet !== -1 && iListen < iSet,
    'attached after, the event is already gone and the cover never comes off');
  check('S141', 'and the panorama is asked directly in case the event is missed',
    /if\(rmPano && rmPano\.getPano\(\)\)\{ rmPaneReady\('street'\);/.test(admin),
    'a covered-up working panorama is the worst of both');
}


/* A lat/lng that lands at a given point in the test frame - saves restating
   the projection maths inside every fixture. */
function rmLatLngAt(api, e, n){ return api.rmToWorld({e: e, n: n, u: 0}); }

suite('142. Measure Roof - a gutter is found by its ridge, not by being bright');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);
  const constLines = admin.match(/^const RM_(PHOTO_FOV|EDGE_MIN|DATUM_MIN_SAMPLES|DATUM_SPREAD_M|EAVE_MIN_M|EAVE_MAX_M|DATUM_STEP_M|PAIR_TOL_PX).*?;/gm) || [];
  const consts = constLines.join(LF_);
  check('S142', 'every threshold this suite leans on was really found in the page',
    constLines.length === 8,
    'found ' + constLines.length + ' of 8 - a missing one becomes undefined in the sandbox, not a failure');

  const NEED = ['rmBasis', 'rmPhotoProject', 'rmPhotoRay', 'rmFacePlane', 'rmPlaneHit3',
                'rmEdgeStrengthAt', 'rmScoreDatum', 'rmSolveDatum', 'rmDatumFromSamples'];
  const missing = NEED.filter(n => !pick(n));
  if (missing.length || constLines.length !== 8) {
    check('S142', 'the photo maths is findable', false, 'missing: ' + missing.join(', '));
  } else {
    const build = extra => new Function(
      'const rmRad = d => d*Math.PI/180; const rmDeg = r => r*180/Math.PI;' + LF_ +
      consts + LF_ + (extra || '') + LF_ +
      NEED.map(pick).join(LF_) + LF_ +
      'return {rmBasis, rmPhotoProject, rmPhotoRay, rmPlaneHit3, rmEdgeStrengthAt, rmScoreDatum, rmSolveDatum, rmDatumFromSamples};')();

    const api = build();
    const W = 640, H = 640, pose = {heading: 0, pitch: 8, fov: 70};
    const cam = {e: 0, n: -18, u: 2.6};

    /* ---- 1. the lens works both ways ---------------------------------- */
    let worst = 0;
    [[100, 120], [320, 320], [540, 200], [280, 480]].forEach(function(px){
      const dir = api.rmPhotoRay(px[0], px[1], W, H, pose);
      const far = {e: cam.e + dir.e * 40, n: cam.n + dir.n * 40, u: cam.u + dir.u * 40};
      const back = api.rmPhotoProject(far, W, H, pose, cam);
      worst = back ? Math.max(worst, Math.hypot(back.x - px[0], back.y - px[1])) : 9999;
    });
    check('S142', 'a pixel sent out and brought back lands on itself',
      worst < 0.01, 'worst round trip was ' + worst.toFixed(4) + ' px');
    const p70 = api.rmPhotoProject({e:0,n:0,u:3}, W, H, {heading:0,pitch:0,fov:70}, {e:-6,n:-14,u:2.6});
    const p40 = api.rmPhotoProject({e:0,n:0,u:3}, W, H, {heading:0,pitch:0,fov:40}, {e:-6,n:-14,u:2.6});
    check('S142', 'the field of view actually changes the picture',
      p70 && p40 && Math.abs(p40.x - W/2) > Math.abs(p70.x - W/2) * 1.5);

    /* ---- 2. a roof face is a real plane ------------------------------- */
    const planeApi = new Function(
      'const rmRad = d => d*Math.PI/180;' + LF_ +
      'let rmOrigin={lat:40.2969,lng:-111.6946};' + LF_ +
      'function rmDatum(){ return {m: 3, source:"assumed"}; }' + LF_ +
      'function rmLowestPlaneM(){ return 1460; }' + LF_ +
      pick('rmMetresPerDeg') + LF_ + pick('rmToLocal') + LF_ + pick('rmToWorld') + LF_ +
      pick('rmFacePlane') + LF_ + pick('rmPlaneHit3') + LF_ +
      'return {rmFacePlane, rmPlaneHit3, rmToWorld};')();
    const face = {center: planeApi.rmToWorld({e:0,n:0,u:0}), planeHeightM: 1462, azimuth: 180, pitch: 30,
                  sw: {lat:0,lng:0}, ne: {lat:0,lng:0}};
    const pl = planeApi.rmFacePlane(face);
    check('S142', 'a roof face becomes a plane at the right height',
      pl && Math.abs(pl.point.u - 5) < 0.01,
      'centre should be datum 3 m plus 2 m above the lowest eave, got ' + (pl ? pl.point.u.toFixed(3) : 'null'));
    if (pl) {
      const downhill = {e: pl.point.e, n: pl.point.n - 4};
      const onPlane = (pl.d - (pl.normal.e*downhill.e + pl.normal.n*downhill.n)) / pl.normal.u;
      check('S142', 'four metres downhill loses exactly the pitch in height',
        Math.abs((pl.point.u - onPlane) - 4*Math.tan(Math.PI/6)) < 0.02,
        'got a drop of ' + (pl.point.u - onPlane).toFixed(3) + ' m');
      const c2 = {e: 0, n: -20, u: 2.5};
      const target = {e: 1.5, n: -2, u: 0};
      target.u = (pl.d - (pl.normal.e*target.e + pl.normal.n*target.n)) / pl.normal.u;
      const len = Math.hypot(target.e-c2.e, target.n-c2.n, target.u-c2.u);
      const dir = {e:(target.e-c2.e)/len, n:(target.n-c2.n)/len, u:(target.u-c2.u)/len};
      const hit = planeApi.rmPlaneHit3(dir, c2, pl);
      check('S142', 'a ray aimed at the roof lands ON the roof',
        hit && Math.hypot(hit.e-target.e, hit.n-target.n, hit.u-target.u) < 0.01);
      check('S142', 'and a ray pointing away from it lands nowhere',
        planeApi.rmPlaneHit3({e:-dir.e,n:-dir.n,u:-dir.u}, c2, pl) === null);
    }

    /* ---- 3. gutters, not drainpipes ---------------------------------- */
    const mk = (w, h) => ({w: w, h: h, gy: new Float32Array(w*h), mag: new Float32Array(w*h)});
    const photo = mk(200, 200);
    for (let x = 0; x < 200; x++) { const i = 120*200 + x; photo.gy[i] = 90; photo.mag[i] = 90; }
    for (let y = 0; y < 200; y++) { if (y === 120) continue; const i = y*200 + 100; photo.gy[i] = 0; photo.mag[i] = 240; }
    check('S142', 'a horizontal edge is seen where it is',
      api.rmEdgeStrengthAt(photo, 100, 120) === 90);
    check('S142', 'a brighter DRAINPIPE crossing it registers as nothing',
      api.rmEdgeStrengthAt(photo, 100, 60) === 0,
      'total gradient would score 240 here and snap the roofline onto a downpipe');

    /* ---- 4. THE ONE THIS SUITE EXISTS FOR ---------------------------- */
    /* On a real house the first solver answered 25 ft to the lowest eave,
       because roof-against-sky is the brightest horizontal edge in any photo of
       a house and a lone gutter cannot outshine it. The fix is to refuse to
       identify a gutter except in company: its ridge, at the separation the
       roof model already knows. */
    const TRUE_DATUM = 2.35;
    const solveApi = build('function rmDatum(){ return {m: 3.6, source:"assumed"}; }');
    const sample = {e: 1.2, n: 3.0, rel: 1.4, ridge: {e: 1.2, n: 6.5, rel: 3.3}};
    const eaveAt = D => solveApi.rmPhotoProject({e: sample.e, n: sample.n, u: D + sample.rel}, 640, 640, pose, cam);
    const ridgeAt = D => solveApi.rmPhotoProject({e: sample.ridge.e, n: sample.ridge.n, u: D + sample.ridge.rel}, 640, 640, pose, cam);
    const eRow = eaveAt(TRUE_DATUM), rRow = ridgeAt(TRUE_DATUM);
    check('S142', 'the fixture really does separate gutter from ridge in the picture',
      Math.abs(eRow.y - rRow.y) > 8,
      'rows ' + Math.round(eRow.y) + ' and ' + Math.round(rRow.y) + ' - closer than that and one edge satisfies both');

    const draw = (shot, row, strength) => {
      const r = Math.round(row);
      if (!(r >= 0 && r < 640)) return;
      for (let x = 0; x < 640; x++) { const i = r*640 + x; shot.gy[i] = strength; shot.mag[i] = strength; }
    };
    const shot = mk(640, 640);
    draw(shot, eRow.y, 70);
    draw(shot, rRow.y, 70);
    /* And the sky: a blazing horizontal edge above the roof with nothing the
       right distance below it. This is the edge that used to win.
       ⚠ IT MUST SIT WHERE THE EAVE CAN REACH IT. The first version put it 55 px
       up, which the search - bounded to real house heights - could never get to,
       so the test passed with the ridge requirement DELETED. A guard that the
       fixture cannot reach is a guard nobody is testing. */
    const skyRow = eRow.y - 45;
    check('S142', 'the sky edge is somewhere the search can actually reach',
      Math.abs(skyRow - eaveAt(4.4).y) < 12,
      'sky at ' + Math.round(skyRow) + ', eave at the top of the range reaches ' +
      Math.round(eaveAt(4.4).y) + ' - if it cannot get there the sky proves nothing');
    draw(shot, skyRow, 250);
    const got = solveApi.rmSolveDatum(sample, shot, cam, pose);
    check('S142', 'the roof height is solved back out of the photograph',
      got && Math.abs(got.m - TRUE_DATUM) < 0.08,
      got ? 'got ' + got.m.toFixed(3) + ' m, wanted ' + TRUE_DATUM : 'solved nothing');
    check('S142', 'and the blazing SKY edge does not win, though it is far brighter',
      got && got.m < TRUE_DATUM + 0.5,
      'this is the 25-ft-eave bug: ' + (got ? got.m.toFixed(2) + ' m' : 'no answer'));

    /* A lone bright edge with no partner is not a roof at all. */
    const skyOnly = mk(640, 640);
    draw(skyOnly, Math.min(eRow.y, rRow.y) - 55, 250);
    check('S142', 'a bright edge with no ridge below it is refused outright',
      solveApi.rmSolveDatum(sample, skyOnly, cam, pose) === null,
      'one line is never enough to say where a roof is');
    check('S142', 'and an empty sky produces no answer rather than a confident one',
      solveApi.rmSolveDatum(sample, mk(640, 640), cam, pose) === null);

    /* ---- 4a. each guard, exercised on its own ------------------------ */
    /* ⚠ ALL THREE OF THESE WERE ADDED AFTER A RED-CHECK FOUND THE ORIGINALS
       VACUOUS: the sabotage was applied, the suite stayed green, and the
       comment above each guard was the only thing claiming it mattered. */

    /* THE WEAKER OF THE TWO, not the brighter. A dim gutter paired with a
       blazing ridge is a coincidence; a matched pair of ordinary edges is a
       roof. Scored on the brighter, the coincidence wins. */
    const D3 = TRUE_DATUM + 1.4;
    const lopsided = mk(640, 640);
    draw(lopsided, eRow.y, 70); draw(lopsided, rRow.y, 70);        /* the real roof */
    draw(lopsided, eaveAt(D3).y, 30);                              /* barely an edge */
    draw(lopsided, ridgeAt(D3).y, 250);                            /* blazing */
    const pairPick = solveApi.rmSolveDatum(lopsided.w ? sample : sample, lopsided, cam, pose);
    check('S142', 'a dim gutter with a blazing ridge loses to an honest pair',
      pairPick && Math.abs(pairPick.m - TRUE_DATUM) < 0.12,
      'got ' + (pairPick ? pairPick.m.toFixed(2) : 'null') + ' - scoring on the brighter of the two ' +
      'picks the coincidence at ' + D3.toFixed(2));

    /* A FAINT SMUDGE IS NOT A GUTTER. Both edges present, both below the
       threshold: the answer must be no answer. */
    const faint = mk(640, 640);
    draw(faint, eRow.y, 12); draw(faint, rRow.y, 12);
    check('S142', 'a pair of faint smudges is refused, not measured',
      solveApi.rmSolveDatum(sample, faint, cam, pose) === null,
      'film grain would otherwise place the roofline');

    /* TWO LINES THAT LAND ON THE SAME ROW ARE ONE LINE. A shallow face seen
       head-on projects its gutter and ridge within a pixel of each other, and
       then any single edge satisfies both and the pairing proves nothing. */
    const flatSample = {e: 1.2, n: 3.0, rel: 1.4, ridge: {e: 1.2, n: 3.1, rel: 1.42}};
    const fe = solveApi.rmPhotoProject({e: 1.2, n: 3.0, u: TRUE_DATUM + 1.4}, 640, 640, pose, cam);
    const fr = solveApi.rmPhotoProject({e: 1.2, n: 3.1, u: TRUE_DATUM + 1.42}, 640, 640, pose, cam);
    check('S142', 'the head-on fixture really does collapse the two rows',
      Math.abs(fe.y - fr.y) < 6, 'rows ' + fe.y.toFixed(1) + ' and ' + fr.y.toFixed(1));
    const oneLine = mk(640, 640);
    draw(oneLine, fe.y, 90);
    check('S142', 'a gutter and ridge on the same row are not a pair',
      solveApi.rmSolveDatum(flatSample, oneLine, cam, pose) === null,
      'one edge answering for both is the pairing proving nothing');

    /* THE BOUNDS ARE A HOUSE, NOT A RANGE OF NUMBERS. */
    const minM = Number((admin.match(/const RM_EAVE_MIN_M = ([\d.]+)/) || [])[1]);
    const maxM = Number((admin.match(/const RM_EAVE_MAX_M = ([\d.]+)/) || [])[1]);
    check('S142', 'the bounds describe a real eave, in feet you could point at',
      minM >= 1.5 && minM <= 2.5 && maxM >= 4.0 && maxM <= 6.0,
      'got ' + (minM * 3.28084).toFixed(1) + ' to ' + (maxM * 3.28084).toFixed(1) +
      ' ft - anything wider lets the search walk up to the skyline again');
    const tooHigh = mk(640, 640);
    draw(tooHigh, eaveAt(8.0).y, 90); draw(tooHigh, ridgeAt(8.0).y, 90);
    check('S142', 'a perfect pair at an impossible height is still refused',
      solveApi.rmSolveDatum(sample, tooHigh, cam, pose) === null,
      'a 26 ft eave is a church, not a house we hang lights on');

    /* ---- 4b. two roofs in one picture -------------------------------- */
    /* A porch roof below the main one fits the same eave-and-ridge shape at a
       different height, so two separate bands of datum both score full marks.
       Averaging across the gap lands between them - on neither roof. */
    const D2 = TRUE_DATUM + 1.0;
    const two = mk(640, 640);
    draw(two, eRow.y, 70); draw(two, rRow.y, 70);
    draw(two, eaveAt(D2).y, 70); draw(two, ridgeAt(D2).y, 70);
    const pickedOne = solveApi.rmSolveDatum(sample, two, cam, pose);
    check('S142', 'two roofs in one picture: it picks ONE, never the gap between them',
      pickedOne && (Math.abs(pickedOne.m - TRUE_DATUM) < 0.12 || Math.abs(pickedOne.m - D2) < 0.12),
      'got ' + (pickedOne ? pickedOne.m.toFixed(2) : 'null') + ' m against roofs at ' +
      TRUE_DATUM + ' and ' + D2.toFixed(2) + ' - a value in between matches no roof on the house');

    /* ---- 5. a tree over one gutter must not stop the job -------------- */
    /* Owner: "make sure that it can still draw the line if a tree is in the
       way." A blocked gutter simply produces no sample; the others still do. */
    const treed = mk(640, 640);
    draw(treed, eRow.y, 70);
    draw(treed, rRow.y, 70);
    const blocked = {e: -40, n: 3.0, rel: 1.4, ridge: {e: -40, n: 6.5, rel: 3.3}};  /* off the frame entirely */
    check('S142', 'a gutter nobody can see yields nothing, quietly',
      solveApi.rmSolveDatum(blocked, treed, cam, pose) === null);
    const mixed = solveApi.rmDatumFromSamples([blocked, sample, sample, sample, blocked], treed, cam, pose);
    check('S142', 'and the gutters that ARE visible still answer for the house',
      mixed.ok === true && Math.abs(mixed.m - TRUE_DATUM) < 0.08,
      JSON.stringify(mixed) + ' - two hidden gutters must not lose the other three');

    /* ---- 6. several gutters must agree ------------------------------- */
    check('S142', 'one gutter is not enough to move the whole roof',
      solveApi.rmDatumFromSamples([sample], shot, cam, pose).ok === false);
    const agreed = solveApi.rmDatumFromSamples([sample, sample, sample], shot, cam, pose);
    check('S142', 'but several that agree are believed',
      agreed.ok === true && Math.abs(agreed.m - TRUE_DATUM) < 0.08, JSON.stringify(agreed));

    /* ---- 7. the search cannot reach a height no house has ------------ */
    check('S142', 'the search is bounded to heights a house actually has',
      /const RM_EAVE_MIN_M = /.test(admin) && /const RM_EAVE_MAX_M = /.test(admin) &&
      !/RM_DATUM_LOOK_PX/.test(admin),
      'the old wide pixel window is what let the search walk up to the skyline');
    const tall = solveApi.rmSolveDatum(sample, shot, cam, pose);
    check('S142', 'and every answer it can give is inside those bounds',
      !tall || (tall.m >= 1.8 - 1e-9 && tall.m <= 4.9 + 1e-9),
      'got ' + (tall ? tall.m : 'null'));
  }

  /* ---- 8. the honest bits stay written down ------------------------- */
  check('S142', 'the tainted-image case is named rather than silently swallowed',
    /return \{error: 'tainted'/.test(admin) && /silent fallback/.test(admin));
  check('S142', 'the page still never picks a Google key by hand',
    !/streetview\?[^']*key=AIza/.test(admin));
  check('S142', 'and the status line says when the height is still only assumed',
    /The height is still assumed/.test(admin));
  check('S142', 'a failed photo read never removes the lines that were drawn',
    !!pick('rmDatumFromStreetPhoto') && !/rmRuns\s*=/.test(pick('rmDatumFromStreetPhoto')),
    'a tree over the house must cost the HEIGHT, never the roofline itself');
}

suite('143. Measure Roof - strands you are running, and a photo read that waits for the road');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* ---- 1. the strand count is the job, not the offer ------------------ */
  /* Seen live: the front of the house switched on, three lines, and the panel
     said "Separate strands 8" - it was counting every line the roof model had
     offered, greyed-out ones included. Whoever packs the van reads that. */
  const onFn = pick('rmRunIsOn');
  if (!onFn) {
    check('S143', 'the switched-on test is findable', false, 'rmRunIsOn renamed or removed');
  } else {
    const api = new Function(
      onFn + LF_ +
      'function count(runs){ return runs.filter(rmRunIsOn).length; }' + LF_ +
      'return {count, rmRunIsOn};')();
    const runs = [{on: true}, {on: false}, {on: false}, {}, {on: false}];
    check('S143', 'only the lines switched on are counted as strands',
      api.count(runs) === 2,
      'got ' + api.count(runs) + ' of 5, expected 2 - a run with no flag at all counts as on');
    check('S143', 'and the results panel counts them that way',
      /rmRuns\.filter\(rmRunIsOn\)\.length[\s\S]{0,140}Separate strands/.test(admin) ||
      /Separate strands<\/span><strong>'\+rmRuns\.filter\(rmRunIsOn\)\.length/.test(admin),
      'rmRuns.length counts the greyed-out lines too');
    check('S143', 'and so does the material list',
      /Separate strands<\/span><strong>'\+\(rmRuns\.filter\(rmRunIsOn\)\.length\|\|1\)/.test(admin),
      'the van gets packed off this number');
    check('S143', 'the raw run count is no longer used for strands anywhere',
      !/Separate strands<\/span><strong>'\+rmRuns\.length/.test(admin) &&
      !/Separate strands<\/span><strong>'\+\(rmRuns\.length\|\|1\)/.test(admin),
      'one of the two panels was left counting every line');
  }

  /* ---- 2. the photo read waits for a road ---------------------------- */
  /* Seen live on the test house: lines drawn, sides correct, and the status
     line honestly reporting "the height is still assumed: the camera is not on
     the road yet". pano_changed fires before position_changed, so the first
     attempt read a camera still standing at the house - and nothing tried
     again once it moved. */
  const tryFn = pick('rmTryPhotoDatum');
  check('S143', 'the photo read refuses to run without a road',
    !!tryFn && /if\(!rmCamOnRoad\(\)\) return;/.test(tryFn),
    'reading the photo from a camera standing in the living room measures nothing');
  check('S143', 'it is retried when the camera moves onto the road',
    /rmResideSuggestions\(\);[\s\S]{0,180}rmTryPhotoDatum\(\);/.test(admin),
    'the move onto the road is the moment the photograph becomes readable');
  check('S143', 'it stops once the photograph has answered',
    !!tryFn && /if\(rmDatumSource === 'photo'\) return;/.test(tryFn),
    're-reading a settled answer would fetch a photo on every camera nudge');
  check('S143', 'and it gives up rather than retrying all afternoon',
    !!tryFn && /rmPhotoDatumTries >= RM_PHOTO_DATUM_TRIES/.test(tryFn) &&
    /const RM_PHOTO_DATUM_TRIES = \d+;/.test(admin),
    'a house Google photographed badly would otherwise be retried forever');
  check('S143', 'two reads never overlap',
    !!tryFn && /rmPhotoDatumBusy/.test(tryFn),
    'a second fetch starting mid-flight would race the first one to set the datum');
  check('S143', 'a thrown fetch releases the latch instead of jamming it',
    !!tryFn && /catch\(function\(\)\{ rmPhotoDatumBusy = false; \}\)/.test(tryFn),
    'a network error would otherwise leave it permanently busy and never retry');
  check('S143', 'and every counter is reset per house',
    /rmGuessedCount = 0; rmPhotoDatumTries = 0; rmPhotoDatumBusy = false;/.test(admin),
    'the second address of the day would start with the first one used up');
}


suite('144. Measure Roof - the peaks are offered too, and only once each');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "it doesnt seem to be drawing a line along every single ridge on the
     front side, make sure that gets fixed." Only the downhill edge of each roof
     face was ever suggested, so every peak on the house had to be traced by
     hand - and the whole point of this tool is picking lines, not drawing them. */
  const NEED = ['rmMetresPerDeg', 'rmToLocal', 'rmToWorld', 'rmFaceEdgePick', 'rmFaceEdgeLine',
                'rmFaceRidge', 'rmFaceEave'];
  const missing = NEED.filter(n => !pick(n));
  if (missing.length) {
    check('S144', 'the line builders are findable', false, 'missing: ' + missing.join(', '));
  } else {
    const api = new Function(
      'let rmOrigin={lat:40.2969,lng:-111.6946};' + LF_ +
      NEED.map(pick).join(LF_) + LF_ +
      'return {rmFaceRidge, rmFaceEave, rmToLocal};')();
    /* A face sloping down to the south: its gutter is the south edge and its
       ridge is the north one. */
    const mid = api.rmToLocal ? null : null;
    const toW = new Function('let rmOrigin={lat:40.2969,lng:-111.6946};' + LF_ +
      pick('rmMetresPerDeg') + LF_ + pick('rmToLocal') + LF_ + pick('rmToWorld') + LF_ +
      'return rmToWorld;')();
    const sw = toW({e: -5, n: -4, u: 0}), ne = toW({e: 5, n: 4, u: 0});
    const face = {sw: {lat: sw.lat, lng: sw.lng}, ne: {lat: ne.lat, lng: ne.lng},
                  azimuth: 180, pitch: 26, areaSqFt: 0};
    const eave = api.rmFaceEave(face);
    const ridge = api.rmFaceRidge(face);
    check('S144', 'a roof face now offers a peak as well as a gutter',
      !!eave && !!ridge, 'eave ' + (eave ? 'ok' : 'missing') + ', ridge ' + (ridge ? 'ok' : 'missing'));
    if (eave && ridge) {
      const el = api.rmToLocal((eave.a.lat + eave.b.lat) / 2, (eave.a.lng + eave.b.lng) / 2, 0);
      const rl = api.rmToLocal((ridge.a.lat + ridge.b.lat) / 2, (ridge.a.lng + ridge.b.lng) / 2, 0);
      check('S144', 'and they are opposite edges, not the same line twice',
        Math.hypot(el.e - rl.e, el.n - rl.n) > 5,
        'gutter and peak came out ' + Math.hypot(el.e - rl.e, el.n - rl.n).toFixed(1) + ' m apart');
      /* ⚠ The gutter is the DOWNHILL edge. This face slopes south (azimuth 180),
         so the gutter must be the south side and the peak the north one - the
         other way round puts every light on the wrong edge of the roof. */
      check('S144', 'the gutter is downhill and the peak is uphill, not the reverse',
        el.n < rl.n,
        'gutter at n=' + el.n.toFixed(1) + ', peak at n=' + rl.n.toFixed(1) + ' on a south-facing roof');
      check('S144', 'each is labelled with what it is',
        eave.kind === 'perimeter' && ridge.kind === 'ridge',
        'got ' + eave.kind + ' and ' + ridge.kind);
      const rakes = new Function('let rmOrigin={lat:40.2969,lng:-111.6946};' + LF_ +
        ['rmMetresPerDeg','rmToLocal','rmToWorld','rmFaceEdgePick','rmFaceEdgeLine','rmFaceRakes']
          .map(pick).join(LF_) + LF_ + 'return rmFaceRakes;')()(face);
      check('S144', 'a face offers TWO sloping edges - a dormer has two sides',
        rakes.length === 2, 'got ' + rakes.length);
      check('S144', 'and both are perimeter, because lights really do run up them',
        rakes.every(function(x){ return x.kind === 'perimeter'; }),
        'got ' + rakes.map(function(x){ return x.kind; }).join(', '));
    }
  }

  /* ---- what is offered, and what deliberately is not ------------------ */
  const build = pick('rmBuildSuggestions');
  /* ⚠ THE PEAK IS NOT A RUN. Owner, seeing the blue line along the top of the
     roof: "we dont do ridges, sorry that blue line on top of the peak we dont
     do." rmFaceRidge still EXISTS and must - the height solver cannot find a
     gutter in a photograph except paired with its own peak - but nothing puts
     lights along it. */
  check('S144', 'the peak is never offered as a run',
    !!build && !/addLine\(face, rmFaceRidge\(face\)\)/.test(build),
    'lights do not go along a ridge, and a line nobody will hang is work to switch off');
  check('S144', 'but the peak is still worked out, because the height needs it',
    !!pick('rmFaceRidge') && !!pick('rmFaceRidgeMid') &&
    /rmFaceRidgeMid\(r\.face\)/.test(pick('rmDatumFromStreetPhoto') || ''),
    'removing it would take the pairing with it and the search walks back up to the sky');

  /* ⚠ A DORMER HAS A FRONT AND A DEPTH. Owner: "be sure that with things like
     doorways and doormers it catches the front and the depth." The gutter is
     the front; the two sloping edges either side are the depth. */
  check('S144', 'both sloping edges are offered as well as the gutter',
    !!build && /addLine\(face, rmFaceEave\(face\)\);/.test(build) &&
    /rmFaceRakes\(face\)\.forEach\(function\(rake\)\{ addLine\(face, rake\); \}\);/.test(build),
    'a dormer traced across its front only misses the two edges that give it depth');
  check('S144', 'and they are built by the SAME builder as the gutter',
    !!build && /const addLine = function\(face, line\)/.test(build),
    'two copies of how a suggested line is made is one that quietly falls behind');

  /* ⚠ EVERY kind is deduped, not just peaks. Two faces that meet share the
     edge between them and each names it as one of its own, so an undeduped
     gutter or rake is offered twice - the footage doubles and so does the
     strand count. */
  check('S144', 'an edge two faces share is only offered once, whatever kind it is',
    !!build && /if\(alreadySeen\(line\)\) return;/.test(build) && /ridgesSoFar/.test(build),
    'the seam between two planes belongs to both of them');
  check('S144', 'the dedup matches on position AND length, not position alone',
    !!build && /Math\.abs\(len - o\.len\) < 2/.test(build),
    'two different runs can share a midpoint - a short edge over a porch sits under a long one');
  check('S144', 'a sliver is still not offered, whichever kind it is',
    !!build && /if\(rmRunFeet\(run\) < 6\) return;/.test(build),
    'a two-foot peak is noise on the list, not a run somebody wants');
  check('S144', 'and a peak is sided and defaulted the same way a gutter is',
    !!build && /on: rmFaceFacesTheRoad\(line\)/.test(build) && /side: rmEaveSide\(line\)/.test(build),
    'the front of the house means the front of the house, peaks included');
}


suite('145. Measure Roof - the lines are moved onto the gutters the satellite shows');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "make sure the lines follow the gutters with 0 offset on every and
     any house."
     The roof model cannot do it: it describes each face as a compass-aligned
     BOX, and a real roof is a polygon at whatever angle the house was built.
     The satellite picture can - seen from overhead there is no depth in it, so
     a pixel IS a place, and Web Mercator gives the metres per pixel exactly. */
  const NEED = ['rmSkyMpp', 'rmSkyProject', 'rmSkyUnproject', 'rmCrossGrad', 'rmSnapOffsetM'];
  const missing = NEED.filter(n => !pick(n));
  if (missing.length) {
    check('S145', 'the sky snapper is findable', false, 'missing: ' + missing.join(', '));
  } else {
    const consts = (admin.match(/^const RM_SKY_ZOOM.*?;/gm) || [])
      .concat(admin.match(/^const RM_SNAP_LOOK_M.*?;/gm) || [])
      .concat(admin.match(/^const RM_SNAP_MIN_GRAD.*?;/gm) || [])
      .concat(admin.match(/^const RM_SNAP_KEEP.*?;/gm) || [])
      .concat(admin.match(/^const RM_SNAP_MAX_MOVE_M.*?;/gm) || []);
    check('S145', 'all five snapping thresholds were really found',
      consts.length === 5, 'found ' + consts.length + ' of 5 - a missing one is undefined, not a failure');
    const api = new Function(consts.join(LF_) + LF_ + NEED.map(pick).join(LF_) + LF_ +
      'return {rmSkyMpp, rmSkyProject, rmSkyUnproject, rmCrossGrad, rmSnapOffsetM};')();

    /* ---- 1. a pixel really is a place ------------------------------- */
    const mpp = api.rmSkyMpp(40.3854);
    check('S145', 'the scale is Web Mercator, at this latitude, at this zoom',
      mpp > 0.05 && mpp < 0.07,
      'got ' + mpp.toFixed(4) + ' m per pixel - about 2 inches is right for zoom 20 at scale 2 in Utah');
    /* ⚠ Project and unproject must be exact inverses: every snapped line is a
       pixel measurement turned back into a place on somebody's roof. */
    let worst = 0;
    [{e: 0, n: 0}, {e: 12.5, n: -7.25}, {e: -20, n: 18}].forEach(function(p){
      const q = api.rmSkyProject(p, mpp, 1280, 1280);
      const back = api.rmSkyUnproject(q.x, q.y, mpp, 1280, 1280);
      worst = Math.max(worst, Math.hypot(back.e - p.e, back.n - p.n));
    });
    check('S145', 'a place sent to a pixel and back lands on itself',
      worst < 1e-9, 'worst round trip ' + worst.toExponential(2) + ' m');
    check('S145', 'north is UP in the picture, not down',
      api.rmSkyProject({e: 0, n: 10}, mpp, 1280, 1280).y < 640,
      'a flipped axis mirrors every correction to the wrong side of the roof');

    /* ---- 2. it finds the edge, and moves the line onto it ----------- */
    /* A gutter running east-west, drawn as a hard brightness step, sitting
       0.6 m NORTH of where the roof model thinks it is. */
    const W = 400, H = 400;
    const sky = {w: W, h: H, mpp: mpp, gx: new Float32Array(W*H), gy: new Float32Array(W*H), mag: new Float32Array(W*H)};
    const offsetM = 0.6;
    const edgeRow = Math.round(H/2 - offsetM/mpp);
    for (let x = 0; x < W; x++) { const i = edgeRow*W + x; sky.gy[i] = 200; sky.mag[i] = 200; }
    const a = {e: -6, n: 0}, b = {e: 6, n: 0};
    const off = api.rmSnapOffsetM(a, b, sky);
    check('S145', 'a line beside a gutter is moved onto it',
      off && Math.abs(Math.abs(off.m) - offsetM) < 0.08,
      off ? 'moved ' + off.m.toFixed(3) + ' m, the gutter was ' + offsetM + ' m away' : 'found nothing');
    check('S145', 'and it moves the right WAY, toward the edge, not away',
      off && Math.abs((0 + off.n) - offsetM) < 0.08,
      off ? 'ended up at n=' + (0 + off.n).toFixed(3) + ', gutter is at n=' + offsetM : 'no offset');

    /* ---- 3. only the change ACROSS the line counts ------------------ */
    /* ⚠ A roof is full of texture running ALONG a gutter - tile courses, panel
       seams, the ridge itself. Scoring on total gradient snaps a line onto the
       nearest stripe. Only the component across the line is evidence. */
    const striped = {w: W, h: H, mpp: mpp, gx: new Float32Array(W*H), gy: new Float32Array(W*H), mag: new Float32Array(W*H)};
    for (let x = 0; x < W; x++) { const i = edgeRow*W + x; striped.gy[i] = 200; striped.mag[i] = 200; }
    /* a blazing VERTICAL edge - all gx, no gy - right where the line already is */
    for (let y = 0; y < H; y++) { const i = y*W + 200; striped.gx[i] = 255; striped.mag[i] = 255; }
    const off2 = api.rmSnapOffsetM(a, b, striped);
    check('S145', 'a bright edge running the WRONG way is ignored',
      off2 && Math.abs(Math.abs(off2.m) - offsetM) < 0.08,
      off2 ? 'moved ' + off2.m.toFixed(3) : 'found nothing - the crosswise test threw the real gutter away too');
    check('S145', 'the cross-gradient is what is measured, not the total',
      /sky\.gx\[i\] \* nx \+ sky\.gy\[i\] \* ny/.test(pick('rmCrossGrad') || ''),
      'total gradient snaps a roofline onto whatever is brightest nearby');

    /* ---- 4. it refuses rather than guessing ------------------------- */
    const blank = {w: W, h: H, mpp: mpp, gx: new Float32Array(W*H), gy: new Float32Array(W*H), mag: new Float32Array(W*H)};
    check('S145', 'a blank picture moves nothing',
      api.rmSnapOffsetM(a, b, blank) === null,
      'a line nudged onto noise is worse than one left where the model put it');
    /* An edge much too far away is a DIFFERENT gutter - the next roof along.
       ⚠ TWO SEPARATE REFUSALS, and they must be tested separately. One edge
       sits INSIDE the search but beyond the move limit - only the limit can
       refuse it - and one sits outside the search entirely. The first version
       only had the far one, so the limit was never exercised and a red-check
       deleting it passed. */
    const mkSky = () => ({w: W, h: H, mpp: mpp, gx: new Float32Array(W*H), gy: new Float32Array(W*H), mag: new Float32Array(W*H)});
    const edgeAt = (sky, metres) => {
      const row = Math.round(H/2 - metres/mpp);
      for (let x = 0; x < W; x++) { const i = row*W + x; sky.gy[i] = 200; sky.mag[i] = 200; }
      return sky;
    };
    check('S145', 'an edge the search CAN see but that is too far to move to is refused',
      api.rmSnapOffsetM(a, b, edgeAt(mkSky(), 2.2)) === null,
      'two metres is the next roof along, and yanking a line that far is worse than leaving it');
    check('S145', 'and an edge outside the search is not reached at all',
      api.rmSnapOffsetM(a, b, edgeAt(mkSky(), 4.0)) === null,
      'four metres away is somebody elses house');
    check('S145', 'the search reaches FURTHER than the move limit, or the limit is dead code',
      (function(){
        const look = Number((admin.match(/const RM_SNAP_LOOK_M = ([\d.]+)/) || [])[1]);
        const cap = Number((admin.match(/const RM_SNAP_MAX_MOVE_M = ([\d.]+)/) || [])[1]);
        return look > cap + 0.3;
      })(),
      'a guard that only fires in a sliver between the two is a guard nobody is testing');
    /* Half a gutter behind a tree, half of it clear: the clear half decides. */
    const treed = {w: W, h: H, mpp: mpp, gx: new Float32Array(W*H), gy: new Float32Array(W*H), mag: new Float32Array(W*H)};
    for (let x = 0; x < W/2; x++) { const i = edgeRow*W + x; treed.gy[i] = 200; treed.mag[i] = 200; }
    const treedOff = api.rmSnapOffsetM(a, b, treed);
    check('S145', 'half a gutter under a tree still answers, or honestly does not',
      treedOff === null || Math.abs(Math.abs(treedOff.m) - offsetM) < 0.12,
      'it may decline - but it must never split the difference with the tree: got ' +
      (treedOff ? treedOff.m.toFixed(3) : 'null'));

    /* ---- 5. the outliers are thrown away, not averaged in ----------- */
    check('S145', 'samples that found something else are discarded, not averaged',
      /Math\.abs\(o - median\) <= 3/.test(pick('rmSnapOffsetM') || ''),
      'a chimney and a gutter averaged together is a line through neither');
    check('S145', 'and the ends of the line are not sampled',
      /0\.12 \+ 0\.76/.test(pick('rmSnapOffsetM') || ''),
      'a corner is where two edges meet, and the other one is the strongest thing there');
  }

  /* ---- 6. what it must never touch ---------------------------------- */
  const snapAll = pick('rmSnapLinesToSky');
  check('S145', 'a line somebody drew or dragged is never moved',
    !!snapAll && /!r\.suggested \|\| r\.touched/.test(snapAll),
    'their work is the last word - moving it is the one unforgivable thing here');
  check('S145', 'heights are re-asked after the lines move',
    !!snapAll && snapAll.indexOf('rmRefreshHeights') > snapAll.indexOf('rmSnapOffsetM'),
    'a height read at the old position is left behind by the correction');
  check('S145', 'sideways first, then height',
    /rmSnapLinesToSky\(\)\.then\([\s\S]{0,400}rmTryPhotoDatum\(\)/.test(admin),
    'reading the height first and moving the line afterwards leaves the height at the old spot');
  check('S145', 'and a failed snap still leaves the height to be read',
    /catch\(function\(\)\{ rmTryPhotoDatum\(\); \}\)/.test(admin),
    'one picture failing must not cost the other');
}


suite('146. Measure Roof - the street view frames the house instead of the street');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "theres to much going on you cant see the house clearly."
     Part of that was the drawing and part was the pane, but the biggest part
     was the LENS. Street View opens at zoom 1 - a ninety degree field of view,
     most of a street - and from the ~29 m the camera usually sits at an
     ordinary house then covers about a seventh of the pane. At that size a
     line ON the gutter and a line a foot off it are the same picture. */
  const fn = pick('rmFrameHouseInStreet');
  const consts = (admin.match(/^const RM_FRAME_FILL.*?;/gm) || [])
    .concat(admin.match(/^const RM_ZOOM_MIN.*?;/gm) || []);
  if (!fn || consts.length !== 2) {
    check('S146', 'the framing is findable', false,
      'rmFrameHouseInStreet or its constants are missing (' + consts.length + ' of 2)');
  } else {
    let setZoomTo = null;
    const api = new Function(
      'const rmDeg = r => r * 180 / Math.PI;' + LF_ +
      consts.join(LF_) + LF_ +
      'let rmOrigin={lat:40.2969,lng:-111.6946}, rmStreetReady=true, rmBuilding=null, __cam=null, __head=0, rmFramed=false;' + LF_ +
      /* Framing now AIMS before it zooms, so the pov setter and the height
         helpers it uses to work out the tilt have to be here too. */
      'let rmPano={setZoom:function(z){ __z = z; }, setPov:function(p){ __pov = p; }};' + LF_ +
      'let __pov=null;' + LF_ +
      'function rmDatum(){ return {m: 3, source:"assumed"}; }' + LF_ +
      'function rmHighestRelM(){ return 3; }' + LF_ +
      'let __z=null;' + LF_ +
      'function rmCamOnRoad(){ return __cam; }' + LF_ +
      'function rmPanoPov(){ return {heading: __head, pitch: 0, zoom: 1}; }' + LF_ +
      pick('rmMetresPerDeg') + LF_ + pick('rmToLocal') + LF_ + pick('rmToWorld') + LF_ + fn + LF_ +
      'return {run: rmFrameHouseInStreet,' + LF_ +
      '        setup: function(b, cam, head){ rmBuilding = b; __cam = cam; __head = head; __z = null; rmFramed = false; },' + LF_ +
      '        zoom: function(){ return __z; }, pov: function(){ return __pov; },' + LF_ +
      '        toWorld: rmToWorld};')();

    /* A 14 m wide house, camera 29 m away looking straight at it. */
    const sw = api.toWorld({e: -7, n: -5, u: 0}), ne = api.toWorld({e: 7, n: 5, u: 0});
    const house = {sw: {lat: sw.lat, lng: sw.lng}, ne: {lat: ne.lat, lng: ne.lng}};
    api.setup(house, {e: 0, n: -29, u: 2.5}, 0);
    const far = api.run();
    check('S146', 'a house 29 m away is measured as a real angle, not guessed',
      far && far.houseDeg > 20 && far.houseDeg < 40,
      far ? 'house subtends ' + far.houseDeg + ' deg' : 'framed nothing');
    check('S146', 'and the lens is narrowed until the house fills the frame',
      far && far.fov < 60 && far.zoom > 1.2,
      far ? 'fov ' + far.fov + ' deg at zoom ' + far.zoom + ' - 90 deg is the whole street' : 'no framing');
    /* Tolerance 0.01, not 0.001: the returned figure is rounded to two places
       for reporting while the panorama is given the full one, and comparing
       those at 0.001 fails on a correct answer. */
    /* ⭐ AIM BEFORE ZOOM. The heading was set once, in the callback that found
       the panorama, and Google then moves the camera to the nearest road
       photo - so the pane opened looking down the street with the house out
       of frame, and the zoom obligingly framed the empty road. */
    check('S146', 'the panorama is pointed AT the house, not left where it was',
      api.pov() && Math.abs(api.pov().heading - 0) < 1,
      'camera due south of the house must look due north: got ' +
      (api.pov() ? api.pov().heading.toFixed(1) : 'no pov set'));
    check('S146', 'and tilted up enough to hold the roof rather than the lawn',
      api.pov() && api.pov().pitch > 0 && api.pov().pitch < 28,
      'pitch ' + (api.pov() ? api.pov().pitch.toFixed(1) : 'none'));
    check('S146', 'the zoom is actually applied to the panorama, not just returned',
      api.zoom() !== null && Math.abs(api.zoom() - far.zoom) < 0.01,
      'a computed zoom nobody sets changes nothing on screen (set ' + api.zoom() + ', returned ' + far.zoom + ')');

    /* ⚠ CLOSER MUST MEAN WIDER, not narrower. Getting this backwards frames a
       house you are standing next to as if it were down the road. */
    api.setup(house, {e: 0, n: -12, u: 2.5}, 0);
    const near = api.run();
    check('S146', 'standing closer opens the lens rather than closing it',
      near && near.fov > far.fov && near.zoom < far.zoom,
      'near: fov ' + (near && near.fov) + ' zoom ' + (near && near.zoom) +
      ' vs far: fov ' + far.fov + ' zoom ' + far.zoom);

    /* ⚠ MEASURED ACROSS WHAT THE CAMERA SEES. A house at an angle to the
       compass is wider from the corner than its north/south box suggests, and
       framing on the box crops the ends off. */
    api.setup(house, {e: -25, n: -25, u: 2.5}, 45);
    const corner = api.run();
    check('S146', 'seen from the corner the house is measured across the diagonal',
      corner && corner.houseDeg > far.houseDeg * 0.7,
      'from the corner it subtends ' + (corner && corner.houseDeg) + ' deg');

    /* Nonsense in, nothing out - never frame on a bad measurement. */
    const tiny = api.toWorld({e: -0.05, n: -0.05, u: 0}), tiny2 = api.toWorld({e: 0.05, n: 0.05, u: 0});
    api.setup({sw: {lat: tiny.lat, lng: tiny.lng}, ne: {lat: tiny2.lat, lng: tiny2.lng}}, {e: 0, n: -29, u: 2.5}, 0);
    check('S146', 'a house that subtends almost nothing is left alone',
      api.run() === null && api.zoom() === null,
      'zooming to 3 degrees on a bad footprint shows somebody a brick');
    api.setup(house, null, 0);
    check('S146', 'and with no camera on the road it does not guess',
      api.run() === null);
    api.setup(null, {e: 0, n: -29, u: 2.5}, 0);
    check('S146', 'nor with no footprint',
      api.run() === null);

    /* The bounds are a house, not a range of numbers. */
    const zmax = Number((admin.match(/RM_ZOOM_MAX = ([\d.]+)/) || [])[1]);
    /* ⚠ THE CAP CAME DOWN, and the check has to come with it. At 3.2 the pane
       showed a FIFTEEN DEGREE view - one window, roofline off both edges -
       because fov = 180 / 2^zoom is only an approximation and Google's real
       field of view depends on the container's shape too. Under-zooming is
       the safe direction: a house a little small is readable, a wall is not. */
    check('S146', 'the zoom is capped so it cannot end up inside a brick',
      zmax >= 1.8 && zmax <= 2.6,
      'RM_ZOOM_MAX is ' + zmax + ' - above about 2.4 the view becomes a keyhole on this pane');
  }

  /* Ordering asserted with indexOf rather than a regex spanning a newline: a
     backslash-n does not survive every route into this file, and a degraded
     escape gives a broken regex rather than a failing check. */
  /* ⚠ SCOPED TO THE CAMERA-MOVED LISTENER. rmTryPhotoDatum() is also called
     where the lines are built, which is EARLIER in the file, so an unscoped
     indexOf finds that one and measures the distance to a framing call four
     hundred lines away. Anchor on the comment that marks the listener. */
  check('S146', 'it is retried when the camera reaches the road',
    (function(){
      const a = admin.indexOf('The move onto the road is exactly when');
      if (a === -1) return false;
      /* To the end of the listener, not a magic number of characters - the
         suite has its own check against fixed windows, and it is right: they
         go stale silently as the code between them grows. */
      const end = admin.indexOf('});', a);
      if (end === -1) return false;
      const near = admin.slice(a, end);
      return /rmTryPhotoDatum\(\);/.test(near) && /rmFrameHouseInStreet\(\);/.test(near);
    })(),
    'the camera is still at the house when the lines are built, so the first try has nothing to measure from');
  check('S146', 'but it frames only ONCE per house',
    /if\(rmFramed\) return null;/.test(admin) && /rmFramed = true;/.test(admin) && /rmFramed = false;/.test(admin),
    'a tool that yanks the zoom back every time the camera nudges cannot be used to check a gutter');
  check('S146', 'framing runs once both the house and the camera are known',
    (function(){
      const a = admin.indexOf('rmGuessedCount = guessed;');
      if (a === -1) return false;
      const end = admin.indexOf('const status = document.getElementById', a);
      return end !== -1 && admin.slice(a, end).indexOf('rmFrameHouseInStreet();') !== -1;
    })(),
    'framed before the footprint lands and there is nothing to frame on');
  check('S146', 'and it keeps trying, because the two halves arrive separately',
    /if\(rmFramed \|\| \+\+frameTries > \d+\)\{ clearInterval\(frameTimer\); return; \}/.test(admin),
    'the camera usually lands BEFORE the roof model, so one attempt at each moment is two misses');
}


suite('147. Measure Roof - only the outside of the house, and all of it');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);
  const world = new Function('let rmOrigin={lat:40.2969,lng:-111.6946};' + LF_ +
    ['rmMetresPerDeg','rmToLocal','rmToWorld'].map(pick).join(LF_) + LF_ +
    'return {toWorld: rmToWorld, toLocal: rmToLocal};')();

  /* ---- 1. a chimney is not a roof face ------------------------------- */
  /* Owner: "be sure to have it detect things like satelites or chimnees and
     know that isnt a spot we are going to hang." Google models a chimney as a
     little plane of its own, the same shape as a real face, just small. */
  const worth = pick('rmFaceIsWorthHanging');
  if (!worth) {
    check('S147', 'the chimney test is findable', false, 'rmFaceIsWorthHanging missing');
  } else {
    const api = new Function((admin.match(/^const RM_MIN_FACE_SQFT.*?;/m) || [''])[0] + LF_ +
      worth + LF_ + 'return rmFaceIsWorthHanging;')();
    check('S147', 'a chimney-sized plane is not offered', api({areaSqFt: 5}) === false);
    check('S147', 'nor a satellite dish mount', api({areaSqFt: 2}) === false);
    /* ⚠ THE THRESHOLD MUST CLEAR A DORMER. A dormer is small and we very much
       do want it - setting this by eye at "small = skip" throws away exactly
       the faces the owner asked to have caught. */
    check('S147', 'but the smallest dormer worth hanging still is',
      api({areaSqFt: 32}) === true,
      'a couple of metres across is a dormer, not a chimney');
    check('S147', 'and an unknown area is never a reason to throw a face away',
      api({}) === true && api({areaSqFt: 0}) === true,
      'most of the roof would go with it');
  }

  /* ---- 2. only the outside ------------------------------------------- */
  /* Owner: "make sure its only doing the perimeter because theres some lines
     im noticing that are just on the house but on no perimeter." Where two
     planes meet, each names the shared edge as one of its own. */
  const outside = pick('rmEdgeIsOnTheOutside');
  if (!outside) {
    check('S147', 'the outside test is findable', false, 'rmEdgeIsOnTheOutside missing');
  } else {
    const api = new Function('let rmOrigin={lat:40.2969,lng:-111.6946}; let rmFaces=[];' + LF_ +
      (admin.match(/^const RM_OUTSIDE_PROBE_M.*?;/m) || [''])[0] + LF_ +
      ['rmMetresPerDeg','rmToLocal','rmToWorld'].map(pick).join(LF_) + LF_ + outside + LF_ +
      'return rmEdgeIsOnTheOutside;')();
    const mk = (e0, n0, e1, n1) => {
      const sw = world.toWorld({e: e0, n: n0, u: 0}), ne = world.toWorld({e: e1, n: n1, u: 0});
      return {sw: {lat: sw.lat, lng: sw.lng}, ne: {lat: ne.lat, lng: ne.lng},
              center: world.toWorld({e: (e0 + e1) / 2, n: (n0 + n1) / 2, u: 0})};
    };
    /* Two faces meeting along n = 0: west face covers n -6..0, east covers 0..6 */
    const south = mk(-6, -6, 6, 0), north = mk(-6, 0, 6, 6);
    const lineAt = n => ({a: world.toWorld({e: -5, n: n, u: 0}), b: world.toWorld({e: 5, n: n, u: 0})});
    check('S147', 'the seam where two roof planes meet is NOT offered',
      api(south, lineAt(0), [south, north]) === false,
      'a valley across the middle of a roof is real geometry and nothing hangs on it');
    check('S147', 'but the outer edge of the same face is',
      api(south, lineAt(-6), [south, north]) === true,
      'that is the gutter, and dropping it would take the front of the house with it');
    check('S147', 'and with only one face on the roof nothing is judged a seam',
      api(south, lineAt(0), [south]) === true,
      'a simple house has no seams, and refusing its edges leaves nothing at all');
  }

  /* ---- 3. the line reaches the corners -------------------------------- */
  /* Owner: "be sure it does the entire front because I just opened it on
     another house and it doesnt go across the whole house." */
  const reach = pick('rmEndReach');
  const cont = pick('rmEdgeContinues');
  if (!reach || !cont) {
    check('S147', 'the end-reach is findable', false, 'rmEndReach or rmEdgeContinues missing');
  } else {
    const consts = ['RM_END_STEP_M', 'RM_END_MAX_GROW_M', 'RM_END_MAX_TRIM_M', 'RM_SNAP_MIN_GRAD', 'RM_SKY_ZOOM']
      .map(n => (admin.match(new RegExp('^const ' + n + '.*?;', 'm')) || [''])[0]);
    check('S147', 'every end-reach threshold was found in the page',
      consts.every(Boolean), 'missing: ' + consts.map((c, i) => c ? '' : i).filter(String).join(','));
    /* rmEndReach now asks the footprint whether a point is still on the house,
       so both of those come in too - and rmBuilding stays null here, which is
       the "no footprint known" case the guard has to tolerate. */
    const api = new Function('let rmOrigin={lat:40.2969,lng:-111.6946}; let rmBuilding=null;' + LF_ +
      consts.join(LF_) + LF_ +
      (admin.match(/^const RM_STAY_ON_HOUSE_M.*?;/m) || [''])[0] + LF_ +
      ['rmMetresPerDeg','rmToLocal','rmToWorld','rmSkyMpp','rmSkyProject','rmCrossGrad',
       'rmFootprintBox','rmInsideFootprint'].map(pick).join(LF_) + LF_ +
      cont + LF_ + reach + LF_ + 'return {rmEndReach, rmSkyMpp};')();
    const mpp = api.rmSkyMpp(40.2969), W = 400, H = 400;
    const sky = {w: W, h: H, mpp: mpp, gx: new Float32Array(W*H), gy: new Float32Array(W*H), mag: new Float32Array(W*H)};
    /* A gutter running east-west across the middle, 12 m long: from e=-6 to +6. */
    const row = H / 2;
    const pxPerM = 1 / mpp;
    for (let e = -6; e <= 6; e += 0.02) {
      const x = Math.round(W / 2 + e * pxPerM);
      if (x >= 0 && x < W) { const i = Math.round(row) * W + x; sky.gy[i] = 200; sky.mag[i] = 200; }
    }
    /* The model only found the middle 6 m of it. */
    const a = {e: -3, n: 0}, b = {e: 3, n: 0};
    const growB = api.rmEndReach(a, b, sky, +1);
    const growA = api.rmEndReach(a, b, sky, -1);
    check('S147', 'a line that stops short is grown out to the real corner',
      growB > 2.4 && growB < 3.6 && growA > 2.4 && growA < 3.6,
      'grew ' + growA.toFixed(2) + ' and ' + growB.toFixed(2) + ' m, the gutter runs 3 m past each end');
    /* ⭐ AND IT MAY NEVER LEAVE THE BUILDING. On the test house a line grew
       along the FENCE - in a satellite picture a fence is a long straight
       bright-to-dark edge running the same way as a gutter, which is exactly
       what the edge test looks for. The result was one line across the whole
       front, sloping, ending over the lawn. No threshold fixes that; the
       footprint does. */
    const fpApi = new Function('let rmOrigin={lat:40.2969,lng:-111.6946}; let rmBuilding=null;' + LF_ +
      (admin.match(/^const RM_STAY_ON_HOUSE_M.*?;/m) || [''])[0] + LF_ +
      ['rmMetresPerDeg','rmToLocal','rmToWorld','rmFootprintBox','rmInsideFootprint'].map(pick).join(LF_) + LF_ +
      'return {set:function(b){rmBuilding=b;}, box:rmFootprintBox, inside:rmInsideFootprint};')();
    const c1 = world.toWorld({e: -6, n: -4, u: 0}), c2 = world.toWorld({e: 6, n: 4, u: 0});
    fpApi.set({sw: {lat: c1.lat, lng: c1.lng}, ne: {lat: c2.lat, lng: c2.lng}});
    const fbox = fpApi.box();
    check('S147', 'a point on the roof is inside the footprint',
      fpApi.inside({e: 0, n: 0}, fbox) === true);
    check('S147', 'a point out on the fence is not',
      fpApi.inside({e: -12, n: 0}, fbox) === false,
      'this is the guard that stops a line growing along a fence');
    check('S147', 'but the eaves overhang a little and are still allowed',
      fpApi.inside({e: -6.4, n: 0}, fbox) === true,
      'a gutter hangs past the wall it is fixed to');
    check('S147', 'growing a line stops at the footprint, whatever the picture shows',
      /if\(box && !rmInsideFootprint\(pt, box\)\) break;/.test(pick('rmEndReach') || ''),
      'a fence is a perfect straight edge and will win every time otherwise');
    check('S147', 'and sliding one sideways is clamped the same way',
      /!rmInsideFootprint\(\{e: a\.e \+ off\.e/.test(pick('rmSnapLinesToSky') || ''),
      'two metres sideways is enough to land a gutter on a driveway edge');

    /* ⚠ It must not invent gutter where there is none. */
    const bare = {w: W, h: H, mpp: mpp, gx: new Float32Array(W*H), gy: new Float32Array(W*H), mag: new Float32Array(W*H)};
    check('S147', 'and never grows a line into a blank picture',
      api.rmEndReach(a, b, bare, +1) <= 0,
      'a line grown onto nothing is a made-up measurement somebody will be billed for');
    /* A line already reaching the full edge is left alone. */
    const full = api.rmEndReach({e: -6, n: 0}, {e: 6, n: 0}, sky, +1);
    check('S147', 'a line already at the corner is not stretched further',
      full <= 0.3,
      'grew ' + full.toFixed(2) + ' m past an edge that has already ended');
  }

  /* ---- 4. hidden means hidden ---------------------------------------- */
  /* Owner: "make sure that if the house is in the way on the street view you
     cant see the line because you cant tell what it goes to anyway." */
  const box = pick('rmBoxEntry');
  if (!box) {
    check('S147', 'the occlusion test is findable', false, 'rmBoxEntry missing');
  } else {
    const api = new Function(box + LF_ + 'return rmBoxEntry;')();
    const house = {minE: -5, maxE: 5, minN: -4, maxN: 4, minU: 0, maxU: 6};
    const cam = {e: 0, n: -25, u: 2.5};
    const behind = {e: 0, n: 6, u: 3};      /* the far gutter */
    const infront = {e: 0, n: -5, u: 3};    /* the near gutter */
    const t = api(cam, behind, house);
    check('S147', 'a line behind the house is found to be behind it',
      t !== null && t > 0 && t < 1,
      'entry fraction ' + t);
    check('S147', 'and one in front of it is not',
      (function(){ const q = api(cam, infront, house); return q === null || q >= 0.995; })(),
      'hiding the near gutter would hide the whole job');
    check('S147', 'a ray that misses the house entirely enters nothing',
      api(cam, {e: 40, n: 0, u: 3}, house) === null);
    check('S147', 'the box is pulled in so a gutter does not hide behind its own wall',
      /const RM_OCCLUDE_SHRINK_M/.test(admin) && /rmHouseBox/.test(admin),
      'a box that reaches the surface reports every line on it as occluded');
    check('S147', 'and the run is judged at its middle, not an end',
      /Judged at the MIDDLE of the run/.test(admin),
      'half a hidden line is exactly the line that cannot be read');
  }
}


suite('148. Measure Roof - the skyline is the roofline, and its corners are the corners');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "make it have a corner detector, so its looking for corners from
     street view and then it just connects them."
     Where a roof meets the sky is the highest-contrast boundary in any photo
     of a house, and its vertices ARE the corners - the peak of every gable,
     the end of every eave. Far more reliable than hunting corners in a picture
     full of windows and shrubs. */
  const NEED = ['rmSkylineRows', 'rmFillSpikes', 'rmSimplifyLine', 'rmCornersInPhoto'];
  const missing = NEED.filter(n => !pick(n));
  const consts = ['RM_SKY_DROP', 'RM_SKY_CONFIRM_ROWS', 'RM_SPIKE_MAX_W_M', 'RM_CORNER_TOL_PX',
                  'RM_CORNER_MIN_TURN', 'RM_CORNER_MIN_GAP_PX', 'RM_CORNER_MAX']
    .map(n => (admin.match(new RegExp('^const ' + n + '.*?;', 'm')) || [''])[0]);
  check('S148', 'every skyline threshold was really found in the page',
    consts.every(Boolean), 'missing one of the constants');
  if (missing.length || !consts.every(Boolean)) {
    check('S148', 'the corner detector is findable', false, 'missing: ' + missing.join(', '));
  } else {
    const api = new Function(consts.join(LF_) + LF_ + NEED.map(pick).join(LF_) + LF_ +
      'return {rmSkylineRows, rmFillSpikes, rmSimplifyLine, rmCornersInPhoto};')();

    /* A photograph: bright sky above a dark roof. The roof profile is a gable -
       up from the left eave to a peak, down to the right eave. */
    const W = 240, H = 160;
    const mk = profile => {
      const lum = new Float32Array(W * H);
      for (let x = 0; x < W; x++) {
        const top = profile(x);
        for (let y = 0; y < H; y++) lum[y * W + x] = (y < top) ? 200 : 90;   /* sky : roof */
      }
      return {w: W, h: H, lum: lum};
    };
    const gable = x => (x < 120 ? 100 - Math.round(x * 0.4) : 52 + Math.round((x - 120) * 0.4));

    const rows = api.rmSkylineRows(mk(gable));
    check('S148', 'the sky/roof boundary is found in every column',
      rows.filter(r => r !== null).length > W * 0.95,
      'found the skyline in ' + rows.filter(r => r !== null).length + ' of ' + W + ' columns');
    check('S148', 'and it follows the roof, not the top of the picture',
      rows[10] !== null && Math.abs(rows[10] - gable(10)) <= 1 &&
      Math.abs(rows[120] - gable(120)) <= 1,
      'at x=10 got ' + rows[10] + ' want ' + gable(10) + '; at the peak got ' +
      rows[120] + ' want ' + gable(120));

    const found = api.rmCornersInPhoto(mk(gable), 0.05);
    /* ⚠ A ROOF CORNER TURNS SHARPLY. Douglas-Peucker keeps a point when the
       line strays far enough from straight, which is NOT the same as turning
       there - so a gentle sag over twenty pixels scored as high as a gable
       peak, and a real house came back with forty corners. */
    check('S148', 'a gentle sag is not a corner',
      (function(){
        const sag = x => 60 + Math.round(6 * Math.sin(x / W * Math.PI));
        return api.rmCornersInPhoto(mk(sag), 0.05).corners.length <= 3;
      })(),
      'a roofline that merely bows must not be chopped into pieces');
    check('S148', 'a plain gable comes back as three corners: eave, peak, eave',
      found.corners.length === 3,
      'got ' + found.corners.length + ' - ' + JSON.stringify(found.corners.map(c => [c.x, Math.round(c.y)])));
    check('S148', 'and the middle one is the peak, at the top of the roof',
      found.corners.length === 3 && Math.abs(found.corners[1].x - 120) < 4 &&
      found.corners[1].y < found.corners[0].y && found.corners[1].y < found.corners[2].y,
      JSON.stringify(found.corners.map(c => [c.x, Math.round(c.y)])));

    /* ---- chimneys ---------------------------------------------------- */
    /* ⚠ Owner: "be sure to not catch satelites and chineys in a corner
       detector." A chimney breaks the skyline as a NARROW spike where a real
       feature is measured in yards. Width is a property of the thing itself,
       not a threshold chosen to suit one house. */
    /* ⚠ FLAT-TOPPED ON PURPOSE. The first version sloped its top along with the
       roof, so the walk that measures a spike's width broke after a few pixels
       and the WIDTH rule never got to decide anything - a red-check deleting
       that rule entirely went unnoticed. A chimney really does have a flat top
       against the sky, and it is the width that has to do the work. */
    const withChimney = x => (x >= 60 && x < 72) ? gable(60) - 18 : gable(x);
    const dirty = api.rmCornersInPhoto(mk(withChimney), 0.05);
    check('S148', 'a chimney is not mistaken for a corner',
      dirty.spikesRemoved >= 1 && dirty.corners.length === 3,
      'got ' + dirty.corners.length + ' corners and removed ' + dirty.spikesRemoved +
      ' spikes - a chimney would otherwise add two');
    /* ⚠ AND A STEP BETWEEN TWO ROOF LEVELS IS A CORNER, NOT A CHIMNEY. A house
       where one roof meets a taller one steps UP and stays up - it has one
       shoulder, where a chimney has two. At the first threshold this fired on
       every such step and one real house reported EIGHTY-FOUR chimneys, which
       is not a report anybody can act on and was smoothing away real corners
       into the bargain. */
    const stepUp = x => (x >= 130) ? 40 : gable(x);
    const stepped = api.rmCornersInPhoto(mk(stepUp), 0.05);
    check('S148', 'a step up to a taller roof is kept, not filled in as a chimney',
      stepped.spikesRemoved === 0 && stepped.corners.length >= 3,
      'removed ' + stepped.spikesRemoved + ' spikes from a roofline that has none');

    /* ⚠ AND A DORMER MUST SURVIVE. This is the same shape, only wider - if the
       spike rule is set by height rather than width it takes the dormer too,
       and dormers are exactly what the owner asked to catch. */
    /* ⚠ IT HAS TO STICK UP ABOVE THE ROOF ON BOTH SIDES, or the guard that
       asks "does this rise out of the roofline" rejects it before the WIDTH
       rule is ever consulted - and then deleting the width rule changes
       nothing and the red-check passes over it. The first version sat below
       the right-hand shoulder because the gable climbs that way. */
    const withDormer = x => (x >= 30 && x < 85) ? 40 : gable(x);
    const dormer = api.rmCornersInPhoto(mk(withDormer), 0.05);
    check('S148', 'but a dormer is kept, being wider than a chimney',
      dormer.corners.length > 3,
      'got ' + dormer.corners.length + ' corners, removed ' + dormer.spikesRemoved +
      ' - a dormer is a corner, a chimney is not');

    /* ---- a tree, and a bird ------------------------------------------ */
    /* A tree covering the middle splits the skyline. Joining across the gap
       would invent a corner inside the tree. */
    const treed = mk(gable);
    for (let x = 100; x < 140; x++) for (let y = 0; y < H; y++) treed.lum[y * W + x] = 70;
    const split = api.rmCornersInPhoto(treed, 0.05);
    check('S148', 'a tree splits the roofline rather than being joined across',
      split.runs === 2,
      'got ' + split.runs + ' runs - one run would draw a corner inside the tree');
    /* ⚠ THE SKY IS READ FROM SEVERAL ROWS, not one. A branch or a wire across
       the very top of the frame makes row zero dark, and a single-row reading
       then thinks there is no sky in that column at all - so the roofline is
       lost exactly where something is in front of it. */
    const branchy = mk(gable);
    for (let x = 30; x < 90; x++) branchy.lum[0 * W + x] = 55;
    const bRows = api.rmSkylineRows(branchy);
    check('S148', 'a branch across the top of the frame does not blind it',
      bRows[50] !== null && Math.abs(bRows[50] - gable(50)) <= 1,
      'column 50 came back ' + bRows[50] + ', the roof is at ' + gable(50));

    /* A single dark row is a wire or a bird, not a roof. */
    const wired = mk(gable);
    for (let x = 0; x < W; x++) wired.lum[20 * W + x] = 80;
    const wire = api.rmSkylineRows(wired);
    check('S148', 'a wire across the sky is not read as the roofline',
      wire[10] !== null && wire[10] > 25,
      'the skyline was found at row ' + wire[10] + ', the wire is at 20');

    /* ---- the simplifier ---------------------------------------------- */
    const straight = [];
    for (let i = 0; i <= 20; i++) straight.push({x: i * 5, y: 50 + i * 0.05});
    check('S148', 'a straight run keeps only its two ends',
      api.rmSimplifyLine(straight, 2.5).length === 2,
      'a corner every few pixels is not a roofline, it is noise');
  }
}


suite('149. Measure Roof - corners are named, picked, added and reordered');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "it should just have a corner detector and not assume which ones you
     want just assign a number (or letter if 0-9 runs out) where you toggle a
     corner on or off, and also have a way to add a corner", "space bar toggles
     select from make a dot", and "hold shift click the number you want and
     pick the one you want to switch it with". */
  const NEED = ['rmCornerLabel', 'rmCornerAt', 'rmSwapCorners', 'rmToggleCorner',
                'rmAddCorner', 'rmCornersToRun'];
  const missing = NEED.filter(n => !pick(n));
  if (missing.length) {
    check('S149', 'the corner controls are findable', false, 'missing: ' + missing.join(', '));
  } else {
    const api = new Function(
      "const RM_LABELS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';" + LF_ +
      'let rmCorners = [], rmRuns = [], rmCurrentBand = 0;' + LF_ +
      'function rmDatum(){ return {m: 3, source:"assumed"}; }' + LF_ +
      'function rmSyncSky(){}' + LF_ +
      'function rmCornersChanged(){ rmCornersToRun(); }' + LF_ +
      'function rmRenderResults(){}' + LF_ + 'function rmPaintStreet(){}' + LF_ +
      'function rmRenderCornerBar(){}' + LF_ +
      NEED.map(pick).join(LF_) + LF_ +
      'return {L: rmCornerLabel, at: rmCornerAt, swap: rmSwapCorners, toggle: rmToggleCorner,' + LF_ +
      '        add: rmAddCorner, run: function(){ return rmRuns.filter(function(r){return r.fromCorners;})[0]; },' + LF_ +
      '        set: function(c){ rmCorners = c; rmCornersToRun(); },' + LF_ +
'        all: function(){ return rmCorners; }};')();

    /* ---- naming ------------------------------------------------------ */
    check('S149', 'the first ten corners are numbers',
      api.L(0) === '0' && api.L(9) === '9');
    /* ⚠ Owner: "or letter if 0-9 runs out". A house with more than ten corners
       is ordinary, so this is the common case, not the edge case. */
    check('S149', 'and then it carries on into letters',
      api.L(10) === 'A' && api.L(35) === 'Z',
      'got ' + api.L(10) + ' and ' + api.L(35));
    check('S149', 'a key finds its own corner, upper or lower case',
      (function(){
        api.set([{on:true},{on:true},{on:true},{on:true},{on:true},{on:true},
                 {on:true},{on:true},{on:true},{on:true},{on:true}]);
        return api.at('0') === 0 && api.at('a') === 10 && api.at('A') === 10;
      })());
    check('S149', 'and a key for a corner that does not exist finds nothing',
      api.at('Z') === -1 && api.at('!') === -1,
      'pressing a stray key must not toggle the last corner in the list');

    /* ---- picking ----------------------------------------------------- */
    const four = () => [
      {lat: 1, lng: 1, h: 4, on: true}, {lat: 1, lng: 2, h: 5, on: true},
      {lat: 1, lng: 3, h: 5, on: true}, {lat: 1, lng: 4, h: 4, on: true}];
    api.set(four());
    api.toggle(1);
    check('S149', 'switching a corner off drops it from the line',
      api.all()[1].on === false && api.run().path.length === 3,
      'the run should join the three that are left');
    api.toggle(1);
    check('S149', 'and switching it back on puts it back where it belongs',
      api.run().path.length === 4 && api.run().path[1].lng === 2,
      'it must return to its own place in the order, not the end');

    /* ---- the order IS the line --------------------------------------- */
    /* ⚠ THIS IS THE ONE THAT MATTERS. Two corners joined in the wrong order run
       the string diagonally across a roof. Swapping has to move the corners,
       not just relabel them, so everything after renumbers itself. */
    api.set(four());
    api.swap(0, 3);
    check('S149', 'swapping two corners reorders the line itself',
      api.run().path[0].lng === 4 && api.run().path[3].lng === 1,
      'got ' + api.run().path.map(p => p.lng).join(',') + ' - the number IS the position');
    check('S149', 'and the labels follow the new order automatically',
      api.L(0) === '0' && api.all()[0].lng === 4,
      'there is nothing else to renumber: the label is worked out from the place');
    const before = api.all().length;
    check('S149', 'a swap with a corner that does not exist changes nothing',
      api.swap(0, 99) === false && api.swap(-1, 0) === false && api.all().length === before);
    check('S149', 'and swapping a corner with itself is not an error either',
      api.swap(2, 2) === false && api.all().length === before);

    /* ---- adding ------------------------------------------------------ */
    api.set(four());
    api.add({lat: 9, lng: 9, h: 6});
    check('S149', 'a corner placed by hand joins the end of the line',
      api.all().length === 5 && api.all()[4].lat === 9 && api.all()[4].on === true,
      'a new dot should be in the line straight away, not waiting to be switched on');
    check('S149', 'and it is marked as placed by hand',
      api.all()[4].byHand === true,
      'so the detector re-running cannot silently throw away somebody work');
    check('S149', 'a corner with nowhere to go is refused rather than guessed',
      api.add(null) === false);

    /* ---- fewer than two ---------------------------------------------- */
    api.set([{lat:1,lng:1,h:4,on:true}]);
    check('S149', 'one corner on its own draws no line',
      !api.run(), 'a line needs two ends');
  }

    /* ---- strands, and taking a dot back ------------------------------ */
    /* Owner: "also give me a way to end the strand", and "make backspace
       delete a dot". The top of a house and the bottom are separate runs of
       string, so a dot has to be able to say which run it belongs to. */
    const strandApi = new Function(
      "const RM_LABELS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';" + LF_ +
      'let rmCorners = [], rmRuns = [], rmCurrentBand = 0;' + LF_ +
      'function rmDatum(){ return {m: 3, source:"assumed"}; }' + LF_ +
      'function rmSyncSky(){}' + LF_ + 'function rmRenderResults(){}' + LF_ +
      'function rmPaintStreet(){}' + LF_ + 'function rmRenderCornerBar(){}' + LF_ +
      'function rmCornersChanged(){ rmCornersToRun(); }' + LF_ +
      'const document = {getElementById: function(){ return null; }};' + LF_ +
      ['rmCornerLabel','rmAddCorner','rmEndStrand','rmDeleteLastCorner','rmCornersToRun']
        .map(pick).join(LF_) + LF_ +
      'return {add: rmAddCorner, end: rmEndStrand, del: rmDeleteLastCorner,' + LF_ +
      '        all: function(){ return rmCorners; }, runs: function(){ return rmRuns; }};')();
    strandApi.add({lat: 1, lng: 1, h: 4});
    strandApi.add({lat: 1, lng: 2, h: 4});
    check('S149', 'dots start out on the first strand',
      strandApi.all().every(function(c){ return c.band === 0; }));
    check('S149', 'ending a strand starts the next dot on a new one',
      strandApi.end() === true && (strandApi.add({lat: 2, lng: 1, h: 8}), strandApi.all()[2].band === 1),
      'the top of the house and the bottom are not one continuous line');
    strandApi.add({lat: 2, lng: 2, h: 8});
    check('S149', 'and each strand becomes its own run',
      strandApi.runs().filter(function(r){ return r.fromCorners; }).length === 2,
      'got ' + strandApi.runs().length + ' runs from two strands');
    /* ⚠ An empty strand is not a strand - pressing end twice must not leave a
       gap in the numbering that nothing will ever fill. */
    check('S149', 'ending twice in a row does nothing the second time',
      strandApi.end() === true && strandApi.end() === false);
    const had = strandApi.all().length;
    check('S149', 'backspace takes the last dot back off',
      strandApi.del() === true && strandApi.all().length === had - 1);

  /* ---- the controls exist on screen -------------------------------- */
  check('S149', 'space swaps picking for placing',
    /rmCornerMode = rmCornerMode === 'dot' \? 'select' : 'dot';/.test(admin),
    'owner asked for space bar to toggle select from make a dot');
  check('S149', 'a click on the panorama places a corner while in dot mode',
    /if\(rmCornerMode === 'dot'\)\{/.test(admin) && /rmAddCorner\(\{lat: w\.lat/.test(admin),
    'the dormer corners that meet the main roof are not against the sky and can only be placed by hand');
  check('S149', 'the panorama accepts clicks while placing, or nothing lands',
    /rmCornerMode === 'dot'\) && rmStreetReady/.test(admin),
    'the panorama swallows clicks for panning unless the sheet is over it');
  check('S149', 'shift starts and finishes a swap, from the key or the dot',
    (admin.match(/rmSwapFrom === null/g) || []).length >= 3,
    'the number strip, the keyboard and the dots themselves all offer it');
  check('S149', 'a corner is drawn with its number on, whether it is on or off',
    /data-rmcornerdot/.test(admin) && /rmCornerLabel\(i\)/.test(admin),
    'a corner you cannot see is a corner you cannot pick');
  check('S149', 'and corners are cleared when a new house is loaded',
    /rmCorners = \[\]; rmCornerMode = 'dot'; rmSwapFrom = null;/.test(admin),
    'the next address would otherwise open with the last one roofline on it');
  /* The tool opens READY TO PLACE, because that is now the whole job. */
  check('S149', 'and it opens ready to place a dot, not ready to pick one',
    /let rmCornerMode = 'dot';/.test(admin),
    'nothing is drawn automatically any more, so picking has nothing to pick from');
  /* ⚠ A CONTROL THAT LIES ABOUT ITS OWN STATE IS WORSE THAN NO CONTROL. The
     strip was hidden until the first dot existed, so the line telling somebody
     how to place one was invisible exactly when it was needed - and the label,
     never redrawn, claimed to be PICKING while the tool was placing. */
  check('S149', 'the mode strip is shown before there is anything in it',
    /bar\.style\.display = rmStreetReady \|\| rmSkyReady \? 'block' : 'none';/.test(admin),
    'the instructions were hidden exactly when somebody needed them');
  /* indexOf rather than a regex spanning a newline - the backslash-n does not
     survive every route into this file, and a degraded escape gives a broken
     regex instead of a failing check. */
  check('S149', 'and it is redrawn when the house loads, so the label is true',
    (function(){
      const a = admin.indexOf('rmRenderCornerBar();');
      const b = admin.indexOf("status.textContent = 'Click along the roofline");
      return a !== -1 && b !== -1 && b > a && (b - a) < 60;
    })(),
    'an unrefreshed label says PICKING while the tool is PLACING');
  /* ⭐ TWO BUTTONS, SO THE MODE ONLY GOVERNS ONE. Owner: "make it so right
     click is always select and left click is place dot if thats what its on
     but it switches if you click space." */
  /* ⭐ THE MAP DOES NOT PLACE DOTS AT ALL ANY MORE. Owner: "make sure that you
     use the street view to draw the lines not the sky view", and earlier "its
     using skyview to place corners which is bad it should use street view only
     to detect where corners are... sky view cant give height."

     ⚠ THIS REPLACES A TEST THAT PINNED THE OPPOSITE, and the reason the old
     behaviour could not be rescued is worth writing down. Looking straight
     down there is no height in the picture, so a dot placed from above had to
     INVENT one - the typed working height, or the roof model's guess. A dot at
     the wrong height is at the wrong place, and parallax swings it across the
     house the moment the camera moves. Making the guess cleverer only makes it
     a better guess. From the street a click is a ray that meets a real wall
     and the height falls out of the geometry, so there is nothing to invent. */
  check('S149', 'the map does not place a corner',
    (function(){
      const i = admin.indexOf("getElementById('rmMapLock').addEventListener('click'");
      const j = admin.indexOf('addEventListener', i + 40);
      return i !== -1 && admin.slice(i, j).indexOf('rmAddCorner') === -1;
    })(),
    'a dot from above has to invent a height, and an invented height drifts');
  check('S149', 'and it says where dots do go, rather than doing nothing',
    /Dots go in from the street view/.test(admin),
    'a click that silently does nothing reads as broken');
  /* The street view still does, and takes its height from the ray. */
  check('S149', 'the street view is what places a corner',
    (function(){
      const i = admin.indexOf("getElementById('rmPanoLock').addEventListener('click'");
      return i !== -1 && admin.indexOf('rmAddCorner(', i) > i;
    })(),
    'that is the only view where a gutter can be told from a chimney');
  check('S149', 'and its height comes from where the ray met the house',
    /rmAddCorner\(\{lat: w\.lat, lng: w\.lng, h: best\.u,/.test(admin),
    'best.u is the crossing, not a number anybody typed');
  /* The map keeps what it is genuinely better at. */
  check('S149', 'the map can still be used to pick a dot',
    (function(){
      const i = admin.indexOf("['rmPanoLock', 'rmMapLock'].forEach");
      return i !== -1 && admin.indexOf('rmToggleCorner', i) > i;
    })(),
    'right-click still toggles one on or off from above');
  check('S149', 'and every dot shows its own height, so a wrong one is visible',
    /Math\.round\(\(c\.h \|\| 0\) \* RM_M_TO_FT\)/.test(admin),
    'the one thing that makes a dot appear to move is invisible until it is said');
  check('S149', 'a click that misses the roof model still places a dot',
    /const wall = rmWallPlane\(\);/.test(admin) && /REFUSING A CLICK IS WORSE/.test(admin),
    'Google roof planes stop at its own boxes, and refusing puts that gap on the office');
  check('S149', 'the right button always selects, whatever the mode',
    /addEventListener\('contextmenu'/.test(admin) && /rmCornerNearPixel/.test(admin),
    'having to change mode just to take one dot out is the friction this removes');
  check('S149', 'and it works over the map as well as the panorama',
    /\['rmPanoLock', 'rmMapLock'\]\.forEach/.test(admin));
  /* ⭐ ARROW KEYS FOR ANOTHER ANGLE. Owner: "I cant place dot from multiple
     angles make it so I can use my arrow keys to do that." */
  /* ⚠ THE ARROWS MOVE, THEY DO NOT TURN. This check used to assert the
     opposite. Owner: "the arrow keys are making me turn, I want the arrow keys
     to make me move right and left." Turning only changes what is in frame,
     and the frame is already aimed at the house - what somebody needs when a
     corner is behind a tree is to stand somewhere else. */
  check('S149', 'left and right WALK ALONG the street rather than turning',
    /k === 'ArrowLeft' \? -90 : k === 'ArrowRight' \? 90/.test(admin) &&
    /rmPano\.setPano\(best\.pano\)/.test(admin),
    'turning changes what is in frame; only moving changes what is behind what');
  check('S149', 'and the view is re-aimed at the house after every step',
    /addListenerOnce\(rmPano, 'position_changed'[\s\S]{0,300}rmHeadingTo\(pos\.lat\(\)/.test(admin),
    'moving without turning back leaves the house off the frame within two presses');
  check('S149', 'a step that is not really in that direction is refused',
    /if\(!best \|\| bd > 70\) return;/.test(admin),
    'the nearest link to "left" on a dead-end street is the one straight ahead');
  check('S149', 'there is a button to end a strand as well as a key',
    /id="rmEndStrandBtn"/.test(admin) && /rmEndStrandBtn'\)\.addEventListener/.test(admin),
    'not everybody reaches for a keyboard');
  check('S149', 'the map takes dots as well as the street view',
    /rmCornerMode === 'dot' && !rmDrawing/.test(admin) && /const skyLock = \(rmDrawing \|\| rmCornerMode === 'dot'\)/.test(admin),
    'from above a click is exact; from the street the height is what you can see');
}


suite('150. Measure Roof - a corner is placed from the street, by two views agreeing');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "its using skyview to place corners which is bad it should use
     street view only to detect where corners are", and "you need depth,
     height, and length to find the actual size of a line and sky view cant
     give height."
     One photograph cannot give depth. Two can: the same corner seen from two
     places gives two rays that cross where it is. Nothing from above is
     involved - which is the whole point. */
  const NEED = ['rmRayClosest', 'rmTriangulateCorners', 'rmPhotoRay', 'rmBasis'];
  const missing = NEED.filter(n => !pick(n));
  const consts = ['RM_TRI_MAX_GAP_M', 'RM_TRI_MIN_BASE_M', 'RM_TRI_MERGE_M']
    .map(n => (admin.match(new RegExp('^const ' + n + '.*?;', 'm')) || [''])[0]);
  check('S150', 'every triangulation threshold was really found',
    consts.every(Boolean), 'missing one of the constants');
  if (missing.length || !consts.every(Boolean)) {
    check('S150', 'the triangulation is findable', false, 'missing: ' + missing.join(', '));
  } else {
    const api = new Function('const rmRad = d => d*Math.PI/180;' + LF_ +
      consts.join(LF_) + LF_ + ['rmBasis','rmPhotoRay','rmRayClosest'].map(pick).join(LF_) + LF_ +
      'return {closest: rmRayClosest, ray: rmPhotoRay};')();

    /* ---- two rays that cross ----------------------------------------- */
    const target = {e: 2, n: 4, u: 6};
    const camA = {e: -12, n: -20, u: 2.5};
    const camB = {e: 12, n: -20, u: 2.5};
    const unit = (c, t) => { const d = {e: t.e-c.e, n: t.n-c.n, u: t.u-c.u};
      const l = Math.hypot(d.e,d.n,d.u); return {e:d.e/l, n:d.n/l, u:d.u/l}; };
    const meet = api.closest(camA, unit(camA, target), camB, unit(camB, target));
    check('S150', 'two rays aimed at one corner meet exactly there',
      meet && Math.hypot(meet.pt.e-target.e, meet.pt.n-target.n, meet.pt.u-target.u) < 0.01 && meet.gap < 0.01,
      meet ? 'landed ' + Math.hypot(meet.pt.e-target.e, meet.pt.n-target.n, meet.pt.u-target.u).toFixed(3) +
             ' m out with a gap of ' + meet.gap.toFixed(3) : 'no crossing found');
    /* ⚠ THE GAP IS THE EVIDENCE. Two rays in space almost never come within a
       few centimetres by accident, which is what lets corners be matched
       between views without describing them at all. */
    const other = {e: -6, n: 9, u: 3};
    const wrong = api.closest(camA, unit(camA, target), camB, unit(camB, other));
    check('S150', 'rays aimed at DIFFERENT corners do not pretend to meet',
      !wrong || wrong.gap > 0.45,
      'gap came out ' + (wrong ? wrong.gap.toFixed(2) : 'null') + ' m - if that is small, ' +
      'every corner matches every other and the whole method collapses');
    check('S150', 'a ray pointing away from the corner is refused',
      api.closest(camA, unit(camA, target), camB, {e:-unit(camB,target).e, n:-unit(camB,target).n, u:-unit(camB,target).u}) === null,
      'a crossing behind the camera is not a crossing');
    check('S150', 'and two parallel rays never cross',
      api.closest(camA, {e:0,n:1,u:0}, camB, {e:0,n:1,u:0}) === null);

    /* ---- height comes out of it, which is the whole point ------------ */
    /* Owner: "sky view cant give height". Two street views can, and this is
       the check that says so - the corner is six metres up and nothing from
       above was consulted. */
    check('S150', 'the HEIGHT of a corner falls out of two street views',
      meet && Math.abs(meet.pt.u - 6) < 0.01,
      'got ' + (meet ? meet.pt.u.toFixed(2) : '?') + ' m, the corner is 6 m up');

    /* ---- a baseline is required -------------------------------------- */
    const triApi = new Function('const rmRad = d => d*Math.PI/180;' + LF_ +
      consts.join(LF_) + LF_ +
      'let rmBuilding = null; let rmOrigin = {lat:40.2969,lng:-111.6946};' + LF_ +
      (admin.match(/^const RM_STAY_ON_HOUSE_M.*?;/m) || [''])[0] + LF_ +
      ['rmMetresPerDeg','rmToLocal','rmToWorld','rmFootprintBox','rmInsideFootprint',
       'rmBasis','rmPhotoRay','rmRayClosest','rmTriangulateCorners'].map(pick).join(LF_) + LF_ +
      'return rmTriangulateCorners;')();
    const mkView = (cam, pts) => {
      const W = 400, H = 400, pose = {heading: 0, pitch: 0, fov: 70};
      const focal = (W/2)/Math.tan(rmRadJs(pose.fov)/2);
      function rmRadJs(d){ return d*Math.PI/180; }
      const corners = pts.map(function(t){
        /* project the target into this view by hand, so the fixture does not
           lean on the very code it is testing */
        const v = {e: t.e-cam.e, n: t.n-cam.n, u: t.u-cam.u};
        const f = v.n, r = v.e, up = v.u;      /* heading 0, pitch 0 */
        return {x: W/2 + focal*r/f, y: H/2 - focal*up/f};
      });
      return {cam: cam, pose: pose, w: W, h: H, corners: corners};
    };
    function rmRadJs(d){ return d*Math.PI/180; }
    const A = mkView(camA, [target]), B = mkView(camB, [target]);
    const got = triApi(A, B);
    check('S150', 'two views agree on the corner and place it correctly',
      got.points.length === 1 &&
      Math.hypot(got.points[0].e-target.e, got.points[0].n-target.n, got.points[0].u-target.u) < 0.05,
      JSON.stringify(got.points));
    /* ⚠ Two views a metre apart cannot judge depth however sharp the corners
       are - the rays are almost the same ray, and a tiny error in either
       throws the crossing metres away. */
    const near = mkView({e: -12.5, n: -20, u: 2.5}, [target]);
    check('S150', 'two views too close together are refused rather than trusted',
      triApi(A, near).points.length === 0,
      'a short baseline turns a pixel of error into metres of depth');
  }

  /* ---- and the placement no longer asks the roof model -------------- */
  const det = pick('rmDetectCornersFromStreet');
  /* ---- the order is a path, not a ranking -------------------------- */
  /* ⚠ Owner, counting them on screen: "you have like 20 lines running deep",
     against the three the house has. Sorting corners left to right sweeps
     ACROSS the house, so consecutive corners jump between the near edge of the
     roof and the far one, and every jump is a line running deep. */
  check('S150', 'corners are chained to the nearest, not sorted across the view',
    !!det && /remaining\.splice\(bj, 1\)/.test(det) && /let bj = 0, bd = Infinity;/.test(det),
    'a roofline is a path somebody walks, not a ranking left to right');
  /* ⭐ AND THE HOUSE IS HUNG AS TWO STRANDS, NOT ONE. Owner: "there are only
     two strands on the house so the whole top should be connected and the
     whole bottom should be connected." Joining the top to the bottom draws a
     line down the middle of the roof that nobody will ever hang - and charges
     for it. Where the split falls is not guessed: the biggest gap in the
     heights IS the step from one roof to the other. */
  check('S150', 'corners are split into roof levels by the biggest gap in height',
    !!det && /widest >= RM_STRAND_GAP_M/.test(det) && /const RM_STRAND_GAP_M/.test(admin),
    'a house at two levels is two runs of string');
  check('S150', 'and a house all on one level stays a single strand',
    !!det && /bands\.push\(byHeight\);/.test(det),
    'splitting a flat roofline in two invents a join that is not there');
  check('S150', 'each level becomes its own run',
    /ONE RUN PER ROOF LEVEL/.test(admin) && /const b = c\.band \|\| 0;/.test(admin),
    'one run through both levels is the line down the middle of the roof');
  {
    /* Four corners round a rectangle. Sorted across, the order zigzags front to
       back; chained, it goes round. */
    const pts = [{e:-5,n:-4,u:5},{e:5,n:-4,u:5},{e:5,n:4,u:5},{e:-5,n:4,u:5}];
    const along = {e: 1, n: 0};
    const sorted = pts.slice().sort((a,b)=>(a.e*along.e+a.n*along.n)-(b.e*along.e+b.n*along.n));
    const chain = [sorted.shift()];
    while (sorted.length) {
      const last = chain[chain.length-1];
      let bi = 0, bd = Infinity;
      sorted.forEach((p,i)=>{ const d=Math.hypot(p.e-last.e,p.n-last.n,p.u-last.u); if(d<bd){bd=d;bi=i;} });
      chain.push(sorted.splice(bi,1)[0]);
    }
    const legLen = c => { let t=0; for(let i=1;i<c.length;i++) t+=Math.hypot(c[i].e-c[i-1].e,c[i].n-c[i-1].n); return t; };
    const acrossOrder = pts.slice().sort((a,b)=>(a.e*along.e+a.n*along.n)-(b.e*along.e+b.n*along.n));
    check('S150', 'and chaining really is shorter than sorting across',
      legLen(chain) < legLen(acrossOrder),
      'chained ' + legLen(chain).toFixed(1) + ' m vs sorted ' + legLen(acrossOrder).toFixed(1) +
      ' m - the extra is the zigzag, and every leg of it reads as a line running deep');
  }

  check('S150', 'corner placement never consults the roof planes',
    !!det && !/rmFacePlane/.test(det),
    'a corner found in the street and placed from above is a sky-view corner in a street-view coat');
  check('S150', 'it looks from several places along the road',
    !!det && /rmFindPanosAround/.test(det) && /views\.length < 4/.test(det),
    'owner: "look for corners at every single angle the you can see the house"');
  check('S150', 'and it says so plainly when there is only one angle',
    !!det && /only driven past this house once/.test(det),
    'a house with one photo cannot be measured this way, and guessing anyway is the old bug');
  check('S150', 'every pair of views is tried, not just the first two',
    !!det && /for\(let j = i \+ 1; j < views\.length; j\+\+\)/.test(det),
    'a corner hidden from one angle is still caught by two others');
}


suite('151. Measure Roof - a clicked dot takes its depth from the wall, not the roof');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "its way off, the street view will look right but the sky view will
     be way off."
     That is the signature of a DEPTH error. Every point along the ray from the
     camera through a pixel projects back to that same pixel, so a dot can sit
     perfectly on the gutter in the street view and be ten feet into next
     door's garden on the map. The street view cannot show the mistake. */
  const fn = pick('rmFootprintWallHit');
  if (!fn) {
    check('S151', 'the wall depth is findable', false, 'rmFootprintWallHit missing');
  } else {
    const api = new Function(
      'let rmOrigin={lat:40.2969,lng:-111.6946}; let rmBuilding=null;' + LF_ +
      (admin.match(/^const RM_STAY_ON_HOUSE_M.*?;/m) || [''])[0] + LF_ +
      ['rmMetresPerDeg','rmToLocal','rmToWorld','rmFootprintBox'].map(pick).join(LF_) + LF_ +
      fn + LF_ +
      'return {hit: rmFootprintWallHit, house: function(b){ rmBuilding = b; }, toWorld: rmToWorld};')();
    /* A house 20 m across and 10 m deep, camera 25 m to the south. */
    const c1 = api.toWorld({e: -10, n: -5, u: 0}), c2 = api.toWorld({e: 10, n: 5, u: 0});
    api.house({sw: {lat: c1.lat, lng: c1.lng}, ne: {lat: c2.lat, lng: c2.lng}});
    const cam = {e: 0, n: -25, u: 2.5};
    /* Aimed at a gutter above the middle of the front wall, 5 m up. The front
       wall (with the overhang allowed) sits at n = -5.8. */
    const aim = (t) => { const d = {e: t.e-cam.e, n: t.n-cam.n, u: t.u-cam.u};
      const l = Math.hypot(d.e,d.n,d.u); return {e:d.e/l, n:d.n/l, u:d.u/l}; };
    const got = api.hit(aim({e: 0, n: -5.8, u: 5}), cam);
    check('S151', 'a ray aimed at the front gutter lands on the front wall',
      got && Math.abs(got.n - (-5.8)) < 0.05 && Math.abs(got.e) < 0.05,
      got ? 'landed at e=' + got.e.toFixed(2) + ' n=' + got.n.toFixed(2) : 'hit nothing');
    check('S151', 'and its height comes out of the same crossing',
      got && Math.abs(got.u - 5) < 0.05,
      got ? 'height ' + got.u.toFixed(2) + ' m' : 'no hit');

    /* ⚠ THE WHOLE POINT: a wall is met nearly square on, so an error in the
       aim barely moves the PLAN position. A roof plane is met at a shallow
       angle, where the same error slides the crossing yards along the ray -
       and every yard of that lands on the map. */
    const nudged = api.hit(aim({e: 0, n: -5.8, u: 5.6}), cam);
    check('S151', 'aiming half a metre high barely moves it in plan',
      nudged && Math.hypot(nudged.e - got.e, nudged.n - got.n) < 0.35,
      'moved ' + (nudged ? Math.hypot(nudged.e - got.e, nudged.n - got.n).toFixed(2) : '?') +
      ' m in plan - on a roof plane the same nudge moves it several times that');

    /* It has to be ON the wall, not past its end. */
    check('S151', 'a ray past the end of the house hits nothing',
      api.hit(aim({e: 40, n: -5.8, u: 5}), cam) === null,
      'the wall is a segment, not an infinite line, and a dot beyond it is not on the house');
    check('S151', 'a ray pointing away from the house hits nothing',
      api.hit({e: 0, n: -1, u: 0}, cam) === null);
    /* A roofline is not underground and not on the fourth floor. */
    check('S151', 'a crossing at a silly height is refused',
      api.hit(aim({e: 0, n: -5.8, u: 40}), cam) === null,
      'a dot forty metres up is a ray that missed everything real');
    /* With no footprint there is nothing to measure against. */
    api.house(null);
    check('S151', 'and with no footprint it says so rather than guessing',
      api.hit(aim({e: 0, n: -5.8, u: 5}), cam) === null);
  }

  /* ⚠ AND THE FACE COMES BEFORE THE WHOLE BUILDING. Measured on the test
     house: the building box runs 8.0 m west of centre, but most of the roof
     faces inside it stop about 4 m west. A click at a gutter on a set-back
     face was landing on the near face of the WHOLE-BUILDING box, up to four
     and a half metres in front of the wall it belongs to - which looks right
     from where it was placed and floats in the garden from anywhere else. */
  check('S151', 'the part of the house the ray points at is tried first',
    (function(){
      const i = admin.indexOf('let best = rmHouseHit(dir, cam) || rmFootprintWallHit(dir, cam);');
      return i !== -1;
    })(),
    'a house is not a box - it is several parts at different depths');
  check('S151', 'a face only counts if the ray is at THAT face roof height there',
    /Math\.abs\(pu - roofU\) > RM_FACE_EDGE_TOL_M/.test(pick('rmRoofEdgeHit') || ''),
    'without it a ray flying over a low garage is placed on the garage front');
}


suite('152. Measure Roof - a dot seen twice is exact, with no model at all');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "its not exact enough because when I try to do a doorwell and I
     need to move to a new angle if it moves even a little then it gets in the
     way so you need to make there be 0 margin of error."
     A single click gives a RAY, not a point. Something has to say how far
     along it the roof is, and every available answer is a model of the house
     that is close but never right - and all of that error lands in the depth,
     which is invisible from the camera that placed the dot and obvious from
     any other. Two rays from two places cross at ONE point. That is geometry,
     not a model. */
  const solve = pick('rmSolveFromRays');
  if (!solve) {
    check('S152', 'the pinning solve is findable', false, 'rmSolveFromRays missing');
  } else {
    const api = new Function(solve + LF_ + 'return rmSolveFromRays;')();
    const unit = (c, t) => { const d = {e: t.e-c.e, n: t.n-c.n, u: t.u-c.u};
      const l = Math.hypot(d.e,d.n,d.u); return {e:d.e/l, n:d.n/l, u:d.u/l}; };
    const truth = {e: 1.5, n: 3.25, u: 5.75};
    const camA = {e: -14, n: -22, u: 2.5};
    const camB = {e: 11, n: -21, u: 2.5};
    const camC = {e: -2, n: -30, u: 2.5};

    const two = api([{cam: camA, dir: unit(camA, truth)}, {cam: camB, dir: unit(camB, truth)}]);
    check('S152', 'two clean sightings land exactly on the corner',
      two && Math.hypot(two.pt.e-truth.e, two.pt.n-truth.n, two.pt.u-truth.u) < 1e-6,
      two ? 'off by ' + Math.hypot(two.pt.e-truth.e, two.pt.n-truth.n, two.pt.u-truth.u).toExponential(2) + ' m'
          : 'solved nothing');
    check('S152', 'and it reports the rays met, which is how good the pin is',
      two && two.spread < 1e-6,
      'the spread is the honest measure of the pin and is shown to the office');

    /* ⚠ THE HEIGHT COMES OUT TOO, from the street alone. Nothing above was
       consulted - no datum, no roof plane, no footprint. */
    check('S152', 'the height falls out of the crossing with no model involved',
      two && Math.abs(two.pt.u - 5.75) < 1e-6,
      'got ' + (two ? two.pt.u.toFixed(4) : '?'));

    /* A third sighting must not make a good answer worse. */
    const three = api([{cam: camA, dir: unit(camA, truth)}, {cam: camB, dir: unit(camB, truth)},
                       {cam: camC, dir: unit(camC, truth)}]);
    check('S152', 'a third sighting keeps it exact rather than dragging it',
      three && Math.hypot(three.pt.e-truth.e, three.pt.n-truth.n, three.pt.u-truth.u) < 1e-6);

    /* ⚠ AIMING ERROR MUST NOT EXPLODE. A click is never perfect, so the thing
       that matters is how a small mis-aim behaves - it should stay small, not
       slide yards along the ray the way a model-derived depth does. */
    const wobble = (c, t, dx) => { const d = unit(c, {e: t.e + dx, n: t.n, u: t.u}); return {cam: c, dir: d}; };
    const off = api([wobble(camA, truth, 0.15), wobble(camB, truth, -0.15)]);
    check('S152', 'a small mis-aim gives a small error, not a large one',
      off && Math.hypot(off.pt.e-truth.e, off.pt.n-truth.n, off.pt.u-truth.u) < 0.3,
      'off by ' + (off ? Math.hypot(off.pt.e-truth.e, off.pt.n-truth.n, off.pt.u-truth.u).toFixed(3) : '?') + ' m');
    check('S152', 'and the spread reports the disagreement honestly',
      off && off.spread > 0,
      'a pin that cannot admit its own error is worse than none');

    /* Nonsense in, nothing out. */
    check('S152', 'one sighting alone is refused - that is the whole problem',
      api([{cam: camA, dir: unit(camA, truth)}]) === null,
      'a single ray has no crossing, which is exactly why a single click cannot be exact');
    const par = {e: 0, n: 1, u: 0};
    check('S152', 'two parallel sightings are refused rather than solved',
      api([{cam: camA, dir: par}, {cam: {e: camA.e + 3, n: camA.n, u: camA.u}, dir: par}]) === null,
      'a singular solve produces a confident nonsense');
  }

  /* ---- the rule about moving far enough ---------------------------- */
  const pin = pick('rmPinCorner');
  check('S152', 'two sightings from nearly the same spot are refused',
    !!pin && /RM_PIN_MIN_BASE_M/.test(pin) && /move further along the street first/.test(pin),
    'the rays are almost one ray, and the solve turns a pixel of aim into metres');
  check('S152', 'every sighting is kept, so more angles narrow it',
    !!pin && /c\.rays = \(c\.rays \|\| \[\]\)\.concat\(\[ray\]\);/.test(pin),
    'throwing away the earlier ones would make the third click no better than the second');
  check('S152', 'a dot remembers the ray it was first placed along',
    /rays: pt\.ray \? \[pt\.ray\] : \[\]/.test(admin),
    'without it the second sighting has nothing to cross with');
  check('S152', 'clicking an existing dot pins it rather than adding another',
    /const near = rmDotUnderClick\(/.test(admin) && /if\(near >= 0\)\{/.test(admin));
  check('S152', 'and a pinned dot looks different from a guessed one',
    /if\(c\.pinned\) parts\.push\('<circle/.test(admin),
    'the office should be able to tell at a glance which dots are still guesses');
}


suite('153. Measure Roof - a set-back part of the house keeps its own depth');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "it didnt fix"; "when you move position it stops working right
     because both positions arent synced like that".
     A rule that made each dot prefer the face the PREVIOUS dot landed on was
     tried and reverted. It scored well on the wrong measure - it forced four
     dots onto one plane and then reported that they were coplanar - and it
     destroyed the thing that matters most here: houses step back, and the
     dormer fronts, dormer depths and recessed entries the owner wants caught
     are exactly the dots that sit on the FAR plane. */
  const fn = pick('rmRoofEdgeHit');
  if (!fn) {
    check('S153', 'the face-depth pick is findable', false, 'rmRoofEdgeHit missing');
  } else {
    const F = (minE, maxE, minN, maxN, hM) => ({
      sw: {lat: 40 + minN/111132, lng: -111 + minE/85300},
      ne: {lat: 40 + maxN/111132, lng: -111 + maxE/85300},
      center: {lat: 40 + (minN+maxN)/2/111132, lng: -111 + (minE+maxE)/2/85300},
      planeHeightM: hM, azimuth: 0, pitch: 0
    });
    const api = new Function(
      'let rmOrigin = {lat: 40, lng: -111};' + LF_ +
      'let rmFaces = []; let rmRoofDatumM = 5; let rmDatumSource = "test"; let rmRoadDir = null; let rmPano = null; let rmCamGroundDrop = 0; const RM_CAM_HEIGHT_M = 2.5; let rmBuilding = null;' + LF_ +
      (admin.match(/^const RM_FACE_EDGE_TOL_M.*?$/m) || [''])[0] + LF_ +
      ['rmMetresPerDeg','rmToLocal','rmToWorld','rmFaceEaveM','rmLowestPlaneM',
       'rmDatum','rmFacePlane'].map(pick).join(LF_) + LF_ +
      fn + LF_ +
      'return {hit: rmRoofEdgeHit, faces: function(f){ rmFaces = f; }};')();

    /* A house that steps back, like the test house: the north half comes out
       to e = -8, the south half stops at e = -4. Both roofs at 5 m. */
    const FRONT = F(-8, -4,  0,  6, 5);
    const BACK  = F(-4,  0, -6,  0, 5);
    api.faces([FRONT, BACK]);
    const cam = {e: -30, n: 0, u: 2.5};
    const aim = t => { const d = {e: t.e-cam.e, n: t.n-cam.n, u: t.u-cam.u};
      const l = Math.hypot(d.e,d.n,d.u); return {e:d.e/l, n:d.n/l, u:d.u/l}; };

    const front = api.hit(aim({e: -8, n: 3, u: 5}), cam);
    check('S153', 'a dot on the part that comes forward lands on it',
      front && Math.abs(front.e - (-8)) < 0.4,
      front ? 'landed at e=' + front.e.toFixed(2) : 'hit nothing');

    /* ⚠ THE ONE THAT MATTERS. This ray passes clean SOUTH of the front part -
       nothing of it is in the way - and is aimed at the recessed part's own
       west edge, four metres further back. */
    const back = api.hit(aim({e: -4, n: -3, u: 5}), cam);
    check('S153', 'a dot on the part that is set back keeps its own depth',
      back && Math.abs(back.e - (-4)) < 0.4,
      back ? 'landed at e=' + back.e.toFixed(2) +
             ' (dragging it to -8 is the reverted rule coming back)' : 'hit nothing');

    /* And the two really are at different depths - the whole point. */
    check('S153', 'the two dots come out four metres apart, not on one plane',
      front && back && Math.abs(front.e - back.e) > 3,
      'got ' + (front && back ? Math.abs(front.e - back.e).toFixed(2) : '?') +
      ' m apart; a rule that flattens this destroys dormer depths and recessed entries');
  }

  /* The reverted rule must not reappear by name. */
  check('S153', 'no dot is nudged toward the face the last one used',
    !/rmLastFaceUsed/.test(admin),
    'this was shipped once and reverted - see the note by RM_FACE_EDGE_TOL_M');
  check('S153', 'and why it was wrong is written down where it would be re-added',
    /DO NOT MAKE CONSECUTIVE DOTS PREFER THE FACE/.test(admin) &&
    /MEASURED THE CONSTRAINT IT HAD JUST IMPOSED/.test(admin),
    'a bare revert invites the same idea back next week');
}


/* ================= Suite 158. The listeners let go when the session ends ==========
   From the office error log, 2026-08-22:
     Uncaught Error in snapshot listener: [code=permission-denied]
     Unhandled promise: Missing or insufficient permissions.

   ⚠ IT LOOKS LIKE A RULES BUG AND IT IS NOT. Every collection this page listens to
   has a rule and every one of those rules is `allow read: if request.auth != null`.
   The reads were refused because there was no auth left when they ran: signOut
   pulls the token out from under about forty still-open listeners, Firestore
   refuses each, and each refusal is an uncaught error plus an unhandled rejection.
   CLAUDE.md already warns that Firestore reports ANY refusal as "insufficient
   permissions" — this is that warning from the read side. */
suite('158. The listeners let go when the session ends');
{
  const LFC = String.fromCharCode(10);
  check('S144', 'onSnapshot is wrapped rather than imported raw',
    /onSnapshot as onSnapshotRaw/.test(admin) && /function onSnapshot\(ref, a, b\)/.test(admin),
    'aliasing the import is what makes every existing call site reach the wrapper — ' +
    'editing 42 call sites by hand in a 2.6MB file is how this gets half-fixed');
  check('S144', 'every unsubscribe is kept',
    /LIVE_LISTENERS\.push\(stop\)/.test(admin),
    'Firestore hands back an unsubscribe and this page threw away 42 of 44 — with ' +
    'nothing kept there is nothing to detach');
  check('S144', 'and something detaches them',
    /function detachAllListeners\(\)/.test(admin) && /LIVE_LISTENERS\.pop\(\)/.test(admin));

  /* ⚠ THE ORDER IS THE WHOLE FIX. signOut resolves the moment the token is
     cleared, so detaching only in onAuthStateChanged is already too late for some
     listeners — the refusals have started. Both logout buttons detach FIRST. */
  /* Anchored to the next real structure, never a character count — the suite has
     its own check forbidding fixed windows, and it is right: a window silently
     goes stale as the code around it grows. */
  const chip = admin.indexOf("userChipLogout");
  const chipBlk = chip === -1 ? '' : admin.slice(chip, admin.indexOf('onAuthStateChanged(auth,', chip));
  check('S144', 'the logout buttons detach BEFORE signOut, not after',
    /detachAllListeners\(\); signOut\(auth\)/.test(chipBlk) ||
    (chipBlk.indexOf('detachAllListeners()') !== -1 &&
     chipBlk.indexOf('detachAllListeners()') < chipBlk.indexOf('signOut(auth)')),
    'detaching after the token is gone still produces the log this exists to stop');

  /* A session can end without the button — a token expiring, or a sign-out in
     another tab. That path has to detach too or the bug simply moves. */
  const auth = admin.indexOf('onAuthStateChanged(auth, function(user){');
  const authBlk = auth === -1 ? '' : admin.slice(auth, admin.indexOf('function switchToAdminPanel', auth));
  check('S144', 'a session that ends any other way still detaches',
    /\} else \{[\s\S]{0,400}detachAllListeners\(\)/.test(authBlk),
    'a token expiring leaves every listener open and reproduces the log exactly');
  check('S144', 'and signing back in clears the signed-out flag',
    /HU_SIGNED_OUT = false/.test(authBlk),
    'without it a re-login without a reload silences every real listener error');

  /* ⚠ AND IT MUST NOT SWALLOW A REAL FAULT. Only the denial that arrives AFTER
     sign-out is expected; one that happens while somebody is signed in is news. */
  const w = admin.indexOf('function onSnapshot(ref, a, b)');
  const wBlk = w === -1 ? '' : admin.slice(w, admin.indexOf('function detachAllListeners', w));
  check('S144', 'a listener failing while signed IN is still reported',
    /HU_SIGNED_OUT && err && err\.code === 'permission-denied'/.test(wBlk) &&
    /console\.error\('Snapshot listener failed:'/.test(wBlk),
    'a blanket catch here would hide a genuine rules regression for ever');
  check('S144', 'and the caller keeps whatever error handler it passed',
    /if\(typeof b === 'function'\) b\(err\)/.test(wBlk),
    'the wrapper inserts its own onError, so a caller-supplied one has to be called on');
}

suite('154. Measure Roof - clicking further back goes BACK, not UP');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "it seems to be mixing up depth and height when i click a dot a
     little deeper the sky view is saying its all a straight line so fix that
     how when i click a spot on the house further back the map view knows where
     that is", and "different angles still isnt working so its like im drawing
     on a 2D picture."

     Every click used to be crossed with ONE vertical plane - the front of the
     building's bounding box. On a vertical plane, clicking higher up the
     picture cannot move you backwards, only UP. So depth never changed, every
     dot shared one line of longitude, and from above the roof was a straight
     line. These tests are that sentence, made checkable. */
  const fn = pick('rmHouseHit');
  if (!fn) {
    check('S154', 'the solid-cast click path is findable', false, 'rmHouseHit missing');
  } else {
    const F = (minE, maxE, minN, maxN, hM) => ({
      sw: {lat: 40 + minN/111132, lng: -111 + minE/85300},
      ne: {lat: 40 + maxN/111132, lng: -111 + maxE/85300},
      center: {lat: 40 + (minN+maxN)/2/111132, lng: -111 + (minE+maxE)/2/85300},
      planeHeightM: hM, azimuth: 0, pitch: 0
    });
    const api = new Function(
      'let rmOrigin = {lat: 40, lng: -111};' + LF_ +
      'let rmFaces = []; let rmRoofDatumM = 4; let rmDatumSource = "test";' + LF_ +
      ['RM_FACE_PAD_M','RM_EAVE_TOL_M','RM_WALL_JOIN_M','RM_WALL_GAP_M','RM_WALL_PLANE_TOL_M'].map(n =>
        (admin.match(new RegExp('^const ' + n + ' = [^;]*;', 'm')) || [''])[0]).join(LF_) + LF_ +
      ['rmMetresPerDeg','rmToLocal','rmToWorld','rmFaceEaveM','rmLowestPlaneM','rmDatum',
       'rmFacePlane','rmPlaneHit3','rmFaceBoxLocal','rmFaceRoofUAt',
       'rmSomethingInGap','rmMergedWalls','rmWallRoofUAt','rmFaceWallHit','rmRoofSurfaceHit'].map(pick).join(LF_) + LF_ +
      fn + LF_ +
      'return {hit: rmHouseHit, faces: function(f){ rmFaces = f; }};')();

    /* A garage that comes forward with the house behind it, both 6 m wide. */
    const GARAGE = F(-8, -4, -3, 3, 4);      /* roof 4 m up */
    const HOUSE  = F(-4,  4, -3, 3, 8);      /* roof 8 m up, four metres back */
    api.faces([GARAGE, HOUSE]);
    const cam = {e: -30, n: 0, u: 2.5};
    const aim = t => { const d = {e: t.e-cam.e, n: t.n-cam.n, u: t.u-cam.u};
      const l = Math.hypot(d.e,d.n,d.u); return {e:d.e/l, n:d.n/l, u:d.u/l}; };

    const front = api.hit(aim({e: -8, n: 0, u: 4}), cam);
    check('S154', 'the garage gutter lands on the garage',
      front && Math.abs(front.e - (-8)) < 0.5,
      front ? 'landed at e=' + front.e.toFixed(2) : 'hit nothing');

    /* ⚠ THE ONE THE OWNER ASKED FOR. This ray clears the garage roof entirely
       and is aimed at the gutter of the house behind it, four metres back. */
    const back = api.hit(aim({e: -4, n: 0, u: 8}), cam);
    check('S154', 'a gutter further back lands further back',
      back && Math.abs(back.e - (-4)) < 0.5,
      back ? 'landed at e=' + back.e.toFixed(2) +
             ' (-8 means it was caught by the garage wall carried into the sky)' : 'hit nothing');
    check('S154', 'so the two gutters are four metres apart on the map',
      front && back && (back.e - front.e) > 3,
      'got ' + (front && back ? (back.e - front.e).toFixed(2) : '?') +
      ' m; if this is 0 the sky view draws them as one straight line');

    /* ⚠ AND HEIGHT MUST STILL BE HEIGHT. Two clicks up the same wall differ in
       height and NOT in depth - that half was never broken and must not be
       "fixed" into depth by mistake. */
    const lo = api.hit(aim({e: -8, n: 0, u: 2.0}), cam);
    const hi = api.hit(aim({e: -8, n: 0, u: 3.5}), cam);
    check('S154', 'clicking higher up one wall changes height, not depth',
      lo && hi && Math.abs(hi.e - lo.e) < 0.3 && (hi.u - lo.u) > 1,
      lo && hi ? 'depth moved ' + Math.abs(hi.e-lo.e).toFixed(2) + ' m, height moved ' +
                 (hi.u-lo.u).toFixed(2) + ' m' : 'hit nothing');

    /* Three dots across a stepped house are not collinear in plan. That is the
       "sky view is saying its all a straight line" symptom, directly. */
    const a1 = api.hit(aim({e: -8, n:  2, u: 4}), cam);
    const a2 = api.hit(aim({e: -8, n: -2, u: 4}), cam);
    const a3 = back;
    const spread = [a1,a2,a3].every(Boolean)
      ? Math.max(a1.e,a2.e,a3.e) - Math.min(a1.e,a2.e,a3.e) : -1;
    check('S154', 'dots across a stepped house are not one straight line from above',
      spread > 3, 'depth spread across the three is ' + spread.toFixed(2) + ' m');

    /* A wall may not be used above the roof it holds up. */
    check('S154', 'a wall stops at its own roof',
      /pu > roofU \+ RM_EAVE_TOL_M/.test(pick('rmFaceWallHit') || ''),
      'otherwise a ray clearing a low garage is caught by the garage front');
    /* A face is bounded by its own patch, never the whole building. */
    check('S154', 'a roof face is bounded by its own patch, not the building box',
      !/rmInsideFootprint/.test(pick('rmRoofSurfaceHit') || '') &&
      /rmFaceBoxLocal/.test(pick('rmRoofSurfaceHit') || ''),
      'bounding a face by the whole footprint flattens every set-back');
  }
}


suite('155. Measure Roof - the wheel zooms, at the pointer, while placing dots');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "also add zoom features so i can scroll with my mouse to zoom."
     While dots are being placed both panes are covered by a transparent sheet -
     the only way to catch a click, because the map and the panorama swallow
     their own - and Google's scrollwheel is switched off at the same moment.
     So there was no way to get closer to a corner without leaving dot mode. */
  check('S155', 'the sky sheet takes the wheel',
    /getElementById\('rmMapLock'\)\.addEventListener\('wheel'/.test(admin));
  check('S155', 'the street sheet takes the wheel',
    /getElementById\('rmPanoLock'\)\.addEventListener\('wheel'/.test(admin));
  /* ⚠ A wheel listener that means to preventDefault MUST say passive:false, or
     the browser ignores it and scrolls the page behind the tool instead. */
  const wheelBlocks = (admin.match(/addEventListener\('wheel'[\s\S]*?\{passive: false\}\)/g) || []);
  check('S155', 'both say passive:false, or the page scrolls instead',
    wheelBlocks.length === 2, 'found ' + wheelBlocks.length + ' of 2');

  const fn = pick('rmZoomKeepPoint');
  if (!fn) {
    check('S155', 'the pointer-anchor maths is findable', false, 'rmZoomKeepPoint missing');
  } else {
    const api = new Function(
      'const rmRad = d => d*Math.PI/180;' + LF_ +
      'function rmFovDeg(zoom){ return 180 / Math.pow(2, zoom); }' + LF_ +
      fn + LF_ + 'return rmZoomKeepPoint;')();
    /* ⭐ ZOOMING AT THE POINTER, not at the middle. Zooming to the centre
       throws whatever you were aiming at off the screen, which on a roof
       corner means hunting for it again after every notch. */
    check('S155', 'zooming in leans the aim toward the pointer',
      api(1, 1.25) > 0 && api(1, 1.25) < 1,
      'got ' + api(1, 1.25).toFixed(3) + ' - must be a fraction of the way, never past it');
    check('S155', 'zooming out leans it back the other way',
      api(1.25, 1) < 0,
      'the point under the pointer moves toward the middle as the view widens');
    check('S155', 'and standing still moves nothing',
      Math.abs(api(1, 1)) < 1e-12);
    /* The swing must never overshoot the pointer, at any step size. */
    let worst = 0;
    for (let z = 0.4; z <= 4; z += 0.05) worst = Math.max(worst, api(z, Math.min(4, z + 0.25)));
    check('S155', 'no step ever swings past the pointer',
      worst < 1, 'the biggest swing was ' + worst.toFixed(3) + ' of the way');
  }

  /* The sky pan-back keeps the spot under the pointer after the zoom. */
  check('S155', 'the map pans back by the amount the zoom moved the spot',
    /rmMap\.panBy\(dx \* \(scale - 1\), dy \* \(scale - 1\)\)/.test(admin),
    'without this the map zooms to its centre and the corner leaves the screen');
  check('S155', 'the wheel is allowed closer than the automatic framing is',
    /RM_WHEEL_ZOOM_MAX = 4/.test(admin) && /RM_ZOOM_MAX = 2\.3/.test(admin),
    'the framing stays wide so it never ends up looking at a blank wall; a hand on the wheel is deliberate');
}


suite('156. Measure Roof - a tree does not put an indent in the house');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "the system thinks there is a indent in the house where the tree is
     but its not its perpendicular on that whole part so that needs to be fixed
     using the wall to see where the roof would be."

     Google works the roof out from overhead imagery, so where a tree overhangs
     it has no face at all and the faces either side stop at the tree. Read
     literally that is a notch cut into the front of the house, and a ray aimed
     into the gap sails past the missing wall to land on something further
     back - the dot ends up deep inside a wall that is in life dead straight. */
  const fn = pick('rmFaceWallHit');
  if (!fn) {
    check('S156', 'the wall pick is findable', false, 'rmFaceWallHit missing');
  } else {
    const F = (minE, maxE, minN, maxN, hM) => ({
      sw: {lat: 40 + minN/111132, lng: -111 + minE/85300},
      ne: {lat: 40 + maxN/111132, lng: -111 + maxE/85300},
      center: {lat: 40 + (minN+maxN)/2/111132, lng: -111 + (minE+maxE)/2/85300},
      planeHeightM: hM, azimuth: 0, pitch: 0
    });
    const api = new Function(
      'let rmOrigin = {lat: 40, lng: -111};' + LF_ +
      'let rmFaces = []; let rmRoofDatumM = 5; let rmDatumSource = "test"; let rmRoadDir = null; let rmPano = null; let rmCamGroundDrop = 0; const RM_CAM_HEIGHT_M = 2.5; let rmBuilding = null;' + LF_ +
      ['RM_FACE_PAD_M','RM_EAVE_TOL_M','RM_WALL_JOIN_M','RM_WALL_GAP_M','RM_WALL_PLANE_TOL_M'].map(n =>
        (admin.match(new RegExp('^const ' + n + ' = [^;]*;', 'm')) || [''])[0]).join(LF_) + LF_ +
      ['rmMetresPerDeg','rmToLocal','rmToWorld','rmFaceEaveM','rmLowestPlaneM','rmDatum',
       'rmFacePlane','rmPlaneHit3','rmFaceBoxLocal','rmFaceRoofUAt',
       'rmSomethingInGap','rmMergedWalls','rmWallRoofUAt'].map(pick).join(LF_) + LF_ +
      fn + LF_ +
      'return {hit: rmFaceWallHit, walls: rmMergedWalls, faces: function(f){ rmFaces = f; }};')();

    /* One straight front wall at e = -8, with a TREE over the middle of it, so
       Google gives a patch above and a patch below and nothing between. The
       body of the house sits four metres back. */
    const ABOVE = F(-8, -4,  2,  6, 5);
    const BELOW = F(-8, -4, -6, -2, 5);
    const BODY  = F(-4,  4, -6,  6, 9);
    api.faces([ABOVE, BELOW, BODY]);
    const cam = {e: -30, n: 0, u: 2.5};
    const aim = t => { const d = {e: t.e-cam.e, n: t.n-cam.n, u: t.u-cam.u};
      const l = Math.hypot(d.e,d.n,d.u); return {e:d.e/l, n:d.n/l, u:d.u/l}; };

    /* The wall really does run the whole way, gap and all. */
    const front = api.walls().filter(g => g.axis === 'E' && Math.abs(g.at - (-8)) < 0.5);
    check('S156', 'the two patches either side of the tree are one wall',
      front.length === 1 && front[0].lo < -5.5 && front[0].hi > 5.5,
      front.length === 1 ? 'runs ' + front[0].lo.toFixed(1) + ' to ' + front[0].hi.toFixed(1)
                         : 'found ' + front.length + ' separate walls on that line');

    /* ⭐ THE ONE THE OWNER ASKED FOR. Aimed straight into the gap the tree made. */
    const inGap = api.hit(aim({e: -8, n: 0, u: 4.6}), cam);
    check('S156', 'a dot where the tree is lands on the wall, not inside the house',
      inGap && Math.abs(inGap.e - (-8)) < 0.5,
      inGap ? 'landed at e=' + inGap.e.toFixed(2) +
              ' (-4 means it fell through the gap into the body of the house)' : 'hit nothing');
    /* And it comes out at the height the roof would be, taken from next door. */
    check('S156', 'and the roof over the gap is taken from the nearest real patch',
      inGap && Math.abs(inGap.u - 4.6) < 0.6,
      inGap ? 'height ' + inGap.u.toFixed(2) + ' m' : 'no hit');

    /* It must agree with the same click just off to the side, where there IS a
       face - a wall that changes depth as you slide along it is not a wall. */
    const beside = api.hit(aim({e: -8, n: 3, u: 4.6}), cam);
    check('S156', 'the gap and the wall beside it come out at the same depth',
      inGap && beside && Math.abs(inGap.e - beside.e) < 0.2,
      'that whole part is perpendicular, so it cannot step in and out');

    /* ⚠ AND MERGING MUST NOT GLUE TOGETHER WALLS THAT REALLY ARE DIFFERENT.
       The body is four metres back and stays four metres back. */
    const deep = api.walls().filter(g => g.axis === 'E' && Math.abs(g.at - (-4)) < 0.5);
    check('S156', 'a wall that really is set back is left where it is',
      deep.length >= 1,
      'joining every wall into one would flatten the house the other way');
    const onBody = api.hit(aim({e: -4, n: 0, u: 8.6}), cam);
    check('S156', 'so a dot on the part that is genuinely further back still is',
      onBody && Math.abs(onBody.e - (-4)) < 0.5,
      onBody ? 'landed at e=' + onBody.e.toFixed(2) : 'hit nothing');

    /* ⚠ AND THE OTHER HALF, which is what protects a doorwell. Same shape of
       hole in the front wall - same width, same place - but this time there IS
       a roof over it, sitting lower because it is a recessed entry. Width alone
       cannot tell this from the tree; the roof can, and must. */
    const PORCH = F(-6, -4, -2, 2, 3);      /* its own roof, two metres lower */
    api.faces([ABOVE, BELOW, PORCH, BODY]);
    const front2 = api.walls().filter(g => g.axis === 'E' && Math.abs(g.at - (-8)) < 0.5);
    check('S156', 'a recess with its own roof is NOT bridged over',
      front2.length === 2,
      'the front wall came back as ' + front2.length + ' run(s); one means the doorwell was paved over');
    const inPorch = api.hit(aim({e: -6, n: 0, u: 2.8}), cam);
    check('S156', 'so a dot in the doorwell lands in the doorwell',
      inPorch && Math.abs(inPorch.e - (-6)) < 0.6,
      inPorch ? 'landed at e=' + inPorch.e.toFixed(2) + ' (-8 means it was bridged flat)' : 'hit nothing');

    /* ⚠ AND AN EMPTY HOLE IS STILL NOT ALWAYS A TREE. Here nothing stands in
       the gap, but the roof on one side is a single storey and on the other it
       is two - so what the roofline does in between is genuinely unknown, and
       inventing a wall straight across it would invent a gutter with it.
       Guessing is only safe where the roof carries on at the same height. */
    const LOW  = F(-8, -4,  2,  6, 5);
    const HIGH = F(-8, -4, -6, -2, 9);
    api.faces([LOW, HIGH, BODY]);
    const split = api.walls().filter(g => g.axis === 'E' && Math.abs(g.at - (-8)) < 0.5);
    check('S156', 'a hole between two roofs at different heights is left alone',
      split.length === 2,
      'came back as ' + split.length + ' run(s); bridging a storey change invents a gutter that is not there');
  }
}


suite('157. Measure Roof - the house the system assumes, drawn before anything else');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "the first thing the system should do is draw the house as if there
     were no obstacles using things like walls, not like a literal drawing that
     I see but where the system will assume the house is."
     Google's roof faces are patches of whatever it could see from overhead, so
     a tree leaves a hole. Read literally that is a notch in the front wall. A
     house is made of straight walls; a gap the width of a tree is a tree. */
  const NEED = ['rmCoveredAt','rmHouseOutline','rmOutlineEaveU','rmHouseWireframe'];
  const missing = NEED.filter(n => !pick(n));
  if (missing.length) {
    check('S157', 'the assumed-house model is findable', false, 'missing: ' + missing.join(', '));
  } else {
    const F = (minE, maxE, minN, maxN, hM) => ({
      sw: {lat: 40 + minN/111132, lng: -111 + minE/85300},
      ne: {lat: 40 + maxN/111132, lng: -111 + maxE/85300},
      center: {lat: 40 + (minN+maxN)/2/111132, lng: -111 + (minE+maxE)/2/85300},
      planeHeightM: hM, azimuth: 0, pitch: 0
    });
    const api = new Function(
      'let rmOrigin = {lat: 40, lng: -111};' + LF_ +
      'let rmFaces = []; let rmRoofDatumM = 5; let rmDatumSource = "test"; let rmRoadDir = null; let rmPano = null; let rmCamGroundDrop = 0; const RM_CAM_HEIGHT_M = 2.5; let rmBuilding = null;' + LF_ +
      ['RM_WALL_JOIN_M','RM_WALL_GAP_M','RM_WALL_PLANE_TOL_M','RM_OUTLINE_CELL_M','RM_OUTSIDE_STEP_M','RM_FRONT_COS'].map(n =>
        (admin.match(new RegExp('^const ' + n + ' = [^;]*;', 'm')) || [''])[0]).join(LF_) + LF_ +
      ['rmMetresPerDeg','rmToLocal','rmToWorld','rmFaceEaveM','rmLowestPlaneM','rmDatum',
       'rmFacePlane','rmFaceBoxLocal','rmFaceRoofUAt','rmSomethingInGap','rmMergedWalls','rmBridgedPatches','rmWallOutward','rmCamLocal','rmCamOnRoad','rmRoadDirection'].map(pick).join(LF_) + LF_ +
      NEED.map(pick).join(LF_) + LF_ +
      'return {outline: rmHouseOutline, wire: rmHouseWireframe, eave: rmOutlineEaveU,' +
      ' faces: function(f){ rmFaces = f; }};')();

    /* A straight front wall at e = -8 with a TREE over four metres of it, and
       the body of the house genuinely four metres further back. */
    api.faces([F(-8, -4,  2,  6, 5), F(-8, -4, -6, -2, 5), F(-4, 4, -6, 6, 9)]);
    const segs = api.outline();
    check('S157', 'the assumed house has an outline at all', segs.length > 0);

    /* ⭐ THE TREE GAP IS CLOSED. If the notch survived there would be wall
       running north-south part-way in, at the back of the bite. */
    const notch = segs.filter(function(sd){
      const vertical = Math.abs(sd.a.e - sd.b.e) < 0.01;
      if(!vertical) return false;
      if(!(sd.a.e > -7.4 && sd.a.e < -4.6)) return false;      /* part-way in */
      const lo = Math.min(sd.a.n, sd.b.n), hi = Math.max(sd.a.n, sd.b.n);
      return hi > -2.2 && lo < 2.2;                            /* in the gap */
    });
    check('S157', 'a tree does not become a notch in the front wall',
      notch.length === 0,
      'found ' + notch.length + ' piece(s) of wall inside the gap - that whole part is perpendicular');

    /* And the front wall really does run the whole way across. */
    const front = segs.filter(sd => Math.abs(sd.a.e - sd.b.e) < 0.01 && sd.a.e < -7.4);
    const cover = front.reduce((a, sd) => a + Math.abs(sd.b.n - sd.a.n), 0);
    check('S157', 'the front wall runs the whole width, gap included',
      cover > 11, 'the front covers ' + cover.toFixed(1) + ' m of the 12 m it should');

    /* ⚠ AND A REAL SET-BACK MUST SURVIVE. Closing small bites must not swallow
       the genuine step the house actually has, or the model flattens the other
       way and every recessed entry is lost. */
    const stepped = segs.filter(function(sd){
      const horizontal = Math.abs(sd.a.n - sd.b.n) < 0.01;
      const lo = Math.min(sd.a.e, sd.b.e), hi = Math.max(sd.a.e, sd.b.e);
      return horizontal && lo < -7 && hi > -4.5;              /* runs across the step */
    });
    check('S157', 'a genuine step in the house is kept',
      stepped.length > 0,
      'the front is four metres proud of the body and must stay that way');

    /* Every drawn wall carries the height of the roof over it, or it cannot be
       drawn in the street view at all. */
    /* ⭐ AN L-SHAPED HOUSE MUST COME OUT L-SHAPED. This is the honest check on
       the outline, and it is deliberately not an area figure: a collapsed union
       still scores well on area while being a plain rectangle. A rectangle has
       four walls. An L has six, and one of them is the inside corner. An
       earlier version kept only whole face-box edges with house on one side and
       garden on the other, which is all-or-nothing - a wall outside along half
       its length and buried along the rest failed and vanished - and every
       house came out as a bare rectangle. */
    api.faces([F(-8, 0, -6, 6, 5), F(0, 8, -6, 0, 5)]);     /* an L */
    const Ls = api.outline();
    const vert = Ls.filter(sd => Math.abs(sd.a.e - sd.b.e) < 0.01);
    const horiz = Ls.filter(sd => Math.abs(sd.a.n - sd.b.n) < 0.01);
    check('S157', 'an L-shaped house comes out with six walls, not four',
      Ls.length >= 6, 'got ' + Ls.length + ' walls (' + vert.length + ' north-south, ' +
      horiz.length + ' east-west); four means the shape collapsed to a rectangle');
    /* The inside corner is the giveaway: a wall part-way across the middle. */
    const step = horiz.filter(function(sd){
      const lo = Math.min(sd.a.e, sd.b.e), hi = Math.max(sd.a.e, sd.b.e);
      return Math.abs(sd.a.n - 0) < 0.4 && hi > 0.4 && lo > -0.4;
    });
    /* ⭐ THE FRONT, BY DEFAULT. Owner: "remember default is front", and
       "the left side should not be included just because it is visible from
       street view." A wall is front when its outside faces the ROAD, not when
       it faces the camera - standing at an angle you can see a good deal of a
       flank, and drawing it makes the model look like a house nobody asked to
       light. */
    (function(){
      const road = {e: -1, n: 0};                 /* road due west of the house */
      const wallsFor = function(){
        return api.wire({e: -30, n: 0, u: 2.5});
      };
      api.faces([F(-8, 8, -6, 6, 5)]);            /* one plain rectangle */
      const shown = wallsFor();
      const westWall = shown.filter(sg => Math.abs(sg.a.e - sg.b.e) < 0.01 && sg.a.e < -7);
      const flanks = shown.filter(sg => Math.abs(sg.a.n - sg.b.n) < 0.01);
      check('S157', 'the wall facing the road is drawn',
        westWall.length > 0, 'the front is the whole point');
      check('S157', 'the flanks running back from the road are not, by default',
        flanks.length === 0,
        'got ' + flanks.length + ' side wall(s); default is front');
    })();

    check('S157', 'and it has the inside corner where the L steps in',
      step.length > 0,
      'no wall found along the step; the notch in the L was filled in');
    /* Put the real house back for anything after this. */
    api.faces([F(-8, -4,  2,  6, 5), F(-8, -4, -6, -2, 5), F(-4, 4, -6, 6, 9)]);

    const wire = api.wire();
    check('S157', 'every wall drawn carries its roof height',
      wire.length > 0 && wire.every(sg => isFinite(sg.a.u) && isFinite(sg.b.u) &&
        sg.a.u > 0.5 && sg.a.u < 25),
      'got ' + wire.length + ' walls');
    /* ⭐ THE GUTTER OF THE ROOF THIS WALL HOLDS UP, not the nearest roof
       anywhere. Owner: "double check that the lines are red and line up with
       the gutter from every angle."
       ⚠ MEASURED ON THE TEST HOUSE: the front wall was being drawn at 10 ft,
       level with the top of the garage door, because the nearest patch by plain
       distance was a low roof round the side. That front is two storeys and its
       gutter is at 16-18 ft. Nearest-by-distance is the wrong question. */
    (function(){
      /* ⚠ TWO SEPARATE THINGS ARE AT WORK AND EACH NEEDS ITS OWN CASE. An
         earlier version of this test passed with the fix sabotaged, twice,
         because both branches were reading from the same inward point and so
         always agreed. Written out properly:

         (a) READING FROM INSIDE is what picks the right face at all. Here the
             LOW roof is nearer AT THE WALL (0.2 m against 0.5) and the TALL one
             is nearer one step INSIDE, so only the inward read gets the
             two-storey gutter. */
      const TALL = F(-7.5, 0, -6, 6, 9);    /* two storeys, starting just inside */
      const LOW  = F(-9, -8.2, -6, 6, 4);   /* a low roof just OUTSIDE the wall */
      api.faces([TALL, LOW]);
      const atWall = api.eave(-8, 0, null);
      const inside = api.eave(-8, 0, {e: 1.6, n: 0});
      check('S157', 'a wall takes the gutter of the roof it holds up',
        inside !== null && Math.abs(inside - 10) < 0.7,
        'got ' + (inside === null ? 'null' : inside.toFixed(2)) + ' m, wanted 10');
      check('S157', 'and reading it from OUTSIDE gets the wrong roof, which is the bug',
        atWall !== null && Math.abs(atWall - 5) < 0.7,
        'without the inward step the nearest patch is the low roof across the garden - ' +
        'measured on the real house this drew the front wall at 10 ft, level with the ' +
        'top of the garage door');
      check('S157', 'the wireframe passes that inward step',
        /rmOutlineEaveU\(sd\.a\.e, sd\.a\.n, inw\)/.test(admin),
        'without a direction there is no way to tell inside from outside');

      /* (b) OF THE ROOFS THAT DO MEET THIS WALL, THE LOWEST IS THE GUTTER -
             that is where a gutter sits, at the bottom edge of the roof it
             drains, and it is where the lights go. Both of these contain the
             inward point, so nearest-by-distance cannot separate them. */
      api.faces([F(-8, 0, -6, 6, 9), F(-8, 0, -6, 6, 4)]);
      const two = api.eave(-8, 0, {e: 1.6, n: 0});
      check('S157', 'where two roofs meet one wall, the lower one is the gutter',
        two !== null && Math.abs(two - 5) < 0.7,
        'got ' + (two === null ? 'null' : two.toFixed(2)) + ' m; 10 is the ridge, not the gutter');
    })();
    api.faces([F(-8, -4,  2,  6, 5), F(-8, -4, -6, -2, 5), F(-4, 4, -6, 6, 9)]);

    check('S157', 'and the roof over the tree gap is the roof either side of it',
      Math.abs(api.eave(-8, 0) - 5) < 0.6,
      'got ' + api.eave(-8, 0));
  }

  /* It is drawn, in both windows, and it can be turned off. */
  check('S157', 'the assumed house is drawn in the street view',
    /if\(rmShowModel\)\{[\s\S]{0,600}rmHouseWireframe\(\)\.forEach/.test(admin));
  /* ⚠ NOT the cached rmModel() here. Which walls show depends on where the
     camera is standing, and the cache is keyed on the house, not the camera. */
  check('S157', 'and it is rebuilt per camera, not served from the house cache',
    (function(){
      /* the comment there mentions rmModel by name, so look for the CALL */
      return !/rmModel\(\)\.forEach/.test(admin);
    })(),
    'a cache keyed on the house would show the far side after you walk round');
  check('S157', 'and on the map',
    /function rmSyncModelSky/.test(admin) && /rmModelLines\.push\(new google\.maps\.Polyline/.test(admin));
  check('S157', 'it is built the moment the roof arrives, before any line is offered',
    (function(){
      const i = admin.indexOf('rmFacesReady = true;');
      const j = admin.indexOf('rmSyncModelSky();', i);
      const k = admin.indexOf('rmBuildWhenReady();', i);
      return i !== -1 && j > i && k > j;
    })(),
    'everything else is measured against it, so it comes first');
  check('S157', 'and it can be turned off when it is in the way',
    /id="rmModelBtn"/.test(admin) && /function rmSetShowModel/.test(admin));
  /* Working it out is a grid and two passes, so not on every repaint. */
  check('S157', 'the outline is worked out once per house, not every repaint',
    /rmModelCache && rmModelKey === key/.test(admin),
    'rmPaintStreet runs on every mouse move of the panorama');
}

/* =====================================================================
   TWO SESSIONS APPEND SUITES TO THIS FILE. Both of us used to add ours
   immediately above the Promise.all summary below, which made every merge
   conflict land on the same line.

   ⚠ AND THE CONFLICT HAD A TRAP IN IT. Each side's block ends UNCLOSED inside
   the conflict - both sides share the single '}' that follows - so stripping
   the markers and keeping both blocks leaves the file ONE BRACE SHORT, and
   node reports "SyntaxError: Unexpected end of input", which reads like a
   truncated file rather than a merge artefact. It cost the other session two
   attempts to spot.

   So we append under our own sentinel and never the same line. Suite numbers
   are reserved the same way: 150-249 roofline, 250-349 schedule and routing.
   ===================================================================== */

/* ===== ROOFLINE SUITES - lanil-9d appends BELOW this line ===== */

suite('165. Measure Roof - loading an address forgets the last house');
{
  /* Owner, after loading a few addresses: "well thats just completely wrong now."

     ⚠ MEASURED, NOT INFERRED. rmReset ran only when the overlay OPENED, never
     when Load Property was clicked. Loading a house in Salt Lake City after one
     in Holladay - four kilometres apart, different roof, different everything -
     left FOUR DOTS on screen and a roof height of 3.03 m still labelled
     "street", i.e. measured. Both were drawn and reported against the new
     house.

     ⚠ THE DATUM IS THE DANGEROUS ONE. Dots in the wrong place look wrong. A
     roof height carried over looks RIGHT - it says measured, it is a plausible
     number - and it silently scales every line on the new roof. */
  check('S165', 'loading an address forgets the last house',
    /function rmForgetLastHouse\(\)/.test(admin) &&
    /rmOrigin = \{lat: coords\.lat, lng: coords\.lng\};\s*\n\s*rmForgetLastHouse\(\);/.test(admin),
    'rmReset only ever ran when the overlay opened');

  /* Each thing that leaked, named, so adding a new one without clearing it fails here. */
  const forget = extractFn(admin, 'rmForgetLastHouse') || '';
  const mustClear = [
    ['the dots', /rmCorners = \[\]/],
    ['which strand is being drawn', /rmCurrentBand = 0/],
    ['the corners offered', /rmCandidates = \[\]/],
    ['the roof model', /rmFaces = \[\]/],
    ['the building outline', /rmBuilding = null/],
    ['the assumed-house cache', /rmModelCache = null/],
    ['the roof height', /rmRoofDatumM = null/],
    ['and how it was arrived at', /rmDatumSource = ''/],
    ['the measured camera height', /rmCamHeightM = null/],
    ['which way the road runs', /rmRoadDir = null/],
    ['whether the camera has been aimed', /rmFramed = false/]
  ];
  mustClear.forEach(function(pair){
    check('S165', 'it forgets ' + pair[0], pair[1].test(forget),
      'anything remembered here is reported against the NEXT house');
  });
  /* ⚠ AND THE ONE THAT COSTS MONEY. rmPhotoExtraFeet is added straight into
     the total, so feet measured off a photograph of the BACK of one house were
     still in the total after loading a different address. A quote longer than
     the house, with nothing on screen to explain where the extra came from.
     ⭐ FOUND BY AUDITING EVERY PIECE OF PER-HOUSE STATE rather than waiting for
     a fourth report. Three leaks had already been fixed one at a time; nobody
     had noticed this one, and it is the only one that changes a price. */
  ['rmPhotoExtraFeet = 0', 'rmPhotoRuns = []', 'rmPhotoRef = null',
   'rmPhotoRefPx = 0', 'rmPhotoRefFt = 0', 'rmPhotoBlob = null'].forEach(function(bit){
    check('S165', 'it forgets the photo measurement: ' + bit,
      forget.indexOf(bit) !== -1,
      'those feet are added to the total for whatever house is loaded next');
  });
  check('S165', 'and the photo feet really do reach the total',
    admin.indexOf('out.perimeter += rmPhotoExtraFeet') !== -1,
    'if this stops being true the checks above are guarding nothing');

  /* The bar has to redraw, or the numbers stay on screen after the dots are gone. */
  check('S165', 'and the dot list on screen is redrawn',
    /rmRenderCornerBar\(\);/.test(forget),
    'clearing the array but not the bar leaves numbered buttons for dots that no longer exist');
  /* The map overlay for the old house has to come off the map, not just be dropped. */
  check('S165', 'the old assumed-house lines are taken off the map',
    /rmModelLines\.forEach\(function\(l\)\{ l\.setMap\(null\); \}\)/.test(forget),
    'dropping the array leaves the polylines drawn over the new house');
}

suite('164. Measure Roof - the camera height is measured, not assumed');
{
  /* Owner: "measure height not just legth and depth."
     ⚠ RM_CAM_HEIGHT_M IS 2.50 AND IT IS WRONG ON EVERY PANORAMA MEASURED: the
     yard reads 2.391 off its own ground plane, its neighbour 2.46, a third
     2.39. A constant cannot be right for three different values, and the error
     lands in EVERY height reported, because a click's height is the camera's
     height plus whatever the ray does from there. 10.9 cm on the yard, measured
     twice independently by two sessions. */
  check('S164', 'the panorama is asked how high its own camera is',
    /import \{ fetchPano as rmFetchPano, cameraHeight as rmDepthCameraHeight \}/.test(admin) &&
    /function rmMeasureCameraHeight\(\)/.test(admin));
  check('S164', 'and that measurement is what a click uses',
    /p\.u = \(rmCamHeightM !== null \? rmCamHeightM : RM_CAM_HEIGHT_M\) \+ rmCamGroundDrop;/.test(admin),
    'measuring it and then not using it is worse than not measuring it');
  /* ⚠ THE FALLBACK IS THE POINT. This reads an undocumented endpoint. */
  check('S164', 'it falls back to the old constant rather than failing',
    /catch\(function\(\)\{ \/\* no depth map here; the constant stands \*\/ \}\)/.test(admin),
    'an undocumented endpoint must never be able to break the tool');
  check('S164', 'a silly answer is refused rather than believed',
    /h > 1\.2 && h < 4/.test(admin),
    'if the largest horizontal plane is not the road, the number is not a camera height');
  check('S164', 'it is measured once per panorama, not once per repaint',
    /if\(!id \|\| id === rmCamHeightPano\) return;/.test(admin),
    'rmPaintStreet runs on every mouse move of the panorama');
  /* ⚠ AND IT MUST NOT SURVIVE A MOVE. A stale height from the last panorama is
     worse than the constant, because it is confidently wrong. */
  check('S164', 'and it is cleared on arrival so the last one cannot linger',
    (function(){
      const i = admin.indexOf('rmCamHeightPano = id;');
      const j = admin.indexOf('rmCamHeightM = null;', i);
      return i !== -1 && j > i && (j - i) < 120;
    })(),
    'a height from the previous panorama is confidently wrong');
  check('S164', 'and a late answer for a panorama already left is dropped',
    /if\(rmCamHeightPano !== id\) return;/.test(admin),
    'two moves in quick succession would otherwise apply the first answer to the second place');
  /* Why this one survived the bearing refutation, recorded where it is done. */
  check('S164', 'why this survives the refuted bearing is written down',
    /rotation about the vertical does not touch the vertical/.test(admin),
    'so nobody bins it along with toEastNorth');
}


suite('163. Measure Roof - the street view follows the address');
{
  /* ⚠ LOADING A SECOND ADDRESS LEFT THE STREET VIEW ON THE FIRST HOUSE.
     Reproduced live: load Sandy, then load Lehi. rmPano.getPosition() comes
     back as the Lehi panorama and every number agrees - origin, distance,
     heading - but the picture on screen is still the Sandy house. Somebody
     would place dots on the wrong building with nothing anywhere saying so.

     ⭐ AND IT ONLY SHOWS UP ON THE SECOND ADDRESS. A fresh page load renders
     the right house every time, which is why four addresses tested one at a
     time never caught it, and why the owner asking to test many addresses in
     one sitting is what found it. */
  check('S163', 'a property load names the panorama outright',
    /svc\.getPanorama\(\{location: center, radius: RM_STREET_SEARCH_M\}/.test(admin) &&
    /rmPano\.setPano\(data\.location\.pano\);/.test(admin),
    'setPosition asks the panorama to find its own way and does not reliably repaint');
  check('S163', 'and only falls back to setPosition when there is no imagery',
    (function(){
      const i = admin.indexOf('svc.getPanorama({location: center, radius: RM_STREET_SEARCH_M}');
      const j = admin.indexOf('rmPano.setPosition(center);', i);
      const k = admin.indexOf('} else {', i);
      return i !== -1 && j > i && k > i && k < j;    /* setPosition is the else */
    })(),
    'it is the fallback, not the path');
  check('S163', 'the listener is attached before the pano is changed',
    (function(){
      const i = admin.indexOf("svc.getPanorama({location: center, radius: RM_STREET_SEARCH_M}");
      const l = admin.indexOf("addListenerOnce(rmPano, 'pano_changed'", i);
      const p = admin.indexOf('rmPano.setPano(data.location.pano);', i);
      return i !== -1 && l > i && p > l;
    })(),
    'attached after, the event has gone and the new house is never framed');
  check('S163', 'and the new house is framed from scratch rather than inheriting',
    (function(){
      const i = admin.indexOf("svc.getPanorama({location: center, radius: RM_STREET_SEARCH_M}");
      const f = admin.indexOf('rmFramed = false;', i);
      const p = admin.indexOf('rmPano.setPano(data.location.pano);', i);
      return i !== -1 && f > i && f < p;
    })(),
    'keeping the previous framing points the camera at where the last house was');
}


suite('162. Measure Roof - the first dot on a wall measures the roof height');
{
  /* Owner: "measure height not just legth and depth". The panel has promised
     this for weeks - "Trace anything in Street View and it is measured instead"
     - and it was only ever wired to the OLD TRACING path. Once the work moved to
     dots the datum stopped being measured on every house: four addresses checked
     in a row, all four said "assumed". */
  check('S162', 'placing a dot can set the roof height',
    (function(){
      const i = admin.indexOf("rmAddCorner({lat: w.lat, lng: w.lng, h: best.u,");
      const j = admin.lastIndexOf('rmSetDatumFromStreet(w)', i);
      return i !== -1 && j !== -1 && j < i && (i - j) < 900;
    })(),
    'it was wired to rmAddPoint only, which the dot workflow never calls');

  /* ⚠ AND ONLY FROM A WALL, WHICH IS THE WHOLE ARGUMENT. */
  check('S162', 'and only from a WALL hit, never a roof hit',
    /best\.kind === 'wall' && rmDatumSource !== 'street' && rmSetDatumFromStreet\(w\)/.test(admin),
    'a wall height comes from the camera and the ray, which know nothing about the datum; ' +
    'a roof height comes from a plane the datum PLACED, so using it would be measuring ' +
    'the assumption and calling it a measurement');
  check('S162', 'a measurement already taken is not overwritten by a later click',
    /rmDatumSource !== 'street'/.test(admin),
    'the first real observation stands; later clicks do not drift it');
  /* The two kinds have to be distinguishable at all for that test to mean anything. */
  check('S162', 'the solid-cast says which kind of surface it hit',
    /kind: 'wall'/.test(admin) && /kind: 'roof'/.test(admin),
    'without the label the wall-only rule cannot be enforced');
  check('S162', 'and the heights are refreshed so every line moves with it',
    (function(){
      const i = admin.indexOf("best.kind === 'wall' && rmDatumSource !== 'street'");
      const j = admin.indexOf('rmRefreshHeights();', i);
      return i !== -1 && j > i && (j - i) < 200;
    })(),
    'a new datum that nothing redraws is a number in a variable');
}


suite('161. Measure Roof - corners are offered, and only the ones clicked count');
{
  const LF_ = String.fromCharCode(10);
  const pick = n => extractFn(admin, n);

  /* Owner: "also start getting the generated corners and you can click the ones
     you want to keep."
     ⚠ THE WHOLE POINT IS THAT A SUGGESTION IS NOT A DECISION. Every previous
     attempt at automatic lines failed by drawing its guesses as facts, and the
     office could not tell which was which. Offered corners carry no number,
     count for nothing, and become real only when clicked. */
  const NEED = ['rmCornerCandidates','rmCandidateUnderClick','rmKeepCandidate','rmSuggestCorners'];
  const missing = NEED.filter(n => !pick(n));
  if (missing.length) {
    check('S161', 'the offer-and-pick path is findable', false, 'missing: ' + missing.join(', '));
  } else {
    const api = new Function(
      'let rmCandidates = []; let rmCorners = []; let rmCurrentBand = 0;' + LF_ +
      'let rmOrigin = {lat: 40, lng: -111};' + LF_ +
      'function rmDatum(){ return {m: 3}; }' + LF_ +
      'function rmCornersChanged(){}' + LF_ +
      ['rmMetresPerDeg','rmToWorld','rmAddCorner','rmKeepCandidate'].map(pick).join(LF_) + LF_ +
      'return {keep: rmKeepCandidate,' +
      ' set: function(c){ rmCandidates = c; }, cands: function(){ return rmCandidates; },' +
      ' corners: function(){ return rmCorners; }};')();

    api.set([{lat: 40.0001, lng: -111.0001, h: 5, from: 'model'},
             {lat: 40.0002, lng: -111.0002, h: 6, from: 'model'}]);
    check('S161', 'an offered corner counts for nothing until it is clicked',
      api.corners().length === 0 && api.cands().length === 2,
      'a suggestion that behaves like a decision is worse than no suggestion');

    api.keep(0);
    check('S161', 'clicking one turns it into a real corner',
      api.corners().length === 1 && Math.abs(api.corners()[0].h - 5) < 1e-9,
      'and it keeps the height it was offered at');
    check('S161', 'and it stops being offered, because it has been decided',
      api.cands().length === 1,
      'leaving it on screen invites keeping the same corner twice');
    check('S161', 'the one not clicked is simply ignored',
      api.cands().length === 1 && Math.abs(api.cands()[0].h - 6) < 1e-9,
      'rejecting a suggestion costs one glance; that is the whole bargain');
    check('S161', 'keeping something that is not there does nothing',
      api.keep(99) === false && api.corners().length === 1);

    /* ⭐ THE ORDER IS THE OFFICE'S, NOT THE MODEL'S. They join in the order they
       were clicked, so picking the corners picks the run as well. */
    const before = api.corners().length;
    api.keep(0);
    check('S161', 'they join in the order they were clicked',
      api.corners().length === before + 1 &&
      Math.abs(api.corners()[before].h - 6) < 1e-9,
      'the office is choosing the strand, not just the corners');
  }

  /* Quiet on screen: a ring, no number, and drawn under the kept dots. */
  check('S161', 'an offered corner is a small hollow ring with no number',
    /rmCandidates\.forEach\(function\(c, i\)\{[\s\S]{0,600}fill="none"[\s\S]{0,300}#F4BE55/.test(admin) &&
    !/rmCandidates\.forEach[\s\S]{0,600}<text/.test(admin),
    'owner: "the dots should look clean and small so theyre not hindering the view"');
  check('S161', 'and it is drawn before the kept corners, so it sits under them',
    (function(){
      const a = admin.indexOf('rmCandidates.forEach(function(c, i){');
      const b = admin.indexOf('THE CORNERS, WITH THEIR NUMBERS ON');
      return a !== -1 && b > a;
    })());
  /* A click on a ring means that ring. */
  check('S161', 'a click on a ring takes it rather than dropping a new dot beside it',
    (function(){
      const a = admin.indexOf('const cand = rmCandidateUnderClick(');
      const b = admin.indexOf('const near = rmDotUnderClick(', a);
      const c = admin.indexOf('rmAddCorner({lat: w.lat', a);
      return a !== -1 && b > a && c > a;      /* candidates checked first */
    })(),
    'aiming at a suggestion and getting a fresh dot an inch away is maddening');
  /* Signed as interim, because the source is the one she ruled out. */
  check('S161', 'the interim source says so, and says what replaces it',
    /THIS IS AN INTERIM SOURCE AND IT IS SIGNED AS ONE/.test(admin) &&
    /depth-map generator/.test(admin),
    'it comes from overhead segments, which she ruled out for deciding placement');
}


suite('160. Measure Roof - a click on nothing is refused, and the scaffolding is quiet');
{
  /* ⭐ CLICKING THE SKY USED TO PLACE A DOT. Found by the other session driving
     the deployed tool: a click on cloud above the roof produced a confident dot
     numbered 0 at 31 ft, drawn in BOTH views, agreeing with itself.

     The cause: when no roof face is hit, the fallback crosses the ray with the
     wall the house presents to the camera - and that is an INFINITE PLANE. A
     ray aimed well above the roof still crosses it, somewhere up in the air.

     Owner: "you need to make there be 0 margin of error." A click with no
     surface under it has no depth, and no depth means no height. Refusing is
     the only honest answer, and a confident wrong dot is worse than a refusal
     because nothing about it looks wrong. */
  check('S160', 'the fallback wall crossing has to be ON the house',
    /const onHouse = w2 && w2\.u > 0\.3 && w2\.u < roofTop \+ RM_EAVE_TOL_M;/.test(admin),
    'an infinite plane is crossed by a ray aimed at the sky');
  check('S160', 'and a click above the roofline is refused, not placed',
    /That is above the roofline/.test(admin) &&
    (function(){
      const i = admin.indexOf('const onHouse = w2 &&');
      const j = admin.indexOf('rmAddCorner(', i);
      const k = admin.indexOf('return;', i);
      return i !== -1 && k > i && k < j;      /* it returns before adding */
    })(),
    'placing it anyway is what produced a dot at 31 ft on a cloud');
  /* ⚠ AND THE FIRST FIX FOR THIS DID NOT WORK, WHICH IS WHY THE GUARD MOVED.
     Guarding only the fallback was not enough: a ray aimed at the sky meets no
     wall, but it can still cross a ROOF PLANE carried out to the corner of its
     own bounding box - Google's patches are axis-aligned boxes bigger than the
     faces they describe. Verified live after the first fix shipped: a click on
     open cloud still produced a dot, at 38 ft, on a house whose ridge is 21.
     So the check belongs where every path meets, just before the dot is made. */
  check('S160', 'nothing is accepted above the roof, whichever path found it',
    /if\(top !== null && best\.u > top \+ RM_EAVE_TOL_M\)\{/.test(admin) &&
    (function(){
      const i = admin.indexOf('if(top !== null && best.u > top + RM_EAVE_TOL_M){');
      const j = admin.indexOf('rmAddCorner(', i);
      const k = admin.indexOf('return;', i);
      return i !== -1 && j > i && k > i && k < j;   /* refuses before adding */
    })(),
    'guarding one path leaves the others open, which is how 38 ft survived the first fix');
  /* ⭐ AND THE CEILING IS THIS HOUSE'S OWN RIDGE, RUN not grepped. A fixed
     number would refuse real dots on a tall house and accept sky over a
     bungalow. */
  (function(){
    const LF2 = String.fromCharCode(10);
    const pick2 = n => extractFn(admin, n);
    const F2 = (minE, maxE, minN, maxN, hM) => ({
      sw: {lat: 40 + minN/111132, lng: -111 + minE/85300},
      ne: {lat: 40 + maxN/111132, lng: -111 + maxE/85300},
      center: {lat: 40 + (minN+maxN)/2/111132, lng: -111 + (minE+maxE)/2/85300},
      planeHeightM: hM, azimuth: 0, pitch: 0
    });
    const api2 = new Function(
      'let rmOrigin = {lat: 40, lng: -111};' + LF2 +
      'let rmFaces = []; let rmRoofDatumM = 3; let rmDatumSource = "test";' + LF2 +
      ['rmMetresPerDeg','rmToLocal','rmFaceEaveM','rmLowestPlaneM','rmDatum',
       'rmFacePlane','rmRoofTopM'].map(pick2).join(LF2) + LF2 +
      'return {top: rmRoofTopM, faces: function(f){ rmFaces = f; }};')();
    api2.faces([F2(-8, 0, -6, 6, 4), F2(0, 8, -6, 6, 9)]);
    const t = api2.top();
    /* datum 3, lowest eave 4, so the tall face sits at 3 + (9-4) = 8 */
    check('S160', 'the ceiling is the tallest roof this house actually has',
      t !== null && Math.abs(t - 8) < 0.4,
      'got ' + (t === null ? 'null' : t.toFixed(2)) + ' m, wanted 8');
    api2.faces([]);
    check('S160', 'and with no roof model there is no ceiling to enforce',
      api2.top() === null,
      'refusing every click on a house Google has no model for is worse than allowing them');
  })();
  check('S160', 'past the END of a roof patch is still accepted',
    /Past the end of a roof patch it is still/.test(admin),
    'that is what the fallback is for; only past the TOP is refused');

  /* ⭐ AND THE SCAFFOLDING NO LONGER SHOUTS OVER THE WORK. Opening the tool
     showed a cyan outline and a yellow ground line and no red anywhere, so the
     scaffolding read as the job. Owner: "double check that the lines are red",
     and on the model itself "we outline from street view not sky view which is
     clearly not what your doing". */
  check('S160', 'the assumed house is off until it is built from the street',
    /let rmShowModel = false;/.test(admin),
    'it is drawn from overhead roof segments, which is the source she ruled out');
  check('S160', 'and the button offers it rather than hiding it',
    /id="rmModelBtn"[^>]*>Show assumed house</.test(admin),
    'the label has to match the state it starts in');
  check('S160', 'why it is off is written down, so it can be turned back on',
    /OFF BY DEFAULT, AND THIS RECORDS WHY/.test(admin) &&
    /axis-aligned\s*\n?\s*BOUNDING boxes/.test(admin),
    'she asked for it drawn; it comes back when it is worth looking at');
  check('S160', 'the yellow ground guide belongs to the wall picker only',
    /const shownWall = \(rmWallPicking \|\| rmCornerMode !== 'dot'\) \? rmActiveWall\(\) : null;/.test(admin),
    'across the lawn it reads as a proposed run of lights along the grass');
}


/* ===== SCHEDULE SUITES - lanil-0b appends BELOW this line ===== */


/* ================= Suite 250. The house, measured from the street ==================
   Owner, 2026-08-22: "measure height not just legth and depth", and the standing rule
   "we outline from street view not sky view".

   js/svdepth.js reads the depth map every Street View panorama ships. It is an ES
   module and pure, so this IMPORTS and RUNS it rather than lifting it — no extraction
   list to fall out of step with, and no browser needed.

   ⚠ THE PAYLOADS HERE ARE SYNTHETIC AND BUILT BYTE BY BYTE, on purpose. A fixture
   fetched from Google would make this suite depend on the network and on an
   undocumented endpoint staying up. Building the bytes means the decoder is tested
   against the format as documented in the file, and a change to either shows up here. */
suite('250. The house, measured from the street');
{
  pendingAsync.push((async () => {
    const sv = await import('./js/svdepth.js');

    /* Encode a depth map the way Google does, so the decoder is exercised for real. */
    function makePayload(W, H, planes, idxFn){
      const off = 8, n = planes.length;
      const buf = new Uint8Array(off + W * H + n * 16);
      buf[0] = 8; buf[1] = n & 255; buf[2] = n >> 8;
      buf[3] = W & 255; buf[4] = W >> 8; buf[5] = H & 255; buf[6] = H >> 8; buf[7] = off;
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) buf[off + y * W + x] = idxFn(x, y);
      const dv = new DataView(buf.buffer, off + W * H);
      planes.forEach((pl, i) => {
        dv.setFloat32(i * 16, pl.n[0], true); dv.setFloat32(i * 16 + 4, pl.n[1], true);
        dv.setFloat32(i * 16 + 8, pl.n[2], true); dv.setFloat32(i * 16 + 12, pl.d, true);
      });
      return Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    }
    const CAM = 2.4;
    const planes = [
      { n: [0, 0, 0], d: 0 },        // 0 = sky, never a surface
      { n: [0, 0, -1], d: CAM },     // ground, camera CAM metres above it
      { n: [-1, 0, 0], d: -10 }      // a wall 10 m ahead
    ];
    const W = 8, H = 4;
    const b64 = makePayload(W, H, planes, (x, y) => (y === 0 ? 0 : y === 3 ? 1 : 2));
    const d = sv.decodeDepthPayload(b64);

    check('svdepth', 'the depth payload decodes to the size its header claims',
      d.width === W && d.height === H && d.planeCount === 3,
      'got ' + d.width + 'x' + d.height + ' with ' + d.planeCount + ' planes');

    /* ⚠ A SHORT PAYLOAD MUST THROW, NOT RETURN SOMETHING PLAUSIBLE. Reading past the
       end yields zeros, and a zeroed plane is a surface at the origin — a measurement
       that looks like a number and is not one. */
    let threw = false;
    try { sv.decodeDepthPayload(b64.slice(0, 12)); } catch (e) { threw = true; }
    check('svdepth', 'a truncated payload throws rather than measuring zeros',
      threw, 'silent garbage here becomes a confident wrong height on a real house');

    check('svdepth', 'the camera height is measured off the ground plane',
      Math.abs(sv.cameraHeight(d) - CAM) < 1e-6,
      'the tool assumes 2.50; real panoramas come back 2.39-2.46, and every height ' +
      'derived from it inherits that error — got ' + sv.cameraHeight(d));

    const noGround = sv.decodeDepthPayload(makePayload(W, H, [planes[0], planes[2]], () => 1));
    check('svdepth', 'and it returns null rather than guessing when no ground is in view',
      sv.cameraHeight(noGround) === null);

    check('svdepth', 'sky has no distance',
      sv.distanceAt(d, 0, 0) === null,
      'plane 0 is sky; treating it as a surface puts a dot on a cloud');

    /* ⭐ THE ONE THE WHOLE FILE EXISTS FOR. Height must come out right, and it must NOT
       depend on the north calibration — a rotation about the vertical leaves the
       vertical alone, which is why this survived that being withdrawn. */
    const hGround = sv.heightAboveGround(d, 0, 3);
    check('svdepth', 'a point on the ground measures about zero above the ground',
      hGround !== null && Math.abs(hGround) < 0.35,
      'got ' + hGround);

    const hWall = sv.heightAboveGround(d, 0, 1);
    check('svdepth', 'a point up on the wall measures higher than one on the ground',
      hWall !== null && hGround !== null && hWall > hGround + 1,
      'wall ' + hWall + ' against ground ' + hGround);

    check('svdepth', 'height is unchanged by the panorama yaw',
      Math.abs(sv.heightAboveGround(d, 0, 1) - hWall) < 1e-9 &&
      Math.abs((sv.pointAt(d, 0, 1, 0) || {}).up - (sv.pointAt(d, 0, 1, 137) || {}).up) < 1e-9,
      'a rotation about the vertical axis cannot change a vertical measurement — if ' +
      'this fails, height has been coupled to the bearing and inherits its refutation');

    check('svdepth', 'a click on the sky has no height',
      sv.heightAboveGround(d, 0, 0) === null);

    /* ⛔ The bearing half is WITHDRAWN and this check exists to keep it withdrawn. */
    const src = read('js/svdepth.js');
    check('svdepth', 'the withdrawn bearing result stays marked as withdrawn',
      /WITHDRAWN 2026-08-22/.test(src) && /0\.0%/.test(src) &&
      /toEastNorth/.test(src),
      'six approaches were tried and refuted; without this note the next person ' +
      'repeats them, or worse, picks the bearing up believing it was measured');
  })());
}


/* ================= Suite 251. The corners, offered rather than hunted ==============
   Owner, 2026-08-22: "also start getting the generated corners and you can click the
   ones you want to keep".

   ⚠ THESE FIXTURES ARE SILHOUETTES GIVEN DIRECTLY, not depth-map payloads, and that is
   deliberate. A first attempt built a synthetic depth map and it tested the FIXTURE, not
   the code: only 31 of 64 columns' rays actually met the plane, so the roof shape I
   thought I had built was not there, and the run reported corners in the wrong places.
   Feeding the silhouette straight in isolates the corner logic from the much harder job
   of constructing a believable panorama. skylineOf is covered separately in Suite 250's
   file against real payload bytes. */
suite('251. The corners, offered rather than hunted');
{
  pendingAsync.push((async () => {
    const rc = await import('./js/roofcorners.js');
    const D = { width: 64, height: 32, indices: new Uint8Array(0), planes: [], planeCount: 0 };
    const mk = (h, planeOf) => {
      const L = [];
      for (let i = 0; i < 64; i++)
        L.push({ x: i, y: 0, distance: 12, plane: planeOf ? planeOf(i) : 2, p: [i * 0.25, 12, h(i)] });
      return L;
    };
    const find = (line) => rc.roofCornerCandidates(D, { skyline: line, cameraHeightM: 2.4, toleranceM: 0.3 });

    /* A gable: flat eave, a rise to a peak, a fall, flat eave. Three real corners. */
    const gable = find(mk(i => i < 20 ? 3.0 : i < 32 ? 3.0 + (i - 20) * 0.25
                                       : i < 44 ? 3.0 + (44 - i) * 0.25 : 3.0));
    check('corners', 'a gable offers exactly its three corners',
      gable.length === 3 && gable.map(c => c.col).sort((a, b) => a - b).join() === '20,32,44',
      'got ' + gable.map(c => c.col).sort((a, b) => a - b).join());

    check('corners', 'and it is confident about them',
      gable.every(c => c.confidence > 0.9),
      'a clean roof must not be hedged — got ' + gable.map(c => c.confidence.toFixed(2)).join(','));

    /* ⚠ THE HEIGHT IS THE POINT OF THE WHOLE FILE. Eave 3.0 m above a camera 2.4 m up. */
    const peak = gable.find(c => c.col === 32), eave = gable.find(c => c.col === 20);
    check('corners', 'each corner carries its own measured height',
      Math.abs(eave.heightM - 5.4) < 0.01 && Math.abs(peak.heightM - 8.4) < 0.01,
      'eave ' + eave.heightM + ', peak ' + peak.heightM);

    /* A chimney: three columns lifted off an otherwise flat roof. */
    const chim = find(mk(i => (i >= 30 && i <= 32) ? 4.2 : 3.0));
    check('corners', 'a chimney is found but demoted, not deleted',
      chim.length > 0 && chim.every(c => c.confidence < 0.5) &&
      chim.some(c => /chimney, vent or aerial/.test(c.why)),
      'the office must still be able to click one it wants — deleting on a guess is the ' +
      'one thing this must not do. got ' + chim.map(c => c.confidence.toFixed(2)).join(','));

    check('corners', 'and it is reported as only a few columns wide',
      chim.every(c => c.spikeWidthCols <= 6) && gable.every(c => c.spikeWidthCols > 6),
      'width is what separates a chimney from a gable — chimney ' +
      chim.map(c => c.spikeWidthCols).join(',') + ' against gable ' +
      gable.map(c => c.spikeWidthCols).join(','));

    /* A tree: the silhouette wanders across many planes, which a roof edge never does. */
    const tree = find(mk(i => 3.0 + Math.sin(i * 1.7) * 0.35, i => 2 + (i % 5)));
    check('corners', 'a tree is recognised by its surface changing, not by its shape',
      tree.length > 0 && tree.every(c => c.confidence < 0.25) &&
      tree.some(c => /likely a tree/.test(c.why)),
      'lanil-9d\'s test, and better than the roughness one it replaced: a roof edge holds ' +
      'ONE face along its length and a canopy does not');

    /* ⚠ NOTHING TO OFFER IS A REAL ANSWER. A flat roof has no corners in silhouette, and
       inventing one would put a dot in the middle of a straight gutter. */
    check('corners', 'a dead flat roofline offers nothing at all',
      find(mk(() => 3.0)).length === 0);

    /* ⚠ REGRESSION GUARD FOR TWO BUGS THIS SUITE CAUGHT, both of which scored a perfect
       synthetic gable as junk (0.11 confidence, five 2-column spikes):
         - roughness was measured ACROSS the corner, so a corner was penalised for being
           a corner. It is measured on each side separately now.
         - width grew the window until the point sat near its own chord, which returns 2
           for everything, because any point is nearly collinear with its neighbours. */
    check('corners', 'a corner is not penalised for being a corner',
      gable.every(c => !/broken up/.test(c.why)),
      'measuring roughness across the corner reports every clean gable as broken — ' +
      'got: ' + gable.map(c => c.why).join(' | '));

    /* Ordering is the interface: the caller shows the best first. */
    check('corners', 'candidates come back best first',
      chim.every((c, i, a) => i === 0 || a[i - 1].confidence >= c.confidence));

    /* ⛔ AND IT MUST NEVER RETURN A WORLD POSITION. It cannot know one — the bearing of a
       depth-map column is exactly what was refuted today — and a function that returned a
       lat/lng would be lying. The caller anchors these through the rendered panorama. */
    const src = read('js/roofcorners.js');
    check('corners', 'no candidate claims a lat/lng',
      gable.every(c => c.lat === undefined && c.lng === undefined) &&
      !/lat:/.test(src.replace(/\/\*[\s\S]*?\*\//g, '')),
      'the caller supplies north; this file must not pretend to know it');
  })());
}

Promise.all(pendingAsync).then(function () {
  console.log('\n' + '='.repeat(55));
  console.log(pass + ' passed, ' + fail + ' failed' + (warn ? ', ' + warn + ' notes' : ''));
  if (fail) {
    console.log('\nFailures:');
    results.forEach(r => console.log('  - ' + r));
    console.log('\nFix these before pushing.');
  } else {
    console.log('\nAll good. Safe to push.');
  }
  if (gaps.length) {
    console.log('\n' + gaps.length + ' known data-flow gaps (not blockers, but worth fixing):');
    gaps.forEach(g => console.log('  - ' + g.split(' — ')[0]));
    console.log('  See the GAP lines above for detail.');
  }
  console.log('='.repeat(55) + '\n');
  process.exit(fail ? 1 : 0);
}).catch(function (e) {
  // An async suite that blew up must never be mistaken for a clean run.
  console.log('\n  FAIL  ' + ((e && e.__suite) || 'an async suite') + ' — crashed partway through');
  /* ⚠ A BARE ReferenceError HERE IS ALMOST ALWAYS ONE THING: a lifted function calling
     a helper its sandbox was never given. Saying so turns a bisect into a one-line fix,
     and assertSandbox above is what stops most of them reaching this point at all. */
  if (e instanceof ReferenceError) {
    console.log('          a lifted function called a helper its sandbox was never ' +
      'given — add it to that harness\'s extraction list (see sandboxDeps)');
  }
  console.log('          ' + (e && e.stack || e));
  console.log('\n' + '='.repeat(55));
  console.log(pass + ' passed, ' + (fail + 1) + ' failed\n');
  process.exit(1);
});
